'use client';

import { useMemo, useState } from 'react';
import useSWR from 'swr';
import { AlertTriangle, Copy, Eye, Search } from 'lucide-react';
import { formatDate } from '@/lib/utils';

function formatDateTime(dateStr) {
  if (!dateStr) return '—';
  const d = new Date(dateStr);
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleString('en-IN', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    second: '2-digit'
  });
}
import PageError from '@/components/PageError';
import AdminRecordModal from '@/components/admin/AdminRecordModal';
import { useToast } from '@/components/ToastProvider';
import {
  contextLabel,
  formatFullErrorLog,
  formatLogReference,
  parseLogDetails,
  postgresHintFromLog,
  severityBadgeClass,
} from '@/lib/platformErrorLogDisplay';

const fetcher = async (url) => {
  const res = await fetch(url, { credentials: 'include' });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(json?.error || 'Failed to load error logs');
  return json;
};

function summaryLine(row) {
  return row.user_message || row.error_message || '—';
}

function DetailField({ label, children, mono = false }) {
  return (
    <div>
      <div className="text-xs text-tertiary" style={{ textTransform: 'uppercase', marginBottom: '0.2rem' }}>
        {label}
      </div>
      <div
        className={mono ? 'font-mono text-xs' : undefined}
        style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}
      >
        {children ?? '—'}
      </div>
    </div>
  );
}

function ErrorLogDetailPanel({ row }) {
  const details = parseLogDetails(row);
  const pgHint = postgresHintFromLog(row);
  const ref = formatLogReference(row.id);

  return (
    <div style={{ display: 'grid', gap: '1.25rem', fontSize: '0.9rem' }}>
      <section>
        <h3 className="text-sm" style={{ margin: '0 0 0.5rem', fontWeight: 700 }}>
          Overview
        </h3>
        <div style={{ display: 'grid', gap: '0.65rem' }}>
          <DetailField label="System Defined Unique Code">
            <strong>{ref || '—'}</strong>
            {row.error_code ? (
              <span className="text-xs text-tertiary" style={{ display: 'block', marginTop: '0.15rem' }}>
                Catalog code: {row.error_code}
              </span>
            ) : null}
            <span className="text-xs text-tertiary" style={{ display: 'block', marginTop: '0.15rem' }}>
              Full ID: {row.id}
            </span>
          </DetailField>
          <DetailField label="When">{formatDateTime(row.created_at)}</DetailField>
          <DetailField label="Severity">
            <span className={`badge ${severityBadgeClass(row.severity)}`}>{row.severity || 'error'}</span>
          </DetailField>
          <DetailField label="Functionality">
            {contextLabel(row.context)}
            <span className="text-xs text-tertiary" style={{ display: 'block' }}>{row.context}</span>
          </DetailField>
          <DetailField label="HTTP status">
            {row.status_code ?? '—'}
            {row.error_code && !String(row.error_code).startsWith('PH-') ? (
              <span className="text-xs text-tertiary" style={{ display: 'block' }}>
                Postgres / driver code: {row.error_code}
              </span>
            ) : null}
          </DetailField>
        </div>
      </section>

      <section>
        <h3 className="text-sm" style={{ margin: '0 0 0.5rem', fontWeight: 700 }}>
          User &amp; tenant
        </h3>
        <div style={{ display: 'grid', gap: '0.65rem' }}>
          <DetailField label="User">{row.user_name || '—'}</DetailField>
          <DetailField label="Email">{details.actorEmail || row.user_email || '—'}</DetailField>
          <DetailField label="Company">{row.company_name || '—'}</DetailField>
          <DetailField label="Campus">{row.tenant_name || '—'}</DetailField>
          <DetailField label="IP address">{row.ip_address || '—'}</DetailField>
        </div>
      </section>

      <section>
        <h3 className="text-sm" style={{ margin: '0 0 0.5rem', fontWeight: 700 }}>
          Request
        </h3>
        <div style={{ display: 'grid', gap: '0.65rem' }}>
          <DetailField label="Route" mono>
            {[details.requestMethod, details.route, details.requestQuery].filter(Boolean).join(' ') || '—'}
          </DetailField>
          <DetailField label="Source">{details.source || 'server'}</DetailField>
          {details.userAgent ? (
            <DetailField label="User agent">
              <span className="text-xs">{details.userAgent}</span>
            </DetailField>
          ) : null}
        </div>
      </section>

      <section>
        <h3 className="text-sm" style={{ margin: '0 0 0.5rem', fontWeight: 700 }}>
          Error
        </h3>
        <div style={{ display: 'grid', gap: '0.65rem' }}>
          <DetailField label="User-facing message">{row.user_message || '—'}</DetailField>
          <DetailField label="Technical message">{row.error_message || '—'}</DetailField>
          {details.technicalMessage && details.technicalMessage !== row.error_message ? (
            <DetailField label="Caught exception" mono>
              {details.technicalMessage}
            </DetailField>
          ) : null}
          {details.systemErrorCode ? (
            <DetailField label="Catalog code" mono>
              {details.systemErrorCode}
            </DetailField>
          ) : null}
          {pgHint ? (
            <div
              style={{
                padding: '0.65rem 0.75rem',
                borderRadius: 'var(--radius-md)',
                background: 'rgba(245, 158, 11, 0.1)',
                border: '1px solid rgba(245, 158, 11, 0.35)',
                fontSize: '0.85rem',
                lineHeight: 1.5,
              }}
            >
              <strong>Likely cause:</strong> {pgHint}
            </div>
          ) : null}
          {details.pgDetail ? (
            <DetailField label="Postgres detail" mono>
              {details.pgDetail}
            </DetailField>
          ) : null}
        </div>
      </section>

      {details.stack ? (
        <section>
          <h3 className="text-sm" style={{ margin: '0 0 0.5rem', fontWeight: 700 }}>
            Stack trace
          </h3>
          <pre
            style={{
              margin: 0,
              padding: '0.75rem',
              borderRadius: 'var(--radius-md)',
              background: 'var(--bg-secondary)',
              overflow: 'auto',
              maxHeight: '28vh',
              fontSize: '0.72rem',
              lineHeight: 1.45,
            }}
          >
            {details.stack}
          </pre>
        </section>
      ) : null}

      {(details.requestBody || details.clientDetails) ? (
        <section>
          <h3 className="text-sm" style={{ margin: '0 0 0.5rem', fontWeight: 700 }}>
            Request / client payload
          </h3>
          <pre
            style={{
              margin: 0,
              padding: '0.75rem',
              borderRadius: 'var(--radius-md)',
              background: 'var(--bg-secondary)',
              overflow: 'auto',
              maxHeight: '28vh',
              fontSize: '0.72rem',
              lineHeight: 1.45,
            }}
          >
            {JSON.stringify(
              {
                requestBody: details.requestBody ?? undefined,
                clientDetails: details.clientDetails ?? undefined,
              },
              null,
              2,
            )}
          </pre>
        </section>
      ) : null}

      <section>
        <h3 className="text-sm" style={{ margin: '0 0 0.5rem', fontWeight: 700 }}>
          Raw details (JSON)
        </h3>
        <pre
          style={{
            margin: 0,
            padding: '0.75rem',
            borderRadius: 'var(--radius-md)',
            background: 'var(--bg-secondary)',
            overflow: 'auto',
            maxHeight: '24vh',
            fontSize: '0.72rem',
            lineHeight: 1.45,
          }}
        >
          {JSON.stringify(details, null, 2)}
        </pre>
      </section>
    </div>
  );
}

export default function AdminErrorLogsPage() {
  const { addToast } = useToast();
  const [contextFilter, setContextFilter] = useState('');
  const [severityFilter, setSeverityFilter] = useState('');
  const [searchQ, setSearchQ] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');

  const queryString = useMemo(() => {
    const p = new URLSearchParams();
    if (contextFilter) p.set('context', contextFilter);
    if (severityFilter) p.set('severity', severityFilter);
    if (searchQ) p.set('q', searchQ);
    if (fromDate) p.set('from', fromDate);
    if (toDate) p.set('to', toDate);
    const s = p.toString();
    return s ? `?${s}` : '';
  }, [contextFilter, severityFilter, searchQ, fromDate, toDate]);

  const { data, error, isLoading } = useSWR(`/api/admin/error-logs${queryString}`, fetcher, {
    revalidateOnFocus: false,
  });

  const logs = data?.logs || [];
  const [selected, setSelected] = useState(null);

  const contextOptions = useMemo(() => {
    const fromApi = data?.contexts || [];
    const fromRows = [...new Set(logs.map((l) => l.context).filter(Boolean))];
    return [...new Set([...fromApi, ...fromRows])].sort();
  }, [data?.contexts, logs]);

  const runSearch = () => setSearchQ(searchInput.trim());

  const copyFullLog = async () => {
    if (!selected) return;
    const text = formatFullErrorLog(selected);
    try {
      await navigator.clipboard.writeText(text);
      addToast('Full log copied to clipboard', 'success');
    } catch {
      try {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.setAttribute('readonly', '');
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        addToast('Full log copied to clipboard', 'success');
      } catch {
        addToast('Could not copy to clipboard', 'error');
      }
    }
  };

  if (error) {
    return <PageError message={error.message} />;
  }

  return (
    <div className="animate-fadeIn">
      <div style={{ marginBottom: '1.25rem' }}>
        <h1 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 800, display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <AlertTriangle size={22} className="text-primary-600" aria-hidden="true" />
          Platform error logs
        </h1>
        <p className="text-secondary text-sm" style={{ margin: '0.35rem 0 0', maxWidth: '48rem', lineHeight: 1.55 }}>
          Full diagnostics for failed API operations. Employers see a short message and reference code — search by reference,
          email, route, or error text. Open a row for stack traces, request payloads, and Postgres hints.
        </p>
      </div>

      <div
        className="card"
        style={{
          marginBottom: '1rem',
          display: 'grid',
          gap: '0.75rem',
          gridTemplateColumns: 'repeat(auto-fit, minmax(12rem, 1fr))',
          alignItems: 'end',
        }}
      >
        <div className="form-group" style={{ margin: 0, gridColumn: '1 / -1' }}>
          <label className="form-label" htmlFor="error-log-search">
            Search
          </label>
          <div style={{ display: 'flex', gap: '0.5rem' }}>
            <input
              id="error-log-search"
              className="form-input"
              placeholder="Reference, email, route, error message…"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') runSearch();
              }}
            />
            <button type="button" className="btn btn-secondary" onClick={runSearch}>
              <Search size={16} aria-hidden="true" />
            </button>
          </div>
        </div>
        <div className="form-group" style={{ margin: 0 }}>
          <label className="form-label">From</label>
          <input className="form-input" type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} />
        </div>
        <div className="form-group" style={{ margin: 0 }}>
          <label className="form-label">To</label>
          <input className="form-input" type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} />
        </div>
        <div className="form-group" style={{ margin: 0 }}>
          <label className="form-label">Severity</label>
          <select className="form-select" value={severityFilter} onChange={(e) => setSeverityFilter(e.target.value)}>
            <option value="">All severities</option>
            <option value="error">Error</option>
            <option value="warning">Warning</option>
            <option value="info">Info / Debug</option>
          </select>
        </div>
        <div className="form-group" style={{ margin: 0 }}>
          <label className="form-label">Functionality</label>
          <select className="form-select" value={contextFilter} onChange={(e) => setContextFilter(e.target.value)}>
            <option value="">All functionalities</option>
            {contextOptions.map((c) => (
              <option key={c} value={c}>
                {contextLabel(c)}
              </option>
            ))}
          </select>
        </div>
      </div>

      {data?.migrationRequired ? (
        <div className="card" style={{ borderColor: 'var(--warning-300, #fcd34d)', marginBottom: '1rem' }}>
          <p style={{ margin: 0, color: 'var(--text-secondary)', lineHeight: 1.55 }}>
            {data.error || 'Run migration 083_platform_error_logs.sql to enable error logging.'}
          </p>
        </div>
      ) : null}

      <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
        {isLoading ? (
          <div className="skeleton" style={{ height: 220, margin: '1rem' }} />
        ) : logs.length === 0 ? (
          <p className="text-secondary" style={{ padding: '1.5rem', margin: 0 }}>
            No error logs match your filters.
          </p>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table className="data-table" style={{ width: '100%' }}>
              <thead>
                <tr>
                  <th>When</th>
                  <th>Unique Code</th>
                  <th>Severity</th>
                  <th>Functionality</th>
                  <th>Route</th>
                  <th>User</th>
                  <th>Status</th>
                  <th>Summary</th>
                  <th style={{ width: 56 }} />
                </tr>
              </thead>
              <tbody>
                {logs.map((row) => (
                  <tr key={row.id}>
                    <td className="text-sm" style={{ whiteSpace: 'nowrap' }}>{formatDateTime(row.created_at)}</td>
                    <td className="font-mono text-xs">
                      <div>{row.reference || formatLogReference(row.id)}</div>
                      {row.error_code ? (
                        <div className="text-xs text-tertiary">{row.error_code}</div>
                      ) : null}
                    </td>
                    <td className="text-sm">
                      <span className={`badge ${severityBadgeClass(row.severity)}`}>
                        {(row.severity || 'error').toUpperCase()}
                      </span>
                    </td>
                    <td className="text-sm" style={{ minWidth: 140 }}>
                      {contextLabel(row.context)}
                    </td>
                    <td className="font-mono text-xs" style={{ maxWidth: 160 }}>
                      {row.route || parseLogDetails(row).route || '—'}
                    </td>
                    <td className="text-sm">
                      <div>{row.user_name || '—'}</div>
                      <div className="text-xs text-tertiary">{row.user_email || '—'}</div>
                    </td>
                    <td>
                      <span className={`badge ${severityBadgeClass(row.severity)}`} style={{ marginBottom: '0.2rem' }}>
                        {row.status_code ?? '—'}
                      </span>
                      {row.error_code && !String(row.error_code).startsWith('PH-') ? (
                        <div className="text-xs text-tertiary font-mono">{row.error_code}</div>
                      ) : null}
                    </td>
                    <td className="text-sm" style={{ maxWidth: 260 }}>
                      <div style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{summaryLine(row)}</div>
                      {postgresHintFromLog(row) ? (
                        <div className="text-xs text-tertiary" style={{ marginTop: '0.2rem' }}>
                          {postgresHintFromLog(row)}
                        </div>
                      ) : null}
                    </td>
                    <td>
                      <button
                        type="button"
                        className="btn btn-ghost btn-sm"
                        aria-label="View full log"
                        onClick={() => setSelected(row)}
                      >
                        <Eye size={15} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <AdminRecordModal
        title={selected ? `Error log — ${formatLogReference(selected.id) || 'details'}` : 'Error log details'}
        mode={selected ? 'view' : null}
        onClose={() => setSelected(null)}
        footer={
          selected ? (
            <button type="button" className="btn btn-secondary" onClick={() => void copyFullLog()}>
              <Copy size={15} aria-hidden="true" style={{ marginRight: '0.35rem' }} />
              Copy full log
            </button>
          ) : null
        }
      >
        {selected ? <ErrorLogDetailPanel row={selected} /> : null}
      </AdminRecordModal>
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import useSWR, { mutate as mutateByKey } from 'swr';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS, FEEDBACK_STATUS_FILTER_OPTIONS, feedbackStatusFilterFn } from '@/lib/tableQueryPresets';
import { formatDate, formatFeedbackRole } from '@/lib/utils';
import PageError from '@/components/PageError';
import { useToast } from '@/components/ToastProvider';
import { ExportCsvSplitButton } from '@/components/export/ExportCsvSplitButton';
import AdminRecordModal from '@/components/admin/AdminRecordModal';
import { StandardTableIconAction } from '@/components/ui/StandardTableIconAction';

const PAGE_SIZE = 10;
const EXPORT_PAGE_SIZE = 500;

const fetchOpts = { credentials: 'include' };

const fetcher = (url) =>
  fetch(url, fetchOpts).then((res) => {
    if (!res.ok) throw new Error('Failed to load feedback');
    return res.json();
  });

const STATUSES = ['Submitted', 'Under Review', 'Planned', 'Closed'];

export default function AdminFeedbackInboxPage() {
  const { addToast } = useToast();
  const [page, setPage] = useState(1);
  const listKey = `/api/feedback?page=${page}&pageSize=${PAGE_SIZE}`;
  const exportKey = `/api/feedback?page=1&pageSize=${EXPORT_PAGE_SIZE}`;

  const { data, error, isLoading, mutate } = useSWR(listKey, fetcher);
  const { data: exportData } = useSWR(exportKey, fetcher, { revalidateOnFocus: false });

  const [panelMode, setPanelMode] = useState(null);
  const [selectedId, setSelectedId] = useState(null);
  const [panelLoading, setPanelLoading] = useState(false);
  const [panelError, setPanelError] = useState('');
  const [threadData, setThreadData] = useState(null);
  const [replyText, setReplyText] = useState('');
  const [replyLoading, setReplyLoading] = useState(false);

  const items = data?.items || [];
  const total = data?.total ?? 0;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  const {
    search,
    setSearch,
    filter,
    setFilter,
    sort,
    setSort,
    filtered: displayItems,
    filteredCount,
    totalCount: pageTotalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(items, {
    getSearchText: (row) =>
      [
        row.title,
        row.description,
        row.category,
        row.user_name,
        row.user_email,
        row.organization_name,
        row.status,
      ]
        .filter(Boolean)
        .join(' '),
    filterFn: feedbackStatusFilterFn,
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'date_desc',
  });

  const statusCounts = data?.statusCounts;

  const counts = useMemo(
    () => ({
      submitted: statusCounts?.Submitted ?? 0,
      review: statusCounts?.['Under Review'] ?? 0,
      planned: statusCounts?.Planned ?? 0,
      closed: statusCounts?.Closed ?? 0,
    }),
    [statusCounts],
  );

  const refreshLists = () => {
    mutate();
    mutateByKey(exportKey);
  };

  const closePanel = () => {
    setPanelMode(null);
    setSelectedId(null);
    setPanelLoading(false);
    setPanelError('');
    setThreadData(null);
    setReplyText('');
  };

  useEffect(() => {
    closePanel();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- reset detail when list page changes
  }, [page]);

  const updateStatus = async (id, status) => {
    const res = await fetch(`/api/feedback/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ status }),
    });
    if (!res.ok) {
      const j = await res.json().catch(() => ({}));
      addToast(j.error || 'Update failed', 'warning');
      return;
    }
    refreshLists();
    if (selectedId === id && threadData?.item) {
      setThreadData((prev) =>
        prev?.item ? { ...prev, item: { ...prev.item, status } } : prev,
      );
    }
  };

  const loadThread = async (id) => {
    try {
      const res = await fetch(`/api/feedback/${id}`, fetchOpts);
      const body = await res.json().catch(() => ({}));
      if (!res.ok) {
        const msg = body.error || 'Could not load feedback';
        setPanelError(msg);
        addToast(msg, 'warning');
        return null;
      }
      if (body.repliesUnavailable) {
        setThreadData(body);
        addToast(
          body.error || 'Replies table is not set up on this database.',
          'warning',
        );
        return body;
      }
      setThreadData(body);
      return body;
    } catch {
      const msg = 'Network error while loading feedback';
      setPanelError(msg);
      addToast(msg, 'warning');
      return null;
    } finally {
      setPanelLoading(false);
    }
  };

  const openThread = async (id) => {
    setSelectedId(id);
    setPanelMode('view');
    setPanelError('');
    setThreadData(null);
    setReplyText('');
    setPanelLoading(true);
    await loadThread(id);
  };

  const sendReply = async () => {
    if (!selectedId || !replyText.trim()) return;
    setReplyLoading(true);
    const message = replyText.trim();
    try {
      const res = await fetch(`/api/feedback/${selectedId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ message }),
      });
      const body = await res.json().catch(() => ({}));
      if (!res.ok) {
        addToast(body.error || 'Reply failed', 'warning');
        return;
      }
      setReplyText('');
      addToast('Reply posted.', 'success');
      refreshLists();
      await loadThread(selectedId);
    } catch {
      addToast('Network error while posting reply', 'warning');
    } finally {
      setReplyLoading(false);
    }
  };

  const selectedTitle =
    threadData?.item?.title ||
    items.find((row) => row.id === selectedId)?.title ||
    'Feedback';

  if (error) return <PageError error={error} />;

  if (isLoading || !data) {
    return (
      <div>
        <div className="skeleton skeleton-heading" />
        <div className="skeleton skeleton-card" style={{ height: 200 }} />
      </div>
    );
  }

  const buildExportRows = (rows) => {
    const headers = [
      'When',
      'Title',
      'Description',
      'Category',
      'From',
      'Organization',
      'Role',
      'Replies',
      'Latest reply',
      'Status',
    ];
    const rowsList = rows.map((row) => [
      formatDate(row.created_at),
      row.title,
      row.description || '',
      row.category,
      (row.user_name && row.user_name.trim()) || row.user_email || '—',
      row.organization_name || '—',
      formatFeedbackRole(row.user_role),
      String(row.reply_count || 0),
      row.latest_reply || '',
      row.status,
    ]);
    return { headers, rows: rowsList };
  };

  const getExportRows = (scope) => {
    if (scope === 'full') {
      const rows = exportData?.items || items;
      return buildExportRows(rows);
    }
    return buildExportRows(displayItems);
  };

  return (
    <div className="animate-fadeIn">
      <div className="page-header">
        <div className="page-header-left">
          <h1>📥 Feedback inbox</h1>
          <p>Every submission from students, employers, and college admins across the platform.</p>
        </div>
        <ExportCsvSplitButton
          filenameBase="admin_feedback"
          currentCount={displayItems.length}
          fullCount={total}
          getRows={getExportRows}
        />
      </div>

      <div className="grid grid-4" style={{ marginBottom: '1rem' }}>
        <div className="stats-card">
          <div className="stats-card-value">{counts.submitted}</div>
          <div className="stats-card-label">Submitted</div>
        </div>
        <div className="stats-card amber">
          <div className="stats-card-value">{counts.review}</div>
          <div className="stats-card-label">Under review</div>
        </div>
        <div className="stats-card green">
          <div className="stats-card-value">{counts.planned}</div>
          <div className="stats-card-label">Planned</div>
        </div>
        <div className="stats-card">
          <div className="stats-card-value">{counts.closed}</div>
          <div className="stats-card-label">Closed</div>
        </div>
      </div>

      <div className="card">
        <div className="card-header">
          <h3 className="card-title">
            All entries ({total}
            {total > 0 ? ` · page ${page} of ${totalPages}` : ''}
            )
          </h3>
        </div>
        {pageTotalCount > 0 ? (
          <DataTableToolbar
            search={search}
            onSearchChange={setSearch}
            searchPlaceholder="Search title, category, or submitter…"
            filter={filter}
            onFilterChange={setFilter}
            filterOptions={FEEDBACK_STATUS_FILTER_OPTIONS}
            filterLabel="Status"
            sort={sort}
            onSortChange={setSort}
            sortOptions={COMMON_SORT_OPTIONS}
            filteredCount={filteredCount}
            totalCount={pageTotalCount}
            hasActiveFilters={hasActiveFilters}
            onClear={clearFilters}
            style={{ margin: '0 1.25rem 1rem', border: '1px solid var(--border-default)' }}
          />
        ) : null}
        <div className="table-container">
          <table className="data-table">
            <thead>
              <tr>
                <th>When</th>
                <th>Title</th>
                <th>Category</th>
                <th>From</th>
                <th>Role</th>
                <th>Replies</th>
                <th>Status</th>
                <th style={{ width: 72 }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {displayItems.length === 0 && pageTotalCount > 0 ? (
                <tr>
                  <td colSpan={8} className="text-center text-secondary">
                    No feedback on this page matches your search or filters.
                  </td>
                </tr>
              ) : null}
              {displayItems.map((row) => (
                <tr key={row.id}>
                  <td className="text-sm">{formatDate(row.created_at)}</td>
                  <td>
                    <div className="font-semibold">{row.title}</div>
                    <div
                      className="text-sm text-secondary"
                      style={{ maxWidth: 420, marginTop: '0.25rem', lineHeight: 1.45 }}
                    >
                      {row.description}
                    </div>
                  </td>
                  <td>{row.category}</td>
                  <td className="text-sm">
                    <div>{(row.user_name && row.user_name.trim()) || '—'}</div>
                    {row.user_email ? (
                      <div className="text-xs text-tertiary">{row.user_email}</div>
                    ) : null}
                    <div className="text-xs text-secondary" style={{ marginTop: '0.2rem' }}>
                      {row.organization_name || '—'}
                    </div>
                  </td>
                  <td>
                    <span className="badge badge-gray">{formatFeedbackRole(row.user_role)}</span>
                  </td>
                  <td>
                    {Number(row.reply_count || 0) > 0 ? (
                      <span className="badge badge-green">{row.reply_count} replied</span>
                    ) : (
                      <span className="badge badge-gray">No reply</span>
                    )}
                  </td>
                  <td>
                    <select
                      className="form-select"
                      style={{ minWidth: '140px' }}
                      value={row.status}
                      onChange={(e) => updateStatus(row.id, e.target.value)}
                    >
                      {STATUSES.map((s) => (
                        <option key={s} value={s}>
                          {s}
                        </option>
                      ))}
                    </select>
                  </td>
                  <td>
                    <StandardTableIconAction
                      action="view"
                      showLabel={false}
                      onClick={() => openThread(row.id)}
                      tooltip="View thread and reply"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {total > PAGE_SIZE && (
          <div
            style={{
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: '0.75rem',
              padding: '0.75rem 1rem',
              borderTop: '1px solid var(--border-default)',
            }}
          >
            <span className="text-sm text-secondary">
              Showing {(page - 1) * PAGE_SIZE + 1}–{Math.min(page * PAGE_SIZE, total)} of {total}
            </span>
            <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
              <button
                type="button"
                className="btn btn-outline btn-sm"
                disabled={page <= 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
              >
                Previous
              </button>
              <span className="text-sm text-secondary">
                Page {page} / {totalPages}
              </span>
              <button
                type="button"
                className="btn btn-outline btn-sm"
                disabled={page >= totalPages}
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              >
                Next
              </button>
            </div>
          </div>
        )}
        {items.length === 0 && (
          <p className="text-sm text-secondary" style={{ padding: '1rem' }}>
            No feedback yet — or the <code>platform_feedback</code> table is not created. Run{' '}
            <code>db/migrations/002_platform_feedback.sql</code>.
          </p>
        )}
      </div>

      <AdminRecordModal
        title={selectedTitle}
        mode={panelMode}
        loading={panelLoading}
        saving={replyLoading}
        error={panelError}
        onClose={closePanel}
        footer={
          threadData?.item && !threadData.repliesUnavailable ? (
            <button
              type="button"
              className="btn btn-primary"
              onClick={sendReply}
              disabled={replyLoading || !replyText.trim()}
            >
              {replyLoading ? 'Sending…' : 'Send reply'}
            </button>
          ) : null
        }
      >
        {threadData?.item ? (
          <>
            {threadData.repliesUnavailable ? (
              <div
                className="card"
                style={{
                  marginBottom: '1rem',
                  padding: '0.75rem 1rem',
                  borderColor: 'var(--warning-300)',
                  background: 'var(--warning-50)',
                }}
              >
                <p className="text-sm" style={{ margin: 0, color: 'var(--warning-800)' }}>
                  {threadData.error ||
                    'Replies are disabled until db/migrations/003_platform_feedback_replies.sql is applied.'}
                </p>
              </div>
            ) : null}

            <div style={{ marginBottom: '1rem' }}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '0.75rem',
                  alignItems: 'flex-start',
                }}
              >
                <div>
                  <div className="text-xs text-tertiary" style={{ marginBottom: '0.25rem' }}>
                    {formatDate(threadData.item.created_at)}
                    {threadData.item.category ? ` · ${threadData.item.category}` : ''}
                  </div>
                  <div className="text-sm" style={{ whiteSpace: 'pre-wrap', lineHeight: 1.5 }}>
                    {threadData.item.description}
                  </div>
                  {threadData.item.organization_name ? (
                    <div className="text-xs text-tertiary" style={{ marginTop: '0.5rem' }}>
                      {threadData.item.organization_name}
                      {' · '}
                      {formatFeedbackRole(threadData.item.user_role)}
                      {threadData.item.user_email ? ` · ${threadData.item.user_email}` : ''}
                    </div>
                  ) : null}
                </div>
                <select
                  className="form-select"
                  style={{ minWidth: '140px', flexShrink: 0 }}
                  value={threadData.item.status}
                  onChange={(e) => updateStatus(threadData.item.id, e.target.value)}
                >
                  {STATUSES.map((s) => (
                    <option key={s} value={s}>
                      {s}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', marginBottom: '1rem' }}>
              <p className="text-xs font-semibold text-secondary" style={{ margin: 0, textTransform: 'uppercase' }}>
                Discussion
              </p>
              {(threadData.replies || []).map((r) => (
                <div
                  key={r.id}
                  style={{
                    border: '1px solid var(--border-default)',
                    borderRadius: 'var(--radius-md)',
                    padding: '0.65rem 0.75rem',
                  }}
                >
                  <div className="text-sm" style={{ whiteSpace: 'pre-wrap' }}>
                    {r.message}
                  </div>
                  <div className="text-xs text-tertiary" style={{ marginTop: '0.35rem' }}>
                    {(r.author_name && r.author_name.trim()) || r.author_email || 'Super Admin'} ·{' '}
                    {formatDate(r.created_at)}
                  </div>
                </div>
              ))}
              {(threadData.replies || []).length === 0 && !threadData.repliesUnavailable ? (
                <p className="text-sm text-secondary" style={{ margin: 0 }}>
                  No replies yet. Send the first response below.
                </p>
              ) : null}
            </div>

            {!threadData.repliesUnavailable ? (
              <div className="form-group" style={{ marginBottom: 0 }}>
                <label className="form-label" htmlFor="admin-feedback-reply">
                  Reply as Super Admin
                </label>
                <textarea
                  id="admin-feedback-reply"
                  className="form-input"
                  rows={4}
                  placeholder="Type your reply to the feedback submitter…"
                  value={replyText}
                  onChange={(e) => setReplyText(e.target.value)}
                />
              </div>
            ) : null}
          </>
        ) : null}
      </AdminRecordModal>
    </div>
  );
}

'use client';

import useSWR from 'swr';
import { ClipboardList, Search, Building2, GraduationCap } from 'lucide-react';
import { formatDate, formatStatus, getStatusColor } from '@/lib/utils';
import CompanyNameLink from '@/components/CompanyNameLink';
import { StandardTableIconAction } from '@/components/ui/StandardTableIconAction';
import ApplicationDetailModal from './ApplicationDetailModal';
import { useState, useMemo } from 'react';

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load applications');
  return json;
};

const TABLE_COLUMNS = [
  'Student',
  'Roll No.',
  'Department',
  'Company',
  'Type',
  'Opening',
  'Status',
  'Applied',
  'Actions',
];

function openingLabel(a) {
  return a.opening_title || a.drive_title || '—';
}

function applicationKindLabel(a) {
  if (a.source_kind === 'drive') return 'Placement drive';
  const jt = String(a.job_type || '').toLowerCase();
  if (jt === 'internship') return 'Internship';
  if (jt === 'short_project' || jt === 'hackathon') return 'Project';
  if (jt === 'full_time' || jt === 'part_time' || jt === 'contract') return 'Job';
  return 'Program';
}

export default function DtCollegeApplications() {
  const { data, isLoading, error } = useSWR('/api/college/applications', fetcher);
  const applications = Array.isArray(data?.applications) ? data.applications : [];
  const counts = data?.counts || { drives: 0, programs: 0, total: 0 };
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [kindFilter, setKindFilter] = useState('');
  const [viewRow, setViewRow] = useState(null);

  const filtered = useMemo(
    () =>
      applications.filter((a) => {
        const haystack = [
          a.student_name,
          a.roll_number,
          a.department,
          a.company_name,
          a.drive_title,
          a.opening_title,
          applicationKindLabel(a),
        ]
          .filter(Boolean)
          .join(' ')
          .toLowerCase();
        const matchSearch = !search || haystack.includes(search.toLowerCase());
        const matchStatus = !statusFilter || a.status === statusFilter;
        const matchKind =
          !kindFilter ||
          (kindFilter === 'drive' && a.source_kind === 'drive') ||
          (kindFilter === 'program' && a.source_kind === 'program');
        return matchSearch && matchStatus && matchKind;
      }),
    [applications, search, statusFilter, kindFilter],
  );

  const statuses = useMemo(
    () => [...new Set(applications.map((a) => a.status).filter(Boolean))],
    [applications],
  );

  const summaryLine = isLoading
    ? 'Loading applications…'
    : error
      ? 'Could not load counts'
      : `${counts.total || applications.length} applications · ${counts.drives || 0} placement drives · ${counts.programs || 0} jobs & programs`;

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem', minWidth: 0, maxWidth: '100%' }}>
      <div
        style={{
          marginBottom: '2rem',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start',
          flexWrap: 'wrap',
          gap: '1rem',
        }}
      >
        <div>
          <h1
            style={{
              fontSize: '1.75rem',
              fontWeight: 800,
              color: 'var(--text-primary)',
              margin: '0 0 0.35rem',
              letterSpacing: '-0.02em',
              display: 'flex',
              alignItems: 'center',
              gap: '0.5rem',
            }}
          >
            <ClipboardList size={24} aria-hidden />
            Applications
          </h1>
          <p style={{ fontSize: '0.875rem', color: 'var(--text-secondary)', margin: 0 }}>{summaryLine}</p>
        </div>
      </div>

      <div
        className="card"
        style={{
          padding: '1.25rem',
          marginBottom: '1.5rem',
          display: 'flex',
          gap: '1rem',
          flexWrap: 'wrap',
          alignItems: 'center',
          border: '1px solid var(--border-default)',
        }}
      >
        <div style={{ position: 'relative', flex: '1 1 240px' }}>
          <Search
            size={16}
            style={{
              position: 'absolute',
              left: '1rem',
              top: '50%',
              transform: 'translateY(-50%)',
              color: 'var(--text-tertiary)',
              pointerEvents: 'none',
            }}
          />
          <input
            className="form-input"
            placeholder="Search student, roll, company, opening…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ paddingLeft: '2.5rem' }}
            disabled={isLoading && !applications.length}
          />
        </div>
        <select
          className="form-select"
          style={{ width: 'auto', padding: '0.65rem 2rem 0.65rem 1rem' }}
          value={kindFilter}
          onChange={(e) => setKindFilter(e.target.value)}
          disabled={isLoading && !applications.length}
        >
          <option value="">All types</option>
          <option value="drive">Placement drives</option>
          <option value="program">Jobs & programs</option>
        </select>
        <select
          className="form-select"
          style={{ width: 'auto', padding: '0.65rem 2rem 0.65rem 1rem' }}
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          disabled={isLoading && !applications.length}
        >
          <option value="">All statuses</option>
          {statuses.map((s) => (
            <option key={s} value={s}>
              {formatStatus(s)}
            </option>
          ))}
        </select>
        <span style={{ marginLeft: 'auto', fontSize: '0.9rem', fontWeight: 600, color: 'var(--text-secondary)' }}>
          {isLoading && !applications.length ? '—' : `${filtered.length} of ${applications.length}`}
        </span>
      </div>

      {error ? (
        <div
          className="card"
          role="alert"
          style={{
            padding: '1rem 1.25rem',
            marginBottom: '1rem',
            background: 'var(--danger-50)',
            border: '1px solid var(--danger-200)',
          }}
        >
          <p style={{ margin: 0, color: 'var(--danger-700)', fontWeight: 600 }}>
            {error.message || 'Could not load applications.'}
          </p>
        </div>
      ) : null}

      <div className="card card-table-shell" style={{ border: '1px solid var(--border-default)', minWidth: 0, maxWidth: '100%' }}>
        <div
          className="table-container"
          style={{ border: 'none', borderRadius: 'inherit', overflowX: 'auto', WebkitOverflowScrolling: 'touch' }}
        >
          <table className="data-table college-applications-table">
            <colgroup>
              <col className="college-applications-col-student" />
              <col className="college-applications-col-roll" />
              <col className="college-applications-col-dept" />
              <col className="college-applications-col-company" />
              <col className="college-applications-col-type" />
              <col className="college-applications-col-opening" />
              <col className="college-applications-col-status" />
              <col className="college-applications-col-applied" />
              <col className="college-applications-col-actions" />
            </colgroup>
            <thead>
              <tr style={{ background: 'var(--bg-secondary)' }}>
                {TABLE_COLUMNS.map((col, i) => (
                  <th
                    key={col}
                    style={
                      i === 0
                        ? { paddingLeft: '1.5rem' }
                        : i === TABLE_COLUMNS.length - 1
                          ? { textAlign: 'right', paddingRight: '1.5rem', width: 1 }
                          : undefined
                    }
                  >
                    {col}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {isLoading && !applications.length ? (
                <tr>
                  <td colSpan={TABLE_COLUMNS.length} style={{ padding: '2rem 1.5rem' }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                      {[1, 2, 3, 4].map((i) => (
                        <div key={i} className="skeleton" style={{ height: 40, borderRadius: 'var(--radius-md)' }} />
                      ))}
                    </div>
                  </td>
                </tr>
              ) : null}

              {!isLoading &&
                !error &&
                filtered.map((a) => {
                  const initials = (a.student_name || 'S')
                    .split(' ')
                    .map((n) => n[0])
                    .join('')
                    .slice(0, 2)
                    .toUpperCase();
                  return (
                    <tr key={`${a.source_kind}-${a.id}`}>
                      <td style={{ paddingLeft: '1.5rem' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                          <div
                            style={{
                              width: 32,
                              height: 32,
                              borderRadius: '50%',
                              background: 'var(--primary-100)',
                              color: 'var(--primary-700)',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              fontSize: '0.7rem',
                              fontWeight: 700,
                              flexShrink: 0,
                              border: '1px solid var(--primary-200)',
                            }}
                          >
                            {initials}
                          </div>
                          <span style={{ fontWeight: 600, fontSize: '0.95rem' }}>{a.student_name || '—'}</span>
                        </div>
                      </td>
                      <td style={{ fontFamily: 'monospace', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                        {a.roll_number || '—'}
                      </td>
                      <td>
                        <div
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '0.35rem',
                            fontSize: '0.9rem',
                            color: 'var(--text-secondary)',
                          }}
                        >
                          <GraduationCap size={13} style={{ flexShrink: 0 }} aria-hidden />
                          {a.department || '—'}
                        </div>
                      </td>
                      <td className="cell-truncate" title={a.company_name || undefined}>
                        <div
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '0.35rem',
                            fontSize: '0.9rem',
                            fontWeight: 500,
                            minWidth: 0,
                          }}
                        >
                          <Building2 size={13} style={{ flexShrink: 0, color: 'var(--text-tertiary)' }} aria-hidden />
                          <span className="cell-truncate" style={{ display: 'block' }}>
                            <CompanyNameLink name={a.company_name} website={a.company_website} />
                          </span>
                        </div>
                      </td>
                      <td className="text-sm text-secondary cell-truncate" title={applicationKindLabel(a)}>
                        {applicationKindLabel(a)}
                      </td>
                      <td className="text-sm text-secondary cell-truncate" title={openingLabel(a)}>
                        {openingLabel(a)}
                      </td>
                      <td>
                        <span className={`badge badge-${getStatusColor(a.status)} badge-dot`} style={{ fontSize: '0.75rem' }}>
                          {formatStatus(a.status)}
                        </span>
                      </td>
                      <td className="text-sm text-secondary cell-truncate" title={a.applied_at ? formatDate(a.applied_at) : undefined}>
                        {a.applied_at ? formatDate(a.applied_at) : '—'}
                      </td>
                      <td style={{ textAlign: 'right', paddingRight: '1.5rem', whiteSpace: 'nowrap' }}>
                        <StandardTableIconAction action="view" showLabel={false} onClick={() => setViewRow(a)} />
                      </td>
                    </tr>
                  );
                })}

              {!isLoading && !error && filtered.length === 0 ? (
                <tr>
                  <td colSpan={TABLE_COLUMNS.length} style={{ textAlign: 'center', padding: '3rem 2rem' }}>
                    <ClipboardList size={36} style={{ margin: '0 auto 0.75rem', opacity: 0.25 }} aria-hidden />
                    <div style={{ fontWeight: 600, color: 'var(--text-primary)', marginBottom: '0.25rem' }}>
                      {applications.length === 0 ? 'No applications yet' : 'No applications match your filters'}
                    </div>
                    <div style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
                      {applications.length === 0
                        ? 'Students apply from placement drives, jobs, internships, and projects on their dashboard.'
                        : 'Try clearing search or filters.'}
                    </div>
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
      </div>

      <ApplicationDetailModal row={viewRow} onClose={() => setViewRow(null)} />
    </div>
  );
}

