'use client';

import { useCallback, useEffect, useState } from 'react';
import { loadClarifications } from '@/lib/demoClarifications';
import { useToast } from '@/components/ToastProvider';
import {
  Search,
  ChevronDown,
  ChevronUp,
  MessageSquare,
  Building2,
  Download,
  FileText,
  Lightbulb,
} from 'lucide-react';

/**
 * Read-only clarifications browser — same layout as /dashboard/student/clarifications
 * but college admins only view Q&A (no posting).
 */
export default function CollegeClarificationsPage() {
  const { addToast } = useToast();
  const [data, setData] = useState({ batches: [] });
  const [filtered, setFiltered] = useState([]);
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('date');
  const [openBatchIds, setOpenBatchIds] = useState(new Set());

  const formatDate = (d) => {
    if (!d) return '';
    try {
      return new Date(d).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
    } catch {
      return String(d).slice(0, 10);
    }
  };

  const refresh = useCallback(async () => {
    try {
      const payload = await loadClarifications();
      setData({ batches: Array.isArray(payload?.batches) ? payload.batches : [] });
    } catch (e) {
      addToast(e.message || 'Failed to load clarifications', 'error');
      setData({ batches: [] });
    }
  }, [addToast]);

  useEffect(() => {
    const t = window.setTimeout(() => void refresh(), 0);
    return () => window.clearTimeout(t);
  }, [refresh]);

  useEffect(() => {
    const q = search.trim().toLowerCase();
    const batches = Array.isArray(data.batches) ? data.batches : [];
    let results = q
      ? batches.filter(
          (b) =>
            String(b.company || '').toLowerCase().includes(q) ||
            (Array.isArray(b.questions) &&
              b.questions.some((qn) => String(qn.text || '').toLowerCase().includes(q))),
        )
      : [...batches];

    if (sortBy === 'name') {
      results = results.sort((a, b) => String(a.company || '').localeCompare(String(b.company || '')));
    } else {
      results = results.sort((a, b) => new Date(b.postedAt) - new Date(a.postedAt));
    }
    setFiltered(results);
  }, [search, sortBy, data.batches]);

  const toggleBatch = (id) => {
    setOpenBatchIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const exportAsText = (batch) => {
    const lines = [`Clarifications — ${batch.company}`, `Posted by: ${batch.postedBy}`, `Date: ${batch.postedAt}`, ''];
    (batch.questions || []).forEach((q, i) => {
      lines.push(`Q${i + 1}: ${q.text}`);
      lines.push(`A: ${q.answer || 'Awaiting company response.'}`);
      lines.push('');
    });
    const blob = new Blob([lines.join('\n')], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${String(batch.company).replace(/\s+/g, '_')}_clarifications.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const exportAsCsv = (batch) => {
    const rows = [['Question', 'Answer', 'Answered By']];
    (batch.questions || []).forEach((q) => {
      rows.push([`"${q.text}"`, `"${q.answer || 'Awaiting response'}"`, `"${q.answeredBy || ''}"`]);
    });
    const csv = rows.map((r) => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${String(batch.company).replace(/\s+/g, '_')}_clarifications.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="animate-fadeIn" style={{ maxWidth: '860px', margin: '0 auto', paddingBottom: '3rem' }}>
      <div className="page-header" style={{ marginBottom: '1.5rem' }}>
        <div className="page-header-left" style={{ flex: 1 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.35rem' }}>
            <div
              style={{
                width: '36px',
                height: '36px',
                borderRadius: '50%',
                background: 'var(--primary-100)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <MessageSquare size={18} color="var(--primary-600)" />
            </div>
            <h1 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 700 }}>Clarifications</h1>
          </div>
          <p className="text-secondary" style={{ margin: 0, fontSize: '0.9rem' }}>
            Same view as students see — read only here. To publish official batches, use your placement tools; students post
            follow-ups from their Clarifications page.
          </p>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '0.75rem', marginBottom: '1.5rem', alignItems: 'center' }}>
        <div style={{ position: 'relative', flex: 1 }}>
          <Search
            size={16}
            style={{
              position: 'absolute',
              left: '14px',
              top: '50%',
              transform: 'translateY(-50%)',
              color: 'var(--gray-400)',
              pointerEvents: 'none',
            }}
          />
          <input
            type="text"
            className="form-input"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search companies or questions…"
            style={{ paddingLeft: '2.5rem', borderRadius: '999px', background: 'var(--surface-2)' }}
          />
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', flexShrink: 0 }}>
          <span style={{ fontSize: '0.8rem', color: 'var(--gray-500)', whiteSpace: 'nowrap' }}>Sort:</span>
          <button
            type="button"
            onClick={() => setSortBy('date')}
            style={{
              padding: '0.35rem 0.85rem',
              borderRadius: '999px',
              fontSize: '0.8rem',
              fontWeight: 500,
              border: '1px solid',
              cursor: 'pointer',
              background: sortBy === 'date' ? 'var(--primary-600)' : 'var(--surface-2)',
              color: sortBy === 'date' ? '#fff' : 'var(--gray-600)',
              borderColor: sortBy === 'date' ? 'var(--primary-600)' : 'var(--gray-300)',
              transition: 'all 0.15s',
            }}
          >
            Recent
          </button>
          <button
            type="button"
            onClick={() => setSortBy('name')}
            style={{
              padding: '0.35rem 0.85rem',
              borderRadius: '999px',
              fontSize: '0.8rem',
              fontWeight: 500,
              border: '1px solid',
              cursor: 'pointer',
              background: sortBy === 'name' ? 'var(--primary-600)' : 'var(--surface-2)',
              color: sortBy === 'name' ? '#fff' : 'var(--gray-600)',
              borderColor: sortBy === 'name' ? 'var(--primary-600)' : 'var(--gray-300)',
              transition: 'all 0.15s',
            }}
          >
            A–Z
          </button>
        </div>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
        {filtered.length === 0 ? (
          <div className="card" style={{ textAlign: 'center', padding: '2.5rem', color: 'var(--gray-400)' }}>
            <MessageSquare size={32} style={{ marginBottom: '0.75rem', opacity: 0.4 }} />
            <p style={{ margin: 0 }}>No clarification threads found{search ? ` for "${search}"` : ''}.</p>
          </div>
        ) : (
          filtered.map((batch) => {
            const isOpen = openBatchIds.has(batch.id);
            const questions = Array.isArray(batch.questions) ? batch.questions : [];
            const answeredCount = questions.filter((q) => q.answer).length;
            return (
              <div
                key={batch.id}
                className="card"
                style={{
                  padding: 0,
                  overflow: 'hidden',
                  border: isOpen ? '1px solid var(--primary-300)' : '1px solid var(--gray-200)',
                  transition: 'border-color 0.2s',
                }}
              >
                <button
                  type="button"
                  onClick={() => toggleBatch(batch.id)}
                  style={{
                    width: '100%',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '1rem',
                    padding: '1rem 1.25rem',
                    background: isOpen ? 'var(--primary-50)' : 'var(--surface)',
                    border: 'none',
                    cursor: 'pointer',
                    textAlign: 'left',
                    transition: 'background 0.2s',
                  }}
                >
                  <div
                    style={{
                      width: '40px',
                      height: '40px',
                      borderRadius: '10px',
                      background: 'var(--primary-100)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      flexShrink: 0,
                    }}
                  >
                    <Building2 size={18} color="var(--primary-600)" />
                  </div>

                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 600, fontSize: '1rem', color: 'var(--gray-900)', marginBottom: '0.2rem' }}>
                      {batch.company}
                    </div>
                    <div style={{ fontSize: '0.8rem', color: 'var(--gray-500)' }}>{formatDate(batch.postedAt)}</div>
                  </div>

                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexShrink: 0 }}>
                    <span
                      style={{
                        padding: '0.2rem 0.7rem',
                        borderRadius: '999px',
                        background: 'var(--gray-100)',
                        color: 'var(--gray-600)',
                        fontSize: '0.78rem',
                        fontWeight: 500,
                      }}
                    >
                      {questions.length} Q{questions.length !== 1 ? 's' : ''}
                    </span>
                    {answeredCount > 0 && (
                      <span
                        style={{
                          padding: '0.2rem 0.7rem',
                          borderRadius: '999px',
                          background: 'var(--success-100, #dcfce7)',
                          color: 'var(--success-700, #15803d)',
                          fontSize: '0.78rem',
                          fontWeight: 500,
                        }}
                      >
                        {answeredCount} Answered
                      </span>
                    )}
                    {isOpen ? <ChevronUp size={18} color="var(--primary-600)" /> : <ChevronDown size={18} color="var(--gray-400)" />}
                  </div>
                </button>

                {isOpen && (
                  <div style={{ padding: '1.25rem', borderTop: '1px solid var(--gray-200)', background: 'var(--surface)' }}>
                    <div
                      style={{
                        display: 'flex',
                        justifyContent: 'flex-end',
                        alignItems: 'center',
                        gap: '0.5rem',
                        marginBottom: '1.25rem',
                        flexWrap: 'wrap',
                      }}
                    >
                      <button
                        type="button"
                        className="btn btn-secondary"
                        style={{ fontSize: '0.8rem', padding: '0.35rem 0.85rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}
                        onClick={() => exportAsText(batch)}
                      >
                        <FileText size={14} /> Export Text
                      </button>
                      <button
                        type="button"
                        className="btn btn-secondary"
                        style={{ fontSize: '0.8rem', padding: '0.35rem 0.85rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}
                        onClick={() => exportAsCsv(batch)}
                      >
                        <Download size={14} /> Export CSV
                      </button>
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
                      {questions.map((q, idx) => (
                        <div key={q.id} style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                          <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'flex-start' }}>
                            <div
                              style={{
                                width: '28px',
                                height: '28px',
                                borderRadius: '50%',
                                flexShrink: 0,
                                background: 'var(--gray-200)',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                fontSize: '0.75rem',
                                fontWeight: 700,
                                color: 'var(--gray-600)',
                              }}
                            >
                              Q{idx + 1}
                            </div>
                            <div
                              style={{
                                flex: 1,
                                background: 'var(--gray-50)',
                                border: '1px solid var(--gray-200)',
                                borderRadius: '0 12px 12px 12px',
                                padding: '0.75rem 1rem',
                              }}
                            >
                              <div style={{ fontSize: '0.78rem', fontWeight: 600, color: 'var(--gray-500)', marginBottom: '0.3rem' }}>
                                {batch.postedBy}
                              </div>
                              <div style={{ fontSize: '0.9rem', color: 'var(--gray-800)', lineHeight: '1.5' }}>{q.text}</div>
                            </div>
                          </div>

                          {q.answer ? (
                            <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'flex-start', paddingLeft: '2rem' }}>
                              <div
                                style={{
                                  flex: 1,
                                  background: 'var(--primary-50)',
                                  border: '1px solid var(--primary-200)',
                                  borderRadius: '12px 12px 12px 0',
                                  padding: '0.75rem 1rem',
                                }}
                              >
                                <div style={{ fontSize: '0.78rem', fontWeight: 600, color: 'var(--primary-600)', marginBottom: '0.3rem' }}>
                                  {q.answeredBy || batch.company} · Official Answer
                                </div>
                                <div style={{ fontSize: '0.9rem', color: 'var(--gray-800)', lineHeight: '1.5' }}>{q.answer}</div>
                              </div>
                              <div
                                style={{
                                  width: '28px',
                                  height: '28px',
                                  borderRadius: '50%',
                                  flexShrink: 0,
                                  background: 'var(--primary-100)',
                                  display: 'flex',
                                  alignItems: 'center',
                                  justifyContent: 'center',
                                }}
                              >
                                <Building2 size={14} color="var(--primary-600)" />
                              </div>
                            </div>
                          ) : (
                            <div style={{ paddingLeft: '3.75rem' }}>
                              <span
                                style={{
                                  fontSize: '0.8rem',
                                  color: 'var(--gray-400)',
                                  fontStyle: 'italic',
                                  display: 'flex',
                                  alignItems: 'center',
                                  gap: '0.4rem',
                                }}
                              >
                                ⏳ Awaiting response from {batch.company}
                              </span>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>

      <div
        style={{
          marginTop: '2rem',
          padding: '1rem 1.25rem',
          borderRadius: '10px',
          background: 'var(--warning-50, #fffbeb)',
          border: '1px solid var(--warning-200, #fde68a)',
          display: 'flex',
          gap: '0.75rem',
          alignItems: 'flex-start',
        }}
      >
        <Lightbulb size={18} color="var(--warning-500, #f59e0b)" style={{ flexShrink: 0, marginTop: '2px' }} />
        <p style={{ margin: 0, fontSize: '0.875rem', color: 'var(--warning-800, #92400e)', lineHeight: '1.6' }}>
          <strong>College view:</strong> Browse and export threads only. Student questions and placement-office batches appear
          here for transparency; posting is done from the student or employer flows.
        </p>
      </div>
    </div>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS } from '@/lib/tableQueryPresets';
import { ExportCsvSplitButton } from '@/components/export/ExportCsvSplitButton';
import { HiringResultBreakdown } from '@/components/assessment/HiringResultBreakdown';
import { buildAssessmentSummary } from '@/lib/assessmentHiringViewShared';
import { useToast } from '@/components/ToastProvider';
import { downloadCsvFromApi } from '@/lib/downloadCsvFromApi';
import { pickRepresentativeAssessmentRows } from '@/lib/assessmentRowsDedupe';
import { COLLEGE_OFFERS_ALL_STUDENTS_CSV_FILENAME } from '@/lib/offersAssessmentStarterCsv';
import { ClipboardList, Users, Upload, Download } from 'lucide-react';

export default function CollegeHiringAssessmentPage() {
  const { addToast } = useToast();
  const [loading, setLoading] = useState(true);
  const [payload, setPayload] = useState(null);
  const [loadError, setLoadError] = useState('');

  useEffect(() => {
    let mounted = true;
    (async () => {
      setLoading(true);
      setLoadError('');
      try {
        const res = await fetch('/api/college/hiring-assessment-view');
        const json = await res.json();
        if (!res.ok) throw new Error(json?.error || 'Failed to load');
        if (!mounted) return;
        setPayload(json);
      } catch (e) {
        if (!mounted) return;
        setPayload(null);
        setLoadError(e?.message || 'Could not load assessment data');
      } finally {
        if (mounted) setLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
  }, []);

  const rows = Array.isArray(payload?.rows) ? payload.rows : [];
  const baseDisplayRows = useMemo(() => pickRepresentativeAssessmentRows(rows), [rows]);
  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered: displayRows,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(baseDisplayRows, {
    getSearchText: (r) =>
      [r.employer_company, r.original_file_name, r.roll_number, r.candidate_name, r.remarks].filter(Boolean).join(' '),
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'name_asc',
  });
  const summary = payload?.summary || buildAssessmentSummary(rows);

  const getCsv = useCallback(
    (_scope) => ({
      headers: [
        'employer_company',
        'upload_file',
        'upload_at',
        'roll_number',
        'candidate_name',
        'hiring_result',
        'remarks',
      ],
      rows: displayRows.map((r) => [
        r.employer_company ?? '',
        r.original_file_name ?? '',
        r.upload_created_at ? new Date(r.upload_created_at).toISOString() : '',
        r.roll_number ?? '',
        r.candidate_name ?? '',
        r.hiring_result ?? '',
        r.remarks ?? '',
      ]),
    }),
    [displayRows],
  );

  const colCount = 6;

  const downloadOffersImportStarter = async () => {
    try {
      await downloadCsvFromApi('/api/college/offers/assessment-starter', COLLEGE_OFFERS_ALL_STUDENTS_CSV_FILENAME);
      addToast('CSV includes every campus master-list student (company prefilled from newest assessment when available).', 'success');
    } catch (e) {
      addToast(e.message || 'Download failed', 'error');
    }
  };

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      {/* Glassmorphic Hero */}
      <div style={{
        position: 'relative', background: 'var(--banner-gradient)',
        borderRadius: 'var(--radius-xl)', padding: '2.5rem', color: 'white', overflow: 'hidden',
        marginBottom: '2rem', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)',
        display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1.5rem'
      }}>
        <div style={{ position: 'absolute', top: '-50px', right: '-50px', width: '250px', height: '250px', background: 'radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%)', borderRadius: '50%' }} />
        <div style={{ position: 'relative', zIndex: 1 }}>
          <h1 style={{ color: '#ffffff', fontSize: '2.25rem', fontWeight: 800, margin: '0 0 0.5rem', letterSpacing: '-0.02em', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <ClipboardList size={28} /> Hiring Assessment
          </h1>
          <p style={{ fontSize: '1rem', color: 'rgba(255,255,255,0.85)', margin: 0 }}>Read-only view of employer CSV uploads for your campus. Export for spreadsheets.</p>
        </div>
        <div style={{ position: 'relative', zIndex: 1, display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
          <button type="button" className="btn" onClick={downloadOffersImportStarter} style={{ background: 'rgba(255,255,255,0.15)', color: 'white', border: '1px solid rgba(255,255,255,0.2)', backdropFilter: 'blur(10px)', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Download size={16} /> All Students Template
          </button>
          <ExportCsvSplitButton filenameBase="hiring_assessment_college_view" currentCount={displayRows.length} fullCount={displayRows.length} getRows={getCsv} />
        </div>
      </div>

      {loading ? (
        <div className="skeleton skeleton-card" style={{ height: 200 }} />
      ) : loadError ? (
        <div className="card" style={{ padding: '1.25rem', borderColor: 'var(--danger-200)', background: 'var(--danger-50)' }}>
          <p style={{ margin: 0, color: 'var(--danger-700)', fontWeight: 600 }}>{loadError}</p>
          <p style={{ margin: '0.5rem 0 0', fontSize: '0.875rem', color: 'var(--text-secondary)' }}>
            If this mentions missing tables, apply migration <code>013_audit_exports_and_assessment_uploads.sql</code> on production.
          </p>
        </div>
      ) : (
        <>
          <div className="grid grid-3" style={{ marginBottom: '1.5rem' }}>
            {[
              { label: 'Total Students', value: summary.uniqueStudentCount ?? 0, sub: summary.totalResultRows > 0 ? `${summary.totalResultRows} upload row(s)` : null, icon: Users, color: 'var(--primary-600)', bg: 'var(--primary-50)' },
              { label: 'Upload Batches', value: summary.uploadsCount, sub: null, icon: Upload, color: 'var(--info-600)', bg: 'rgba(2,132,199,0.08)' },
              { label: 'With hiring result', value: summary.withHiringResult ?? 0, sub: summary.withoutHiringResult ? `${summary.withoutHiringResult} pending` : null, icon: ClipboardList, color: 'var(--warning-600)', bg: 'rgba(217,119,6,0.08)' },
            ].map(({ label, value, sub, icon: Icon, color, bg }) => (
              <div key={label} className="card" style={{ padding: '1.5rem', border: '1px solid var(--border-default)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1rem' }}>
                  <div style={{ padding: '0.5rem', borderRadius: 'var(--radius-md)', background: bg, color }}><Icon size={20} strokeWidth={2} /></div>
                </div>
                <div style={{ fontSize: '2rem', fontWeight: 800, color: 'var(--text-primary)', lineHeight: 1 }}>{value}</div>
                <div style={{ fontSize: '0.875rem', color: 'var(--text-secondary)', marginTop: '0.5rem', fontWeight: 500 }}>{label}</div>
                {sub && <div style={{ fontSize: '0.75rem', color: 'var(--text-tertiary)', marginTop: '0.25rem' }}>{sub}</div>}
              </div>
            ))}
          </div>

          <HiringResultBreakdown summary={summary} />

          <div className="card">
            <p className="text-xs text-secondary" style={{ marginBottom: '0.75rem', lineHeight: 1.5 }}>
              <strong>Detail (read-only).</strong> One row per student; if the same roll appears in multiple assessment files, the <strong>most recent upload</strong>{' '}
              determines what you see here (older batches remain stored). <strong>Candidate</strong> is the name from your campus student master list for that roll (then
              email, then roll). CSV placeholders like &quot;Student_1&quot; are not shown here.
            </p>
            {totalCount > 0 ? (
              <DataTableToolbar
                search={search}
                onSearchChange={setSearch}
                searchPlaceholder="Search employer, roll, or candidate…"
                sort={sort}
                onSortChange={setSort}
                sortOptions={COMMON_SORT_OPTIONS}
                filteredCount={filteredCount}
                totalCount={totalCount}
                hasActiveFilters={hasActiveFilters}
                onClear={clearFilters}
                style={{ marginBottom: '1rem' }}
              />
            ) : null}
            <div className="table-container" style={{ overflowX: 'auto', border: 'none' }}>
              <table className="data-table" style={{ minWidth: 960 }}>
                <thead>
                  <tr>
                    <th>Employer</th>
                    <th>File</th>
                    <th>Roll</th>
                    <th>Candidate</th>
                    <th>Hiring result</th>
                    <th>Remarks</th>
                  </tr>
                </thead>
                <tbody>
                  {displayRows.length === 0 && totalCount > 0 ? (
                    <tr>
                      <td colSpan={colCount} className="text-center text-secondary">
                        No rows match your search.
                      </td>
                    </tr>
                  ) : null}
                  {displayRows.map((r) => (
                    <tr key={r.id}>
                      <td className="text-sm">{r.employer_company || '—'}</td>
                      <td className="text-xs">{r.original_file_name || '—'}</td>
                      <td className="text-sm font-mono">{r.roll_number}</td>
                      <td className="text-sm">{r.candidate_name || '—'}</td>
                      <td className="text-sm">{r.hiring_result || '—'}</td>
                      <td className="text-sm" style={{ maxWidth: 220 }}>
                        {r.remarks || '—'}
                      </td>
                    </tr>
                  ))}
                  {totalCount === 0 ? (
                    <tr>
                      <td colSpan={colCount} className="text-center text-secondary">
                        No assessment upload rows for your campus yet. When employers submit CSV results, they will appear here.
                      </td>
                    </tr>
                  ) : null}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

'use client';
import { useEffect, useMemo, useState } from 'react';
import MobileHeader from '@/components/mobile/MobileHeader';
import { useToast } from '@/components/ToastProvider';
import { downloadCsvFromApi } from '@/lib/downloadCsvFromApi';
import { pickRepresentativeAssessmentRows } from '@/lib/assessmentRowsDedupe';
import { buildAssessmentSummary } from '@/lib/assessmentHiringViewShared';
import { COLLEGE_OFFERS_ALL_STUDENTS_CSV_FILENAME } from '@/lib/offersAssessmentStarterCsv';
import { ClipboardList, Users, Upload, Download, Search, Building2 } from 'lucide-react';
import { HiringResultBreakdown } from '@/components/assessment/HiringResultBreakdown';

export default function mb_HiringAssessment() {
  const { addToast } = useToast();
  const [loading, setLoading] = useState(true);
  const [payload, setPayload] = useState(null);
  const [loadError, setLoadError] = useState('');
  const [activeTab, setActiveTab] = useState('overview');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    let mounted = true;
    (async () => {
      setLoading(true);
      setLoadError('');
      try {
        const res = await fetch('/api/college/hiring-assessment-view');
        const json = await res.json();
        if (!res.ok) throw new Error(json?.error || 'Failed to load');
        if (!mounted) return;
        setPayload(json);
      } catch (e) {
        if (!mounted) return;
        setPayload(null);
        setLoadError(e?.message || 'Could not load assessment data');
      } finally {
        if (mounted) setLoading(false);
      }
    })();
    return () => { mounted = false; };
  }, []);

  const rows = Array.isArray(payload?.rows) ? payload.rows : [];
  const displayRows = useMemo(() => pickRepresentativeAssessmentRows(rows), [rows]);

  const filteredRows = useMemo(() => {
    const q = searchQuery.toLowerCase().trim();
    if (!q) return displayRows.slice(0, 50);
    return displayRows.filter(r =>
      (r.candidate_name && r.candidate_name.toLowerCase().includes(q)) ||
      (r.roll_number && r.roll_number.toLowerCase().includes(q)) ||
      (r.employer_company && r.employer_company.toLowerCase().includes(q))
    ).slice(0, 50);
  }, [displayRows, searchQuery]);

  const summary = payload?.summary || buildAssessmentSummary(rows);

  const downloadOffersImportStarter = async () => {
    try {
      await downloadCsvFromApi('/api/college/offers/assessment-starter', COLLEGE_OFFERS_ALL_STUDENTS_CSV_FILENAME);
      addToast('Template downloaded successfully.', 'success');
    } catch (e) {
      addToast(e.message || 'Download failed', 'error');
    }
  };

  const tabs = [
    { id: 'overview', label: 'Overview' },
    { id: 'results', label: 'Results' },
    { id: 'students', label: 'Students' }
  ];

  return (
    <>
      <MobileHeader
        title="Hiring Assessment"
        action={
          <button className="btn btn-ghost btn-sm" onClick={downloadOffersImportStarter} style={{ padding: '0.4rem', color: 'var(--primary-600)' }}>
            <Download size={18} />
          </button>
        }
      />
      <div className="animate-fadeIn" style={{ padding: '1rem 1rem 5rem 1rem' }}>

        <div style={{ display: 'flex', gap: '0.25rem', marginBottom: '1.25rem', background: 'var(--bg-secondary)', padding: '0.25rem', borderRadius: '12px', border: '1px solid var(--border-default)' }}>
          {tabs.map(({ id, label }) => (
            <button
              key={id}
              type="button"
              onClick={() => setActiveTab(id)}
              style={{ flex: 1, padding: '0.65rem 0', borderRadius: '8px', border: 'none', background: activeTab === id ? 'var(--primary-600)' : 'transparent', color: activeTab === id ? 'white' : 'var(--text-secondary)', fontWeight: activeTab === id ? 700 : 500, cursor: 'pointer', fontSize: '0.85rem', transition: 'all 0.2s' }}
            >
              {label}
            </button>
          ))}
        </div>

        {loading ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            <div className="skeleton" style={{ height: 100, borderRadius: '12px' }} />
            <div className="skeleton" style={{ height: 100, borderRadius: '12px' }} />
            <div className="skeleton" style={{ height: 100, borderRadius: '12px' }} />
          </div>
        ) : loadError ? (
          <div className="card" style={{ padding: '1rem', borderColor: 'var(--danger-200)', background: 'var(--danger-50)' }}>
            <p style={{ margin: 0, color: 'var(--danger-700)', fontWeight: 600, fontSize: '0.9rem' }}>{loadError}</p>
          </div>
        ) : (
          <>
            {activeTab === 'overview' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                <div className="card" style={{ padding: '1rem', display: 'flex', alignItems: 'center', gap: '1rem' }}>
                  <div style={{ padding: '0.75rem', borderRadius: '50%', background: 'var(--primary-50)', color: 'var(--primary-600)' }}>
                    <Users size={24} />
                  </div>
                  <div>
                    <div style={{ fontSize: '1.5rem', fontWeight: 800, color: 'var(--text-primary)', lineHeight: 1 }}>{summary.uniqueStudentCount ?? 0}</div>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginTop: '0.25rem', fontWeight: 600 }}>Total Students</div>
                    {summary.totalResultRows > 0 && <div style={{ fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>{summary.totalResultRows} upload row(s)</div>}
                  </div>
                </div>

                <div className="card" style={{ padding: '1rem', display: 'flex', alignItems: 'center', gap: '1rem' }}>
                  <div style={{ padding: '0.75rem', borderRadius: '50%', background: 'rgba(2,132,199,0.08)', color: 'var(--info-600)' }}>
                    <Upload size={24} />
                  </div>
                  <div>
                    <div style={{ fontSize: '1.5rem', fontWeight: 800, color: 'var(--text-primary)', lineHeight: 1 }}>{summary.uploadsCount}</div>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginTop: '0.25rem', fontWeight: 600 }}>Upload Batches</div>
                  </div>
                </div>

                <div className="card" style={{ padding: '1rem', display: 'flex', alignItems: 'center', gap: '1rem' }}>
                  <div style={{ padding: '0.75rem', borderRadius: '50%', background: 'rgba(217,119,6,0.08)', color: 'var(--warning-600)' }}>
                    <ClipboardList size={24} />
                  </div>
                  <div>
                    <div style={{ fontSize: '1.5rem', fontWeight: 800, color: 'var(--text-primary)', lineHeight: 1 }}>{summary.withHiringResult ?? 0}</div>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginTop: '0.25rem', fontWeight: 600 }}>With hiring result</div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'results' && (
              <div style={{ overflowX: 'auto', paddingBottom: '0.5rem' }}>
                <HiringResultBreakdown summary={summary} />
              </div>
            )}

            {activeTab === 'students' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                <div style={{ position: 'relative' }}>
                  <Search size={16} style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-tertiary)' }} />
                  <input
                    className="form-input"
                    placeholder="Search name, roll, or company..."
                    value={searchQuery}
                    onChange={e => setSearchQuery(e.target.value)}
                    style={{ paddingLeft: '2.5rem', borderRadius: '999px', background: 'var(--surface)' }}
                  />
                </div>

                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                  {filteredRows.map((r) => {
                    const result = String(r.hiring_result || '').trim() || 'No decision';
                    const lk = result.toLowerCase();
                    const isSuccess = lk.includes('select') || lk.includes('shortlist');
                    const isFail = lk.includes('reject') || lk.includes('decline') || lk.includes('withdraw');
                    const badgeClass = isSuccess ? 'badge-success' : isFail ? 'badge-danger' : 'badge-primary';

                    return (
                      <div key={r.id} className="card" style={{ padding: '1rem' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.5rem' }}>
                          <div>
                            <div style={{ fontWeight: 600, fontSize: '0.95rem', color: 'var(--text-primary)' }}>{r.candidate_name || '—'}</div>
                            <div style={{ fontSize: '0.75rem', color: 'var(--text-tertiary)', fontFamily: 'monospace' }}>{r.roll_number}</div>
                          </div>
                          <span className={`badge ${badgeClass}`} style={{ fontSize: '0.65rem' }}>
                            {result}
                          </span>
                        </div>

                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.8rem', color: 'var(--text-secondary)', marginBottom: '0.5rem' }}>
                          <Building2 size={12} style={{ opacity: 0.7 }} />
                          <span style={{ fontWeight: 500 }}>{r.employer_company || '—'}</span>
                        </div>

                        {r.remarks && (
                          <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', background: 'var(--bg-secondary)', padding: '0.5rem', borderRadius: '4px', marginTop: '0.5rem' }}>
                            <span style={{ fontWeight: 600 }}>Remarks:</span> {r.remarks}
                          </div>
                        )}

                        <div style={{ marginTop: '0.5rem', paddingTop: '0.5rem', borderTop: '1px solid var(--border-default)', fontSize: '0.7rem', color: 'var(--text-tertiary)', textAlign: 'right' }}>
                          From: {r.original_file_name || '—'}
                        </div>
                      </div>
                    );
                  })}
                  {filteredRows.length === 0 && (
                    <div style={{ textAlign: 'center', padding: '2rem', color: 'var(--text-tertiary)' }}>
                      No assessment records found.
                    </div>
                  )}
                  {filteredRows.length === 50 && (
                    <div style={{ textAlign: 'center', fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>
                      Showing first 50 results. Use search to find specific students.
                    </div>
                  )}
                </div>
              </div>
            )}
          </>
        )}

      </div>
    </>
  );
}

'use client';

import { useMemo } from 'react';
import useSWR from 'swr';
import { MessageSquareText } from 'lucide-react';
import PageLoading from '@/components/PageLoading';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { SORT_DATE_ASC, SORT_DATE_DESC } from '@/lib/dataTableQuery';
import { formatDate, formatStatus } from '@/lib/utils';

const FEEDBACK_SORT_OPTIONS = [
  {
    value: 'name_asc',
    label: 'Student (A → Z)',
    compare: (a, b) =>
      String(a?.studentName ?? '').localeCompare(String(b?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  {
    value: 'name_desc',
    label: 'Student (Z → A)',
    compare: (a, b) =>
      String(b?.studentName ?? '').localeCompare(String(a?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  SORT_DATE_DESC,
  SORT_DATE_ASC,
];

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load');
  return json;
};

export default function CollegeInternshipFeedbackPage() {
  const { data, error, isLoading } = useSWR('/api/college/internship-feedback', fetcher);
  const items = Array.isArray(data?.items) ? data.items : [];
  const summary = data?.summary || { total: 0, withStudentFeedback: 0, withEmployerFeedback: 0 };

  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(items, {
    getSearchText: (r) =>
      [r.studentName, r.rollNumber, r.branch, r.companyName, r.openingTitle, r.studentFeedback?.feedbackText, r.employerFeedback?.feedbackText]
        .filter(Boolean)
        .join(' '),
    sortOptions: FEEDBACK_SORT_OPTIONS,
    defaultSort: 'date_desc',
  });

  const exportCsv = () => {
    const header = [
      'Student',
      'Roll',
      'Branch',
      'Batch',
      'Company',
      'Internship',
      'Status',
      'Student_rating',
      'Student_feedback',
      'Employer_rating',
      'Employer_feedback',
    ];
    const rows = filtered.map((r) => [
      r.studentName,
      r.rollNumber,
      r.branch,
      r.batchYear != null ? String(r.batchYear) : '',
      r.companyName,
      r.openingTitle,
      formatStatus(r.applicationStatus),
      r.studentFeedback?.rating != null ? String(r.studentFeedback.rating) : '',
      r.studentFeedback?.feedbackText || '',
      r.employerFeedback?.rating != null ? String(r.employerFeedback.rating) : '',
      r.employerFeedback?.feedbackText || '',
    ]);
    const csv = [header, ...rows]
      .map((line) => line.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(','))
      .join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'internship_progress_reviews.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const statLine = useMemo(
    () =>
      `${summary.withStudentFeedback} student · ${summary.withEmployerFeedback} employer submission(s) on ${summary.total} record(s)`,
    [summary],
  );

  if (isLoading) return <PageLoading message="Loading progress reviews…" variant="skeleton-card" />;

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      <div className="page-header" style={{ marginBottom: '1.5rem' }}>
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: 0 }}>
            <MessageSquareText size={26} aria-hidden />
            Internship Progress Reviews
          </h1>
          <p className="text-secondary" style={{ margin: '0.35rem 0 0', lineHeight: 1.55 }}>
            Read-only view of student and employer progress reviews for selected / in-progress internships on your campus.
          </p>
          <p className="text-sm text-tertiary" style={{ margin: '0.35rem 0 0' }}>{statLine}</p>
        </div>
        <div className="page-header-actions">
          <button type="button" className="btn btn-secondary btn-sm" onClick={exportCsv} disabled={!filtered.length}>
            Export CSV
          </button>
        </div>
      </div>

      {error ? (
        <div className="card" style={{ padding: '1.5rem', color: 'var(--danger-600)' }}>{error.message}</div>
      ) : null}

      <DataTableToolbar
        search={search}
        onSearchChange={setSearch}
        sort={sort}
        onSortChange={setSort}
        sortOptions={FEEDBACK_SORT_OPTIONS}
        filteredCount={filteredCount}
        totalCount={totalCount}
        hasActiveFilters={hasActiveFilters}
        onClearFilters={clearFilters}
      />

      <div className="card table-container">
        <div className="table-scroll">
          <table className="data-table">
            <thead>
              <tr>
                <th>Student</th>
                <th>Branch</th>
                <th>Company / Internship</th>
                <th>Student</th>
                <th>Employer</th>
                <th>Updated</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((row) => {
                const updated =
                  row.studentFeedback?.updatedAt || row.employerFeedback?.updatedAt || null;
                return (
                  <tr key={row.programApplicationId}>
                    <td>
                      <div style={{ fontWeight: 600 }}>{row.studentName}</div>
                      <div className="text-xs text-secondary">{row.rollNumber}</div>
                    </td>
                    <td>{row.branch}</td>
                    <td>
                      <div>{row.companyName}</div>
                      <div className="text-xs text-secondary">{row.openingTitle}</div>
                    </td>
                    <td style={{ maxWidth: '280px', whiteSpace: 'pre-wrap', fontSize: '0.875rem' }}>
                      {row.studentFeedback ? (
                        <>
                          {row.studentFeedback.rating ? `${row.studentFeedback.rating}/5 · ` : ''}
                          {row.studentFeedback.feedbackText}
                        </>
                      ) : (
                        '—'
                      )}
                    </td>
                    <td style={{ maxWidth: '280px', whiteSpace: 'pre-wrap', fontSize: '0.875rem' }}>
                      {row.employerFeedback ? (
                        <>
                          {row.employerFeedback.rating ? `${row.employerFeedback.rating}/5 · ` : ''}
                          {row.employerFeedback.feedbackText}
                        </>
                      ) : (
                        '—'
                      )}
                    </td>
                    <td>{updated ? formatDate(updated) : '—'}</td>
                  </tr>
                );
              })}
              {!error && filtered.length === 0 ? (
                <tr>
                  <td colSpan={6} style={{ textAlign: 'center', padding: '2.5rem', color: 'var(--text-secondary)' }}>
                    No progress reviews submitted yet.
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import useSWR from 'swr';
import { UserRoundSearch } from 'lucide-react';
import PageLoading from '@/components/PageLoading';
import DataTableToolbar from '@/components/DataTableToolbar';
import InternshipGuideForm from '@/components/internship/InternshipGuideForm';
import InternshipSupervisorForm from '@/components/internship/InternshipSupervisorForm';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { SORT_DATE_ASC, SORT_DATE_DESC } from '@/lib/dataTableQuery';
import { useToast } from '@/components/ToastProvider';
import { formatDate, formatStatus } from '@/lib/utils';

const GUIDE_SORT_OPTIONS = [
  {
    value: 'name_asc',
    label: 'Student (A → Z)',
    compare: (a, b) =>
      String(a?.studentName ?? '').localeCompare(String(b?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  {
    value: 'name_desc',
    label: 'Student (Z → A)',
    compare: (a, b) =>
      String(b?.studentName ?? '').localeCompare(String(a?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  SORT_DATE_DESC,
  SORT_DATE_ASC,
];

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load');
  return json;
};

export default function CollegeInternshipGuidesPage() {
  const { addToast } = useToast();
  const { data, error, isLoading, mutate } = useSWR('/api/college/internship-guides', fetcher);
  const [savingId, setSavingId] = useState(null);
  const [editingId, setEditingId] = useState(null);

  const items = Array.isArray(data?.items) ? data.items : [];
  const summary = data?.summary || { total: 0, withGuide: 0 };

  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(items, {
    getSearchText: (r) =>
      [
        r.studentName,
        r.rollNumber,
        r.branch,
        r.companyName,
        r.openingTitle,
        r.guide?.guideName,
        r.guide?.guideEmail,
        r.guide?.guideDepartment,
      ]
        .filter(Boolean)
        .join(' '),
    sortOptions: GUIDE_SORT_OPTIONS,
    defaultSort: 'name_asc',
  });

  const saveGuide = async (programApplicationId, payload) => {
    setSavingId(programApplicationId);
    try {
      const res = await fetch('/api/college/internship-guides', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ programApplicationId, ...payload }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Save failed');
      addToast('Internship guide saved.', 'success');
      setEditingId(null);
      await mutate();
    } catch (e) {
      addToast(e.message || 'Save failed', 'error');
    } finally {
      setSavingId(null);
    }
  };

  const clearGuide = async (programApplicationId) => {
    setSavingId(programApplicationId);
    try {
      const res = await fetch('/api/college/internship-guides', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ programApplicationId, clear: true }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Remove failed');
      addToast('Guide removed.', 'success');
      setEditingId(null);
      await mutate();
    } catch (e) {
      addToast(e.message || 'Remove failed', 'error');
    } finally {
      setSavingId(null);
    }
  };

  const exportCsv = () => {
    const header = [
      'Student',
      'Roll',
      'Branch',
      'Batch',
      'Company',
      'Internship',
      'Status',
      'Guide_name',
      'Guide_department',
      'Guide_email',
      'Guide_phone',
      'Guide_notes',
      'Supervisor_name',
      'Supervisor_team',
      'Supervisor_email',
    ];
    const rows = filtered.map((r) => [
      r.studentName,
      r.rollNumber,
      r.branch,
      r.batchYear != null ? String(r.batchYear) : '',
      r.companyName,
      r.openingTitle,
      formatStatus(r.applicationStatus),
      r.guide?.guideName || '',
      r.guide?.guideDepartment || '',
      r.guide?.guideEmail || '',
      r.guide?.guidePhone || '',
      r.guide?.guideNotes || '',
      r.supervisor?.supervisorName || '',
      r.supervisor?.supervisorTeam || '',
      r.supervisor?.supervisorEmail || '',
    ]);
    const csv = [header, ...rows]
      .map((line) => line.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(','))
      .join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'internship_guides.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const statLine = useMemo(
    () => `${summary.withGuide} of ${summary.total} selected / in-progress intern(s) have a guide assigned`,
    [summary],
  );

  if (isLoading) return <PageLoading message="Loading interns…" variant="skeleton-card" />;

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      <div className="page-header" style={{ marginBottom: '1.5rem' }}>
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: 0 }}>
            <UserRoundSearch size={26} aria-hidden />
            Internship guides
          </h1>
          <p className="text-secondary" style={{ margin: '0.35rem 0 0', lineHeight: 1.55 }}>
            Assign a campus faculty or TPO guide for each intern. Students see guide contact details on their
            Internship Progress Reviews page.
          </p>
          <p className="text-sm text-tertiary" style={{ margin: '0.35rem 0 0' }}>{statLine}</p>
        </div>
        <div className="page-header-actions">
          <button type="button" className="btn btn-secondary btn-sm" onClick={exportCsv} disabled={!filtered.length}>
            Export CSV
          </button>
        </div>
      </div>

      {error ? (
        <div className="card" style={{ padding: '1.5rem', color: 'var(--danger-600)' }}>{error.message}</div>
      ) : null}

      <DataTableToolbar
        search={search}
        onSearchChange={setSearch}
        sort={sort}
        onSortChange={setSort}
        sortOptions={GUIDE_SORT_OPTIONS}
        filteredCount={filteredCount}
        totalCount={totalCount}
        hasActiveFilters={hasActiveFilters}
        onClearFilters={clearFilters}
      />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        {filtered.map((row) => {
          const isEditing = editingId === row.programApplicationId;
          const isSaving = savingId === row.programApplicationId;
          return (
            <div key={row.programApplicationId} className="card" style={{ padding: '1.25rem' }}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '1rem',
                  flexWrap: 'wrap',
                  marginBottom: isEditing || !row.guide ? '0.75rem' : 0,
                }}
              >
                <div>
                  <div style={{ fontWeight: 600 }}>{row.studentName}</div>
                  <div className="text-sm text-secondary">
                    {row.rollNumber} · {row.branch}
                  </div>
                  <div className="text-sm" style={{ marginTop: '0.35rem' }}>
                    {row.companyName} — {row.openingTitle}
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: '0.5rem', flexWrap: 'wrap' }}>
                  <span className={`badge badge-${row.applicationStatus === 'selected' ? 'green' : 'amber'} badge-dot`}>
                    {formatStatus(row.applicationStatus)}
                  </span>
                  {!isEditing ? (
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm"
                      onClick={() => setEditingId(row.programApplicationId)}
                    >
                      {row.guide ? 'Edit guide' : 'Assign guide'}
                    </button>
                  ) : (
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      disabled={isSaving}
                      onClick={() => setEditingId(null)}
                    >
                      Cancel
                    </button>
                  )}
                </div>
              </div>

              {!isEditing && row.guide ? (
                <div style={{ marginTop: '0.75rem', paddingTop: '0.75rem', borderTop: '1px solid var(--border-subtle)' }}>
                  <p className="text-xs text-tertiary" style={{ margin: '0 0 0.35rem', fontWeight: 600, letterSpacing: '0.04em' }}>
                    CAMPUS GUIDE
                  </p>
                  <InternshipGuideForm initialGuide={row.guide} readOnly />
                  {row.guide.updatedAt ? (
                    <p className="text-xs text-tertiary" style={{ margin: '0.5rem 0 0' }}>
                      Updated {formatDate(row.guide.updatedAt)}
                    </p>
                  ) : null}
                </div>
              ) : null}

              {!isEditing && row.supervisor ? (
                <div style={{ marginTop: '0.75rem', paddingTop: '0.75rem', borderTop: '1px solid var(--border-subtle)' }}>
                  <p className="text-xs text-tertiary" style={{ margin: '0 0 0.35rem', fontWeight: 600, letterSpacing: '0.04em' }}>
                    COMPANY SUPERVISOR
                  </p>
                  <InternshipSupervisorForm initialSupervisor={row.supervisor} readOnly />
                </div>
              ) : null}

              {isEditing ? (
                <InternshipGuideForm
                  initialGuide={row.guide}
                  saving={isSaving}
                  onSubmit={(payload) => saveGuide(row.programApplicationId, payload)}
                  onClear={row.guide ? () => clearGuide(row.programApplicationId) : null}
                />
              ) : null}
            </div>
          );
        })}

        {!error && filtered.length === 0 ? (
          <div className="card" style={{ padding: '2.5rem', textAlign: 'center', color: 'var(--text-secondary)' }}>
            No selected or in-progress internships on your campus yet.
          </div>
        ) : null}
      </div>
    </div>
  );
}

'use client';

import { useMemo } from 'react';
import useSWR from 'swr';
import { Award } from 'lucide-react';
import PageLoading from '@/components/PageLoading';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { SORT_DATE_ASC, SORT_DATE_DESC } from '@/lib/dataTableQuery';
import { formatDate, formatStatus } from '@/lib/utils';

const PPO_SORT_OPTIONS = [
  {
    value: 'name_asc',
    label: 'Student (A → Z)',
    compare: (a, b) =>
      String(a?.studentName ?? '').localeCompare(String(b?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  {
    value: 'name_desc',
    label: 'Student (Z → A)',
    compare: (a, b) =>
      String(b?.studentName ?? '').localeCompare(String(a?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  SORT_DATE_DESC,
  SORT_DATE_ASC,
];

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load');
  return json;
};

export default function CollegeInternshipPpoPage() {
  const { data, error, isLoading } = useSWR('/api/college/internship-ppo', fetcher);

  const items = Array.isArray(data?.items) ? data.items : [];
  const summary = data?.summary || { total: 0, awaitingStudent: 0, accepted: 0, withJobOffer: 0 };

  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(items, {
    getSearchText: (r) =>
      [r.studentName, r.rollNumber, r.branch, r.companyName, r.openingTitle, r.ppoStatusLabel]
        .filter(Boolean)
        .join(' '),
    sortOptions: PPO_SORT_OPTIONS,
    defaultSort: 'name_asc',
  });

  const exportCsv = () => {
    const header = [
      'Student',
      'Roll',
      'Branch',
      'Batch',
      'Company',
      'Internship',
      'Internship_start',
      'Application_status',
      'PPO_status',
      'PPO_confirmed',
      'Student_responded',
      'Job_offer_status',
    ];
    const rows = filtered.map((r) => [
      r.studentName,
      r.rollNumber,
      r.branch,
      r.batchYear ?? '',
      r.companyName,
      r.openingTitle,
      r.internshipStartDate ? formatDate(r.internshipStartDate) : '',
      formatStatus(r.applicationStatus),
      r.ppoStatusLabel,
      r.ppo?.confirmedAt ? formatDate(r.ppo.confirmedAt) : '',
      r.ppo?.studentRespondedAt ? formatDate(r.ppo.studentRespondedAt) : '',
      r.jobOfferStatus ? formatStatus(r.jobOfferStatus) : '',
    ]);
    const csv = [header, ...rows]
      .map((line) => line.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(','))
      .join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'internship_ppo.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const statLine = useMemo(
    () =>
      `${summary.total} PPO record(s) · ${summary.awaitingStudent} awaiting student · ${summary.withJobOffer} with job offer`,
    [summary],
  );

  if (isLoading) return <PageLoading message="Loading PPO…" variant="skeleton-card" />;

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      <div className="page-header" style={{ marginBottom: '1.5rem' }}>
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: 0 }}>
            <Award size={26} aria-hidden />
            Internship PPO
          </h1>
          <p className="text-secondary" style={{ margin: '0.35rem 0 0', lineHeight: 1.55 }}>
            Read-only view of Pre-Placement Offers for interns on your campus. PPO is separate from internship selection
            and formal job offers.
          </p>
          <p className="text-sm text-tertiary" style={{ margin: '0.35rem 0 0' }}>{statLine}</p>
        </div>
        <div className="page-header-actions">
          <button type="button" className="btn btn-secondary btn-sm" onClick={exportCsv} disabled={!filtered.length}>
            Export CSV
          </button>
        </div>
      </div>

      {error ? (
        <div className="card" style={{ padding: '1.5rem', color: 'var(--danger-600)' }}>{error.message}</div>
      ) : null}

      <DataTableToolbar
        search={search}
        onSearchChange={setSearch}
        sort={sort}
        onSortChange={setSort}
        sortOptions={PPO_SORT_OPTIONS}
        filteredCount={filteredCount}
        totalCount={totalCount}
        hasActiveFilters={hasActiveFilters}
        onClearFilters={clearFilters}
      />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        {filtered.map((row) => (
          <div key={row.programApplicationId} className="card" style={{ padding: '1.25rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', gap: '1rem', flexWrap: 'wrap' }}>
              <div>
                <div style={{ fontWeight: 600 }}>{row.studentName}</div>
                <div className="text-sm text-secondary">
                  {row.rollNumber} · {row.branch}
                  {row.batchYear ? ` · Batch ${row.batchYear}` : ''}
                </div>
                <div className="text-sm" style={{ marginTop: '0.35rem' }}>
                  {row.companyName} — {row.openingTitle}
                </div>
              </div>
              <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', alignItems: 'flex-start' }}>
                <span className="badge badge-blue badge-dot">{row.ppoStatusLabel}</span>
                {row.jobOfferStatus ? (
                  <span className="badge badge-green badge-dot">Offer: {formatStatus(row.jobOfferStatus)}</span>
                ) : null}
              </div>
            </div>
            {row.ppo?.confirmedAt ? (
              <p className="text-xs text-tertiary" style={{ margin: '0.5rem 0 0' }}>
                PPO confirmed {formatDate(row.ppo.confirmedAt)}
                {row.ppo.studentRespondedAt ? ` · Student responded ${formatDate(row.ppo.studentRespondedAt)}` : ''}
              </p>
            ) : null}
          </div>
        ))}

        {!error && filtered.length === 0 ? (
          <div className="card" style={{ padding: '2.5rem', textAlign: 'center', color: 'var(--text-secondary)' }}>
            No PPO records yet for your campus interns.
          </div>
        ) : null}
      </div>
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import useSWR from 'swr';
import { BookOpen, Calendar, GraduationCap, IndianRupee, LayoutGrid, List } from 'lucide-react';
import { formatCurrency, formatDate } from '@/lib/utils';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS, FILTER_ALL } from '@/lib/tableQueryPresets';
import CompanyNameLink from '@/components/CompanyNameLink';
import PageLoading from '@/components/PageLoading';
import { useToast } from '@/components/ToastProvider';
import InternshipDetailModal from './InternshipDetailModal';
import InternshipListingActions from './InternshipListingActions';
import {
  computeInternshipStats,
  getCollegeStatusMeta,
  getJobTypeMeta,
  stipendLabel,
} from './internshipRowUtils';

const fetcher = (url) => fetch(url).then((r) => r.json());

const TYPE_FILTER_OPTIONS = [
  FILTER_ALL,
  { value: 'internship', label: 'Internship' },
  { value: 'short_project', label: 'Short project' },
  { value: 'hackathon', label: 'Hackathon' },
];

const APPROVAL_FILTER_OPTIONS = [
  FILTER_ALL,
  { value: 'pending', label: 'Pending review' },
  { value: 'approved', label: 'Approved' },
  { value: 'rejected', label: 'Rejected' },
];

const TABLE_COLUMNS = [
  'Title',
  'Employer',
  'Type',
  'Stipend',
  'CGPA',
  'Openings',
  'Posted',
  'Campus',
  'Actions',
];

export default function CollegeInternshipsContent() {
  const { addToast } = useToast();
  const { data, error, isLoading, mutate } = useSWR('/api/college/internships', fetcher);
  const [viewMode, setViewMode] = useState('card');
  const [viewRow, setViewRow] = useState(null);
  const [approvalFilter, setApprovalFilter] = useState('');
  const [actionBusyId, setActionBusyId] = useState(null);

  const list = Array.isArray(data?.internships) ? data.internships : [];
  const stats = useMemo(() => computeInternshipStats(list), [list]);

  const {
    search,
    setSearch,
    filter,
    setFilter,
    sort,
    setSort,
    filtered: searchedRows,
    filteredCount: searchedCount,
    totalCount,
    hasActiveFilters: hasSearchFilters,
    clearFilters: clearSearchFilters,
  } = useDataTableQuery(list, {
    getSearchText: (row) =>
      [
        row.title,
        row.company_name,
        row.description,
        ...(Array.isArray(row.skills_required) ? row.skills_required : []),
      ]
        .filter(Boolean)
        .join(' '),
    filterFn: (row, f) => !f || String(row.job_type || 'internship') === f,
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'date_desc',
  });

  const displayRows = useMemo(() => {
    if (!approvalFilter) return searchedRows;
    return searchedRows.filter((row) => String(row.college_status || 'pending') === approvalFilter);
  }, [searchedRows, approvalFilter]);

  const filteredCount = approvalFilter ? displayRows.length : searchedCount;
  const hasActiveFilters = hasSearchFilters || Boolean(approvalFilter);

  const clearFilters = () => {
    clearSearchFilters();
    setApprovalFilter('');
  };

  const reviewListing = async (jobId, action) => {
    setActionBusyId(jobId);
    try {
      const res = await fetch('/api/college/internships', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jobId, action }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || `Failed to ${action} listing`);
      await mutate();
      addToast(action === 'approve' ? 'Listing approved — students can now see it.' : 'Listing rejected.', action === 'approve' ? 'success' : 'info');
      setViewRow((current) => (current?.id === jobId ? null : current));
    } catch (e) {
      addToast(e.message || 'Action failed', 'error');
    } finally {
      setActionBusyId(null);
    }
  };

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '2rem' }}>
      <div className="page-header" style={{ marginBottom: '1.25rem' }}>
        <div className="page-header-left">
          <h1>Internships &amp; Programs</h1>
          <p>
            Review employer listings before they appear to students. Approve each posting for your campus after
            checking eligibility and stipend details.
          </p>
        </div>
      </div>

      {!isLoading && !error ? (
        <p
          className="text-sm text-secondary"
          style={{
            margin: '0 0 1.25rem',
            padding: '0.65rem 0.85rem',
            background: 'var(--bg-secondary)',
            border: '1px solid var(--border-default)',
            borderRadius: 'var(--radius-md)',
          }}
        >
          <strong style={{ color: 'var(--text-primary)' }}>{stats.count}</strong> listing
          {stats.count === 1 ? '' : 's'}
          {stats.pending ? (
            <>
              {' '}
              · <strong style={{ color: 'var(--warning-600, #d97706)' }}>{stats.pending}</strong> awaiting review
            </>
          ) : null}
          {stats.openings ? (
            <>
              {' '}
              · <strong style={{ color: 'var(--text-primary)' }}>{stats.openings}</strong> openings
            </>
          ) : null}
          {stats.avgStipend != null ? (
            <>
              {' '}
              · avg stipend <strong style={{ color: 'var(--text-primary)' }}>{formatCurrency(stats.avgStipend)}</strong>/mo
            </>
          ) : null}
        </p>
      ) : null}

      {error ? (
        <div className="card" style={{ borderColor: 'var(--danger-500)', marginBottom: '1rem' }}>
          <p className="text-sm" style={{ margin: 0 }}>
            Could not load internships. Ensure you are signed in as a college admin and migration{' '}
            <span className="font-mono text-xs">067</span> is applied.
          </p>
        </div>
      ) : null}

      {isLoading ? <PageLoading message="Loading internships…" inline /> : null}

      {!isLoading && !error && totalCount > 0 ? (
        <>
          <DataTableToolbar
            search={search}
            onSearchChange={setSearch}
            searchPlaceholder="Search title, employer, or skills…"
            filter={filter}
            onFilterChange={setFilter}
            filterOptions={TYPE_FILTER_OPTIONS}
            filterLabel="Type"
            sort={sort}
            onSortChange={setSort}
            sortOptions={COMMON_SORT_OPTIONS}
            filteredCount={filteredCount}
            totalCount={totalCount}
            hasActiveFilters={hasActiveFilters}
            onClear={clearFilters}
          />
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: '0.75rem',
              margin: '-0.5rem 0 1rem',
              flexWrap: 'wrap',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>
              <label className="text-sm text-secondary" htmlFor="college-listing-approval-filter">
                Campus status
              </label>
              <select
                id="college-listing-approval-filter"
                className="form-select"
                style={{ width: 'auto', minWidth: '10rem', padding: '0.5rem 2rem 0.5rem 0.75rem' }}
                value={approvalFilter}
                onChange={(e) => setApprovalFilter(e.target.value)}
              >
                {APPROVAL_FILTER_OPTIONS.map((opt) => (
                  <option key={opt.value || 'all'} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>
            <div
              role="group"
              aria-label="View mode"
              style={{
                display: 'flex',
                background: 'var(--bg-secondary)',
                borderRadius: '10px',
                padding: '3px',
                gap: '2px',
                border: '1px solid var(--border-default)',
              }}
            >
              {[
                { mode: 'card', icon: LayoutGrid, label: 'Card view' },
                { mode: 'list', icon: List, label: 'List view' },
              ].map(({ mode, icon: Icon, label }) => (
                <button
                  key={mode}
                  type="button"
                  title={label}
                  aria-label={label}
                  aria-pressed={viewMode === mode}
                  onClick={() => setViewMode(mode)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.35rem',
                    padding: '0.4rem 0.85rem',
                    borderRadius: '7px',
                    border: 'none',
                    cursor: 'pointer',
                    fontSize: '0.85rem',
                    fontWeight: 600,
                    transition: 'background 0.15s ease, color 0.15s ease',
                    background: viewMode === mode ? 'var(--bg-primary)' : 'transparent',
                    color: viewMode === mode ? 'var(--primary-600)' : 'var(--text-tertiary)',
                    boxShadow: viewMode === mode ? '0 1px 4px rgba(0,0,0,0.08)' : 'none',
                  }}
                >
                  <Icon size={15} aria-hidden />
                  {mode === 'card' ? 'Cards' : 'List'}
                </button>
              ))}
            </div>
          </div>
        </>
      ) : null}

      {!isLoading && !error && totalCount > 0 && viewMode === 'list' ? (
        <div className="card card-table-shell" style={{ border: '1px solid var(--border-default)' }}>
          <div className="table-container" style={{ border: 'none', overflowX: 'auto' }}>
            <table className="data-table college-applications-table college-internships-table">
              <colgroup>
                <col className="college-internships-col-title" />
                <col className="college-internships-col-employer" />
                <col className="college-internships-col-type" />
                <col className="college-internships-col-stipend" />
                <col className="college-internships-col-cgpa" />
                <col className="college-internships-col-openings" />
                <col className="college-internships-col-posted" />
                <col className="college-internships-col-campus" />
                <col className="college-internships-col-actions" />
              </colgroup>
              <thead>
                <tr style={{ background: 'var(--bg-secondary)' }}>
                  {TABLE_COLUMNS.map((col, i) => (
                    <th
                      key={col}
                      className={col === 'Actions' ? 'college-internships-col-actions' : undefined}
                      style={
                        i === 0
                          ? { paddingLeft: '1.25rem' }
                          : i === TABLE_COLUMNS.length - 1
                            ? { textAlign: 'right', paddingRight: '1.25rem' }
                            : undefined
                      }
                    >
                      {col}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {displayRows.length === 0 ? (
                  <tr>
                    <td colSpan={TABLE_COLUMNS.length} className="text-center text-secondary">
                      No listings match your search or filters.
                    </td>
                  </tr>
                ) : null}
                {displayRows.map((row) => {
                  const typeMeta = getJobTypeMeta(row.job_type);
                  const campusMeta = getCollegeStatusMeta(row.college_status);
                  const busy = actionBusyId === row.id;
                  return (
                    <tr key={row.id}>
                      <td
                        className="font-semibold text-sm cell-truncate"
                        style={{ paddingLeft: '1.25rem' }}
                        title={row.title || undefined}
                      >
                        {row.title}
                      </td>
                      <td className="text-sm">
                        <CompanyNameLink name={row.company_name} website={row.website} />
                      </td>
                      <td>
                        <span className={`badge ${typeMeta.badge} badge-dot`}>{typeMeta.label}</span>
                      </td>
                      <td className="text-sm">{stipendLabel(row.salary_min, row.salary_max)}</td>
                      <td className="text-sm">{row.min_cgpa != null ? Number(row.min_cgpa) : '—'}</td>
                      <td className="text-sm">{row.vacancies ?? '—'}</td>
                      <td className="text-sm text-secondary">{row.created_at ? formatDate(row.created_at) : '—'}</td>
                      <td>
                        <span className={`badge ${campusMeta.badge} badge-dot`} style={{ fontSize: '0.75rem' }}>
                          {campusMeta.label}
                        </span>
                      </td>
                      <td style={{ textAlign: 'right', paddingRight: '1.25rem', whiteSpace: 'nowrap' }} className="college-internships-col-actions">
                        <InternshipListingActions
                          row={row}
                          busy={busy}
                          onApprove={(id) => reviewListing(id, 'approve')}
                          onReject={(id) => reviewListing(id, 'reject')}
                          onView={setViewRow}
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      ) : null}

      {!isLoading && !error && totalCount > 0 && viewMode === 'card' ? (
        displayRows.length === 0 ? (
          <div className="card">
            <p className="text-secondary" style={{ margin: 0 }}>
              No listings match your search or filters.
            </p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            {displayRows.map((row) => {
              const typeMeta = getJobTypeMeta(row.job_type);
              const campusMeta = getCollegeStatusMeta(row.college_status);
              const busy = actionBusyId === row.id;
              return (
                <div key={row.id} className="card card-hover" style={{ border: '1px solid var(--border-default)' }}>
                  {String(row.college_status || 'pending') === 'pending' ? (
                    <div
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        gap: '0.75rem',
                        flexWrap: 'wrap',
                        marginBottom: '1rem',
                        padding: '0.65rem 0.85rem',
                        borderRadius: 'var(--radius-md)',
                        background: 'rgba(217, 119, 6, 0.08)',
                        border: '1px solid rgba(217, 119, 6, 0.22)',
                      }}
                    >
                      <span className="text-sm" style={{ color: 'var(--warning-700, #b45309)', fontWeight: 600 }}>
                        Pending your campus approval — students cannot apply yet
                      </span>
                    </div>
                  ) : null}
                  <div
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'flex-start',
                      gap: '1rem',
                      flexWrap: 'wrap',
                    }}
                  >
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '0.5rem',
                          flexWrap: 'wrap',
                          marginBottom: '0.35rem',
                        }}
                      >
                        <h3 style={{ fontSize: '1.0625rem', fontWeight: 700, margin: 0 }}>{row.title}</h3>
                        <span className={`badge ${typeMeta.badge} badge-dot`}>{typeMeta.label}</span>
                        <span className={`badge ${campusMeta.badge} badge-dot`}>{campusMeta.label}</span>
                      </div>
                      <div style={{ marginBottom: '0.5rem' }}>
                        <CompanyNameLink name={row.company_name} website={row.website} />
                      </div>
                      <p className="text-sm text-secondary" style={{ margin: '0 0 0.75rem', lineHeight: 1.5 }}>
                        {(row.description || '').slice(0, 280)}
                        {(row.description || '').length > 280 ? '…' : ''}
                      </p>
                      <div
                        className="text-sm text-secondary"
                        style={{ display: 'flex', flexWrap: 'wrap', gap: '1rem' }}
                      >
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                          <IndianRupee size={14} aria-hidden /> Stipend: {stipendLabel(row.salary_min, row.salary_max)}
                        </span>
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                          <BookOpen size={14} aria-hidden /> Min CGPA: {row.min_cgpa != null ? Number(row.min_cgpa) : '—'}
                        </span>
                        <span>Openings: {row.vacancies ?? '—'}</span>
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                          <Calendar size={14} aria-hidden /> Posted {row.created_at ? formatDate(row.created_at) : '—'}
                        </span>
                      </div>
                      {row.skills_required?.length ? (
                        <div style={{ marginTop: '0.65rem', display: 'flex', flexWrap: 'wrap', gap: '0.35rem' }}>
                          {row.skills_required.map((skill) => (
                            <span key={skill} className="badge badge-gray">
                              {skill}
                            </span>
                          ))}
                        </div>
                      ) : null}
                    </div>
                  </div>
                  <div
                    style={{
                      marginTop: '1rem',
                      paddingTop: '1rem',
                      borderTop: '1px solid var(--border-default)',
                      display: 'flex',
                      justifyContent: 'flex-end',
                    }}
                  >
                    <InternshipListingActions
                      row={row}
                      busy={busy}
                      onApprove={(id) => reviewListing(id, 'approve')}
                      onReject={(id) => reviewListing(id, 'reject')}
                      onView={setViewRow}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        )
      ) : null}

      {!isLoading && !error && totalCount === 0 ? (
        <div className="card" style={{ textAlign: 'center', padding: '2.5rem 1.5rem' }}>
          <GraduationCap size={36} style={{ margin: '0 auto 0.75rem', opacity: 0.25, color: 'var(--text-tertiary)' }} />
          <p style={{ margin: 0, fontWeight: 600, color: 'var(--text-primary)' }}>No published listings yet</p>
          <p className="text-sm text-secondary" style={{ margin: '0.5rem 0 0', maxWidth: '36rem', marginInline: 'auto' }}>
            Partners must publish from Internships or Projects and include your college. Listings appear here as{' '}
            <strong>Pending review</strong> until you approve them for students.
          </p>
        </div>
      ) : null}

      <InternshipDetailModal
        row={viewRow}
        onClose={() => setViewRow(null)}
        busy={Boolean(viewRow && actionBusyId === viewRow.id)}
        onApprove={(id) => reviewListing(id, 'approve')}
        onReject={(id) => reviewListing(id, 'reject')}
      />
    </div>
  );
}

'use client';
import { useCallback, useMemo, useState } from 'react';
import useSWR from 'swr';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMPANY_SORT_OPTIONS } from '@/lib/tableQueryPresets';
import Link from 'next/link';
import { formatDate } from '@/lib/utils';
import CompanyNameLink from '@/components/CompanyNameLink';
import { ExportCsvSplitButton } from '@/components/export/ExportCsvSplitButton';
import { useToast } from '@/components/ToastProvider';
import { CalendarDays, Users, Building2, Plus, ChevronRight } from 'lucide-react';
import ValidatedDateInput from '@/components/form/ValidatedDateInput';
import { FIELD_IDS, validateFieldOrError } from '@/lib/inputConstraints';
import { normalizeTimeHm, validateInterviewDateTimeOrError } from '@/lib/dateOnly';
import { findDuplicateCollegeInterviewSlot } from '@/lib/interviewSlotDuplicate';
import InterviewSlotActions from '@/components/interviews/InterviewSlotActions';

const EMPTY_COLLEGE_FORM = {
  company: '',
  round: '',
  date: '',
  startTime: '',
  endTime: '',
  interviewer: '',
  panelNames: '',
  students: '',
  createdBy: 'TPO',
};

function slotToForm(slot) {
  return {
    company: slot.company || '',
    round: slot.round || '',
    date: slot.date || '',
    startTime: slot.startTime || '',
    endTime: slot.endTime || '',
    interviewer: slot.interviewer || '',
    panelNames: slot.panelNames || '',
    students: Array.isArray(slot.students) ? slot.students.join(', ') : '',
    createdBy: slot.createdBy || 'TPO',
  };
}

function formatTimeDisplay(t) {
  if (!t) return '';
  const [h, m] = t.split(':').map(Number);
  if (Number.isNaN(h)) return t;
  const am = h < 12;
  const hr = h % 12 || 12;
  const mm = String(m || 0).padStart(2, '0');
  return `${hr}:${mm} ${am ? 'AM' : 'PM'}`;
}

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load interview slots');
  return json;
};

function formatSlotRange(slot) {
  if (slot.startTime && slot.endTime) {
    return `${formatTimeDisplay(slot.startTime)} – ${formatTimeDisplay(slot.endTime)}`;
  }
  if (slot.time) return slot.time;
  return '—';
}

export default function CollegeInterviewsPage() {
  const { addToast } = useToast();
  const { data, mutate, isLoading } = useSWR('/api/college/interviews', fetcher);
  const [section, setSection] = useState('schedule');
  const slots = Array.isArray(data?.slots) ? data.slots : [];
  const results = Array.isArray(data?.results) ? data.results : [];
  const {
    search: resultsSearch,
    setSearch: setResultsSearch,
    sort: resultsSort,
    setSort: setResultsSort,
    filtered: displayResults,
    filteredCount: resultsFilteredCount,
    totalCount: resultsTotalCount,
    hasActiveFilters: resultsHasActiveFilters,
    clearFilters: clearResultsFilters,
  } = useDataTableQuery(results, {
    getSearchText: (r) => [r.student, r.company, r.round, r.outcome].filter(Boolean).join(' '),
    sortOptions: COMPANY_SORT_OPTIONS,
    defaultSort: 'company_asc',
  });
  const [form, setForm] = useState(EMPTY_COLLEGE_FORM);
  const [editingId, setEditingId] = useState(null);
  const [saving, setSaving] = useState(false);

  const cancelEdit = () => {
    setEditingId(null);
    setForm(EMPTY_COLLEGE_FORM);
  };

  const startEdit = (slot) => {
    setEditingId(slot.id);
    setForm(slotToForm(slot));
  };

  const removeSlot = async (slot) => {
    if (!window.confirm(`Delete interview slot for ${slot.company} · ${slot.round}?`)) return;
    try {
      const res = await fetch(`/api/college/interviews/${slot.id}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Failed to delete slot');
      if (editingId === slot.id) cancelEdit();
      await mutate();
      addToast('Interview slot deleted.', 'success');
    } catch (err) {
      addToast(err.message || 'Failed to delete interview slot', 'error');
    }
  };

  const submit = async (e) => {
    e.preventDefault();
    if (!form.company.trim() || !form.round.trim() || !form.date || !form.startTime || !form.endTime || !form.interviewer.trim()) return;
    const dateErr = validateFieldOrError(FIELD_IDS.COLLEGE_INTERVIEW_DATE, form.date);
    if (dateErr) {
      addToast(dateErr, 'warning');
      return;
    }
    const editingSlot = editingId ? slots.find((s) => s.id === editingId) : null;
    const allowPastDatetime =
      Boolean(editingSlot) &&
      form.date === (editingSlot.date || '') &&
      normalizeTimeHm(form.startTime) === normalizeTimeHm(editingSlot.startTime);
    const dateTimeErr = validateInterviewDateTimeOrError(form.date, form.startTime, {
      allowPast: allowPastDatetime,
    });
    if (dateTimeErr) {
      addToast(dateTimeErr, 'warning');
      return;
    }
    const payload = {
      ...form,
      students: form.students ? form.students.split(',').map((s) => s.trim()).filter(Boolean) : [],
    };
    const duplicate = findDuplicateCollegeInterviewSlot(slots, payload, editingId);
    if (duplicate) {
      addToast('An interview slot with the same company, round, date, time, and interviewer already exists.', 'warning');
      return;
    }

    setSaving(true);
    const isEdit = Boolean(editingId);
    try {
      const url = isEdit ? `/api/college/interviews/${editingId}` : '/api/college/interviews';
      const res = await fetch(url, {
        method: isEdit ? 'PATCH' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || (isEdit ? 'Failed to update slot' : 'Failed to create slot'));
      await mutate();
      cancelEdit();
      addToast(isEdit ? 'Interview slot updated.' : 'Interview slot created successfully.', 'success');
    } catch (err) {
      addToast(err.message || 'Failed to save interview slot', 'error');
    } finally {
      setSaving(false);
    }
  };

  const stats = useMemo(
    () => ({
      total: slots.length,
      tpo: slots.filter((s) => s.createdBy === 'TPO').length,
      company: slots.filter((s) => s.createdBy === 'Company').length,
    }),
    [slots],
  );

  const getScheduleCsv = useCallback(
    (_scope) => ({
      headers: ['Company', 'Round', 'Date', 'Start', 'End', 'Interviewer', 'Panel_names', 'Students', 'Created_by'],
      rows: slots.map((s) => [
        s.company,
        s.round,
        s.date,
        s.startTime || '',
        s.endTime || '',
        s.interviewer,
        s.panelNames || '',
        s.students.join('; '),
        s.createdBy,
      ]),
    }),
    [slots],
  );

  const getResultsCsv = useCallback(
    (_scope) => ({
      headers: ['Student', 'Company', 'Round', 'Outcome', 'Date'],
      rows: displayResults.map((r) => [r.student, r.company, r.round, r.outcome, r.date]),
    }),
    [displayResults],
  );

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      {/* Glassmorphic Hero */}
      <div style={{
        position: 'relative', background: 'var(--banner-gradient)',
        borderRadius: 'var(--radius-xl)', padding: '2.5rem', color: 'white', overflow: 'hidden',
        marginBottom: '2rem', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)',
        display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1.5rem'
      }}>
        <div style={{ position: 'absolute', top: '-50px', right: '-50px', width: '250px', height: '250px', background: 'radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%)', borderRadius: '50%' }} />
        <div style={{ position: 'relative', zIndex: 1 }}>
          <h1 style={{ color: '#ffffff', fontSize: '2.25rem', fontWeight: 800, margin: '0 0 0.5rem', letterSpacing: '-0.02em', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <CalendarDays size={28} /> Interviews
          </h1>
          <p style={{ fontSize: '1rem', color: 'rgba(255,255,255,0.85)', margin: 0 }}>Slot scheduling, panel names, and published outcomes. Evaluator feedback stays with the employer.</p>
        </div>
        <div style={{ position: 'relative', zIndex: 1, display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
          <Link href="/dashboard/college/hiring-assessment" className="btn" style={{ background: 'rgba(255,255,255,0.15)', color: 'white', border: '1px solid rgba(255,255,255,0.2)', backdropFilter: 'blur(10px)', display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
            Hiring Assessment <ChevronRight size={14} />
          </Link>
          {section === 'schedule' ? (
            <ExportCsvSplitButton filenameBase="college_interview_schedule" currentCount={slots.length} fullCount={slots.length} getRows={getScheduleCsv} />
          ) : (
            <ExportCsvSplitButton filenameBase="college_interview_results" currentCount={results.length} fullCount={results.length} getRows={getResultsCsv} />
          )}
        </div>
      </div>

      {/* Pill Tabs */}
      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem', background: 'var(--bg-secondary)', padding: '0.35rem', borderRadius: 'var(--radius-lg)', width: 'fit-content', border: '1px solid var(--border-default)' }}>
        {[{ id: 'schedule', label: 'Scheduling' }, { id: 'results', label: 'Results' }].map(({ id, label }) => (
          <button key={id} type="button" onClick={() => setSection(id)} style={{ padding: '0.5rem 1.25rem', borderRadius: 'var(--radius-md)', border: 'none', background: section === id ? 'var(--primary-600)' : 'transparent', color: section === id ? 'white' : 'var(--text-secondary)', fontWeight: section === id ? 700 : 500, cursor: 'pointer', fontSize: '0.9rem', transition: 'all 0.15s' }}>{label}</button>
        ))}
      </div>

      {section === 'schedule' ? (
        <>
          <div className="grid grid-3" style={{ marginBottom: '1.5rem' }}>
            {[
              { label: 'Total Slots', value: stats.total, icon: CalendarDays, color: 'var(--primary-600)', bg: 'var(--primary-50)' },
              { label: 'Scheduled by TPO', value: stats.tpo, icon: Users, color: 'var(--info-600)', bg: 'rgba(2,132,199,0.08)' },
              { label: 'Scheduled by Company', value: stats.company, icon: Building2, color: 'var(--warning-600)', bg: 'rgba(217,119,6,0.08)' },
            ].map(({ label, value, icon: Icon, color, bg }) => (
              <div key={label} className="card" style={{ padding: '1.5rem', border: '1px solid var(--border-default)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1rem' }}>
                  <div style={{ padding: '0.5rem', borderRadius: 'var(--radius-md)', background: bg, color }}><Icon size={20} strokeWidth={2} /></div>
                </div>
                <div style={{ fontSize: '2rem', fontWeight: 800, color: 'var(--text-primary)', lineHeight: 1 }}>{value}</div>
                <div style={{ fontSize: '0.875rem', color: 'var(--text-secondary)', marginTop: '0.5rem', fontWeight: 500 }}>{label}</div>
              </div>
            ))}
          </div>

          <div className="grid grid-2">
            <div className="card">
              <div className="card-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.5rem' }}>
                <h3 className="card-title">{editingId ? 'Edit Interview Slot' : 'Create Interview Slot'}</h3>
                {editingId ? (
                  <button type="button" className="btn btn-ghost btn-sm" onClick={cancelEdit}>
                    Cancel edit
                  </button>
                ) : null}
              </div>
              <form onSubmit={submit} style={{ display: 'grid', gap: '0.65rem' }}>
                <input className="form-input" placeholder="Company" value={form.company} onChange={(e) => setForm((p) => ({ ...p, company: e.target.value }))} />
                <input className="form-input" placeholder="Round (e.g. Round 2 - HR)" value={form.round} onChange={(e) => setForm((p) => ({ ...p, round: e.target.value }))} />
                <ValidatedDateInput fieldId={FIELD_IDS.COLLEGE_INTERVIEW_DATE} value={form.date} onChange={(v) => setForm((p) => ({ ...p, date: v }))} />
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
                  <div>
                    <label className="form-label" style={{ marginBottom: '0.35rem', display: 'block' }}>
                      Start time
                    </label>
                    <input className="form-input" type="time" value={form.startTime} onChange={(e) => setForm((p) => ({ ...p, startTime: e.target.value }))} />
                  </div>
                  <div>
                    <label className="form-label" style={{ marginBottom: '0.35rem', display: 'block' }}>
                      End time
                    </label>
                    <input className="form-input" type="time" value={form.endTime} onChange={(e) => setForm((p) => ({ ...p, endTime: e.target.value }))} />
                  </div>
                </div>
                <input className="form-input" placeholder="Primary interviewer / host name" value={form.interviewer} onChange={(e) => setForm((p) => ({ ...p, interviewer: e.target.value }))} />
                <input
                  className="form-input"
                  placeholder="Panel / other names (comma-separated, optional)"
                  value={form.panelNames}
                  onChange={(e) => setForm((p) => ({ ...p, panelNames: e.target.value }))}
                />
                <input className="form-input" placeholder="Assign students (comma-separated)" value={form.students} onChange={(e) => setForm((p) => ({ ...p, students: e.target.value }))} />
                <select className="form-select" value={form.createdBy} onChange={(e) => setForm((p) => ({ ...p, createdBy: e.target.value }))}>
                  <option value="TPO">Scheduled by College (TPO)</option>
                  <option value="Company">Scheduled by Company</option>
                </select>
                <button className="btn btn-primary" type="submit" disabled={saving}>
                  {saving ? 'Saving…' : editingId ? 'Save changes' : 'Create Slot'}
                </button>
              </form>
            </div>

            <div className="card">
              <div className="card-header">
                <h3 className="card-title">Upcoming Slots</h3>
              </div>
              {isLoading ? <div className="text-sm text-secondary">Loading slots...</div> : null}
              <div style={{ display: 'grid', gap: '0.6rem' }}>
                {slots.map((slot) => (
                  <div
                    key={slot.id}
                    style={{
                      border: `1px solid ${editingId === slot.id ? 'var(--primary-400)' : 'var(--border-default)'}`,
                      borderRadius: 'var(--radius-md)',
                      padding: '0.7rem',
                      background: editingId === slot.id ? 'var(--primary-50)' : undefined,
                    }}
                  >
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '0.5rem' }}>
                      <div className="font-semibold">
                        {slot.company} • {slot.round}
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
                        <span className={`badge ${slot.createdBy === 'TPO' ? 'badge-indigo' : 'badge-blue'}`}>{slot.createdBy}</span>
                        <InterviewSlotActions
                          onEdit={() => startEdit(slot)}
                          onDelete={() => removeSlot(slot)}
                          disabled={saving}
                        />
                      </div>
                    </div>
                    <div className="text-sm text-secondary">
                      {formatDate(slot.date)} · {formatSlotRange(slot)} · {slot.interviewer}
                    </div>
                    {slot.panelNames ? <div className="text-xs text-tertiary">Panel / names: {slot.panelNames}</div> : null}
                    <div className="text-xs text-tertiary" style={{ marginTop: '0.25rem' }}>
                      Assigned: {slot.students.join(', ') || 'Not assigned yet'}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </>
      ) : (
        <>
          <div className="card" style={{ marginBottom: '1rem', borderLeft: '4px solid var(--info-500)' }}>
            <p className="text-sm text-secondary" style={{ margin: 0 }}>
              Colleges see <strong>outcomes only</strong> (shortlist / reject / pending). Written feedback and rubric scores (Communication, Projects, Technical)
              are captured for the company workflow but are <strong>not displayed here</strong>.
            </p>
          </div>
          {resultsTotalCount > 0 ? (
            <DataTableToolbar
              search={resultsSearch}
              onSearchChange={setResultsSearch}
              searchPlaceholder="Search student, company, or outcome…"
              sort={resultsSort}
              onSortChange={setResultsSort}
              sortOptions={COMPANY_SORT_OPTIONS}
              filteredCount={resultsFilteredCount}
              totalCount={resultsTotalCount}
              hasActiveFilters={resultsHasActiveFilters}
              onClear={clearResultsFilters}
            />
          ) : null}
          <div className="table-container">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Student</th>
                  <th>Company</th>
                  <th>Round</th>
                  <th>Outcome</th>
                  <th>Date</th>
                </tr>
              </thead>
              <tbody>
                {displayResults.length === 0 && resultsTotalCount > 0 ? (
                  <tr>
                    <td colSpan={5} className="text-center text-secondary">
                      No results match your search.
                    </td>
                  </tr>
                ) : null}
                {displayResults.map((r) => (
                  <tr key={r.id}>
                    <td className="font-semibold">{r.student}</td>
                    <td>
                      <CompanyNameLink name={r.company} website={r.website} />
                    </td>
                    <td>{r.round}</td>
                    <td>
                      <span
                        className={`badge ${r.outcome === 'Shortlisted' ? 'badge-success' : r.outcome === 'Rejected' ? 'badge-gray' : 'badge-amber'}`}
                      >
                        {r.outcome}
                      </span>
                    </td>
                    <td>{formatDate(r.date)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}

