  const results = Array.isArray(data?.results) ? data.results : [];
  
  const [form, setForm] = useState(EMPTY_COLLEGE_FORM);
  const [editingId, setEditingId] = useState(null);
  const [saving, setSaving] = useState(false);

  const cancelEdit = () => {
    setEditingId(null);
    setForm(EMPTY_COLLEGE_FORM);
    setShowCreate(false);
  };

  const startEdit = (slot) => {
    setEditingId(slot.id);
    setForm(slotToForm(slot));
    setShowCreate(true);
  };

  const removeSlot = async (slot) => {
    if (!window.confirm(`Delete interview slot for ${slot.company}?`)) return;
    try {
      const res = await fetch(`/api/college/interviews/${slot.id}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Failed to delete slot');
      if (editingId === slot.id) cancelEdit();
      await mutate();
      addToast('Interview slot deleted.', 'success');
    } catch (err) {
      addToast(err.message || 'Failed to delete interview slot', 'error');
    }
  };

  const submit = async (e) => {
    e.preventDefault();
    if (!form.company.trim() || !form.round.trim() || !form.date || !form.startTime || !form.endTime || !form.interviewer.trim()) return;
    const dateErr = validateFieldOrError(FIELD_IDS.COLLEGE_INTERVIEW_DATE, form.date);
    if (dateErr) {
      addToast(dateErr, 'warning');
      return;
    }
    const editingSlot = editingId ? slots.find((s) => s.id === editingId) : null;
    const allowPastDatetime =
      Boolean(editingSlot) &&
      form.date === (editingSlot.date || '') &&
      normalizeTimeHm(form.startTime) === normalizeTimeHm(editingSlot.startTime);
    const dateTimeErr = validateInterviewDateTimeOrError(form.date, form.startTime, {
      allowPast: allowPastDatetime,
    });
    if (dateTimeErr) {
      addToast(dateTimeErr, 'warning');
      return;
    }
    const payload = {
      ...form,
      students: form.students ? form.students.split(',').map((s) => s.trim()).filter(Boolean) : [],
    };
    const duplicate = findDuplicateCollegeInterviewSlot(slots, payload, editingId);
    if (duplicate) {
      addToast('An interview slot with the same company, round, date, time, and interviewer already exists.', 'warning');
      return;
    }

    setSaving(true);
    const isEdit = Boolean(editingId);
    try {
      const res = await fetch(isEdit ? `/api/college/interviews/${editingId}` : '/api/college/interviews', {
        method: isEdit ? 'PATCH' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Failed to save slot');
      await mutate();
      cancelEdit();
      addToast(isEdit ? 'Interview slot updated.' : 'Interview slot created successfully.', 'success');
    } catch (err) {
      addToast(err.message || 'Failed to save interview slot', 'error');
    } finally {
      setSaving(false);
    }
  };

  const stats = useMemo(
    () => ({
      total: slots.length,
      tpo: slots.filter((s) => s.createdBy === 'TPO').length,
      company: slots.filter((s) => s.createdBy === 'Company').length,
    }),
    [slots],
  );

  return (
    <>
      <MobileHeader 
        title="Interviews" 
        action={
          section === 'schedule' ? (
            <button
              className="btn btn-primary btn-sm"
              onClick={() => {
                if (showCreate) cancelEdit();
                else setShowCreate(true);
              }}
            >
              <Plus size={16} /> {showCreate ? 'Cancel' : 'New'}
            </button>
          ) : null
        } 
      />
      <div className="animate-fadeIn" style={{ padding: '1rem 1rem 5rem 1rem' }}>
        
        {/* Mobile Tabs */}
        <div style={{ display: 'flex', gap: '0.25rem', marginBottom: '1.25rem', background: 'var(--bg-secondary)', padding: '0.25rem', borderRadius: '12px', border: '1px solid var(--border-default)' }}>
          {[{ id: 'schedule', label: 'Schedule' }, { id: 'results', label: 'Results' }].map(({ id, label }) => (
            <button 
              key={id} 
              type="button" 
              onClick={() => { setSection(id); setShowCreate(false); }} 
              style={{ flex: 1, padding: '0.65rem 0', borderRadius: '8px', border: 'none', background: section === id ? 'var(--primary-600)' : 'transparent', color: section === id ? 'white' : 'var(--text-secondary)', fontWeight: section === id ? 700 : 500, cursor: 'pointer', fontSize: '0.85rem', transition: 'all 0.2s' }}
            >
              {label}
            </button>
          ))}
        </div>

        {section === 'schedule' && showCreate && (
          <div className="card" style={{ padding: '1.25rem', marginBottom: '1.5rem', border: '1px solid var(--primary-300)' }}>
            <h3 style={{ margin: '0 0 1rem', fontSize: '1rem' }}>{editingId ? 'Edit Interview Slot' : 'Create Interview Slot'}</h3>
            <form onSubmit={submit} style={{ display: 'grid', gap: '0.75rem' }}>
              <input className="form-input" placeholder="Company Name" value={form.company} onChange={(e) => setForm((p) => ({ ...p, company: e.target.value }))} />
              <input className="form-input" placeholder="Round (e.g. Round 2 - HR)" value={form.round} onChange={(e) => setForm((p) => ({ ...p, round: e.target.value }))} />
              <ValidatedDateInput fieldId={FIELD_IDS.COLLEGE_INTERVIEW_DATE} value={form.date} onChange={(v) => setForm((p) => ({ ...p, date: v }))} />
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
                <div>
                  <label className="text-xs text-secondary mb-1 block">Start Time</label>
                  <input className="form-input" type="time" value={form.startTime} onChange={(e) => setForm((p) => ({ ...p, startTime: e.target.value }))} />
                </div>
                <div>
                  <label className="text-xs text-secondary mb-1 block">End Time</label>
                  <input className="form-input" type="time" value={form.endTime} onChange={(e) => setForm((p) => ({ ...p, endTime: e.target.value }))} />
                </div>
              </div>
              <input className="form-input" placeholder="Primary interviewer name" value={form.interviewer} onChange={(e) => setForm((p) => ({ ...p, interviewer: e.target.value }))} />
              <input className="form-input" placeholder="Panel members (optional)" value={form.panelNames} onChange={(e) => setForm((p) => ({ ...p, panelNames: e.target.value }))} />
              <textarea className="form-input" placeholder="Assign students (comma-separated roll numbers)" value={form.students} onChange={(e) => setForm((p) => ({ ...p, students: e.target.value }))} rows={2} />
              <select className="form-select" value={form.createdBy} onChange={(e) => setForm((p) => ({ ...p, createdBy: e.target.value }))}>
                <option value="TPO">Scheduled by College (TPO)</option>
                <option value="Company">Scheduled by Company</option>
              </select>
              <button className="btn btn-primary" type="submit" style={{ width: '100%', marginTop: '0.5rem' }} disabled={saving}>
                {saving ? 'Saving…' : editingId ? 'Save changes' : 'Create Slot'}
              </button>
            </form>
          </div>
        )}

        {section === 'schedule' && !showCreate && (
          <>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.5rem', marginBottom: '1.25rem' }}>
              <div className="card" style={{ padding: '0.75rem', textAlign: 'center' }}>
                <div style={{ fontSize: '1.25rem', fontWeight: 800 }}>{stats.total}</div>
                <div style={{ fontSize: '0.65rem', color: 'var(--text-secondary)' }}>Total Slots</div>
              </div>
              <div className="card" style={{ padding: '0.75rem', textAlign: 'center' }}>
                <div style={{ fontSize: '1.25rem', fontWeight: 800, color: 'var(--info-600)' }}>{stats.tpo}</div>
                <div style={{ fontSize: '0.65rem', color: 'var(--text-secondary)' }}>By College</div>
              </div>
              <div className="card" style={{ padding: '0.75rem', textAlign: 'center' }}>
                <div style={{ fontSize: '1.25rem', fontWeight: 800, color: 'var(--warning-600)' }}>{stats.company}</div>
                <div style={{ fontSize: '0.65rem', color: 'var(--text-secondary)' }}>By Company</div>
              </div>
            </div>

            {isLoading ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                {[1, 2, 3].map(i => <div key={i} className="skeleton" style={{ height: 100, borderRadius: '12px' }} />)}
              </div>
            ) : slots.length === 0 ? (
              <div className="card" style={{ textAlign: 'center', padding: '3rem 1rem' }}>
                <CalendarDays size={32} style={{ margin: '0 auto 1rem', opacity: 0.3 }} />
                <div style={{ fontWeight: 600 }}>No upcoming slots</div>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                {slots.map((slot) => (
                  <div key={slot.id} className="card" style={{ padding: '1rem', position: 'relative', overflow: 'hidden' }}>
                    <div style={{ position: 'absolute', left: 0, top: 0, bottom: 0, width: '4px', background: slot.createdBy === 'TPO' ? 'var(--info-500)' : 'var(--warning-500)' }} />
                    
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.5rem', gap: '0.35rem' }}>
                      <div style={{ fontWeight: 600, fontSize: '0.95rem' }}>{slot.company}</div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                        <span className={`badge ${slot.createdBy === 'TPO' ? 'badge-indigo' : 'badge-blue'}`} style={{ fontSize: '0.65rem' }}>{slot.createdBy}</span>
                        <InterviewSlotActions
                          onEdit={() => startEdit(slot)}
                          onDelete={() => removeSlot(slot)}
                          disabled={saving}
                        />
                      </div>
                    </div>
                    
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginBottom: '0.5rem' }}>
                      {slot.round}
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem', fontSize: '0.8rem', color: 'var(--text-secondary)' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        <CalendarDays size={14} style={{ opacity: 0.7 }} />
                        <span>{formatDate(slot.date)} · {formatSlotRange(slot)}</span>
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        <Users size={14} style={{ opacity: 0.7 }} />
                        <span>{slot.interviewer} {slot.panelNames ? `(+ ${slot.panelNames.split(',').length})` : ''}</span>
                      </div>
                    </div>
                    
                    <div style={{ marginTop: '0.75rem', paddingTop: '0.75rem', borderTop: '1px dashed var(--border-default)', fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>
                      Assigned: {slot.students.join(', ') || 'None'}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        )}

        {section === 'results' && (
          <>
            <div style={{ background: 'var(--info-50)', padding: '0.75rem 1rem', borderRadius: '12px', border: '1px solid var(--info-200)', marginBottom: '1.25rem', fontSize: '0.8rem', color: 'var(--info-800)', lineHeight: 1.4 }}>
              <strong>Note:</strong> Colleges see outcomes only. Written feedback and rubric scores stay with the employer.
            </div>
            
            {isLoading ? (
               <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
               {[1, 2, 3].map(i => <div key={i} className="skeleton" style={{ height: 80, borderRadius: '12px' }} />)}
             </div>
            ) : results.length === 0 ? (
              <div className="card" style={{ textAlign: 'center', padding: '3rem 1rem' }}>
                <Users size={32} style={{ margin: '0 auto 1rem', opacity: 0.3 }} />
                <div style={{ fontWeight: 600 }}>No results published yet</div>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                {results.map((r) => (
                  <div key={r.id} className="card" style={{ padding: '1rem' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.5rem' }}>
                      <div style={{ fontWeight: 600, fontSize: '0.95rem' }}>{r.student}</div>
                      <span className={`badge ${r.outcome === 'Shortlisted' ? 'badge-success' : r.outcome === 'Rejected' ? 'badge-gray' : 'badge-amber'}`} style={{ fontSize: '0.7rem' }}>
                        {r.outcome}
                      </span>
                    </div>
                    
                    <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                      <CompanyNameLink name={r.company} website={r.website} /> · {r.round}
                    </div>
                    
                    <div style={{ fontSize: '0.75rem', color: 'var(--text-tertiary)', marginTop: '0.5rem' }}>
                      {formatDate(r.date)}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        )}
      </div>
    </>
  );
}

'use client';

import { useMemo, useState } from 'react';
import useSWR from 'swr';
import { Briefcase, Calendar, IndianRupee, LayoutGrid, List } from 'lucide-react';
import { formatCurrency, formatDate } from '@/lib/utils';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS, FILTER_ALL } from '@/lib/tableQueryPresets';
import CompanyNameLink from '@/components/CompanyNameLink';
import PageLoading from '@/components/PageLoading';
import { useToast } from '@/components/ToastProvider';
import { useCollegeAcademicYearApiPath } from '@/lib/collegeAcademicYearContext';
import InternshipListingActions from '../internships/InternshipListingActions';
import AlumniJobDetailModal from './AlumniJobDetailModal';
import {
  computeAlumniJobStats,
  getAlumniJobTypeMeta,
  getCollegeStatusMeta,
  salaryLabel,
} from './alumniJobRowUtils';

const fetcher = (url) => fetch(url).then((r) => r.json());

const TYPE_FILTER_OPTIONS = [
  FILTER_ALL,
  { value: 'full_time', label: 'Full-time' },
  { value: 'contract', label: 'Contract' },
];

const APPROVAL_FILTER_OPTIONS = [
  FILTER_ALL,
  { value: 'pending', label: 'Pending review' },
  { value: 'approved', label: 'Approved' },
  { value: 'rejected', label: 'Rejected' },
];

const TABLE_COLUMNS = ['Title', 'Employer', 'Type', 'Salary', 'Openings', 'Posted', 'Campus', 'Actions'];

export default function CollegeAlumniJobsContent() {
  const { addToast } = useToast();
  const jobsPath = useCollegeAcademicYearApiPath('/api/college/jobs');
  const { data, error, isLoading, mutate } = useSWR(jobsPath, fetcher);
  const [viewMode, setViewMode] = useState('card');
  const [viewRow, setViewRow] = useState(null);
  const [approvalFilter, setApprovalFilter] = useState('');
  const [actionBusyId, setActionBusyId] = useState(null);

  const list = Array.isArray(data?.jobs) ? data.jobs : [];
  const stats = useMemo(() => computeAlumniJobStats(list), [list]);

  const {
    search,
    setSearch,
    filter,
    setFilter,
    sort,
    setSort,
    filtered: searchedRows,
    filteredCount: searchedCount,
    totalCount,
    hasActiveFilters: hasSearchFilters,
    clearFilters: clearSearchFilters,
  } = useDataTableQuery(list, {
    getSearchText: (row) =>
      [row.title, row.company_name, row.description, ...(Array.isArray(row.skills_required) ? row.skills_required : [])]
        .filter(Boolean)
        .join(' '),
    filterFn: (row, f) => !f || String(row.job_type) === f,
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'date_desc',
  });

  const displayRows = useMemo(() => {
    if (!approvalFilter) return searchedRows;
    return searchedRows.filter((row) => String(row.college_status || 'pending') === approvalFilter);
  }, [searchedRows, approvalFilter]);

  const filteredCount = approvalFilter ? displayRows.length : searchedCount;
  const hasActiveFilters = hasSearchFilters || Boolean(approvalFilter);

  const clearFilters = () => {
    clearSearchFilters();
    setApprovalFilter('');
  };

  const reviewListing = async (jobId, action) => {
    setActionBusyId(jobId);
    try {
      const res = await fetch('/api/college/jobs', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jobId, action }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || `Failed to ${action} listing`);
      await mutate();
      addToast(
        action === 'approve' ? 'Alumni job approved — alumni can now see it.' : 'Alumni job rejected.',
        action === 'approve' ? 'success' : 'info',
      );
      setViewRow((current) => (current?.id === jobId ? null : current));
    } catch (e) {
      addToast(e.message || 'Action failed', 'error');
    } finally {
      setActionBusyId(null);
    }
  };

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '2rem' }}>
      <div className="page-header" style={{ marginBottom: '1.25rem' }}>
        <div className="page-header-left">
          <h1>Alumni Jobs</h1>
          <p>
            Review lateral job postings from employer partners before they appear to alumni. Approve each role for your
            campus after checking salary, experience, and eligibility.
          </p>
        </div>
      </div>

      {!isLoading && !error ? (
        <p
          className="text-sm text-secondary"
          style={{
            margin: '0 0 1.25rem',
            padding: '0.65rem 0.85rem',
            background: 'var(--bg-secondary)',
            border: '1px solid var(--border-default)',
            borderRadius: 'var(--radius-md)',
          }}
        >
          <strong style={{ color: 'var(--text-primary)' }}>{stats.count}</strong> alumni job
          {stats.count === 1 ? '' : 's'}
          {stats.pending ? (
            <>
              {' '}
              · <strong style={{ color: 'var(--warning-600, #d97706)' }}>{stats.pending}</strong> awaiting review
            </>
          ) : null}
          {stats.openings ? (
            <>
              {' '}
              · <strong style={{ color: 'var(--text-primary)' }}>{stats.openings}</strong> openings
            </>
          ) : null}
          {stats.avgSalary != null ? (
            <>
              {' '}
              · avg salary <strong style={{ color: 'var(--text-primary)' }}>{formatCurrency(stats.avgSalary)}</strong>/yr
            </>
          ) : null}
        </p>
      ) : null}

      {error ? (
        <div className="card" style={{ borderColor: 'var(--danger-500)', marginBottom: '1rem' }}>
          <p className="text-sm" style={{ margin: 0 }}>
            Could not load alumni jobs. Ensure you are signed in as a college admin.
          </p>
        </div>
      ) : null}

      {isLoading ? <PageLoading message="Loading alumni jobs…" inline /> : null}

      {!isLoading && !error && totalCount > 0 ? (
        <>
          <DataTableToolbar
            search={search}
            onSearchChange={setSearch}
            searchPlaceholder="Search title, employer, or skills…"
            filter={filter}
            onFilterChange={setFilter}
            filterOptions={TYPE_FILTER_OPTIONS}
            filterLabel="Type"
            sort={sort}
            onSortChange={setSort}
            sortOptions={COMMON_SORT_OPTIONS}
            filteredCount={filteredCount}
            totalCount={totalCount}
            hasActiveFilters={hasActiveFilters}
            onClear={clearFilters}
          />
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: '0.75rem',
              margin: '-0.5rem 0 1rem',
              flexWrap: 'wrap',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>
              <label className="text-sm text-secondary" htmlFor="college-alumni-job-approval-filter">
                Campus status
              </label>
              <select
                id="college-alumni-job-approval-filter"
                className="form-select"
                style={{ width: 'auto', minWidth: '10rem', padding: '0.5rem 2rem 0.5rem 0.75rem' }}
                value={approvalFilter}
                onChange={(e) => setApprovalFilter(e.target.value)}
              >
                {APPROVAL_FILTER_OPTIONS.map((opt) => (
                  <option key={opt.value || 'all'} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>
            <div
              role="group"
              aria-label="View mode"
              style={{
                display: 'flex',
                background: 'var(--bg-secondary)',
                borderRadius: '10px',
                padding: '3px',
                gap: '2px',
                border: '1px solid var(--border-default)',
              }}
            >
              {[
                { mode: 'card', icon: LayoutGrid, label: 'Card view' },
                { mode: 'list', icon: List, label: 'List view' },
              ].map(({ mode, icon: Icon, label }) => (
                <button
                  key={mode}
                  type="button"
                  title={label}
                  aria-label={label}
                  aria-pressed={viewMode === mode}
                  onClick={() => setViewMode(mode)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.35rem',
                    padding: '0.4rem 0.85rem',
                    borderRadius: '7px',
                    border: 'none',
                    cursor: 'pointer',
                    fontSize: '0.85rem',
                    fontWeight: 600,
                    background: viewMode === mode ? 'var(--bg-primary)' : 'transparent',
                    color: viewMode === mode ? 'var(--primary-600)' : 'var(--text-tertiary)',
                    boxShadow: viewMode === mode ? '0 1px 4px rgba(0,0,0,0.08)' : 'none',
                  }}
                >
                  <Icon size={15} aria-hidden />
                  {mode === 'card' ? 'Cards' : 'List'}
                </button>
              ))}
            </div>
          </div>
        </>
      ) : null}

      {!isLoading && !error && totalCount > 0 && viewMode === 'list' ? (
        <div className="card card-table-shell" style={{ border: '1px solid var(--border-default)' }}>
          <div className="table-container" style={{ border: 'none', overflowX: 'auto' }}>
            <table className="data-table college-applications-table college-jobs-table">
              <thead>
                <tr style={{ background: 'var(--bg-secondary)' }}>
                  {TABLE_COLUMNS.map((col, i) => (
                    <th
                      key={col}
                      style={
                        i === 0
                          ? { paddingLeft: '1.25rem' }
                          : i === TABLE_COLUMNS.length - 1
                            ? { textAlign: 'right', paddingRight: '1.25rem' }
                            : undefined
                      }
                    >
                      {col}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {displayRows.length === 0 ? (
                  <tr>
                    <td colSpan={TABLE_COLUMNS.length} className="text-center text-secondary">
                      No jobs match your search or filters.
                    </td>
                  </tr>
                ) : null}
                {displayRows.map((row) => {
                  const typeMeta = getAlumniJobTypeMeta(row.job_type);
                  const campusMeta = getCollegeStatusMeta(row.college_status);
                  const busy = actionBusyId === row.id;
                  return (
                    <tr key={row.id}>
                      <td style={{ paddingLeft: '1.25rem', maxWidth: 240 }}>
                        <div className="font-semibold text-sm cell-truncate" title={row.title}>
                          {row.title}
                        </div>
                      </td>
                      <td className="text-sm">
                        <CompanyNameLink name={row.company_name} website={row.website} />
                      </td>
                      <td>
                        <span className={`badge ${typeMeta.badge} badge-dot`}>{typeMeta.label}</span>
                      </td>
                      <td className="text-sm">{salaryLabel(row.salary_min, row.salary_max)}</td>
                      <td className="text-sm">{row.vacancies ?? '—'}</td>
                      <td className="text-sm text-secondary">{row.created_at ? formatDate(row.created_at) : '—'}</td>
                      <td>
                        <span className={`badge ${campusMeta.badge} badge-dot`} style={{ fontSize: '0.75rem' }}>
                          {campusMeta.label}
                        </span>
                      </td>
                      <td style={{ textAlign: 'right', paddingRight: '1.25rem', whiteSpace: 'nowrap' }}>
                        <InternshipListingActions
                          row={row}
                          busy={busy}
                          onApprove={(id) => reviewListing(id, 'approve')}
                          onReject={(id) => reviewListing(id, 'reject')}
                          onView={setViewRow}
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      ) : null}

      {!isLoading && !error && totalCount > 0 && viewMode === 'card' ? (
        displayRows.length === 0 ? (
          <div className="card">
            <p className="text-secondary" style={{ margin: 0 }}>
              No jobs match your search or filters.
            </p>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            {displayRows.map((row) => {
              const typeMeta = getAlumniJobTypeMeta(row.job_type);
              const campusMeta = getCollegeStatusMeta(row.college_status);
              const busy = actionBusyId === row.id;
              return (
                <div key={row.id} className="card card-hover" style={{ border: '1px solid var(--border-default)' }}>
                  {String(row.college_status || 'pending') === 'pending' ? (
                    <div
                      style={{
                        marginBottom: '1rem',
                        padding: '0.65rem 0.85rem',
                        borderRadius: 'var(--radius-md)',
                        background: 'rgba(217, 119, 6, 0.08)',
                        border: '1px solid rgba(217, 119, 6, 0.22)',
                      }}
                    >
                      <span className="text-sm" style={{ color: 'var(--warning-700, #b45309)', fontWeight: 600 }}>
                        Pending your campus approval — alumni cannot see or apply yet
                      </span>
                    </div>
                  ) : null}
                  <div style={{ minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '0.35rem' }}>
                      <h3 style={{ fontSize: '1.0625rem', fontWeight: 700, margin: 0 }}>{row.title}</h3>
                      <span className={`badge ${typeMeta.badge} badge-dot`}>{typeMeta.label}</span>
                      <span className={`badge ${campusMeta.badge} badge-dot`}>{campusMeta.label}</span>
                    </div>
                    <div style={{ marginBottom: '0.5rem' }}>
                      <CompanyNameLink name={row.company_name} website={row.website} />
                    </div>
                    <p className="text-sm text-secondary" style={{ margin: '0 0 0.75rem', lineHeight: 1.5 }}>
                      {(row.description || '').slice(0, 280)}
                      {(row.description || '').length > 280 ? '…' : ''}
                    </p>
                    <div className="text-sm text-secondary" style={{ display: 'flex', flexWrap: 'wrap', gap: '1rem' }}>
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                        <IndianRupee size={14} aria-hidden /> Salary: {salaryLabel(row.salary_min, row.salary_max)}
                      </span>
                      <span>Openings: {row.vacancies ?? '—'}</span>
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem' }}>
                        <Calendar size={14} aria-hidden /> Posted {row.created_at ? formatDate(row.created_at) : '—'}
                      </span>
                    </div>
                  </div>
                  <div
                    style={{
                      marginTop: '1rem',
                      paddingTop: '1rem',
                      borderTop: '1px solid var(--border-default)',
                      display: 'flex',
                      justifyContent: 'flex-end',
                    }}
                  >
                    <InternshipListingActions
                      row={row}
                      busy={busy}
                      onApprove={(id) => reviewListing(id, 'approve')}
                      onReject={(id) => reviewListing(id, 'reject')}
                      onView={setViewRow}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        )
      ) : null}

      {!isLoading && !error && totalCount === 0 ? (
        <div className="card" style={{ textAlign: 'center', padding: '2.5rem 1.5rem' }}>
          <Briefcase size={36} style={{ margin: '0 auto 0.75rem', opacity: 0.25, color: 'var(--text-tertiary)' }} />
          <p style={{ margin: 0, fontWeight: 600, color: 'var(--text-primary)' }}>No alumni jobs yet</p>
          <p className="text-sm text-secondary" style={{ margin: '0.5rem 0 0', maxWidth: '36rem', marginInline: 'auto' }}>
            Employers must publish a lateral role and include your college. Jobs appear here as{' '}
            <strong>Pending review</strong> until you approve them for alumni.
          </p>
        </div>
      ) : null}

      <AlumniJobDetailModal
        row={viewRow}
        onClose={() => setViewRow(null)}
        busy={Boolean(viewRow && actionBusyId === viewRow.id)}
        onApprove={(id) => reviewListing(id, 'approve')}
        onReject={(id) => reviewListing(id, 'reject')}
      />
    </div>
  );
}

'use client';

import { useCallback, useMemo, useState } from 'react';
import useSWR from 'swr';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS, FILTER_ALL } from '@/lib/tableQueryPresets';
import { Send } from 'lucide-react';
import { formatDate, formatCurrency, formatStatus, getStatusColor } from '@/lib/utils';
import { useToast } from '@/components/ToastProvider';
import { StandardTableIconAction } from '@/components/ui/StandardTableIconAction';
import CompanyNameLink from '@/components/CompanyNameLink';
import { toDateOnlyString } from '@/lib/dateOnly';
import { validateCollegeOfferPayload } from '@/lib/apiInputValidation';
import ValidatedNumberInput from '@/components/form/ValidatedNumberInput';
import ValidatedDateInput from '@/components/form/ValidatedDateInput';
import { FIELD_IDS } from '@/lib/inputConstraints';

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load');
  return json;
};

const STATUS_OPTIONS = ['pending', 'accepted', 'rejected', 'expired', 'revoked'];

const OFFER_TABLE_COLUMNS = [
  'Student',
  'College',
  'Role',
  'Salary',
  'Location',
  'Deadline',
  'Status',
  'Actions',
];

export default function DtCollegeOffers() {
  const { addToast } = useToast();
  const { data, error, isLoading, mutate } = useSWR('/api/college/offers', fetcher);
  const { data: studentsPayload } = useSWR('/api/college/students', fetcher);

  const offers = Array.isArray(data?.offers) ? data.offers : [];
  const offerFilterOptions = useMemo(
    () => [FILTER_ALL, ...STATUS_OPTIONS.map((s) => ({ value: s, label: formatStatus(s) }))],
    [],
  );
  const {
    search,
    setSearch,
    filter,
    setFilter,
    sort,
    setSort,
    filtered: displayOffers,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(offers, {
    getSearchText: (o) =>
      [o.student_name, o.roll_number, o.college_name, o.job_title, o.location, o.status].filter(Boolean).join(' '),
    filterFn: (row, f) => !f || String(row.status || '') === f,
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'date_desc',
  });
  const summary = data?.summary || { total: 0, accepted: 0, pending: 0, rejected: 0, avgSalary: 0 };
  const students = useMemo(() => {
    const list = Array.isArray(studentsPayload?.students)
      ? studentsPayload.students
      : Array.isArray(studentsPayload)
        ? studentsPayload
        : [];
    return list.map((s) => ({
      id: s.id,
      label: `${s.name || '—'} (${s.roll || 'no roll'})`,
    }));
  }, [studentsPayload]);

  const [showAdd, setShowAdd] = useState(false);
  const [editId, setEditId] = useState(null);
  const [viewRow, setViewRow] = useState(null);
  const [form, setForm] = useState({
    studentId: '',
    reportedCompanyName: '',
    jobTitle: '',
    salary: '',
    location: '',
    deadline: '',
    joiningDate: '',
    status: 'pending',
  });
  const [saving, setSaving] = useState(false);

  const editingRow = useMemo(() => offers.find((o) => o.id === editId), [offers, editId]);

  const resetForm = () => {
    setForm({
      studentId: '',
      reportedCompanyName: '',
      jobTitle: '',
      salary: '',
      location: '',
      deadline: '',
      joiningDate: '',
      status: 'pending',
    });
  };

  const todayYmd = useMemo(() => toDateOnlyString(new Date()), []);

  const submitAdd = async () => {
    if (!form.studentId || !form.reportedCompanyName.trim() || !form.jobTitle.trim()) {
      addToast('Student, company name, and job title are required.', 'warning');
      return;
    }
    const offerErr = validateCollegeOfferPayload({
      salary: form.salary,
      deadline: form.deadline,
      joiningDate: form.joiningDate,
    });
    if (offerErr) {
      addToast(offerErr, 'warning');
      return;
    }
    setSaving(true);
    try {
      const res = await fetch('/api/college/offers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          studentId: form.studentId,
          reportedCompanyName: form.reportedCompanyName.trim(),
          jobTitle: form.jobTitle.trim(),
          salary: Number(form.salary || 0),
          location: form.location.trim() || null,
          deadline: form.deadline || null,
          joiningDate: form.joiningDate || null,
          status: form.status,
        }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Save failed');
      addToast('Offer added.', 'success');
      setShowAdd(false);
      resetForm();
      await mutate();
    } catch (err) {
      addToast(err.message || 'Save failed', 'error');
    } finally {
      setSaving(false);
    }
  };

  const openEdit = (row) => {
    setEditId(row.id);
    setForm({
      studentId: row.student_id || '',
      reportedCompanyName: row.company_name || '',
      jobTitle: row.job_title || '',
      salary: row.salary != null ? String(row.salary) : '',
      location: row.location || '',
      deadline: row.deadline ? toDateOnlyString(row.deadline) : '',
      joiningDate: row.joining_date ? toDateOnlyString(row.joining_date) : '',
      status: row.status || 'pending',
    });
  };

  const submitEdit = async () => {
    if (!editId) return;
    if (!form.reportedCompanyName.trim() || !form.jobTitle.trim()) {
      addToast('Company name and job title are required.', 'warning');
      return;
    }
    setSaving(true);
    try {
      const res = await fetch('/api/college/offers', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: editId,
          reportedCompanyName: form.reportedCompanyName.trim(),
          jobTitle: form.jobTitle.trim(),
          salary: Number(form.salary || 0),
          location: form.location.trim() || null,
          deadline: form.deadline || null,
          joiningDate: form.joiningDate || null,
          status: form.status,
        }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Update failed');
      addToast('Offer updated.', 'success');
      setEditId(null);
      resetForm();
      await mutate();
    } catch (err) {
      addToast(err.message || 'Update failed', 'error');
    } finally {
      setSaving(false);
    }
  };

  const removeOffer = async (id) => {
    if (!confirm('Delete this offer row?')) return;
    try {
      const res = await fetch('/api/college/offers', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Delete failed');
      addToast('Offer removed.', 'success');
      await mutate();
    } catch (err) {
      addToast(err.message || 'Delete failed', 'error');
    }
  };

  const closeModals = useCallback(() => {
    setShowAdd(false);
    setEditId(null);
    setViewRow(null);
    resetForm();
  }, []);

  const summaryLine = isLoading
    ? 'Loading offers…'
    : error
      ? 'Could not load counts'
      : `${summary.total ?? offers.length} offers · ${summary.accepted ?? 0} accepted · ${summary.pending ?? 0} pending · ${summary.rejected ?? 0} declined`;

  const avgSalaryLine =
    !isLoading && !error && summary.avgSalary
      ? `Avg accepted salary ${formatCurrency(summary.avgSalary)}`
      : null;

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      {error ? (
        <div
          className="card"
          role="alert"
          style={{
            padding: '1rem 1.25rem',
            marginBottom: '1rem',
            background: 'var(--danger-50)',
            border: '1px solid var(--danger-200)',
          }}
        >
          <p style={{ margin: 0, color: 'var(--danger-700)', fontWeight: 600 }}>
            {error.message || 'Could not load offers.'}
          </p>
        </div>
      ) : null}

      <div
        style={{
          marginBottom: '2rem',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start',
          flexWrap: 'wrap',
          gap: '1rem',
        }}
      >
        <div>
          <h1
            style={{
              fontSize: '1.75rem',
              fontWeight: 800,
              color: 'var(--text-primary)',
              margin: '0 0 0.35rem',
              letterSpacing: '-0.02em',
              display: 'flex',
              alignItems: 'center',
              gap: '0.5rem',
            }}
          >
            <Send size={24} aria-hidden />
            Placement offers
          </h1>
          <p style={{ fontSize: '0.875rem', color: 'var(--text-secondary)', margin: 0 }}>{summaryLine}</p>
          {avgSalaryLine ? (
            <p style={{ fontSize: '0.8rem', color: 'var(--text-tertiary)', margin: '0.25rem 0 0' }}>{avgSalaryLine}</p>
          ) : null}
        </div>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', alignItems: 'center' }}>
          <StandardTableIconAction
            action="add"
            variant="primary"
            onClick={() => {
              resetForm();
              setShowAdd(true);
              setEditId(null);
            }}
          />
        </div>
      </div>

      <div className="directive-panel" role="region" aria-label="Student acceptance" style={{ marginBottom: '1rem' }}>
        <p className="directive-panel__title">When students use the app</p>
        <p className="text-sm text-secondary" style={{ margin: 0, lineHeight: 1.55 }}>
          If the student signs in, they can accept or decline <strong>pending</strong> rows on <strong>My Offers</strong>; status then syncs here. You can also set
          status manually when you already know the outcome (e.g. accepted from email). To roll back a mistaken status, open <strong>Edit</strong>, set{' '}
          <strong>Status</strong> to <strong>pending</strong> again, and save — or use <strong>Delete</strong> to remove a row (an older revision may become current
          automatically).
        </p>
      </div>

      {(showAdd || editId) && (
        <div className="card" style={{ marginBottom: '1rem' }}>
          <h3 className="card-title">{editId ? 'Edit offer' : 'Add offer'}</h3>
          {!editId && (
            <div className="form-group">
              <label className="form-label">Student (master list)</label>
              <select
                className="form-select"
                value={form.studentId}
                onChange={(e) => setForm((p) => ({ ...p, studentId: e.target.value }))}
              >
                <option value="">Select student</option>
                {students.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.label}
                  </option>
                ))}
              </select>
            </div>
          )}
          <div className="grid grid-2" style={{ gap: '1rem' }}>
            <div className="form-group">
              <label className="form-label">Company name (text)</label>
              <input
                className="form-input"
                value={form.reportedCompanyName}
                onChange={(e) => setForm((p) => ({ ...p, reportedCompanyName: e.target.value }))}
                placeholder="As shared with the student / email"
                disabled={Boolean(editId && editingRow?.linked_employer)}
              />
              {editId && editingRow?.linked_employer ? (
                <p className="text-xs text-tertiary" style={{ marginTop: '0.25rem' }}>
                  Company comes from the employer account for this row; edit other fields as needed.
                </p>
              ) : null}
            </div>
            <div className="form-group">
              <label className="form-label">Role / job title</label>
              <input
                className="form-input"
                value={form.jobTitle}
                onChange={(e) => setForm((p) => ({ ...p, jobTitle: e.target.value }))}
              />
            </div>
            <div className="form-group">
              <label className="form-label">Salary (INR annual)</label>
              <ValidatedNumberInput
                fieldId={FIELD_IDS.COLLEGE_OFFER_SALARY}
                value={form.salary}
                onChange={(v) => setForm((p) => ({ ...p, salary: v }))}
              />
            </div>
            <div className="form-group">
              <label className="form-label">Location</label>
              <input
                className="form-input"
                value={form.location}
                onChange={(e) => setForm((p) => ({ ...p, location: e.target.value }))}
              />
            </div>
            <div className="form-group">
              <label className="form-label">Response deadline</label>
              <ValidatedDateInput
                fieldId={FIELD_IDS.COLLEGE_OFFER_DEADLINE}
                value={form.deadline}
                onChange={(v) => setForm((p) => ({ ...p, deadline: v }))}
              />
              <label className="form-label" style={{ marginTop: '0.75rem' }}>
                Joining date
              </label>
              <ValidatedDateInput
                fieldId={FIELD_IDS.COLLEGE_OFFER_JOINING}
                context={{ deadline: form.deadline }}
                value={form.joiningDate}
                onChange={(v) => setForm((p) => ({ ...p, joiningDate: v }))}
              />
            </div>
            <div className="form-group">
              <label className="form-label">Status</label>
              <select className="form-select" value={form.status} onChange={(e) => setForm((p) => ({ ...p, status: e.target.value }))}>
                {STATUS_OPTIONS.map((s) => (
                  <option key={s} value={s}>
                    {formatStatus(s)}
                  </option>
                ))}
              </select>
            </div>
          </div>
          <div style={{ display: 'flex', gap: '0.5rem', marginTop: '1rem' }}>
            <button type="button" className="btn btn-primary" disabled={saving} onClick={editId ? submitEdit : submitAdd}>
              {saving ? 'Saving…' : editId ? 'Save changes' : 'Create'}
            </button>
            <button type="button" className="btn btn-secondary" onClick={closeModals}>
              Cancel
            </button>
          </div>
        </div>
      )}

      {!isLoading && totalCount > 0 ? (
        <DataTableToolbar
          search={search}
          onSearchChange={setSearch}
          searchPlaceholder="Search student, role, or company…"
          filter={filter}
          onFilterChange={setFilter}
          filterOptions={offerFilterOptions}
          filterLabel="Status"
          sort={sort}
          onSortChange={setSort}
          sortOptions={COMMON_SORT_OPTIONS}
          filteredCount={filteredCount}
          totalCount={totalCount}
          hasActiveFilters={hasActiveFilters}
          onClear={clearFilters}
        />
      ) : null}

      <div className="card desktop-table" style={{ padding: 0, overflow: 'hidden', border: '1px solid var(--border-default)' }}>
        <div className="table-container" style={{ border: 'none' }}>
        <table className="data-table">
          <thead>
            <tr style={{ background: 'var(--bg-secondary)' }}>
              {OFFER_TABLE_COLUMNS.map((col, i) => (
                <th
                  key={col}
                  style={
                    i === 0
                      ? { paddingLeft: '1.5rem' }
                      : i === OFFER_TABLE_COLUMNS.length - 1
                        ? { paddingRight: '1.5rem' }
                        : undefined
                  }
                >
                  {col}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {isLoading && !offers.length ? (
              <tr>
                <td colSpan={OFFER_TABLE_COLUMNS.length} style={{ padding: '2rem 1.5rem' }}>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                    {[1, 2, 3, 4].map((i) => (
                      <div key={i} className="skeleton" style={{ height: 40, borderRadius: 'var(--radius-md)' }} />
                    ))}
                  </div>
                </td>
              </tr>
            ) : null}
            {!isLoading && !error && displayOffers.length === 0 && totalCount > 0 ? (
              <tr>
                <td colSpan={OFFER_TABLE_COLUMNS.length} className="text-center text-secondary">
                  No offers match your search or filters.
                </td>
              </tr>
            ) : null}
            {!isLoading &&
              !error &&
              displayOffers.map((offer) => (
              <tr key={offer.id}>
                <td className="font-semibold" style={{ paddingLeft: '1.5rem' }}>
                  {offer.student_name}
                  {offer.roll_number ? <div className="text-xs text-tertiary font-mono">{offer.roll_number}</div> : null}
                </td>
                <td>{offer.college_name || '—'}</td>
                <td>{offer.job_title || '—'}</td>
                <td>{offer.salary ? formatCurrency(Number(offer.salary)) : '—'}</td>
                <td>{offer.location || '—'}</td>
                <td>{offer.deadline ? formatDate(offer.deadline) : '—'}</td>
                <td>
                  <span className={`badge badge-${getStatusColor(offer.status)} badge-dot`}>{formatStatus(offer.status)}</span>
                </td>
                <td style={{ paddingRight: '1.5rem' }}>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.35rem', alignItems: 'center' }}>
                    <StandardTableIconAction action="view" onClick={() => setViewRow(offer)} />
                    <StandardTableIconAction
                      action="edit"
                      onClick={() => {
                        setShowAdd(false);
                        openEdit(offer);
                      }}
                    />
                    <StandardTableIconAction action="delete" variant="danger" onClick={() => removeOffer(offer.id)} />
                  </div>
                </td>
              </tr>
            ))}
            {!isLoading && !error && offers.length === 0 ? (
              <tr>
                <td colSpan={OFFER_TABLE_COLUMNS.length} style={{ textAlign: 'center', padding: '3rem 2rem' }}>
                  <Send size={36} style={{ margin: '0 auto 0.75rem', opacity: 0.25 }} aria-hidden />
                  <div style={{ fontWeight: 600, color: 'var(--text-primary)', marginBottom: '0.25rem' }}>No offers yet</div>
                  <div style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>Use Add offer above to log off-platform placements.</div>
                </td>
              </tr>
            ) : null}
          </tbody>
        </table>
        </div>
      </div>

      {viewRow && (
        <div
          className="card"
          style={{
            marginTop: '1rem',
            border: '1px solid var(--border)',
            position: 'sticky',
            bottom: '1rem',
            zIndex: 2,
          }}
        >
          <div className="card-header" style={{ justifyContent: 'space-between' }}>
            <h3 className="card-title">Offer detail</h3>
            <button type="button" className="btn btn-secondary btn-sm" onClick={() => setViewRow(null)}>
              Close
            </button>
          </div>
          <div className="text-sm" style={{ lineHeight: 1.7 }}>
            <div>
              <strong>Student:</strong> {viewRow.student_name} ({viewRow.roll_number || '—'})
            </div>
            <div>
              <strong>College:</strong> {viewRow.college_name}
            </div>
            <div>
              <strong>Company:</strong>{' '}
              <CompanyNameLink name={viewRow.company_name} website={viewRow.company_website} />
            </div>
            <div>
              <strong>Role:</strong> {viewRow.job_title || '—'}
            </div>
            <div>
              <strong>Salary:</strong> {viewRow.salary ? formatCurrency(Number(viewRow.salary)) : '—'}
            </div>
            <div>
              <strong>Location:</strong> {viewRow.location || '—'}
            </div>
            <div>
              <strong>Deadline:</strong> {viewRow.deadline ? formatDate(viewRow.deadline) : '—'}
            </div>
            <div>
              <strong>Status:</strong> {formatStatus(viewRow.status)}
            </div>
            <div className="text-xs text-tertiary" style={{ marginTop: '0.5rem' }}>
              Linked employer account: {viewRow.linked_employer ? 'yes' : 'no (college-reported text company)'}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import useSWR from 'swr';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS } from '@/lib/tableQueryPresets';
import { ExportCsvSplitButton } from '@/components/export/ExportCsvSplitButton';
import { formatDate } from '@/lib/utils';
import { getCurrentAcademicYear } from '@/lib/academicYear';
import { BarChart2, TrendingUp, DollarSign, Building2, Trophy } from 'lucide-react';

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load reports');
  return json;
};

export default function CollegeReportsPage() {
  const { data, isLoading, error } = useSWR('/api/college/reports', fetcher);
  const DEPT_PLACEMENT = Array.isArray(data?.deptPlacement) ? data.deptPlacement : [];
  const SALARY_DIST = Array.isArray(data?.salaryDist) ? data.salaryDist : [];
  const TOP_RECRUITERS = Array.isArray(data?.topRecruiters) ? data.topRecruiters : [];
  const YOY = Array.isArray(data?.yoy) ? data.yoy : [];
  const STUDENT_COMPANY_EVENTS = Array.isArray(data?.studentCompanyEvents) ? data.studentCompanyEvents : [];
  const summary = data?.summary || { placementRate: 0, avgPackage: 0, highestPackage: 0, companiesVisited: 0 };
  const [studentReportCompany, setStudentReportCompany] = useState('');
  const [currentAcademicYear, setCurrentAcademicYear] = useState(getCurrentAcademicYear());

  const previousAcademicYear = useMemo(() => {
    const startYear = Number(currentAcademicYear.split('-')[0]);
    if (!Number.isFinite(startYear)) return '';
    const prevStart = startYear - 1;
    const prevEnd = String((prevStart + 1) % 100).padStart(2, '0');
    return `${prevStart}-${prevEnd}`;
  }, [currentAcademicYear]);

  useEffect(() => {
    if (typeof window === 'undefined') return undefined;
    const syncYear = () => { const saved = window.sessionStorage.getItem('activeAcademicYear'); if (saved) setCurrentAcademicYear(saved); };
    syncYear();
    window.addEventListener('placementhub-academic-year', syncYear);
    return () => window.removeEventListener('placementhub-academic-year', syncYear);
  }, []);

  const studentEventCompanies = useMemo(() => Array.from(new Set(STUDENT_COMPANY_EVENTS.map((r) => r.company))).sort(), [STUDENT_COMPANY_EVENTS]);
  const companyFilteredEvents = useMemo(
    () =>
      STUDENT_COMPANY_EVENTS.filter((r) => !studentReportCompany || r.company === studentReportCompany),
    [STUDENT_COMPANY_EVENTS, studentReportCompany],
  );
  const {
    search: studentReportSearch,
    setSearch: setStudentReportSearch,
    sort: studentReportSort,
    setSort: setStudentReportSort,
    filtered: filteredStudentEvents,
    filteredCount: studentEventsFilteredCount,
    totalCount: studentEventsTotalCount,
    hasActiveFilters: studentEventsHasActiveFilters,
    clearFilters: clearStudentEventsFilters,
  } = useDataTableQuery(companyFilteredEvents, {
    getSearchText: (r) => [r.student, r.roll, r.dept, r.company, r.eventType, r.outcome, r.attended].filter(Boolean).join(' '),
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'name_asc',
  });

  const reportExports = useMemo(() => [
    { id: 'dept', label: 'Department-wise placement', filename: 'reports_department_placement', rowCount: DEPT_PLACEMENT.length, getRows: () => ({ headers: ['Department', 'Placement_pct', 'Placed', 'Total'], rows: DEPT_PLACEMENT.map((d) => [d.dept, String(d.pct), String(d.placed), String(d.total)]) }) },
    { id: 'salary', label: 'Salary distribution', filename: 'reports_salary_distribution', rowCount: SALARY_DIST.length, getRows: () => ({ headers: ['Range', 'Students', 'Pct'], rows: SALARY_DIST.map((d) => [d.range, String(d.count), String(d.pct)]) }) },
    { id: 'recruiters', label: 'Top recruiters', filename: 'reports_top_recruiters', rowCount: TOP_RECRUITERS.length, getRows: () => ({ headers: ['Rank', 'Company', 'Hires', 'Avg_CTC'], rows: TOP_RECRUITERS.map((c, i) => [String(i + 1), c.name, String(c.hires), c.ctc]) }) },
    { id: 'yoy', label: 'Year-over-year comparison', filename: 'reports_yoy_comparison', rowCount: YOY.length, getRows: () => ({ headers: ['Metric', `Year_${previousAcademicYear.replace('-', '_')}`, `Year_${currentAcademicYear.replace('-', '_')}`, 'Change'], rows: YOY.map((r) => [r.metric, r.prev, r.curr, r.change]) }) },
    { id: 'student_events', label: 'Student–company events & outcomes', filename: 'reports_student_company_events', rowCount: STUDENT_COMPANY_EVENTS.length, getRows: () => ({ headers: ['Student', 'Roll', 'Dept', 'Company', 'Event', 'Event_date', 'Attended', 'Outcome'], rows: STUDENT_COMPANY_EVENTS.map((r) => [r.student, r.roll, r.dept, r.company, r.eventType, r.eventDate, r.attended, r.outcome]) }) },
  ], [DEPT_PLACEMENT, SALARY_DIST, TOP_RECRUITERS, YOY, STUDENT_COMPANY_EVENTS, previousAcademicYear, currentAcademicYear]);

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      {/* Glassmorphic Hero */}
      <div
        className="gradient-banner"
        style={{
        position: 'relative', background: 'var(--banner-gradient)',
        borderRadius: 'var(--radius-xl)', padding: '2.5rem', color: 'white', overflow: 'visible',
        marginBottom: '2.5rem', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)',
        display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1.5rem'
      }}>
        <div style={{ position: 'absolute', top: '-50px', right: '-50px', width: '250px', height: '250px', background: 'radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%)', borderRadius: '50%' }} />
        <div style={{ position: 'relative', zIndex: 1 }}>
          <h1 style={{ color: '#ffffff', fontSize: '2.25rem', fontWeight: 800, margin: '0 0 0.5rem', letterSpacing: '-0.02em', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <BarChart2 size={28} /> Reports & Analytics
          </h1>
          <p style={{ fontSize: '1rem', color: 'rgba(255,255,255,0.85)', margin: 0 }}>
            Placement season {currentAcademicYear} · Comprehensive analytics and exportable reports
          </p>
        </div>
        <div style={{ position: 'relative', zIndex: 1 }}>
          <ExportCsvSplitButton mode="multi" exportMenus={reportExports} />
        </div>
      </div>

      {isLoading && (
        <div className="grid grid-4" style={{ marginBottom: '2rem' }}>
          {[1,2,3,4].map(i => <div key={i} className="skeleton" style={{ height: 120, borderRadius: 'var(--radius-lg)' }} />)}
        </div>
      )}
      {error && <div className="card" style={{ padding: '1.5rem', background: 'var(--danger-50)', border: '1px solid var(--danger-200)', marginBottom: '1.5rem' }}><p style={{ margin: 0, color: 'var(--danger-700)', fontWeight: 600 }}>{error.message}</p></div>}

      {/* Summary KPI Cards */}
      <div className="grid grid-4" style={{ marginBottom: '2rem' }}>
        {[
          { label: 'Placement Rate', value: `${summary.placementRate}%`, icon: TrendingUp, color: 'var(--success-600)', bg: 'rgba(5,150,105,0.08)' },
          { label: 'Average Package', value: summary.avgPackage ? `₹${(summary.avgPackage / 100000).toFixed(1)}L` : '—', icon: DollarSign, color: 'var(--primary-600)', bg: 'var(--primary-50)' },
          { label: 'Highest Package', value: summary.highestPackage ? `₹${(summary.highestPackage / 100000).toFixed(1)}L` : '—', icon: TrendingUp, color: 'var(--warning-600)', bg: 'rgba(217,119,6,0.08)' },
          { label: 'Companies Visited', value: summary.companiesVisited || 0, icon: Building2, color: 'var(--info-600)', bg: 'rgba(2,132,199,0.08)' },
        ].map(({ label, value, icon: Icon, color, bg }) => (
          <div key={label} className="card" style={{ padding: '1.5rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1rem' }}>
              <div style={{ padding: '0.6rem', borderRadius: 'var(--radius-md)', background: bg, color }}><Icon size={22} strokeWidth={2} /></div>
            </div>
            <div style={{ fontSize: '2rem', fontWeight: 800, color: 'var(--text-primary)', lineHeight: 1 }}>{value}</div>
            <div style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', marginTop: '0.5rem', fontWeight: 500 }}>{label}</div>
          </div>
        ))}
      </div>

      {/* Student-level Events */}
      <div className="card" style={{ marginBottom: '2rem', border: '1px solid var(--border-default)', padding: 0, overflow: 'hidden' }}>
        <div style={{ padding: '1.5rem', borderBottom: '1px solid var(--border-default)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '1rem', background: 'var(--bg-secondary)' }}>
          <div>
            <h3 style={{ margin: 0, fontWeight: 800, fontSize: '1.1rem', color: 'var(--text-primary)' }}>Student-Level Events & Outcomes</h3>
            <p style={{ margin: '0.25rem 0 0', fontSize: '0.9rem', color: 'var(--text-secondary)' }}>Who attended which company touchpoints and the recorded outcome.</p>
          </div>
          <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap', alignItems: 'center' }}>
            <select className="form-select" style={{ width: 'auto' }} value={studentReportCompany} onChange={e => setStudentReportCompany(e.target.value)}>
              <option value="">All companies</option>
              {studentEventCompanies.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
        </div>
        {studentEventsTotalCount > 0 ? (
          <DataTableToolbar
            search={studentReportSearch}
            onSearchChange={setStudentReportSearch}
            searchPlaceholder="Search student, company, or outcome…"
            sort={studentReportSort}
            onSortChange={setStudentReportSort}
            sortOptions={COMMON_SORT_OPTIONS}
            filteredCount={studentEventsFilteredCount}
            totalCount={studentEventsTotalCount}
            hasActiveFilters={studentEventsHasActiveFilters}
            onClear={clearStudentEventsFilters}
            style={{ margin: '1rem 1.25rem 0', border: '1px solid var(--border-default)' }}
          />
        ) : null}
        <div className="table-container" style={{ border: 'none' }}>
          <table className="data-table">
            <thead><tr style={{ background: 'var(--bg-secondary)' }}><th style={{ paddingLeft: '1.5rem' }}>Student</th><th>Roll</th><th>Dept</th><th>Company</th><th>Event</th><th>Date</th><th>Attended</th><th style={{ paddingRight: '1.5rem' }}>Outcome</th></tr></thead>
            <tbody>
              {filteredStudentEvents.map((r, idx) => (
                <tr key={`${r.roll}-${r.company}-${r.eventType}-${idx}`}>
                  <td style={{ paddingLeft: '1.5rem', fontWeight: 600 }}>{r.student}</td>
                  <td style={{ fontFamily: 'monospace', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>{r.roll}</td>
                  <td style={{ fontSize: '0.9rem' }}>{r.dept}</td>
                  <td style={{ fontWeight: 500 }}>{r.company}</td>
                  <td><span className="badge badge-gray" style={{ fontSize: '0.75rem' }}>{r.eventType}</span></td>
                  <td style={{ fontSize: '0.875rem', color: 'var(--text-secondary)' }}>{formatDate(r.eventDate)}</td>
                  <td><span className={`badge ${r.attended === 'Yes' ? 'badge-green' : r.attended === 'No' ? 'badge-gray' : 'badge-indigo'}`} style={{ fontSize: '0.75rem' }}>{r.attended}</span></td>
                  <td style={{ paddingRight: '1.5rem', fontSize: '0.9rem' }}>{r.outcome}</td>
                </tr>
              ))}
              {filteredStudentEvents.length === 0 && <tr><td colSpan={8} style={{ textAlign: 'center', padding: '3rem', color: 'var(--text-tertiary)' }}>{studentEventsTotalCount > 0 ? 'No rows match your search.' : 'No data found.'}</td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      {/* Analytics Grid */}
      <div className="grid grid-2" style={{ gap: '1.5rem' }}>
        {/* Dept Placement */}
        <div className="card" style={{ border: '1px solid var(--border-default)' }}>
          <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid var(--border-default)', background: 'var(--bg-secondary)' }}>
            <h3 style={{ margin: 0, fontWeight: 800, fontSize: '1rem', color: 'var(--text-primary)' }}>Department-wise Placement Rate</h3>
          </div>
          <div style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            {DEPT_PLACEMENT.map(d => (
              <div key={d.dept}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.4rem' }}>
                  <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>{d.dept}</span>
                  <span style={{ fontSize: '0.85rem', fontWeight: 700, color: d.pct >= 80 ? 'var(--success-600)' : d.pct >= 50 ? 'var(--warning-600)' : 'var(--danger-600)' }}>{d.placed}/{d.total} ({d.pct}%)</span>
                </div>
                <div style={{ height: 8, background: 'var(--gray-200)', borderRadius: 999, overflow: 'hidden' }}>
                  <div style={{ height: '100%', width: `${d.pct}%`, background: d.pct >= 80 ? 'var(--success-500)' : d.pct >= 50 ? 'var(--warning-500)' : 'var(--danger-500)', borderRadius: 999 }} />
                </div>
              </div>
            ))}
            {DEPT_PLACEMENT.length === 0 && <p className="text-secondary text-sm" style={{ margin: 0 }}>No department data yet.</p>}
          </div>
        </div>

        {/* Salary Dist */}
        <div className="card" style={{ border: '1px solid var(--border-default)' }}>
          <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid var(--border-default)', background: 'var(--bg-secondary)' }}>
            <h3 style={{ margin: 0, fontWeight: 800, fontSize: '1rem', color: 'var(--text-primary)' }}>Salary Distribution</h3>
          </div>
          <div style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            {SALARY_DIST.map(d => (
              <div key={d.range}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.4rem' }}>
                  <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>{d.range}</span>
                  <span style={{ fontSize: '0.85rem', fontWeight: 700, color: 'var(--text-secondary)' }}>{d.count} students ({d.pct}%)</span>
                </div>
                <div style={{ height: 8, background: 'var(--gray-200)', borderRadius: 999, overflow: 'hidden' }}>
                  <div style={{ height: '100%', width: `${Math.min(100, d.pct * 2.5)}%`, background: 'linear-gradient(90deg, var(--primary-500), var(--primary-600))', borderRadius: 999 }} />
                </div>
              </div>
            ))}
            {SALARY_DIST.length === 0 && <p className="text-secondary text-sm" style={{ margin: 0 }}>No salary data yet.</p>}
          </div>
        </div>

        {/* Top Recruiters */}
        <div className="card" style={{ padding: 0, overflow: 'hidden', border: '1px solid var(--border-default)' }}>
          <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid var(--border-default)', background: 'var(--bg-secondary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Trophy size={18} style={{ color: 'var(--warning-500)' }} />
            <h3 style={{ margin: 0, fontWeight: 800, fontSize: '1rem', color: 'var(--text-primary)' }}>Top Recruiters</h3>
          </div>
          <div className="table-container" style={{ border: 'none' }}>
            <table className="data-table">
              <thead><tr style={{ background: 'var(--bg-secondary)' }}><th style={{ width: 40, paddingLeft: '1.5rem' }}>#</th><th>Company</th><th style={{ textAlign: 'right' }}>Hires</th><th style={{ textAlign: 'right', paddingRight: '1.5rem' }}>Avg CTC</th></tr></thead>
              <tbody>
                {TOP_RECRUITERS.map((c, i) => (
                  <tr key={c.name}>
                    <td style={{ paddingLeft: '1.5rem', fontWeight: 700, color: i === 0 ? 'var(--warning-600)' : 'var(--text-tertiary)' }}>{i + 1}</td>
                    <td style={{ fontWeight: 600 }}>{c.name}</td>
                    <td style={{ textAlign: 'right', fontWeight: 700 }}>{c.hires}</td>
                    <td style={{ textAlign: 'right', paddingRight: '1.5rem', fontWeight: 700, color: 'var(--success-600)' }}>{c.ctc}</td>
                  </tr>
                ))}
                {TOP_RECRUITERS.length === 0 && <tr><td colSpan={4} style={{ textAlign: 'center', padding: '2rem', color: 'var(--text-tertiary)' }}>No data yet.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>

        {/* YoY */}
        <div className="card" style={{ padding: 0, overflow: 'hidden', border: '1px solid var(--border-default)' }}>
          <div style={{ padding: '1.25rem 1.5rem', borderBottom: '1px solid var(--border-default)', background: 'var(--bg-secondary)' }}>
            <h3 style={{ margin: 0, fontWeight: 800, fontSize: '1rem', color: 'var(--text-primary)' }}>Year-over-Year Comparison</h3>
          </div>
          <div className="table-container" style={{ border: 'none' }}>
            <table className="data-table">
              <thead><tr style={{ background: 'var(--bg-secondary)' }}><th style={{ paddingLeft: '1.5rem' }}>Metric</th><th>{previousAcademicYear}</th><th>{currentAcademicYear}</th><th style={{ paddingRight: '1.5rem' }}>Change</th></tr></thead>
              <tbody>
                {YOY.map(r => (
                  <tr key={r.metric}>
                    <td style={{ paddingLeft: '1.5rem', fontWeight: 600 }}>{r.metric}</td>
                    <td style={{ color: 'var(--text-secondary)' }}>{r.prev}</td>
                    <td style={{ fontWeight: 700 }}>{r.curr}</td>
                    <td style={{ paddingRight: '1.5rem' }}>
                      <span style={{ fontSize: '0.85rem', fontWeight: 700, color: r.up ? 'var(--success-600)' : 'var(--danger-600)' }}>{r.up ? '↑' : '↓'} {r.change}</span>
                    </td>
                  </tr>
                ))}
                {YOY.length === 0 && <tr><td colSpan={4} style={{ textAlign: 'center', padding: '2rem', color: 'var(--text-tertiary)' }}>No data yet.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';
import { useEffect, useMemo, useState } from 'react';
import useSWR from 'swr';
import MobileHeader from '@/components/mobile/MobileHeader';
import { getCurrentAcademicYear } from '@/lib/academicYear';
import { BarChart2, TrendingUp, DollarSign, Building2, Trophy, Search, Download } from 'lucide-react';
import { formatDate } from '@/lib/utils';
import { useToast } from '@/components/ToastProvider';

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load reports');
  return json;
};

export default function mb_Reports() {
  const { addToast } = useToast();
  const { data, isLoading, error } = useSWR('/api/college/reports', fetcher);
  const [activeTab, setActiveTab] = useState('overview');
  const [studentReportSearch, setStudentReportSearch] = useState('');
  const [currentAcademicYear, setCurrentAcademicYear] = useState(getCurrentAcademicYear());

  const DEPT_PLACEMENT = Array.isArray(data?.deptPlacement) ? data.deptPlacement : [];
  const SALARY_DIST = Array.isArray(data?.salaryDist) ? data.salaryDist : [];
  const TOP_RECRUITERS = Array.isArray(data?.topRecruiters) ? data.topRecruiters : [];
  const YOY = Array.isArray(data?.yoy) ? data.yoy : [];
  const STUDENT_COMPANY_EVENTS = Array.isArray(data?.studentCompanyEvents) ? data.studentCompanyEvents : [];
  const summary = data?.summary || { placementRate: 0, avgPackage: 0, highestPackage: 0, companiesVisited: 0 };

  const previousAcademicYear = useMemo(() => {
    const startYear = Number(currentAcademicYear.split('-')[0]);
    if (!Number.isFinite(startYear)) return '';
    const prevStart = startYear - 1;
    const prevEnd = String((prevStart + 1) % 100).padStart(2, '0');
    return `${prevStart}-${prevEnd}`;
  }, [currentAcademicYear]);

  useEffect(() => {
    if (typeof window === 'undefined') return undefined;
    const syncYear = () => { const saved = window.sessionStorage.getItem('activeAcademicYear'); if (saved) setCurrentAcademicYear(saved); };
    syncYear();
    window.addEventListener('placementhub-academic-year', syncYear);
    return () => window.removeEventListener('placementhub-academic-year', syncYear);
  }, []);

  const filteredStudentEvents = useMemo(() => {
    const q = studentReportSearch.trim().toLowerCase();
    if (!q) return STUDENT_COMPANY_EVENTS.slice(0, 50); // Limit initial view
    return STUDENT_COMPANY_EVENTS.filter((r) => 
      r.student.toLowerCase().includes(q) || r.roll.toLowerCase().includes(q) || r.company.toLowerCase().includes(q) || r.eventType.toLowerCase().includes(q)
    ).slice(0, 50);
  }, [STUDENT_COMPANY_EVENTS, studentReportSearch]);

  const handleExportMobile = () => {
    addToast('Use the desktop view to download comprehensive CSV reports.', 'info');
  };

  const tabs = [
    { id: 'overview', label: 'Overview' },
    { id: 'charts', label: 'Stats' },
    { id: 'events', label: 'Events' }
  ];

  return (
    <>
      <MobileHeader 
        title="Reports" 
        action={
          <button className="btn btn-ghost btn-sm" onClick={handleExportMobile} style={{ padding: '0.4rem', color: 'var(--primary-600)' }}>
            <Download size={18} />
          </button>
        } 
      />
      
      <div className="animate-fadeIn" style={{ padding: '1rem 1rem 5rem 1rem' }}>
        <div style={{ display: 'flex', gap: '0.25rem', marginBottom: '1.25rem', background: 'var(--bg-secondary)', padding: '0.25rem', borderRadius: '12px', border: '1px solid var(--border-default)' }}>
          {tabs.map(({ id, label }) => (
            <button 
              key={id} 
              type="button" 
              onClick={() => setActiveTab(id)} 
              style={{ flex: 1, padding: '0.65rem 0', borderRadius: '8px', border: 'none', background: activeTab === id ? 'var(--primary-600)' : 'transparent', color: activeTab === id ? 'white' : 'var(--text-secondary)', fontWeight: activeTab === id ? 700 : 500, cursor: 'pointer', fontSize: '0.85rem', transition: 'all 0.2s' }}
            >
              {label}
            </button>
          ))}
        </div>

        {isLoading && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            {[1, 2, 3].map(i => <div key={i} className="skeleton" style={{ height: 100, borderRadius: '12px' }} />)}
          </div>
        )}

        {error && (
          <div className="card" style={{ padding: '1rem', background: 'var(--danger-50)', border: '1px solid var(--danger-200)', textAlign: 'center' }}>
            <p style={{ margin: 0, color: 'var(--danger-700)', fontWeight: 600 }}>{error.message}</p>
          </div>
        )}

        {!isLoading && !error && activeTab === 'overview' && (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
            {[
              { label: 'Placement Rate', value: `${summary.placementRate}%`, icon: TrendingUp, color: 'var(--success-600)', bg: 'rgba(5,150,105,0.08)' },
              { label: 'Avg Package', value: summary.avgPackage ? `₹${(summary.avgPackage / 100000).toFixed(1)}L` : '—', icon: DollarSign, color: 'var(--primary-600)', bg: 'var(--primary-50)' },
              { label: 'High Package', value: summary.highestPackage ? `₹${(summary.highestPackage / 100000).toFixed(1)}L` : '—', icon: TrendingUp, color: 'var(--warning-600)', bg: 'rgba(217,119,6,0.08)' },
