                <div>
                  <div style={{ fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--text-tertiary)', marginBottom: '0.3rem', display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                    <Calendar size={11} /> Date
                  </div>
                  <div style={{ fontWeight: 600, fontSize: '0.9rem', color: 'var(--text-primary)' }}>
                    {drive.date ? formatDate(drive.date) : '—'}
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--text-tertiary)', marginBottom: '0.3rem' }}>Type</div>
                  <DriveTypeBadge type={drive.type} />
                </div>
                <div>
                  <div style={{ fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--text-tertiary)', marginBottom: '0.3rem' }}>Venue</div>
                  <div style={{ fontWeight: 600, fontSize: '0.9rem', color: drive.venue?.trim() ? 'var(--text-primary)' : 'var(--text-tertiary)' }}>
                    {drive.venue?.trim() || '—'}
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--text-tertiary)', marginBottom: '0.3rem', display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                    <Users size={11} /> Registered
                  </div>
                  <div style={{ fontWeight: 600, fontSize: '0.9rem', color: 'var(--text-primary)' }}>
                    {drive.registered ?? 0} students
                  </div>
                </div>
              </div>

              {/* CTC breakup (internal) */}
              {(drive.ctc_breakup || drive.ctcBreakup) && (
                <div style={{ marginTop: '0.85rem', paddingTop: '0.85rem', borderTop: '1px dashed var(--border-default)' }}>
                  <div style={{ fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--text-tertiary)', marginBottom: '0.35rem' }}>
                    CTC breakup (internal)
                  </div>
                  <p style={{ margin: 0, fontSize: '0.875rem', whiteSpace: 'pre-wrap', lineHeight: 1.5, color: 'var(--text-secondary)' }}>
                    {drive.ctc_breakup || drive.ctcBreakup}
                  </p>
                  <p style={{ margin: '0.35rem 0 0', fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>
                    Not shown to the college in the dashboard.
                  </p>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {!isLoading && filteredDrives.length === 0 && (
        <div style={{
          textAlign: 'center', padding: '4rem 2rem',
          background: 'var(--bg-secondary)', borderRadius: 'var(--radius-xl)',
          border: '1px dashed var(--border-default)',
        }}>
          <div style={{ background: 'var(--primary-50)', width: '68px', height: '68px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.25rem' }}>
            <Target size={30} style={{ color: 'var(--primary-500)' }} />
          </div>
          <h3 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--text-primary)', marginBottom: '0.5rem' }}>
            {allDrives.length === 0 ? 'No placement drives found' : 'No drives match your filters'}
          </h3>
          <p style={{ color: 'var(--text-secondary)', fontSize: '0.95rem', maxWidth: '420px', margin: '0 auto 1.5rem', lineHeight: 1.6 }}>
            {allDrives.length === 0
              ? (campusFilterActive
                ? `No drives found for the selected campus${selectedIds.size > 1 ? 'es' : ''}. Try a different filter or request a new drive.`
                : 'No drives scheduled yet. Request a placement drive with one of your approved partner campuses.')
              : 'Try adjusting search, status, date, or campus filters to see more results.'}
          </p>
          {allDrives.length === 0 ? (
            <Link href="/dashboard/employer/drives/request" className="btn btn-primary">
              Request New Drive
            </Link>
          ) : (
            <button type="button" className="btn btn-secondary" onClick={clearFilters}>
              Clear filters
            </button>
          )}
        </div>
      )}

      {viewDrive ? (
        <DriveDetailsDialog drive={viewDrive} onClose={() => setViewDrive(null)} />
      ) : null}

    </div>
  );
}

function DriveDetailsDialog({ drive, onClose }) {
  const ctcBreakup = drive.ctc_breakup || drive.ctcBreakup;
  const jobType = drive.job_type || drive.jobType;
  const skills = drive.skills_required || drive.skillsRequired;
  const locations = drive.locations;
  const { numeric: salaryLabel, words: salaryWords } = formatSalaryRangeParts(
    drive.salary_min ?? drive.salaryMin,
    drive.salary_max ?? drive.salaryMax,
  );
  const modalBackdrop = {
    position: 'fixed',
    inset: 0,
    zIndex: 200,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '1rem',
    background: 'rgba(15, 23, 42, 0.55)',
  };

  return (
    <div style={modalBackdrop} role="presentation" onClick={onClose}>
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="drive-details-title"
        className="card"
        style={{
          maxWidth: 520,
          width: '100%',
          maxHeight: '90vh',
          overflow: 'auto',
          padding: '1.25rem',
          position: 'relative',
          border: '1px solid var(--border-default)',
          boxShadow: 'var(--shadow-lg)',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        <button
          type="button"
          className="btn btn-ghost btn-sm"
          aria-label="Close"
          style={{ position: 'absolute', top: '0.75rem', right: '0.75rem' }}
          onClick={onClose}
        >
          <X size={18} />
        </button>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1rem', paddingRight: '2rem' }}>
          <EntityLogo name={drive.college} size="sm" shape="rounded" />
          <div>
            <p className="text-sm text-secondary" style={{ margin: 0 }}>
              {drive.college}
            </p>
            <h2 id="drive-details-title" style={{ fontSize: '1.1rem', margin: '0.25rem 0 0' }}>
              {drive.role}
            </h2>
          </div>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: '0.85rem' }}>
          <div>
            <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Status</div>
            <span className={`badge badge-${getStatusColor(drive.status)} badge-dot`}>{formatStatus(drive.status)}</span>
          </div>
          <div>
            <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Drive date</div>
            <div className="text-sm font-semibold">{drive.date ? formatDate(drive.date) : '—'}</div>
          </div>
          <div>
            <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Type</div>
            <DriveTypeBadge type={drive.type} />
          </div>
          <div>
            <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Registered</div>
            <div className="text-sm font-semibold">{drive.registered ?? 0} students</div>
          </div>
          <div style={{ gridColumn: '1 / -1' }}>
            <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Venue</div>
            <div className="text-sm">{drive.venue?.trim() || '—'}</div>
          </div>
        </div>

        {(drive.description || '').trim() ? (
          <DriveDetailsSection title="Job description">
            <p style={{ margin: 0, fontSize: '0.875rem', whiteSpace: 'pre-wrap', lineHeight: 1.5, color: 'var(--text-secondary)' }}>
              {drive.description.trim()}
            </p>
          </DriveDetailsSection>
        ) : null}

        <DriveDetailsSection title="Role & compensation">
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: '0.75rem' }}>
            <div>
              <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Role type</div>
              <div className="text-sm font-semibold">
                {PLACEMENT_DRIVE_JOB_TYPE_LABELS[jobType] || jobType || '—'}
              </div>
            </div>
            <div>
              <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Openings</div>
              <div className="text-sm font-semibold">{drive.max_students ?? drive.vacancies ?? '—'}</div>
            </div>
            <div>
              <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>CTC band (public)</div>
              <div className="text-sm font-semibold">{salaryLabel}</div>
              {salaryWords ? (
                <div className="text-xs text-secondary" style={{ marginTop: '0.25rem', lineHeight: 1.4 }}>
                  {salaryWords}
                </div>
              ) : null}
            </div>
            <div>
              <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Skills</div>
              <div className="text-sm">{Array.isArray(skills) && skills.length ? skills.join(', ') : '—'}</div>
            </div>
            {Array.isArray(locations) && locations.length ? (
              <div style={{ gridColumn: '1 / -1' }}>
                <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Work locations</div>
                <div className="text-sm">{locations.join(', ')}</div>
              </div>
            ) : null}
          </div>
        </DriveDetailsSection>

        <DriveDetailsSection title="Eligibility">
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: '0.75rem' }}>
            <div>
              <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Minimum CGPA</div>
              <div className="text-sm font-semibold">
                {formatEmployerMinCgpa(drive.min_cgpa ?? drive.minCgpa)}
              </div>
            </div>
            <div>
              <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Eligible branches</div>
              <div className="text-sm font-semibold">
                {formatEligibleBranchesLabel(drive.eligible_branches ?? drive.eligibleBranches)}
              </div>
            </div>
            <div>
              <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Max backlogs</div>
              <div className="text-sm font-semibold">
                {drive.max_backlogs ?? drive.maxBacklogs ?? '—'}
              </div>
            </div>
            <div>
              <div className="text-xs text-secondary" style={{ marginBottom: '0.25rem' }}>Batch year</div>
              <div className="text-sm font-semibold">{drive.batch_year ?? drive.batchYear ?? '—'}</div>
            </div>
          </div>
          {formatEmployerMinCgpa(drive.min_cgpa ?? drive.minCgpa) === '—' ? (
            <p className="text-xs text-secondary" style={{ margin: '0.65rem 0 0' }}>
              No drive-specific eligibility criteria set — campus placement rules still apply.
            </p>
          ) : null}
        </DriveDetailsSection>

        {ctcBreakup ? (
          <DriveDetailsSection title="Compensation (internal)">
            <p style={{ margin: 0, fontSize: '0.875rem', whiteSpace: 'pre-wrap', lineHeight: 1.5, color: 'var(--text-secondary)' }}>
              {ctcBreakup}
            </p>
            <p className="text-xs text-tertiary" style={{ margin: '0.35rem 0 0' }}>
              Not shown to the college in the dashboard.
            </p>
          </DriveDetailsSection>
        ) : null}
        <div style={{ marginTop: '1.25rem', display: 'flex', gap: '0.5rem', flexWrap: 'wrap', justifyContent: 'flex-end' }}>
          {canReviewApplicants(drive) ? (
            <Link
              href={`/dashboard/employer/applications?tab=drives&driveId=${encodeURIComponent(drive.id)}`}
              className="btn btn-primary btn-sm"
            >
              Review applications
            </Link>
          ) : null}
          {canEditDrive(drive) ? (
            <Link href={`/dashboard/employer/drives/edit/${drive.id}`} className="btn btn-secondary btn-sm">
              Edit drive
            </Link>
          ) : null}
          <button type="button" className="btn btn-secondary btn-sm" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState, useCallback } from 'react';
import Link from 'next/link';
import { Briefcase, FolderDot, GraduationCap, Target } from 'lucide-react';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS } from '@/lib/tableQueryPresets';
import { ExportCsvSplitButton } from '@/components/export/ExportCsvSplitButton';
import { HiringResultBreakdown } from '@/components/assessment/HiringResultBreakdown';
import { useToast } from '@/components/ToastProvider';
import { pickRepresentativeAssessmentRows, buildAssessmentSummary } from '@/lib/assessmentHiringViewShared';
import { toCsvIsoDate } from '@/lib/csvExport';
import { shouldShowFilterCount } from '@/lib/filterBadgeLabel';

const KIND_TABS = [
  { id: 'internship', label: 'Internship', icon: GraduationCap },
  { id: 'drive', label: 'Drive', icon: Target },
  { id: 'projects', label: 'Projects', icon: FolderDot },
];

export default function EmployerHiringAssessmentPage() {
  const { addToast } = useToast();
  const [campusesLoading, setCampusesLoading] = useState(true);
  const [approvedCampuses, setApprovedCampuses] = useState([]);
  const [selectedTenantId, setSelectedTenantId] = useState('');
  const [kindTab, setKindTab] = useState('internship');
  const [loading, setLoading] = useState(false);
  const [payload, setPayload] = useState(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      setCampusesLoading(true);
      try {
        const res = await fetch('/api/employer/campuses');
        const json = await res.json();
        if (!res.ok) throw new Error(json?.error || 'Failed to load campuses');
        const list = Array.isArray(json.colleges) ? json.colleges : [];
        const approved = list.filter((c) => String(c.approval_status || '').toLowerCase() === 'approved');
        if (!mounted) return;
        setApprovedCampuses(approved);
        if (approved.length && !selectedTenantId) {
          setSelectedTenantId(approved[0].id);
        }
      } catch (e) {
        if (!mounted) return;
        setApprovedCampuses([]);
        addToast(e.message || 'Could not load campuses', 'error');
      } finally {
        if (mounted) setCampusesLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!selectedTenantId) {
      setPayload(null);
      return;
    }
    let mounted = true;
    setLoading(true);
    (async () => {
      try {
        const res = await fetch(`/api/employer/hiring-assessment-view?tenantId=${encodeURIComponent(selectedTenantId)}`);
        const json = await res.json();
        if (!res.ok) throw new Error(json?.error || 'Failed to load');
        if (!mounted) return;
        setPayload(json);
      } catch (e) {
        if (!mounted) return;
        setPayload(null);
        addToast(e.message || 'Could not load assessment view', 'error');
      } finally {
        if (mounted) setLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
  }, [selectedTenantId, addToast]);

  const allRows = Array.isArray(payload?.rows) ? payload.rows : [];

  const kindCounts = useMemo(() => {
    const counts = { internship: 0, jobs: 0, drive: 0, projects: 0 };
    for (const r of pickRepresentativeAssessmentRows(allRows)) {
      const k = r.opportunity_kind;
      if (k && counts[k] !== undefined) counts[k] += 1;
    }
    return counts;
  }, [allRows]);

  const scopedRows = useMemo(
    () => allRows.filter((r) => r.opportunity_kind === kindTab),
    [allRows, kindTab],
  );

  const baseDisplayRows = useMemo(() => pickRepresentativeAssessmentRows(scopedRows), [scopedRows]);

  const summary = useMemo(() => buildAssessmentSummary(scopedRows), [scopedRows]);

  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered: displayRows,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(baseDisplayRows, {
    getSearchText: (r) =>
      [r.system_id, r.roll_number, r.candidate_name, r.original_file_name, r.remarks].filter(Boolean).join(' '),
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'name_asc',
  });

  const getCsv = useCallback(
    (_scope) => ({
      headers: [
        'upload_file',
        'upload_at',
        'campus',
        'system_id',
        'roll_number',
        'candidate_name',
        'employer_company',
        'hiring_result',
        'submission_status',
        'remarks',
      ],
      rows: displayRows.map((r) => [
        r.original_file_name ?? '',
        toCsvIsoDate(r.upload_created_at),
        r.tenant_name ?? '',
        r.system_id ?? '',
        r.roll_number ?? '',
        r.candidate_name ?? '',
        r.employer_company ?? '',
        r.hiring_result ?? '',
        r.submission_status ?? 'draft',
        r.remarks ?? '',
      ]),
    }),
    [displayRows],
  );

  return (
    <div className="animate-fadeIn">
      <div className="page-header">
        <div className="page-header-left">
          <h1>Hiring Results Dashboard</h1>
        </div>
        <div className="page-header-actions">
          <ExportCsvSplitButton
            filenameBase={`hiring_results_${kindTab}`}
            currentCount={displayRows.length}
            fullCount={displayRows.length}
            getRows={getCsv}
          />
        </div>
      </div>

      <div className="card" style={{ marginBottom: '1rem' }}>
        <div className="form-group" style={{ marginBottom: 0, maxWidth: '70ch' }}>
          <label className="form-label" htmlFor="hiring-results-campus">
            Campus
          </label>
          <select
            id="hiring-results-campus"
            className="form-select"
            value={selectedTenantId}
            disabled={campusesLoading || approvedCampuses.length === 0}
            onChange={(e) => setSelectedTenantId(e.target.value)}
            style={{ maxWidth: '70ch' }}
          >
            {approvedCampuses.length === 0 ? (
              <option value="">{campusesLoading ? 'Loading…' : 'No approved campuses'}</option>
            ) : (
              approvedCampuses.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name}
                  {c.city ? ` (${c.city})` : ''}
                </option>
              ))
            )}
          </select>
        </div>
      </div>

      <div
        role="tablist"
        aria-label="Opportunity type"
        style={{ display: 'flex', gap: '0.75rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}
      >
        {KIND_TABS.map((t) => {
          const Icon = t.icon;
          const active = kindTab === t.id;
          const n = kindCounts[t.id] ?? 0;
          return (
            <button
              key={t.id}
              type="button"
              role="tab"
              aria-selected={active}
              onClick={() => setKindTab(t.id)}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '0.5rem',
                padding: '0.6rem 1.25rem',
                borderRadius: '999px',
                fontWeight: 700,
                fontSize: '0.9rem',
                transition: 'background 0.2s ease-out, color 0.2s ease-out, box-shadow 0.2s ease-out',
                border: 'none',
                cursor: 'pointer',
                background: active ? 'var(--primary-600)' : 'var(--bg-secondary)',
                color: active ? 'white' : 'var(--text-secondary)',
                boxShadow: active ? '0 4px 10px rgba(79, 70, 229, 0.25)' : 'none',
              }}
            >
              <Icon size={16} strokeWidth={active ? 2.5 : 1.75} aria-hidden />
              {t.label}
              {shouldShowFilterCount(n) ? (
                <span
                  style={{
                    opacity: 0.85,
                    fontSize: '0.75rem',
                    background: active ? 'rgba(255,255,255,0.25)' : 'var(--bg-primary)',
                    borderRadius: '999px',
                    padding: '0.1rem 0.45rem',
                    fontWeight: 700,
                    color: active ? 'white' : 'var(--text-tertiary)',
                  }}
                >
                  {n}
                </span>
              ) : null}
            </button>
          );
        })}
      </div>

      {loading ? (
        <div className="skeleton skeleton-card" style={{ height: 200 }} />
      ) : (
        <>
          <div className="grid grid-3" style={{ marginBottom: '1.25rem' }}>
            <div className="stats-card">
              <div className="stats-card-value">{summary.uniqueStudentCount ?? 0}</div>
              <div className="stats-card-label">Total students</div>
              <div className="text-xs text-tertiary" style={{ marginTop: '0.25rem' }}>
                Distinct students (this campus · {KIND_TABS.find((t) => t.id === kindTab)?.label})
                {summary.totalResultRows > 0 ? (
                  <>
                    <br />
                    {summary.totalResultRows} row{summary.totalResultRows === 1 ? '' : 's'} across uploads
                  </>
                ) : null}
              </div>
            </div>
            <div className="stats-card">
              <div className="stats-card-value">{summary.uploadsCount}</div>
              <div className="stats-card-label">Upload batches</div>
              <div className="text-xs text-tertiary" style={{ marginTop: '0.25rem' }}>
                Distinct CSV uploads represented
              </div>
            </div>
            <div className="stats-card">
              <div className="stats-card-value">{summary.withHiringResult ?? 0}</div>
              <div className="stats-card-label">With hiring result</div>
              <div className="text-xs text-tertiary" style={{ marginTop: '0.25rem' }}>
                {summary.withoutHiringResult ?? 0} with no decision yet
              </div>
            </div>
          </div>

          <HiringResultBreakdown summary={summary} />

          <div className="card">
            <h3 className="card-title" style={{ marginBottom: '0.75rem' }}>
              Detail
            </h3>
            {totalCount > 0 ? (
              <DataTableToolbar
                search={search}
                onSearchChange={setSearch}
                searchPlaceholder="Search roll, candidate, or file…"
                sort={sort}
                onSortChange={setSort}
                sortOptions={COMMON_SORT_OPTIONS}
                filteredCount={filteredCount}
                totalCount={totalCount}
                hasActiveFilters={hasActiveFilters}
                onClear={clearFilters}
                style={{ marginBottom: '1rem' }}
              />
            ) : null}
            <div className="table-container" style={{ overflowX: 'auto', border: 'none' }}>
              <table className="data-table" style={{ minWidth: 900 }}>
                <thead>
                  <tr>
                    <th>File</th>
                    <th>System ID</th>
                    <th>Roll</th>
                    <th>Candidate</th>
                    <th>Hiring result</th>
                    <th>Status</th>
                    <th>Remarks</th>
                  </tr>
                </thead>
                <tbody>
                  {displayRows.length === 0 && totalCount > 0 ? (
                    <tr>
                      <td colSpan={7} className="text-center text-secondary">
                        No rows match your search.
                      </td>
                    </tr>
                  ) : null}
                  {displayRows.map((r) => (
                    <tr key={r.id}>
                      <td className="text-xs">{r.original_file_name || '—'}</td>
                      <td className="font-mono text-sm">{r.system_id || '—'}</td>
                      <td className="font-mono text-sm">{r.roll_number || '—'}</td>
                      <td className="text-sm">{r.candidate_name || '—'}</td>
                      <td className="text-sm">{r.hiring_result || '—'}</td>
                      <td className="text-sm">
                        <span className="badge badge-secondary" style={{ textTransform: 'capitalize' }}>
                          {r.submission_status || 'draft'}
                        </span>
                      </td>
                      <td className="text-sm" style={{ maxWidth: 220 }}>
                        {r.remarks || '—'}
                      </td>
                    </tr>
                  ))}
                  {totalCount === 0 && (
                    <tr>
                      <td colSpan={7} className="text-center text-secondary">
                        No assessment rows for this campus and type yet. Upload a CSV under{' '}
                        <Link href="/dashboard/employer/assessment-uploads">Assessment uploads</Link>.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import useSWR from 'swr';
import Link from 'next/link';
import { Award } from 'lucide-react';
import PageLoading from '@/components/PageLoading';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { SORT_DATE_ASC, SORT_DATE_DESC } from '@/lib/dataTableQuery';
import { useToast } from '@/components/ToastProvider';
import { employerPpoStatusLabel } from '@/lib/internshipPpo';
import { templateMatchesEventTab } from '@/lib/offerEventType';
import { formatDate, formatStatus } from '@/lib/utils';

const PPO_SORT_OPTIONS = [
  {
    value: 'name_asc',
    label: 'Student (A → Z)',
    compare: (a, b) =>
      String(a?.studentName ?? '').localeCompare(String(b?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  {
    value: 'name_desc',
    label: 'Student (Z → A)',
    compare: (a, b) =>
      String(b?.studentName ?? '').localeCompare(String(a?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  SORT_DATE_DESC,
  SORT_DATE_ASC,
];

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load');
  return json;
};

export default function EmployerInternshipPpoPage() {
  const { addToast } = useToast();
  const { data, error, isLoading, mutate } = useSWR('/api/employer/internship-ppo', fetcher);
  const { data: templatesData } = useSWR('/api/employer/offer-templates', fetcher);
  const [busyId, setBusyId] = useState(null);
  const [confirmingId, setConfirmingId] = useState(null);
  const [generatingId, setGeneratingId] = useState(null);
  const [employerNotes, setEmployerNotes] = useState('');
  const [templateId, setTemplateId] = useState('');

  const items = Array.isArray(data?.items) ? data.items : [];
  const summary = data?.summary || { total: 0, withPpo: 0, awaitingStudent: 0, accepted: 0, jobOfferIssued: 0 };
  const templates = (templatesData?.templates || templatesData?.items || [])
    .filter((t) => t.is_active !== false)
    .filter((t) => templateMatchesEventTab(t, 'internship'));

  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(items, {
    getSearchText: (r) =>
      [r.studentName, r.rollNumber, r.openingTitle, employerPpoStatusLabel(r.ppo?.status)].filter(Boolean).join(' '),
    sortOptions: PPO_SORT_OPTIONS,
    defaultSort: 'name_asc',
  });

  const postAction = async (programApplicationId, payload) => {
    setBusyId(programApplicationId);
    try {
      const res = await fetch('/api/employer/internship-ppo', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ programApplicationId, ...payload }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Action failed');
      addToast(json.message || 'Saved.', 'success');
      setConfirmingId(null);
      setGeneratingId(null);
      setEmployerNotes('');
      setTemplateId('');
      await mutate();
    } catch (e) {
      addToast(e.message || 'Action failed', 'error');
    } finally {
      setBusyId(null);
    }
  };

  const statLine = useMemo(
    () =>
      `${summary.withPpo} of ${summary.total} intern(s) with PPO activity · ${summary.awaitingStudent} awaiting student · ${summary.jobOfferIssued} job offer(s) issued`,
    [summary],
  );

  if (isLoading) return <PageLoading message="Loading interns…" variant="skeleton-card" />;

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      <div className="page-header" style={{ marginBottom: '1.5rem' }}>
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: 0 }}>
            <Award size={26} aria-hidden />
            Internship PPO
          </h1>
          <p className="text-secondary" style={{ margin: '0.35rem 0 0', lineHeight: 1.55 }}>
            Pre-Placement Offer (PPO) is a <strong>full-time job offer after internship</strong> based on performance — not
            the internship selection offer (use <Link href="/dashboard/employer/offers">Offers → Internship</Link> for that).
            Confirm PPO per intern on or after the internship start date; after the student accepts, generate a PPO job offer
            from an offer template.
          </p>
          <p className="text-sm text-tertiary" style={{ margin: '0.35rem 0 0' }}>{statLine}</p>
        </div>
      </div>

      {error ? (
        <div className="card" style={{ padding: '1.5rem', color: 'var(--danger-600)' }}>{error.message}</div>
      ) : null}

      {!templates.length ? (
        <div className="card" style={{ padding: '1rem 1.25rem', marginBottom: '1rem' }}>
          <p className="text-sm text-secondary" style={{ margin: 0 }}>
            Create at least one{' '}
            <Link href="/dashboard/employer/offer-templates">job offer template</Link> before generating formal offers
            after PPO acceptance.
          </p>
        </div>
      ) : null}

      <DataTableToolbar
        search={search}
        onSearchChange={setSearch}
        sort={sort}
        onSortChange={setSort}
        sortOptions={PPO_SORT_OPTIONS}
        filteredCount={filteredCount}
        totalCount={totalCount}
        hasActiveFilters={hasActiveFilters}
        onClearFilters={clearFilters}
      />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        {filtered.map((row) => {
          const isBusy = busyId === row.programApplicationId;
          const isConfirming = confirmingId === row.programApplicationId;
          const isGenerating = generatingId === row.programApplicationId;
          const ppoStatus = row.ppo?.status;
          const statusLabel = employerPpoStatusLabel(ppoStatus);

          return (
            <div key={row.programApplicationId} className="card" style={{ padding: '1.25rem' }}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '1rem',
                  flexWrap: 'wrap',
                  marginBottom: '0.75rem',
                }}
              >
                <div>
                  <div style={{ fontWeight: 600 }}>{row.studentName}</div>
                  <div className="text-sm text-secondary">{row.rollNumber || row.systemId}</div>
                  <div className="text-sm" style={{ marginTop: '0.35rem' }}>
                    {row.openingTitle}
                  </div>
                  {row.internshipStartDate ? (
                    <div className="text-xs text-tertiary" style={{ marginTop: '0.25rem' }}>
                      Internship start: {formatDate(row.internshipStartDate)}
                    </div>
                  ) : null}
                </div>
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: '0.5rem', flexWrap: 'wrap' }}>
                  <span className={`badge badge-${row.applicationStatus === 'selected' ? 'green' : 'amber'} badge-dot`}>
                    {formatStatus(row.applicationStatus)}
                  </span>
                  {row.ppo ? (
                    <span className="badge badge-blue badge-dot">{statusLabel}</span>
                  ) : (
                    <span className="badge badge-gray badge-dot">No PPO yet</span>
                  )}
                </div>
              </div>

              {row.ppoNotAvailableReason && !row.ppo ? (
                <p className="text-sm text-secondary" style={{ margin: '0 0 0.75rem' }}>
                  {row.ppoNotAvailableReason}
                </p>
              ) : null}

              {row.ppo?.employerNotes ? (
                <p className="text-sm" style={{ margin: '0 0 0.75rem', whiteSpace: 'pre-wrap' }}>
                  <strong>Your note:</strong> {row.ppo.employerNotes}
                </p>
              ) : null}

              {row.ppo?.offerId ? (
                <p className="text-sm text-secondary" style={{ margin: '0 0 0.75rem' }}>
                  Job offer issued — manage on{' '}
                  <Link href="/dashboard/employer/offers">Offers</Link>.
                </p>
              ) : null}

              <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                {row.canConfirmPpo && !isConfirming ? (
                  <button
                    type="button"
                    className="btn btn-primary btn-sm"
                    disabled={isBusy}
                    onClick={() => {
                      setConfirmingId(row.programApplicationId);
                      setGeneratingId(null);
                      setEmployerNotes(row.ppo?.employerNotes || '');
                    }}
                  >
                    Confirm PPO
                  </button>
                ) : null}

                {row.canRevokePpo ? (
                  <button
                    type="button"
                    className="btn btn-secondary btn-sm"
                    disabled={isBusy}
                    onClick={() => {
                      if (!window.confirm('Revoke this PPO? You can confirm again later if allowed.')) return;
                      postAction(row.programApplicationId, { action: 'revoke' });
                    }}
                  >
                    Revoke PPO
                  </button>
                ) : null}

                {row.canGenerateJobOffer && !isGenerating ? (
                  <button
                    type="button"
                    className="btn btn-primary btn-sm"
                    disabled={isBusy || !templates.length}
                    onClick={() => {
                      setGeneratingId(row.programApplicationId);
                      setConfirmingId(null);
                      setTemplateId('');
                    }}
                  >
                    Generate job offer
                  </button>
                ) : null}
              </div>

              {isConfirming ? (
                <div style={{ marginTop: '1rem', paddingTop: '1rem', borderTop: '1px solid var(--border-subtle)' }}>
                  <label className="form-label" htmlFor={`ppo-notes-${row.programApplicationId}`}>
                    Optional note to student
                  </label>
                  <textarea
                    id={`ppo-notes-${row.programApplicationId}`}
                    className="form-input"
                    rows={3}
                    maxLength={2000}
                    value={employerNotes}
                    onChange={(e) => setEmployerNotes(e.target.value)}
                    placeholder="Context about the PPO (not the job offer letter)."
                  />
                  <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem' }}>
                    <button
                      type="button"
                      className="btn btn-primary btn-sm"
                      disabled={isBusy}
                      onClick={() =>
                        postAction(row.programApplicationId, { action: 'confirm', employerNotes })
                      }
                    >
                      Confirm & notify student
                    </button>
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      disabled={isBusy}
                      onClick={() => {
                        setConfirmingId(null);
                        setEmployerNotes('');
                      }}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              ) : null}

              {isGenerating ? (
                <div style={{ marginTop: '1rem', paddingTop: '1rem', borderTop: '1px solid var(--border-subtle)' }}>
                  <label className="form-label" htmlFor={`ppo-template-${row.programApplicationId}`}>
                    Job offer template
                  </label>
                  <select
                    id={`ppo-template-${row.programApplicationId}`}
                    className="form-input"
                    value={templateId}
                    onChange={(e) => setTemplateId(e.target.value)}
                  >
                    <option value="">Select template…</option>
                    {templates.map((t) => (
                      <option key={t.id} value={t.id}>
                        {t.name} — {t.job_title} (₹{Number(t.salary || 0).toLocaleString('en-IN')})
                      </option>
                    ))}
                  </select>
                  <p className="text-xs text-tertiary" style={{ margin: '0.5rem 0 0' }}>
                    CTC and letter content come from the template you choose — not from the PPO step.
                  </p>
                  <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem' }}>
                    <button
                      type="button"
                      className="btn btn-primary btn-sm"
                      disabled={isBusy || !templateId}
                      onClick={() =>
                        postAction(row.programApplicationId, {
                          action: 'generate-offer',
                          templateId,
                        })
                      }
                    >
                      Generate offer
                    </button>
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      disabled={isBusy}
                      onClick={() => {
                        setGeneratingId(null);
                        setTemplateId('');
                      }}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              ) : null}
            </div>
          );
        })}

        {!error && filtered.length === 0 ? (
          <div className="card" style={{ padding: '2.5rem', textAlign: 'center', color: 'var(--text-secondary)' }}>
            No selected or in-progress interns yet.
          </div>
        ) : null}
      </div>
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import useSWR from 'swr';
import { UserCog } from 'lucide-react';
import PageLoading from '@/components/PageLoading';
import DataTableToolbar from '@/components/DataTableToolbar';
import InternshipSupervisorForm from '@/components/internship/InternshipSupervisorForm';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { SORT_DATE_ASC, SORT_DATE_DESC } from '@/lib/dataTableQuery';
import { useToast } from '@/components/ToastProvider';
import { formatDate, formatStatus } from '@/lib/utils';

const SUPERVISOR_SORT_OPTIONS = [
  {
    value: 'name_asc',
    label: 'Student (A → Z)',
    compare: (a, b) =>
      String(a?.studentName ?? '').localeCompare(String(b?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  {
    value: 'name_desc',
    label: 'Student (Z → A)',
    compare: (a, b) =>
      String(b?.studentName ?? '').localeCompare(String(a?.studentName ?? ''), undefined, {
        sensitivity: 'base',
      }),
  },
  SORT_DATE_DESC,
  SORT_DATE_ASC,
];

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load');
  return json;
};

export default function EmployerInternshipSupervisorsPage() {
  const { addToast } = useToast();
  const { data, error, isLoading, mutate } = useSWR('/api/employer/internship-supervisors', fetcher);
  const [savingId, setSavingId] = useState(null);
  const [editingId, setEditingId] = useState(null);

  const items = Array.isArray(data?.items) ? data.items : [];
  const summary = data?.summary || { total: 0, withSupervisor: 0 };

  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(items, {
    getSearchText: (r) =>
      [
        r.studentName,
        r.rollNumber,
        r.openingTitle,
        r.supervisor?.supervisorName,
        r.supervisor?.supervisorEmail,
        r.supervisor?.supervisorTeam,
      ]
        .filter(Boolean)
        .join(' '),
    sortOptions: SUPERVISOR_SORT_OPTIONS,
    defaultSort: 'name_asc',
  });

  const saveSupervisor = async (programApplicationId, payload) => {
    setSavingId(programApplicationId);
    try {
      const res = await fetch('/api/employer/internship-supervisors', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ programApplicationId, ...payload }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Save failed');
      addToast('Intern supervisor saved.', 'success');
      setEditingId(null);
      await mutate();
    } catch (e) {
      addToast(e.message || 'Save failed', 'error');
    } finally {
      setSavingId(null);
    }
  };

  const clearSupervisor = async (programApplicationId) => {
    setSavingId(programApplicationId);
    try {
      const res = await fetch('/api/employer/internship-supervisors', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ programApplicationId, clear: true }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Remove failed');
      addToast('Supervisor removed.', 'success');
      setEditingId(null);
      await mutate();
    } catch (e) {
      addToast(e.message || 'Remove failed', 'error');
    } finally {
      setSavingId(null);
    }
  };

  const exportCsv = () => {
    const header = [
      'Student',
      'Roll',
      'Internship',
      'Status',
      'Supervisor_name',
      'Supervisor_team',
      'Supervisor_email',
      'Supervisor_phone',
      'Supervisor_notes',
    ];
    const rows = filtered.map((r) => [
      r.studentName,
      r.rollNumber || r.systemId,
      r.openingTitle,
      formatStatus(r.status),
      r.supervisor?.supervisorName || '',
      r.supervisor?.supervisorTeam || '',
      r.supervisor?.supervisorEmail || '',
      r.supervisor?.supervisorPhone || '',
      r.supervisor?.supervisorNotes || '',
    ]);
    const csv = [header, ...rows]
      .map((line) => line.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(','))
      .join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'internship_supervisors.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const statLine = useMemo(
    () => `${summary.withSupervisor} of ${summary.total} selected / in-progress intern(s) have a supervisor assigned`,
    [summary],
  );

  if (isLoading) return <PageLoading message="Loading interns…" variant="skeleton-card" />;

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      <div className="page-header" style={{ marginBottom: '1.5rem' }}>
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', margin: 0 }}>
            <UserCog size={26} aria-hidden />
            Internship supervisors
          </h1>
          <p className="text-secondary" style={{ margin: '0.35rem 0 0', lineHeight: 1.55 }}>
            Assign a company supervisor for each intern. Students see supervisor contact details on their
            Internship Progress Reviews page.
          </p>
          <p className="text-sm text-tertiary" style={{ margin: '0.35rem 0 0' }}>{statLine}</p>
        </div>
        <div className="page-header-actions">
          <button type="button" className="btn btn-secondary btn-sm" onClick={exportCsv} disabled={!filtered.length}>
            Export CSV
          </button>
        </div>
      </div>

      {error ? (
        <div className="card" style={{ padding: '1.5rem', color: 'var(--danger-600)' }}>{error.message}</div>
      ) : null}

      <DataTableToolbar
        search={search}
        onSearchChange={setSearch}
        sort={sort}
        onSortChange={setSort}
        sortOptions={SUPERVISOR_SORT_OPTIONS}
        filteredCount={filteredCount}
        totalCount={totalCount}
        hasActiveFilters={hasActiveFilters}
        onClearFilters={clearFilters}
      />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        {filtered.map((row) => {
          const isEditing = editingId === row.programApplicationId;
          const isSaving = savingId === row.programApplicationId;
          return (
            <div key={row.programApplicationId} className="card" style={{ padding: '1.25rem' }}>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: '1rem',
                  flexWrap: 'wrap',
                  marginBottom: isEditing || !row.supervisor ? '0.75rem' : 0,
                }}
              >
                <div>
                  <div style={{ fontWeight: 600 }}>{row.studentName}</div>
                  <div className="text-sm text-secondary">{row.rollNumber || row.systemId}</div>
                  <div className="text-sm" style={{ marginTop: '0.35rem' }}>
                    {row.openingTitle}
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: '0.5rem', flexWrap: 'wrap' }}>
                  <span className={`badge badge-${row.status === 'selected' ? 'green' : 'amber'} badge-dot`}>
                    {formatStatus(row.status)}
                  </span>
                  {!isEditing ? (
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm"
                      onClick={() => setEditingId(row.programApplicationId)}
                    >
                      {row.supervisor ? 'Edit supervisor' : 'Assign supervisor'}
                    </button>
                  ) : (
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      disabled={isSaving}
                      onClick={() => setEditingId(null)}
                    >
                      Cancel
                    </button>
                  )}
                </div>
              </div>

              {!isEditing && row.supervisor ? (
                <div style={{ marginTop: '0.75rem', paddingTop: '0.75rem', borderTop: '1px solid var(--border-subtle)' }}>
                  <InternshipSupervisorForm initialSupervisor={row.supervisor} readOnly />
                  {row.supervisor.updatedAt ? (
                    <p className="text-xs text-tertiary" style={{ margin: '0.5rem 0 0' }}>
                      Updated {formatDate(row.supervisor.updatedAt)}
                    </p>
                  ) : null}
                </div>
              ) : null}

              {isEditing ? (
                <InternshipSupervisorForm
                  initialSupervisor={row.supervisor}
                  saving={isSaving}
                  onSubmit={(payload) => saveSupervisor(row.programApplicationId, payload)}
                  onClear={row.supervisor ? () => clearSupervisor(row.programApplicationId) : null}
                />
              ) : null}
            </div>
          );
        })}

        {!error && filtered.length === 0 ? (
          <div className="card" style={{ padding: '2.5rem', textAlign: 'center', color: 'var(--text-secondary)' }}>
            No selected or in-progress interns yet.
          </div>
        ) : null}
      </div>
    </div>
  );
}

'use client';

import { useState, useMemo, useCallback } from 'react';
import useSWR from 'swr';
import DataTableToolbar from '@/components/DataTableToolbar';
import PageLoading from '@/components/PageLoading';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS, FILTER_ALL } from '@/lib/tableQueryPresets';
import {
  GraduationCap, Plus, Users, IndianRupee, Activity, FileText, Settings,
  LayoutGrid, List, Ban, ArrowRight, Undo2,
} from 'lucide-react';
import { formatCurrency, formatDate, formatStatus, getStatusColor } from '@/lib/utils';
import { useToast } from '@/components/ToastProvider';
import ValidatedNumberInput from '@/components/form/ValidatedNumberInput';
import SegmentedDateInput from '@/components/form/SegmentedDateInput';
import { FIELD_IDS } from '@/lib/inputConstraints';
import {
  mapEmployerInternshipApiError,
  validateEmployerInternshipForm,
} from '@/lib/employerInternshipFormValidation';
import EmployerCampusTargetPicker from '@/components/employer/EmployerCampusTargetPicker';
import EligibilityGroupPicker from '@/components/employer/EligibilityGroupPicker';
import { StandardTableIconAction } from '@/components/ui/StandardTableIconAction';
import { buildPostingEligibilityChecks } from '@/lib/buildPostingEligibilityChecks';
import {
  buildInternshipDescription,
  formatCommaList,
  formatEligibleBranchesLabel,
  formatInternshipPeriodLabel,
  internshipEligibilityOpportunity,
  parseInternshipAdditionalInfo,
  parseInternshipDescription,
  resolveInternshipDatesFromRow,
} from '@/lib/internshipPostingMeta';
import { buildDefaultTenantSelection } from '@/lib/defaultTestCampus';
import { ExportCsvSplitButton } from '@/components/export/ExportCsvSplitButton';
import { toCsvIsoDate } from '@/lib/csvExport';
import { formatEmployerMinCgpa, formatJobPostingStatus, normalizeEmployerMinCgpa } from '@/lib/employerJobDisplay';
import { useEmployerPostingCampuses } from '@/hooks/useEmployerPostingCampuses';
import EmployerListFormLayout from '@/components/employer/EmployerListFormLayout';
import EmployerCampusSyncDialog from '@/components/employer/EmployerCampusSyncDialog';

async function swrFetcher(url) {
  const res = await fetch(url, { cache: 'no-store', credentials: 'include' });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || `Request failed (${res.status})`);
  return data;
}

function InternFieldError({ message }) {
  if (!message) return null;
  return (
    <p className="form-error" style={{ margin: '0.35rem 0 0' }}>
      {message}
    </p>
  );
}

export default function EmployerInternshipsPage() {
  const { addToast } = useToast();
  const jobsApiPath = '/api/employer/jobs?jobType=internship';
  const { data: campusData } = useSWR('/api/employer/campuses', swrFetcher, { revalidateOnFocus: true });
  const {
    data: jobData,
    error: jobsError,
    isLoading: jobsLoading,
    mutate: mutateInternships,
  } = useSWR(jobsApiPath, swrFetcher, {
    revalidateOnFocus: true,
    dedupingInterval: 0,
  });

  const [showForm, setShowForm] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [title, setTitle] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [stipend, setStipend] = useState('');
  const [stipendMax, setStipendMax] = useState('');
  const [vacancies, setVacancies] = useState('5');
  const [minCgpa, setMinCgpa] = useState('');
  const [keywords, setKeywords] = useState('');
  const [eligibleBranches, setEligibleBranches] = useState('');
  const [specializations, setSpecializations] = useState('');
  const [maxBacklogs, setMaxBacklogs] = useState('0');
  const [fieldErrors, setFieldErrors] = useState({});
  const [batchYear, setBatchYear] = useState('');
  const [notes, setNotes] = useState('');
  const [selectedTenantIds, setSelectedTenantIds] = useState({});
  const [campusSyncJobId, setCampusSyncJobId] = useState(null);
  const [campusSyncSelection, setCampusSyncSelection] = useState({});
  const [campusSyncSubmitting, setCampusSyncSubmitting] = useState(false);
  const [detailInternship, setDetailInternship] = useState(null);
  const [editingId, setEditingId] = useState(null);
  const [closingId, setClosingId] = useState(null);
  const [withdrawingId, setWithdrawingId] = useState(null);
  const [savedDraftId, setSavedDraftId] = useState(null);
  const [viewMode, setViewMode] = useState('card');

  const approvedCampuses = useEmployerPostingCampuses(campusData, 'internship');

  const internships = Array.isArray(jobData?.jobs) ? jobData.jobs : [];
  const internshipStatusFilterOptions = useMemo(
    () => [
      FILTER_ALL,
      { value: 'published', label: 'Published' },
      { value: 'draft', label: 'Draft' },
      { value: 'closed', label: 'Closed' },
      { value: 'cancelled', label: 'Withdrawn' },
    ],
    [],
  );
  const {
    search,
    setSearch,
    filter,
    setFilter,
    sort,
    setSort,
    filtered: displayInternships,
    filteredCount,
    totalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(internships, {
    getSearchText: (intern) => [intern.title, intern.keywords, intern.status].filter(Boolean).join(' '),
    filterFn: (row, f) => !f || String(row.status || '') === f,
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'date_desc',
  });

  const resetFormFields = useCallback(() => {
    setTitle('');
    setStartDate('');
    setEndDate('');
    setStipend('');
    setStipendMax('');
    setVacancies('5');
    setMinCgpa('');
    setKeywords('');
    setEligibleBranches('');
    setSpecializations('');
    setMaxBacklogs('0');
    setFieldErrors({});
    setBatchYear('');
    setNotes('');
    setEditingId(null);
  }, []);

  const closeForm = useCallback(() => {
    setShowForm(false);
    setSavedDraftId(null);
    resetFormFields();
  }, [resetFormFields]);

  const openForm = () => {
    resetFormFields();
    setSavedDraftId(null);
    setSelectedTenantIds(buildDefaultTenantSelection(approvedCampuses));
    setShowForm(true);
  };

  const openDetails = useCallback((intern) => {
    setDetailInternship(intern);
  }, []);

  const openManage = useCallback(
    (intern) => {
      const parsed = parseInternshipDescription(intern.description || '');
      const dates = resolveInternshipDatesFromRow(intern);
      setSavedDraftId(null);
      setEditingId(intern.id);
      setTitle(intern.title || '');
      setStartDate(dates.startDate || parsed.startDate || '');
      setEndDate(dates.endDate || parsed.endDate || '');
      setStipend(intern.salaryMin ?? '');
      setStipendMax(intern.salaryMax ?? '');
      setVacancies(String(intern.vacancies ?? '5'));
      const cgpaVal = normalizeEmployerMinCgpa(intern.minCgpa ?? intern.cgpa);
      setMinCgpa(cgpaVal != null ? String(cgpaVal) : '');
      setKeywords(intern.keywords || '');
      setEligibleBranches(formatCommaList(intern.branches ?? intern.eligibleBranches));
      setSpecializations(formatCommaList(intern.specializations));
      setMaxBacklogs(intern.maxBacklogs != null ? String(intern.maxBacklogs) : '0');
      setBatchYear(intern.batchYear != null ? String(intern.batchYear) : '');
      setNotes(parsed.notes);
      setSelectedTenantIds(buildDefaultTenantSelection(approvedCampuses, intern.tenantIds));
      setShowForm(true);
      setDetailInternship(null);
    },
    [approvedCampuses],
  );

  const closePublishedInternship = useCallback(
    async (intern) => {
      if (!intern?.id) return;
      setClosingId(intern.id);
      try {
        const res = await fetch('/api/employer/jobs', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'close', id: intern.id }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok) {
          addToast(json.error || 'Could not close internship', 'error');
          return;
        }
        addToast('Internship closed. It remains listed under Closed for your records.', 'success');
        setDetailInternship(null);
        if (editingId === intern.id) closeForm();
        await mutateInternships();
      } catch {
        addToast('Network error', 'error');
      } finally {
        setClosingId(null);
      }
    },
    [addToast, mutateInternships, editingId, closeForm],
  );

  const withdrawPublishedInternship = useCallback(
    async (intern) => {
      if (!intern?.id) return;
      setWithdrawingId(intern.id);
      try {
        const res = await fetch('/api/employer/jobs', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'withdraw', id: intern.id }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok) {
          addToast(json.error || 'Could not withdraw internship', 'error');
          return;
        }
        const n = Number(json.applicationsWithdrawn) || 0;
        addToast(
          n > 0
            ? `Internship withdrawn. ${n} student application${n === 1 ? '' : 's'} moved to Withdrawn.`
            : 'Internship withdrawn. It no longer accepts applications.',
          'success',
        );
        setDetailInternship(null);
        if (editingId === intern.id) closeForm();
        await mutateInternships();
      } catch {
        addToast('Network error', 'error');
      } finally {
        setWithdrawingId(null);
      }
    },
    [addToast, mutateInternships, editingId, closeForm],
  );

  const stats = useMemo(() => {
    const n = internships.length;
    let sum = 0;
    let count = 0;
    internships.filter((j) => j.status === 'published').forEach((j) => {
      const a = j.salaryMin != null ? Number(j.salaryMin) : null;
      const b = j.salaryMax != null ? Number(j.salaryMax) : null;
      if (a != null && b != null) {
        sum += (a + b) / 2;
        count += 1;
      } else if (a != null) {
        sum += a;
        count += 1;
      } else if (b != null) {
        sum += b;
        count += 1;
      }
    });
    return {
      count: n,
      published: internships.filter((j) => j.status === 'published').length,
      avgStipend: count ? Math.round(sum / count) : null,
    };
  }, [internships]);

  const editingInternship = useMemo(
    () => (editingId ? internships.find((i) => i.id === editingId) : null),
    [editingId, internships],
  );

  const submitInternship = useCallback(
    async (asDraft) => {
      const jobId = editingId || savedDraftId;
      const tenantIds = Object.entries(selectedTenantIds)
        .filter(([, v]) => v)
        .map(([k]) => k);

      const validation = validateEmployerInternshipForm({
        title,
        startDate,
        endDate,
        batchYear,
        maxBacklogs,
        minCgpa,
        stipend,
        stipendMax,
        vacancies,
        tenantIds,
        asDraft,
      });

      if (validation.formError || Object.keys(validation.fieldErrors).length) {
        setFieldErrors(validation.fieldErrors);
        addToast(validation.formError || 'Fix the highlighted fields and try again.', 'warning');
        return;
      }

      setFieldErrors({});
      const sm = stipend === '' ? null : Number(stipend);
      const sx = stipendMax === '' ? null : Number(stipendMax);

      const resolveStatus = () => {
        if (asDraft) return 'draft';
        if (editingInternship?.status === 'published' || editingInternship?.status === 'closed') {
          return editingInternship.status;
        }
        return 'published';
      };

      setSubmitting(true);
      try {
        const description = buildInternshipDescription(startDate, endDate, notes);
        const payload = {
          title: title.trim(),
          description,
          jobType: 'internship',
          status: resolveStatus(),
          salaryMin: sm,
          salaryMax: sx != null && !Number.isNaN(sx) ? sx : sm,
          minCgpa: validation.minCgpa,
          vacancies: vacancies === '' ? 1 : vacancies,
          keywords,
          eligibleBranches,
          specializations,
          maxBacklogs: validation.maxBacklogs,
          batchYear: validation.batchYear,
          startDate: startDate || null,
          endDate: endDate || null,
          tenantIds: asDraft ? [] : tenantIds,
        };
        if (jobId) payload.id = jobId;

        const res = await fetch('/api/employer/jobs', {
          method: jobId ? 'PATCH' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok) {
          const mapped = mapEmployerInternshipApiError(json.error, json.field);
          setFieldErrors(mapped.fieldErrors);
          addToast(mapped.formError || (asDraft ? 'Could not save draft' : jobId ? 'Could not save changes' : 'Could not publish'), 'error');
          return;
        }

        const savedId = json.job?.id || jobId;
        if (asDraft && !editingId && savedId) {
          setSavedDraftId(savedId);
          addToast('Draft saved. Select campuses and click Publish when ready.', 'success');
          await mutateInternships();
          return;
        }

        addToast(
          asDraft
            ? 'Draft saved (not visible to students).'
            : jobId && editingInternship?.status === 'published'
              ? 'Internship updated.'
              : 'Internship published. Partner colleges and students were notified.',
          'success',
        );
        closeForm();
        await mutateInternships();
      } catch {
        addToast('Network error', 'error');
      } finally {
        setSubmitting(false);
      }
    },
    [
      title,
      selectedTenantIds,
      stipend,
      stipendMax,
      startDate,
      endDate,
      notes,
      minCgpa,
      vacancies,
      keywords,
      eligibleBranches,
      specializations,
      maxBacklogs,
      batchYear,
      editingId,
      savedDraftId,
      editingInternship,
      addToast,
      mutateInternships,
      closeForm,
    ],
  );

  const showCampusPicker =
    !editingId || savedDraftId || editingInternship?.status === 'draft';
  const canSaveAsDraft = editingInternship?.status !== 'published' && editingInternship?.status !== 'closed';

  const campusSyncIntern = useMemo(
    () => internships.find((i) => i.id === campusSyncJobId) ?? null,
    [internships, campusSyncJobId],
  );

  const openCampusSync = useCallback(
    (jobId) => {
      if (!approvedCampuses.length) {
        addToast('No approved campuses yet. Ask a college to approve your tie-up first.', 'warning');
        return;
      }
      const intern = internships.find((i) => i.id === jobId);
      setDetailInternship(null);
      setCampusSyncSelection(buildDefaultTenantSelection(approvedCampuses, intern?.tenantIds));
      setCampusSyncJobId(jobId);
    },
    [approvedCampuses, internships, addToast],
  );

  const submitCampusSync = useCallback(async () => {
    if (!campusSyncJobId) return;
    const tenantIds = Object.entries(campusSyncSelection)
      .filter(([, v]) => v)
      .map(([k]) => k);
    if (!tenantIds.length) {
      addToast('Select at least one approved campus.', 'warning');
      return;
    }
    setCampusSyncSubmitting(true);
    try {
      const res = await fetch('/api/employer/jobs/visibility', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jobId: campusSyncJobId, tenantIds }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) {
        addToast(json.error || 'Could not sync campuses', 'error');
        return;
      }
      const msg =
        json.inserted > 0
          ? `Campus visibility updated (${json.inserted} new). College and students can refresh.`
          : json.skippedNotApproved > 0
            ? 'No new visibility rows (check tie-ups are approved for selected campuses).'
            : 'Visibility already present for those campuses.';
      addToast(msg, json.inserted > 0 ? 'success' : 'info');
      setCampusSyncJobId(null);
      await mutateInternships();
    } catch {
      addToast('Network error', 'error');
    } finally {
      setCampusSyncSubmitting(false);
    }
  }, [campusSyncJobId, campusSyncSelection, addToast, mutateInternships]);

  const getInternshipsCsv = useCallback(
    (scope) => {
      const list = scope === 'current' ? displayInternships : internships;
      return {
        headers: [
          'id',
          'title',
          'keywords',
          'stipend_min_inr',
          'stipend_max_inr',
          'min_cgpa',
          'openings',
          'status',
          'posted_at',
          'start_date',
          'end_date',
          'campus_tenant_ids',
        ],
        rows: list.map((intern) => {
          const dates = resolveInternshipDatesFromRow(intern);
          const cgpaVal = normalizeEmployerMinCgpa(intern.minCgpa ?? intern.cgpa);
          return [
            intern.id,
            intern.title ?? '',
            intern.keywords ?? '',
            intern.salaryMin != null ? String(intern.salaryMin) : '',
            intern.salaryMax != null ? String(intern.salaryMax) : '',
            cgpaVal != null ? String(cgpaVal) : '',
            intern.vacancies != null ? String(intern.vacancies) : '',
            intern.status ?? '',
            intern.createdAt ? toCsvIsoDate(intern.createdAt) : '',
            dates.startDate ?? '',
            dates.endDate ?? '',
            Array.isArray(intern.tenantIds) ? intern.tenantIds.join(';') : '',
          ];
        }),
      };
    },
    [displayInternships, internships],
  );

  if (showForm) {
    return (
      <EmployerListFormLayout
        title={editingId ? 'Edit Internship' : savedDraftId ? 'Post New Internship (draft saved)' : 'Post New Internship'}
        subtitle={
          editingId
            ? editingInternship?.status === 'draft'
              ? 'Update this draft, save again as draft, or publish to approved campuses.'
              : 'Update stipend, eligibility, and description. Use Sync on the list to add campuses.'
            : savedDraftId
              ? 'Draft is saved. Select campuses and publish when ready, or keep editing.'
              : 'Save as draft to finish later, or publish to approved campuses. Stipend fields are monthly INR.'
        }
        onBack={closeForm}
        footer={
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>
            {editingId && editingInternship?.status === 'published' ? (
              <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                <button
                  type="button"
                  className="btn btn-secondary btn-sm"
                  disabled={submitting || closingId === editingId || withdrawingId === editingId}
                  onClick={() => void closePublishedInternship(editingInternship)}
                >
                  {closingId === editingId ? 'Closing…' : 'Close posting'}
                </button>
                <button
                  type="button"
                  className="btn btn-ghost btn-sm"
                  disabled={submitting || withdrawingId === editingId || closingId === editingId}
                  onClick={() => void withdrawPublishedInternship(editingInternship)}
                  title="Withdraw posting and move student applications to Withdrawn"
                >
                  <Undo2 size={14} aria-hidden style={{ marginRight: '0.25rem' }} />
                  {withdrawingId === editingId ? 'Withdrawing…' : 'Withdraw'}
                </button>
              </div>
            ) : (
              <span />
            )}
            <div style={{ display: 'flex', gap: '0.75rem', marginLeft: 'auto', flexWrap: 'wrap' }}>
              <button type="button" className="btn btn-secondary" disabled={submitting} onClick={closeForm}>
                Cancel
              </button>
              {canSaveAsDraft ? (
                <button
                  type="button"
                  className="btn btn-secondary"
                  disabled={submitting}
                  onClick={() => void submitInternship(true)}
                >
                  {submitting ? 'Saving…' : 'Save as Draft'}
                </button>
              ) : null}
              <button
                type="button"
                className="btn btn-primary"
                disabled={submitting}
                onClick={() => void submitInternship(false)}
              >
                {submitting
                  ? editingInternship?.status === 'published'
                    ? 'Saving…'
                    : 'Publishing…'
                  : editingInternship?.status === 'published'
                    ? 'Save changes'
                    : 'Publish Internship'}
              </button>
            </div>
          </div>
        }
      >
        {editingId && editingInternship?.status === 'published' ? (
          <p className="text-sm text-secondary" style={{ marginTop: 0, marginBottom: '1rem' }}>
            Campus visibility is unchanged here. Use <strong>Sync</strong> on a published row to add campuses.
          </p>
        ) : null}
        <div className="grid grid-2">
          {showCampusPicker ? (
            <div className="form-group" style={{ gridColumn: '1 / -1' }}>
              <EmployerCampusTargetPicker
                campuses={approvedCampuses}
                selection={selectedTenantIds}
                onSelectionChange={setSelectedTenantIds}
                label="Target campuses (approved)"
                required={!canSaveAsDraft || !!savedDraftId || editingInternship?.status === 'draft'}
                hint={
                  savedDraftId || editingInternship?.status === 'draft'
                    ? 'Required when you publish. Drafts are not visible to students.'
                    : 'Required to publish. Optional if you only Save as Draft.'
                }
                emptyMessage="No approved campuses. Request access from the campus directory first."
              />
              <InternFieldError message={fieldErrors._campuses} />
            </div>
          ) : null}
          <div className="form-group">
            <label className="form-label">Internship Title <span className="required">*</span></label>
            <input
              className={`form-input${fieldErrors.title ? ' input-error' : ''}`}
              placeholder="e.g., Summer Data Intern"
              value={title}
              onChange={(e) => {
                setTitle(e.target.value);
                if (fieldErrors.title) setFieldErrors((prev) => ({ ...prev, title: '' }));
              }}
            />
            <InternFieldError message={fieldErrors.title} />
          </div>
          <div className="form-group">
            <label className="form-label">Start date <span className="required">*</span></label>
            <SegmentedDateInput
              value={startDate}
              onChange={(v) => {
                setStartDate(v);
                if (fieldErrors.startDate) setFieldErrors((prev) => ({ ...prev, startDate: '' }));
              }}
              aria-label="Internship start date"
            />
            <InternFieldError message={fieldErrors.startDate} />
          </div>
          <div className="form-group">
            <label className="form-label">End date <span className="required">*</span></label>
            <SegmentedDateInput
              value={endDate}
              min={startDate || undefined}
              onChange={(v) => {
                setEndDate(v);
                if (fieldErrors.endDate) setFieldErrors((prev) => ({ ...prev, endDate: '' }));
              }}
              aria-label="Internship end date"
            />
            <InternFieldError message={fieldErrors.endDate} />
          </div>
          <div className="form-group">
            <label className="form-label">Stipend / month (min, INR)</label>
            <ValidatedNumberInput
              fieldId={FIELD_IDS.EMPLOYER_STIPEND_MIN}
              placeholder="40000"
              value={stipend}
              onChange={setStipend}
              stepperStep={1}
            />
          </div>
          <div className="form-group">
            <label className="form-label">Stipend / month (max, optional)</label>
            <ValidatedNumberInput
              fieldId={FIELD_IDS.EMPLOYER_STIPEND_MAX}
              context={{ salaryMin: stipend }}
              placeholder="Same as min if empty"
              value={stipendMax}
              onChange={setStipendMax}
              stepperStep={1}
            />
          </div>
          <div className="form-group">
            <label className="form-label">Openings</label>
            <ValidatedNumberInput fieldId={FIELD_IDS.EMPLOYER_VACANCIES} value={vacancies} onChange={setVacancies} />
          </div>
          <div className="form-group">
            <label className="form-label">Min CGPA</label>
            <ValidatedNumberInput fieldId={FIELD_IDS.EMPLOYER_MIN_CGPA} step="0.1" value={minCgpa} onChange={setMinCgpa} />
          </div>
          <div className="form-group" style={{ gridColumn: '1 / -1' }}>
            <label className="form-label">Eligible branches / groups</label>
            <EligibilityGroupPicker value={eligibleBranches} onChange={setEligibleBranches} />
          </div>
          <div className="form-group">
            <label className="form-label">Specializations</label>
            <input
              className="form-input"
              placeholder="AI/ML, Data Science, Cloud"
              value={specializations}
              onChange={(e) => setSpecializations(e.target.value)}
            />
          </div>
          <div className="form-group">
            <label className="form-label">Max active backlogs</label>
            <ValidatedNumberInput
              fieldId={FIELD_IDS.COLLEGE_RULE_MAX_BACKLOGS}
              value={maxBacklogs}
              onChange={(v) => {
                setMaxBacklogs(v);
                if (fieldErrors.maxBacklogs) setFieldErrors((prev) => ({ ...prev, maxBacklogs: '' }));
              }}
              className={fieldErrors.maxBacklogs ? 'input-error' : undefined}
            />
            <p className="text-xs text-secondary" style={{ margin: '0.35rem 0 0' }}>
              0 means students with no active backlogs only. Increase if you allow backlogs.
            </p>
            <InternFieldError message={fieldErrors.maxBacklogs} />
          </div>
          <div className="form-group">
            <label className="form-label">Batch year <span className="required">*</span></label>
            <ValidatedNumberInput
              fieldId={FIELD_IDS.EMPLOYER_INTERNSHIP_BATCH_YEAR}
              value={batchYear}
              step="1"
              placeholder="e.g. 2026"
              context={{ required: !canSaveAsDraft || !!savedDraftId || editingInternship?.status === 'draft' }}
              onChange={(v) => {
                setBatchYear(v);
                if (fieldErrors.batchYear) setFieldErrors((prev) => ({ ...prev, batchYear: '' }));
              }}
              className={fieldErrors.batchYear ? 'form-input input-error' : 'form-input'}
            />
            <p className="text-xs text-secondary" style={{ margin: '0.35rem 0 0' }}>
              Required when publishing. Current year through 4 years ahead (e.g. {new Date().getFullYear()}–{new Date().getFullYear() + 4}).
            </p>
            <InternFieldError message={fieldErrors.batchYear} />
          </div>
          <div className="form-group" style={{ gridColumn: '1 / -1' }}>
            <label className="form-label">Skills (comma-separated)</label>
            <input className="form-input" placeholder="Python, SQL, ML" value={keywords} onChange={(e) => setKeywords(e.target.value)} />
          </div>
          <div className="form-group" style={{ gridColumn: '1 / -1' }}>
            <label className="form-label">Additional notes</label>
            <textarea className="form-textarea" rows={3} value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Location, PPO hint, project details…" />
          </div>
        </div>
      </EmployerListFormLayout>
    );
  }

  return (
    <div className="animate-fadeIn">
      <div className="page-header">
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <GraduationCap size={28} className="text-secondary" strokeWidth={1.5} /> Internship Programs
          </h1>
          <p className="text-secondary">
            Post internships to <span className="font-mono text-xs">job_postings</span> (same pipeline as Job Postings). Stipend fields are stored as monthly INR.
          </p>
        </div>
        <div className="page-header-actions" style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem', alignItems: 'center' }}>
          {totalCount > 0 ? (
            <ExportCsvSplitButton
              mode="dual"
              filenameBase="employer_internships"
              currentCount={filteredCount}
              fullCount={totalCount}
              getRows={getInternshipsCsv}
            />
          ) : null}
          <button type="button" className="btn btn-primary" onClick={openForm}>
            <Plus size={16} /> Post Internship
          </button>
        </div>
      </div>

      {jobsError && (
        <div className="card" style={{ marginBottom: '1rem', borderColor: 'var(--danger-500)' }}>
          <p className="text-sm" style={{ margin: 0 }}>
            Could not load internships: {jobsError.message}. Check login and database configuration.
          </p>
        </div>
      )}

      <div className="grid grid-3" style={{ marginBottom: '2rem' }}>
        <div className="stats-card">
          <div className="stats-card-icon indigo"><Users size={24} strokeWidth={1.5} /></div>
          <div className="stats-card-value">{stats.published}</div>
          <div className="stats-card-label">Published internships</div>
        </div>
        <div className="stats-card green">
          <div className="stats-card-icon green"><IndianRupee size={24} strokeWidth={1.5} /></div>
          <div className="stats-card-value">{stats.avgStipend != null ? formatCurrency(stats.avgStipend) : '—'}</div>
          <div className="stats-card-label">Avg monthly stipend</div>
        </div>
        <div className="stats-card amber">
          <div className="stats-card-icon amber"><Activity size={24} strokeWidth={1.5} /></div>
          <div className="stats-card-value">{stats.count}</div>
          <div className="stats-card-label">All internship records</div>
        </div>
      </div>

      {jobsLoading && <PageLoading message="Loading internships…" variant="skeleton-list" inline />}
      {!jobsLoading && !jobsError && internships.length === 0 && (
        <div className="card" style={{ textAlign: 'center', padding: '3rem 2rem', border: '1px dashed var(--border-default)' }}>
          <GraduationCap size={40} style={{ color: 'var(--text-tertiary)', margin: '0 auto 1rem', opacity: 0.35 }} />
          <p className="text-sm text-secondary" style={{ margin: 0 }}>No internship postings yet. Use Post Internship to publish one.</p>
        </div>
      )}
      {!jobsLoading && !jobsError && totalCount > 0 && (
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '1rem', flexWrap: 'wrap', marginBottom: '1rem' }}>
          <div style={{ flex: '1 1 320px', minWidth: 0 }}>
            <DataTableToolbar
              search={search}
              onSearchChange={setSearch}
              searchPlaceholder="Search title or keywords…"
              filter={filter}
              onFilterChange={setFilter}
              filterOptions={internshipStatusFilterOptions}
              filterLabel="Status"
              sort={sort}
              onSortChange={setSort}
              sortOptions={COMMON_SORT_OPTIONS}
              filteredCount={filteredCount}
              totalCount={totalCount}
              hasActiveFilters={hasActiveFilters}
              onClear={clearFilters}
            />
          </div>
          <div style={{ display: 'flex', background: 'var(--bg-secondary)', borderRadius: '10px', padding: '3px', gap: '2px', border: '1px solid var(--border-default)', flexShrink: 0 }}>
            {[{ mode: 'card', icon: LayoutGrid, label: 'Card view' }, { mode: 'list', icon: List, label: 'List view' }].map(({ mode, icon: Icon, label }) => (
              <button
                key={mode}
                type="button"
                title={label}
                aria-label={label}
                aria-pressed={viewMode === mode}
                onClick={() => setViewMode(mode)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.35rem',
                  padding: '0.4rem 0.85rem',
                  borderRadius: '7px',
                  border: 'none',
                  cursor: 'pointer',
                  fontSize: '0.85rem',
                  fontWeight: 600,
                  transition: 'all 0.15s ease',
                  background: viewMode === mode ? 'var(--bg-primary)' : 'transparent',
                  color: viewMode === mode ? 'var(--primary-600)' : 'var(--text-tertiary)',
                  boxShadow: viewMode === mode ? '0 1px 4px rgba(0,0,0,0.08)' : 'none',
                }}
              >
                <Icon size={15} aria-hidden />
                {mode === 'card' ? 'Cards' : 'List'}
              </button>
            ))}
          </div>
        </div>
      )}
      {!jobsLoading && !jobsError && totalCount > 0 && viewMode === 'card' && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(360px, 1fr))', gap: '1.5rem' }}>
          {displayInternships.map((intern) => (
            <InternshipCard
              key={String(intern.id)}
              intern={intern}
              closingId={closingId}
              withdrawingId={withdrawingId}
              onCampusSync={openCampusSync}
              onDetails={openDetails}
              onManage={openManage}
              onClosePosting={closePublishedInternship}
              onWithdrawPosting={withdrawPublishedInternship}
            />
          ))}
          {displayInternships.length === 0 && (
            <div style={{ gridColumn: '1 / -1', padding: '4rem 2rem', textAlign: 'center', background: 'var(--bg-secondary)', borderRadius: 'var(--radius-xl)', border: '1px dashed var(--border-default)' }}>
              <GraduationCap size={48} className="text-tertiary" style={{ margin: '0 auto 1rem', opacity: 0.5 }} />
              <h3 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--text-primary)', marginBottom: '0.5rem' }}>No internships match</h3>
              <p style={{ color: 'var(--text-secondary)', margin: 0 }}>Try adjusting your search or status filter.</p>
            </div>
          )}
        </div>
      )}
      {!jobsLoading && !jobsError && totalCount > 0 && viewMode === 'list' && (
        <div className="card" style={{ padding: 0, overflow: 'hidden', border: '1px solid var(--border-default)' }}>
          <div className="table-container" style={{ border: 'none', overflowX: 'auto' }}>
            <table className="data-table" style={{ minWidth: 880 }}>
              <thead>
                <tr style={{ background: 'var(--bg-secondary)' }}>
                  <th style={{ paddingLeft: '1.25rem' }}>Title</th>
                  <th>Stipend / month</th>
                  <th>Period</th>
                  <th>Min CGPA</th>
                  <th>Openings</th>
                  <th>Status</th>
                  <th>Posted</th>
                  <th style={{ textAlign: 'right', paddingRight: '1.25rem', width: 1 }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {displayInternships.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="text-center text-secondary">
                      No internships match your search or filters.
                    </td>
                  </tr>
                ) : null}
                {displayInternships.map((intern) => {
                  const listDates = resolveInternshipDatesFromRow(intern);
                  return (
                  <tr key={String(intern.id)}>
                    <td style={{ paddingLeft: '1.25rem', maxWidth: 280 }}>
                      <div className="font-semibold text-sm" style={{ color: 'var(--text-primary)' }}>{intern.title}</div>
                      {intern.keywords ? (
                        <div className="text-xs text-tertiary" style={{ marginTop: '0.2rem' }}>{intern.keywords}</div>
                      ) : null}
                    </td>
                    <td className="text-sm">{stipendLabel(intern.salaryMin, intern.salaryMax)}</td>
                    <td className="text-sm text-secondary">
                      {formatInternshipPeriodLabel(listDates.startDate, listDates.endDate, formatDate) || '—'}
                    </td>
                    <td className="text-sm">{formatEmployerMinCgpa(intern.minCgpa ?? intern.cgpa)}</td>
                    <td className="text-sm">{intern.vacancies ?? '—'}</td>
                    <td>
                      <span className={`badge badge-${getStatusColor(intern.status)} badge-dot`}>{formatJobPostingStatus(intern.status)}</span>
                    </td>
                    <td className="text-sm text-secondary">{intern.createdAt ? formatDate(intern.createdAt) : '—'}</td>
                    <td style={{ textAlign: 'right', paddingRight: '1.25rem', whiteSpace: 'nowrap' }}>
                      <div style={{ display: 'inline-flex', gap: '0.35rem', alignItems: 'center', justifyContent: 'flex-end' }}>
                        {intern.status === 'published' ? (
                          <StandardTableIconAction
                            action="sync"
                            variant="ghost"
                            showLabel={false}
                            disabled={campusSyncSubmitting && campusSyncJobId === intern.id}
                            tooltip={
                              campusSyncSubmitting && campusSyncJobId === intern.id
                                ? 'Syncing campuses…'
                                : undefined
                            }
                            onClick={() => openCampusSync(intern.id)}
                          />
                        ) : null}
                        <StandardTableIconAction
                          action="details"
                          variant="ghost"
                          showLabel={false}
                          onClick={() => openDetails(intern)}
                        />
                        <StandardTableIconAction
                          action="manage"
                          variant="ghost"
                          showLabel={false}
                          onClick={() => openManage(intern)}
                        />
                      </div>
                    </td>
                  </tr>
                );})}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.25rem', flexWrap: 'wrap', gap: '0.75rem' }}>
        <div className="text-sm text-secondary">
          {internships.length} internship posting{internships.length === 1 ? '' : 's'} from your company
        </div>
      </div>

      {detailInternship ? (
        <InternshipDetailDialog
          internship={detailInternship}
          closingId={closingId}
          withdrawingId={withdrawingId}
          onClose={() => setDetailInternship(null)}
          onManage={openManage}
          onClosePosting={closePublishedInternship}
          onWithdrawPosting={withdrawPublishedInternship}
        />
      ) : null}

      <EmployerCampusSyncDialog
        open={Boolean(campusSyncJobId)}
        jobTitle={campusSyncIntern?.title}
        campuses={approvedCampuses}
        selection={campusSyncSelection}
        onSelectionChange={setCampusSyncSelection}
        submitting={campusSyncSubmitting}
        onClose={() => setCampusSyncJobId(null)}
        onSubmit={() => void submitCampusSync()}
      />
    </div>
  );
}

function InternshipCard({
  intern,
  closingId,
  withdrawingId,
  onCampusSync,
  onDetails,
  onManage,
  onClosePosting,
  onWithdrawPosting,
}) {
  const dates = resolveInternshipDatesFromRow(intern);
  const periodLabel = formatInternshipPeriodLabel(dates.startDate, dates.endDate, formatDate);
  const apps = Number(intern.applications) || 0;

  return (
    <div
      className="card card-hover"
      style={{ display: 'flex', flexDirection: 'column', padding: '1.5rem', height: '100%', border: '1px solid var(--border-default)' }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1rem' }}>
        <div>
          <h3 style={{ fontSize: '1.25rem', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '0.35rem', letterSpacing: '-0.01em' }}>
            {intern.title}
          </h3>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
            <span className={`badge badge-${getStatusColor(intern.status)}`} style={{ padding: '0.2rem 0.5rem' }}>
              {formatJobPostingStatus(intern.status)}
            </span>
            {periodLabel ? (
              <span className="badge badge-gray" style={{ padding: '0.2rem 0.5rem' }}>
                {periodLabel}
              </span>
            ) : null}
          </div>
        </div>
        <div style={{ background: 'var(--success-50)', padding: '0.5rem', borderRadius: 'var(--radius-md)' }}>
          <GraduationCap size={20} className="text-success-700" />
        </div>
      </div>
      {intern.keywords ? (
        <p className="text-xs" style={{ margin: '0 0 1rem', lineHeight: 1.5, color: 'var(--text-secondary)' }}>
          <span className="font-semibold text-tertiary">Skills:</span> {intern.keywords}
        </p>
      ) : null}
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '0.5rem',
          marginTop: 'auto',
          padding: '1rem 0',
          borderTop: '1px solid var(--border-default)',
          borderBottom: '1px solid var(--border-default)',
        }}
      >
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
            <IndianRupee size={14} style={{ color: 'var(--text-tertiary)' }} />
            {stipendLabel(intern.salaryMin, intern.salaryMax)}
          </span>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
            <Users size={14} style={{ color: 'var(--text-tertiary)' }} />
            {intern.vacancies ?? '—'} openings
          </span>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
            <GraduationCap size={14} style={{ color: 'var(--text-tertiary)' }} />
            Min CGPA: {formatEmployerMinCgpa(intern.minCgpa ?? intern.cgpa)}
          </span>
          <span
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.4rem',
              fontSize: '0.85rem',
              color: 'var(--primary-700)',
              fontWeight: 600,
              background: 'var(--primary-50)',
              padding: '0.1rem 0.4rem',
              borderRadius: 'var(--radius-sm)',
              width: 'fit-content',
            }}
          >
            <FileText size={14} aria-hidden />
            {apps} App{apps === 1 ? '' : 's'}
          </span>
        </div>
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', marginTop: '1.25rem' }}>
        <div style={{ display: 'flex', gap: '0.75rem' }}>
          <button type="button" className="btn btn-secondary" style={{ flex: 1, padding: '0.6rem' }} onClick={() => onManage(intern)}>
            Manage
          </button>
          <a
            className="btn btn-primary"
            href={`/dashboard/employer/applications?tab=internships&jobId=${intern.id}`}
            style={{ flex: 1, padding: '0.6rem', textAlign: 'center', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '0.35rem' }}
          >
            Pipeline <ArrowRight size={14} aria-hidden />
          </a>
        </div>
        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
          <button type="button" className="btn btn-ghost" style={{ flex: 1, padding: '0.55rem', fontSize: '0.85rem' }} onClick={() => onDetails(intern)}>
            Details
          </button>
          {intern.status === 'published' && (
            <button
              type="button"
              className="btn btn-ghost"
              style={{ flex: 1, padding: '0.55rem', fontSize: '0.85rem' }}
              onClick={() => onCampusSync(intern.id)}
              title="Sync campuses"
            >
              <Users size={14} style={{ marginRight: '0.25rem' }} aria-hidden />
              Sync campuses
            </button>
          )}
        </div>
        {intern.status === 'published' && (
          <div style={{ display: 'flex', gap: '0.5rem', width: '100%' }}>
            <button
              type="button"
              className="btn btn-ghost"
              style={{ flex: 1, padding: '0.55rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.4rem', color: 'var(--text-secondary)' }}
              disabled={closingId === intern.id || withdrawingId === intern.id}
              onClick={() => void onClosePosting(intern)}
            >
              <Ban size={16} aria-hidden />
              {closingId === intern.id ? 'Closing…' : 'Close'}
            </button>
            <button
              type="button"
              className="btn btn-ghost"
              style={{ flex: 1, padding: '0.55rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.4rem', color: 'var(--danger-600)' }}
              disabled={withdrawingId === intern.id || closingId === intern.id}
              onClick={() => void onWithdrawPosting(intern)}
              title="Withdraw posting; students see applications under Withdrawn"
            >
              <Undo2 size={16} aria-hidden />
              {withdrawingId === intern.id ? 'Withdrawing…' : 'Withdraw'}
            </button>
          </div>
        )}
      </div>
      <div className="text-xs text-tertiary" style={{ textAlign: 'center', marginTop: '1rem' }}>
        Posted {intern.createdAt ? formatDate(intern.createdAt) : '—'}
      </div>
    </div>
  );
}

function InternshipDetailDialog({
  internship,
  closingId,
  withdrawingId,
  onClose,
  onManage,
  onClosePosting,
  onWithdrawPosting,
}) {
  const parsed = parseInternshipDescription(internship.description || '');
  const dates = resolveInternshipDatesFromRow(internship);
  const branchLabel = formatEligibleBranchesLabel(internship.branches ?? internship.eligibleBranches);
  const specializationList =
    internship.specializations ??
    parseInternshipAdditionalInfo(internship.additionalInfo).specializations;
  const specializationLabel = specializationList.length ? specializationList.join(', ') : '—';
  const eligibilityChecks = buildPostingEligibilityChecks(internshipEligibilityOpportunity(internship), null, {
    audience: 'college',
    openStatuses: ['published', 'draft', 'closed'],
  }).filter((row) => row.id !== 'status' && row.id !== 'resume' && row.id !== 'placement' && row.id !== 'cgpa');

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="internship-detail-title"
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 100,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '1.5rem',
      }}
    >
      <button
        type="button"
        aria-label="Close details"
        style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.45)', border: 'none', cursor: 'pointer' }}
        onClick={onClose}
      />
      <div
        className="card animate-slideUp"
        style={{ position: 'relative', width: '100%', maxWidth: 560, maxHeight: '90vh', overflow: 'auto' }}
      >
        <div className="card-header">
          <h3 id="internship-detail-title" className="card-title">{internship.title}</h3>
          <button type="button" className="btn btn-ghost btn-sm" onClick={onClose}>
            ✕ Close
          </button>
        </div>
        <div style={{ display: 'grid', gap: '0.85rem' }}>
          <DetailRow label="Status">
            <span className={`badge badge-${getStatusColor(internship.status)} badge-dot`}>{formatJobPostingStatus(internship.status)}</span>
          </DetailRow>
          <DetailRow label="Stipend / month">{stipendLabel(internship.salaryMin, internship.salaryMax)}</DetailRow>
          <DetailRow label="Start date">{dates.startDate ? formatDate(dates.startDate) : '—'}</DetailRow>
          <DetailRow label="End date">{dates.endDate ? formatDate(dates.endDate) : '—'}</DetailRow>
          <DetailRow label="Branch">{branchLabel}</DetailRow>
          <DetailRow label="Specialization">{specializationLabel}</DetailRow>
          <DetailRow label="Min CGPA">{formatEmployerMinCgpa(internship.minCgpa ?? internship.cgpa)}</DetailRow>
          <DetailRow label="Openings">{internship.vacancies ?? '—'}</DetailRow>
          <DetailRow label="Posted">{internship.createdAt ? formatDate(internship.createdAt) : '—'}</DetailRow>
          {internship.keywords ? <DetailRow label="Skills">{internship.keywords}</DetailRow> : null}
          {eligibilityChecks.length > 0 ? (
            <div style={{ marginTop: '0.25rem' }}>
              <div className="text-xs font-semibold text-tertiary" style={{ marginBottom: '0.5rem' }}>Eligibility</div>
              <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '0.45rem' }}>
                {eligibilityChecks.map((row) => (
                  <li key={row.id} className="text-sm" style={{ color: 'var(--text-secondary)', lineHeight: 1.45 }}>
                    <span style={{ fontWeight: 600, color: 'var(--text-primary)' }}>{row.label}:</span>{' '}
                    {row.requirement}
                  </li>
                ))}
              </ul>
            </div>
          ) : (
            <DetailRow label="Eligibility">Open to all eligible students</DetailRow>
          )}
          {parsed.notes ? <DetailRow label="Notes">{parsed.notes}</DetailRow> : null}
        </div>
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '1.25rem', flexWrap: 'wrap' }}>
          {internship.status === 'published' ? (
            <>
              <button
                type="button"
                className="btn btn-secondary btn-sm"
                disabled={closingId === internship.id || withdrawingId === internship.id}
                onClick={() => void onClosePosting(internship)}
              >
                {closingId === internship.id ? 'Closing…' : 'Close posting'}
              </button>
              <button
                type="button"
                className="btn btn-ghost btn-sm"
                disabled={withdrawingId === internship.id || closingId === internship.id}
                onClick={() => void onWithdrawPosting(internship)}
              >
                {withdrawingId === internship.id ? 'Withdrawing…' : 'Withdraw'}
              </button>
            </>
          ) : null}
          <button type="button" className="btn btn-secondary btn-sm" onClick={() => onManage(internship)}>
            Manage
          </button>
        </div>
      </div>
    </div>
  );
}

function DetailRow({ label, children }) {
  return (
    <div style={{ display: 'grid', gridTemplateColumns: '120px 1fr', gap: '0.75rem', alignItems: 'start' }}>
      <span className="text-xs font-semibold text-tertiary" style={{ paddingTop: '0.15rem' }}>{label}</span>
      <span className="text-sm" style={{ color: 'var(--text-primary)', lineHeight: 1.5 }}>{children}</span>
    </div>
  );
}

function stipendLabel(min, max) {
  if (min == null && max == null) return 'Stipend TBD';
  if (min != null && max != null && Number(min) === Number(max)) {
    return `${formatCurrency(Number(min))}/mo`;
  }
  if (min != null && max != null) {
    return `${formatCurrency(Number(min))}–${formatCurrency(Number(max))}/mo`;
  }
  if (min != null) return `${formatCurrency(Number(min))}/mo`;
  return `${formatCurrency(Number(max))}/mo`;
}

'use client';

import { useState, useMemo, useEffect, useCallback } from 'react';
import useSWR from 'swr';
import Link from 'next/link';
import { formatDate, formatStatus, getStatusColor, formatCurrency } from '@/lib/utils';
import { useToast } from '@/components/ToastProvider';
import { Briefcase, Plus, DollarSign, Users, FileText, ArrowRight, X, Building2, AlignLeft, CheckCircle2, Ban, LayoutGrid, List, Undo2, GitBranch } from 'lucide-react';
import { formatJobPostingStatus } from '@/lib/employerJobDisplay';
import ValidatedNumberInput from '@/components/form/ValidatedNumberInput';
import CurrencyAmountInput from '@/components/form/CurrencyAmountInput';
import { FIELD_IDS, validateFieldOrError } from '@/lib/inputConstraints';
import { buildDefaultTenantSelection } from '@/lib/defaultTestCampus';
import {
  ALUMNI_EMPLOYMENT_TYPE_LABELS,
  ALUMNI_EDUCATION_LEVELS,
  ALUMNI_SENIORITY_LEVELS,
  ALUMNI_WORK_MODES,
  buildAlumniJobDescription,
  validateAlumniJobPostingPayload,
} from '@/lib/alumniJobPosting';
import EmployerCampusTargetPicker from '@/components/employer/EmployerCampusTargetPicker';
import { useEmployerPostingCampuses } from '@/hooks/useEmployerPostingCampuses';
import { StandardTableIconAction } from '@/components/ui/StandardTableIconAction';
import { formatFilterBadgeLabelParen } from '@/lib/filterBadgeLabel';

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json.error || 'Failed to load alumni jobs');
  return json;
};

const emptyForm = {
  title: '',
  keywords: '',
  type: 'full_time',
  salaryMin: '',
  salaryMax: '',
  vacancies: '1',
  minExperience: '',
  maxExperience: '',
  workMode: 'hybrid',
  noticePeriodDays: '',
  seniorityLevel: 'mid',
  educationLevel: 'bachelors',
  location: '',
  industry: '',
  description: '',
};

export default function EmployerJobsPage() {
  const { addToast } = useToast();
  const { data: jobData, error: jobsError, mutate: mutateJobs } = useSWR('/api/employer/jobs?scope=alumni', fetcher, { revalidateOnFocus: true });
  const { data: campusData } = useSWR('/api/employer/campuses', fetcher, { revalidateOnFocus: true });
  const { data: profileData } = useSWR('/api/employer/profile', fetcher, { revalidateOnFocus: true });

  const [showModal, setShowModal] = useState(false);
  const [modalMode, setModalMode] = useState('create');
  const [savedDraftId, setSavedDraftId] = useState(null);
  const [editingJob, setEditingJob] = useState(null);
  const [filter, setFilter] = useState('');
  const [form, setForm] = useState(emptyForm);
  const [selectedTenantIds, setSelectedTenantIds] = useState({});
  const [submitting, setSubmitting] = useState(false);
  const [closingJobId, setClosingJobId] = useState(null);
  const [withdrawingJobId, setWithdrawingJobId] = useState(null);
  const [viewMode, setViewMode] = useState('card');

  const jobsList = Array.isArray(jobData?.jobs) ? jobData.jobs : [];
  const approvedCampuses = useEmployerPostingCampuses(campusData, 'alumni_jobs');

  const filtered = jobsList.filter((j) => !filter || j.status === filter);

  const tabCounts = useMemo(
    () => ({
      all: jobsList.length,
      published: jobsList.filter((j) => j.status === 'published').length,
      draft: jobsList.filter((j) => j.status === 'draft').length,
      closed: jobsList.filter((j) => j.status === 'closed').length,
      withdrawn: jobsList.filter((j) => j.status === 'cancelled').length,
    }),
    [jobsList],
  );

  const profileHeadquarters = profileData?.profile?.headquarters;

  useEffect(() => {
    if (!showModal) return;
    setForm((prev) => {
      const location = prev.location?.trim() ? prev.location : (profileHeadquarters || '');
      return {
        ...prev,
        location,
        description: buildAlumniJobDescription({ ...prev, location }),
      };
    });
  }, [
    showModal,
    form.title,
    form.keywords,
    form.type,
    form.salaryMin,
    form.salaryMax,
    form.vacancies,
    form.minExperience,
    form.maxExperience,
    form.workMode,
    form.noticePeriodDays,
    form.seniorityLevel,
    form.educationLevel,
    form.industry,
    profileHeadquarters,
  ]);

  const openCreate = () => {
    setModalMode('create');
    setSavedDraftId(null);
    setEditingJob(null);
    setForm({ ...emptyForm, type: 'full_time' });
    setSelectedTenantIds(buildDefaultTenantSelection(approvedCampuses));
    setShowModal(true);
    document.body.style.overflow = 'hidden';
  };

  const handleEdit = (job) => {
    setModalMode('edit');
    setSavedDraftId(null);
    setEditingJob(job);
    setForm({
      title: job.title,
      keywords: job.keywords || '',
      type: job.type === 'contract' ? 'contract' : 'full_time',
      salaryMin: job.salaryMin ?? '',
      salaryMax: job.salaryMax ?? '',
      vacancies: job.vacancies ?? '1',
      minExperience: job.minExperience ?? '',
      maxExperience: job.maxExperience ?? '',
      workMode: job.workMode || 'hybrid',
      noticePeriodDays: job.noticePeriodDays ?? '',
      seniorityLevel: job.seniorityLevel || 'mid',
      educationLevel: job.educationLevel || 'bachelors',
      location: job.location || '',
      industry: job.industry || '',
      description: job.description || '',
    });
    setSelectedTenantIds(buildDefaultTenantSelection(approvedCampuses, job.tenantIds));
    setShowModal(true);
    document.body.style.overflow = 'hidden';
  };

  const resetTenantSelection = useCallback(() => {
    setSelectedTenantIds(buildDefaultTenantSelection(approvedCampuses));
  }, [approvedCampuses]);

  const closeModal = () => {
    setShowModal(false);
    setModalMode('create');
    setSavedDraftId(null);
    setEditingJob(null);
    setForm({ ...emptyForm });
    resetTenantSelection();
    document.body.style.overflow = '';
  };

  const setField = useCallback((key, value) => {
    setForm((p) => ({ ...p, [key]: value }));
  }, []);

  const submitJob = async (asDraft) => {
    const titleErr = validateFieldOrError(FIELD_IDS.COMMON_TITLE, form.title, { label: 'Job title' });
    if (titleErr) {
      addToast(titleErr, 'error');
      return;
    }
    const tenantIds = Object.entries(selectedTenantIds)
      .filter(([, v]) => v)
      .map(([k]) => k);
    if (!asDraft && !tenantIds.length) {
      addToast('Select at least one approved campus so notifications are created for that college.', 'warning');
      return;
    }
    const validated = validateAlumniJobPostingPayload({
      salaryMin: form.salaryMin,
      salaryMax: form.salaryMax,
      minExperience: form.minExperience,
      maxExperience: form.maxExperience,
      noticePeriodDays: form.noticePeriodDays,
      jobType: form.type,
    });
    if (validated.error) {
      addToast(validated.error, 'warning');
      return;
    }

    setSubmitting(true);
    try {
      const jobId = modalMode === 'edit' ? editingJob?.id : savedDraftId;
      const res = await fetch('/api/employer/jobs', {
        method: jobId ? 'PATCH' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: jobId,
          title: form.title.trim(),
          description: form.description,
          jobType: form.type,
          status: asDraft ? 'draft' : 'published',
          salaryMin: form.salaryMin,
          salaryMax: form.salaryMax,
          vacancies: form.vacancies,
          keywords: form.keywords,
          minExperience: form.minExperience,
          maxExperience: form.maxExperience,
          workMode: form.workMode,
          noticePeriodDays: form.noticePeriodDays,
          seniorityLevel: form.seniorityLevel,
          educationLevel: form.educationLevel,
          location: form.location,
          industry: form.industry,
          tenantIds: asDraft ? [] : tenantIds,
        }),
      });
      const json = await res.json();
      if (!res.ok) {
        addToast(json.error || (jobId ? 'Update failed' : 'Save failed'), 'error');
        return;
      }
      const savedId = json.job?.id || jobId;
      if (asDraft && modalMode === 'create' && savedId) {
        setSavedDraftId(savedId);
        addToast('Draft saved. Select campuses and click Publish when ready.', 'success');
        mutateJobs();
        return;
      }
      addToast(
        modalMode === 'edit'
          ? 'Job updated successfully.'
          : asDraft
            ? 'Draft saved to the database (no alerts sent).'
            : 'Alumni job published. College admins were notified for each selected campus.',
        'success',
      );
      closeModal();
      mutateJobs();
    } catch {
      addToast('Network error', 'error');
    } finally {
      setSubmitting(false);
    }
  };

  const closePublishedJob = async (job) => {
    if (!job?.id) return;
    setClosingJobId(job.id);
    try {
      const res = await fetch('/api/employer/jobs', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'close', id: job.id }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) {
        addToast(json.error || 'Could not close job', 'error');
        return;
      }
      addToast('Job posting closed. It will stay visible under Closed for your records.', 'success');
      mutateJobs();
    } catch {
      addToast('Network error', 'error');
    } finally {
      setClosingJobId(null);
    }
  };

  const withdrawPublishedJob = async (job) => {
    if (!job?.id) return;
    setWithdrawingJobId(job.id);
    try {
      const res = await fetch('/api/employer/jobs', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'withdraw', id: job.id }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) {
        addToast(json.error || 'Could not withdraw job', 'error');
        return;
      }
      const n = Number(json.applicationsWithdrawn) || 0;
      addToast(
        n > 0
          ? `Job withdrawn. ${n} student application${n === 1 ? '' : 's'} moved to Withdrawn.`
          : 'Job withdrawn. It no longer accepts applications.',
        'success',
      );
      mutateJobs();
    } catch {
      addToast('Network error', 'error');
    } finally {
      setWithdrawingJobId(null);
    }
  };

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      {/* High-Fidelity Glassmorphic Hero Banner */}
      <div 
        style={{
          position: 'relative',
          background: 'var(--banner-gradient)',
          borderRadius: 'var(--radius-xl)',
          padding: '2.5rem',
          color: 'white',
          overflow: 'hidden',
          marginBottom: '2.5rem',
          boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1)',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '1.5rem',
        }}
      >
        {/* Decorative Elements */}
        <div style={{ position: 'absolute', top: '-50px', right: '-50px', width: '250px', height: '250px', background: 'radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%)', borderRadius: '50%' }} />
        <div style={{ position: 'absolute', bottom: '-50px', left: '10%', width: '150px', height: '150px', background: 'radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 60%)', borderRadius: '50%' }} />

        <div style={{ position: 'relative', zIndex: 1, maxWidth: '600px' }}>
          <h1 style={{ color: '#ffffff', fontSize: '2.25rem', fontWeight: 800, margin: '0 0 0.5rem', letterSpacing: '-0.02em', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            Alumni Job Postings
            {jobsList.length > 0 && (
              <span style={{ fontSize: '0.875rem', fontWeight: 700, background: 'rgba(255,255,255,0.2)', padding: '0.2rem 0.6rem', borderRadius: '999px', backdropFilter: 'blur(4px)' }}>
                {jobsList.length} Total
              </span>
            )}
          </h1>
          <p style={{ fontSize: '1.05rem', color: 'rgba(255,255,255,0.85)', margin: 0, lineHeight: 1.5 }}>
            Post lateral roles for alumni — experienced hire openings shared with your campus network.
          </p>
        </div>
        
        <div style={{ position: 'relative', zIndex: 1 }}>
          <button className="btn banner-cta-solid" type="button" onClick={openCreate} style={{ fontSize: '1.05rem', padding: '0.75rem 1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Plus size={18} /> Create Job
          </button>
        </div>
      </div>

      {jobsError && (
        <div
          role="alert"
          style={{
            marginBottom: '1.5rem',
            padding: '1rem 1.25rem',
            borderRadius: 'var(--radius-lg)',
            border: '1px solid var(--color-danger-border, #fecaca)',
            background: 'var(--color-danger-bg, #fef2f2)',
            color: 'var(--color-danger-text, #991b1b)',
          }}
        >
          Could not load alumni jobs: {jobsError.message}. If this persists on production, run database migration{' '}
          <code>npm run db:migrate:075</code> and refresh.
        </div>
      )}

      {/* Filter Tabs + View Toggle */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '2rem', flexWrap: 'wrap', gap: '0.75rem' }}>
        <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
          {[
            { id: '', label: 'All Alumni Jobs', count: tabCounts.all },
            { id: 'published', label: 'Published', count: tabCounts.published },
            { id: 'draft', label: 'Drafts', count: tabCounts.draft },
            { id: 'closed', label: 'Closed', count: tabCounts.closed },
            { id: 'cancelled', label: 'Withdrawn', count: tabCounts.withdrawn },
          ].map((t) => (
            <button
              key={t.id}
              onClick={() => setFilter(t.id)}
              style={{
                padding: '0.5rem 1.25rem',
                borderRadius: '999px',
                fontWeight: 600,
                fontSize: '0.95rem',
                transition: 'all 0.2s ease',
                border: 'none',
                cursor: 'pointer',
                background: filter === t.id ? 'var(--primary-600)' : 'var(--bg-secondary)',
                color: filter === t.id ? 'white' : 'var(--text-secondary)',
                boxShadow: filter === t.id ? '0 4px 10px rgba(79, 70, 229, 0.2)' : 'none',
              }}
            >
              {formatFilterBadgeLabelParen(t.label, t.count)}
            </button>
          ))}
        </div>
        {/* View Toggle */}
        <div style={{ display: 'flex', background: 'var(--bg-secondary)', borderRadius: '10px', padding: '3px', gap: '2px', border: '1px solid var(--border-default)' }}>
          {[{ mode: 'card', icon: LayoutGrid, label: 'Card view' }, { mode: 'list', icon: List, label: 'List view' }].map(({ mode, icon: Icon, label }) => (
            <button
              key={mode}
              title={label}
              aria-label={label}
              onClick={() => setViewMode(mode)}
              style={{
                display: 'flex', alignItems: 'center', gap: '0.35rem',
                padding: '0.4rem 0.85rem', borderRadius: '7px', border: 'none',
                cursor: 'pointer', fontSize: '0.85rem', fontWeight: 600,
                transition: 'all 0.15s ease',
                background: viewMode === mode ? 'var(--bg-primary)' : 'transparent',
                color: viewMode === mode ? 'var(--primary-600)' : 'var(--text-tertiary)',
                boxShadow: viewMode === mode ? '0 1px 4px rgba(0,0,0,0.08)' : 'none',
              }}
            >
              <Icon size={15} />
              <span style={{ display: 'none' }}>{label}</span>
              {mode === 'card' ? 'Cards' : 'List'}
            </button>
          ))}
        </div>
      </div>

      {/* ── Card View ── */}
      {viewMode === 'card' && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(360px, 1fr))', gap: '1.5rem' }}>
          {filtered.map((job) => (
            <div key={job.id} className="card card-hover" style={{ display: 'flex', flexDirection: 'column', padding: '1.5rem', height: '100%', border: '1px solid var(--border-default)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1rem' }}>
                <div>
                  <h3 style={{ fontSize: '1.25rem', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '0.35rem', letterSpacing: '-0.01em' }}>{job.title}</h3>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem', marginBottom: '0.75rem' }}>
                    <span className={`badge badge-${getStatusColor(job.status)}`} style={{ padding: '0.2rem 0.5rem' }}>{formatJobPostingStatus(job.status)}</span>
                    <span className="badge badge-gray" style={{ padding: '0.2rem 0.5rem' }}>{formatStatus(job.type)}</span>
                  </div>
                </div>
                <div style={{ background: 'var(--primary-50)', padding: '0.5rem', borderRadius: 'var(--radius-md)' }}>
                  <Briefcase size={20} className="text-primary-600" />
                </div>
              </div>
              {job.keywords ? (
                <p className="text-xs" style={{ margin: '0 0 1rem', lineHeight: 1.5, color: 'var(--text-secondary)' }}>
                  <span className="font-semibold text-tertiary">Keywords:</span> {job.keywords}
                </p>
              ) : null}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', marginTop: 'auto', padding: '1rem 0', borderTop: '1px solid var(--border-default)', borderBottom: '1px solid var(--border-default)' }}>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
                  <span style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                    <DollarSign size={14} style={{ color: 'var(--text-tertiary)' }} />
                    {job.salaryMin != null && job.salaryMax != null ? `${formatCurrency(job.salaryMin)} – ${formatCurrency(job.salaryMax)}` : 'Salary TBD'}
                  </span>
                  <span style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                    <Users size={14} style={{ color: 'var(--text-tertiary)' }} />
                    {job.vacancies} vacancies
                  </span>
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
                  <span style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                    <Briefcase size={14} style={{ color: 'var(--text-tertiary)' }} />
                    Exp: {job.experienceLabel || '—'}
                  </span>
                  <span style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.85rem', color: 'var(--primary-700)', fontWeight: 600, background: 'var(--primary-50)', padding: '0.1rem 0.4rem', borderRadius: 'var(--radius-sm)', width: 'fit-content' }}>
                    <FileText size={14} />
                    {job.applications} Apps
                  </span>
                </div>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', marginTop: '1.25rem' }}>
                <div style={{ display: 'flex', gap: '0.75rem' }}>
                  <button className="btn btn-secondary" style={{ flex: 1, padding: '0.6rem' }} onClick={(e) => { e.stopPropagation(); handleEdit(job); }}>Edit Job</button>
                  <a className="btn btn-primary" href={`/dashboard/employer/applications?tab=jobs&jobId=${job.id}`} style={{ flex: 1, padding: '0.6rem', textAlign: 'center' }}>View Pipeline</a>
                </div>
                {job.status === 'published' && (
                  <div style={{ display: 'flex', gap: '0.5rem', width: '100%' }}>
                    <button type="button" className="btn btn-ghost" style={{ flex: 1, padding: '0.55rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.4rem', color: 'var(--text-secondary)' }} disabled={closingJobId === job.id || withdrawingJobId === job.id} onClick={(e) => { e.stopPropagation(); void closePublishedJob(job); }}>
                      <Ban size={16} aria-hidden />{closingJobId === job.id ? 'Closing…' : 'Close'}
                    </button>
                    <button type="button" className="btn btn-ghost" style={{ flex: 1, padding: '0.55rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.4rem', color: 'var(--danger-600)' }} disabled={withdrawingJobId === job.id || closingJobId === job.id} onClick={(e) => { e.stopPropagation(); void withdrawPublishedJob(job); }} title="Withdraw job; students see applications under Withdrawn">
                      <Undo2 size={16} aria-hidden />{withdrawingJobId === job.id ? 'Withdrawing…' : 'Withdraw'}
                    </button>
                  </div>
                )}
              </div>
              <div className="text-xs text-tertiary" style={{ textAlign: 'center', marginTop: '1rem' }}>Created {job.createdAt ? formatDate(job.createdAt) : '—'}</div>
            </div>
          ))}
          {filtered.length === 0 && (
            <div style={{ gridColumn: '1 / -1', padding: '4rem 2rem', textAlign: 'center', background: 'var(--bg-secondary)', borderRadius: 'var(--radius-xl)', border: '1px dashed var(--border-default)' }}>
              <Briefcase size={48} className="text-tertiary" style={{ margin: '0 auto 1rem', opacity: 0.5 }} />
              <h3 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--text-primary)', marginBottom: '0.5rem' }}>No alumni jobs yet</h3>
              <p style={{ color: 'var(--text-secondary)', margin: 0 }}>Create your first lateral role for alumni. Internships and campus programs are managed on their own pages.</p>
            </div>
          )}
        </div>
      )}

      {/* ── List View ── */}
      {viewMode === 'list' && (
        <div style={{ background: 'var(--bg-primary)', border: '1px solid var(--border-default)', borderRadius: 'var(--radius-xl)', overflow: 'hidden', boxShadow: 'var(--shadow-sm)' }}>
          {/* Table header */}
          <div style={{ display: 'grid', gridTemplateColumns: '2fr 0.7fr 0.7fr 1.1fr 0.6fr 0.6fr 0.5fr auto', gap: '0', background: 'var(--bg-secondary)', padding: '0.65rem 1.25rem', borderBottom: '1px solid var(--border-default)' }}>
            {['Job Title', 'Type', 'Status', 'Salary', 'Experience', 'Location', 'Apps', 'Actions'].map((h) => (
              <span key={h} style={{ fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--text-tertiary)' }}>{h}</span>
            ))}
          </div>

          {filtered.length === 0 && (
            <div style={{ padding: '4rem 2rem', textAlign: 'center' }}>
              <Briefcase size={40} style={{ margin: '0 auto 1rem', opacity: 0.3, display: 'block', color: 'var(--text-tertiary)' }} />
              <p style={{ color: 'var(--text-secondary)', margin: 0, fontWeight: 600 }}>No alumni jobs match this filter.</p>
            </div>
          )}

          {filtered.map((job, idx) => (
            <div
              key={job.id}
              style={{
                display: 'grid',
                gridTemplateColumns: '2fr 0.7fr 0.7fr 1.1fr 0.6fr 0.6fr 0.5fr auto',
                gap: '0',
                alignItems: 'center',
                padding: '0.9rem 1.25rem',
                borderBottom: idx < filtered.length - 1 ? '1px solid var(--border-default)' : 'none',
                transition: 'background 0.15s ease',
              }}
              onMouseEnter={(e) => (e.currentTarget.style.background = 'var(--bg-secondary)')}
              onMouseLeave={(e) => (e.currentTarget.style.background = 'transparent')}
            >
              {/* Title + keywords */}
              <div style={{ minWidth: 0, paddingRight: '1rem' }}>
                <div style={{ fontWeight: 700, fontSize: '0.975rem', color: 'var(--text-primary)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{job.title}</div>
                {job.keywords && (
                  <div style={{ fontSize: '0.72rem', color: 'var(--text-tertiary)', marginTop: '0.2rem', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{job.keywords}</div>
                )}
              </div>

              {/* Type */}
              <span className="badge badge-gray" style={{ fontSize: '0.72rem', whiteSpace: 'nowrap' }}>{formatStatus(job.type)}</span>

              {/* Status */}
              <span className={`badge badge-${getStatusColor(job.status)}`} style={{ fontSize: '0.72rem', whiteSpace: 'nowrap' }}>{formatJobPostingStatus(job.status)}</span>

              {/* Salary */}
              <span style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>
                {job.salaryMin != null && job.salaryMax != null ? `${formatCurrency(job.salaryMin)} – ${formatCurrency(job.salaryMax)}` : '—'}
              </span>

              {/* Experience */}
              <span style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>
                {job.experienceLabel || '—'}
              </span>

              {/* Location */}
              <span style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {job.location || '—'}
              </span>

              {/* Apps */}
              <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.82rem', fontWeight: 700, color: 'var(--primary-700)', background: 'var(--primary-50)', padding: '0.15rem 0.5rem', borderRadius: 'var(--radius-sm)', whiteSpace: 'nowrap' }}>
                <FileText size={12} />{job.applications}
              </span>

              {/* Actions */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', paddingLeft: '0.75rem' }}>
                <StandardTableIconAction action="edit" onClick={(e) => { e.stopPropagation(); handleEdit(job); }} />
                <Link
                  href={`/dashboard/employer/applications?tab=jobs&jobId=${job.id}`}
                  className="btn btn-primary btn-icon btn-sm"
                  title="View pipeline"
                  aria-label="View pipeline"
                  onClick={(e) => e.stopPropagation()}
                >
                  <GitBranch size={16} strokeWidth={2} aria-hidden />
                </Link>
                {job.status === 'published' && (
                  <>
                    <button
                      type="button"
                      title="Close posting"
                      className="btn btn-ghost"
                      style={{ padding: '0.35rem 0.5rem', color: 'var(--text-tertiary)' }}
                      disabled={closingJobId === job.id || withdrawingJobId === job.id}
                      onClick={(e) => { e.stopPropagation(); void closePublishedJob(job); }}
                    >
                      <Ban size={15} aria-hidden />
                    </button>
                    <button
                      type="button"
                      title="Withdraw posting"
                      className="btn btn-ghost"
                      style={{ padding: '0.35rem 0.5rem', color: 'var(--danger-600)' }}
                      disabled={withdrawingJobId === job.id || closingJobId === job.id}
                      onClick={(e) => { e.stopPropagation(); void withdrawPublishedJob(job); }}
                    >
                      <Undo2 size={15} aria-hidden />
                    </button>
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* High-Fidelity Job Creation Modal */}
      {showModal && (
        <div style={{ position: 'fixed', inset: 0, zIndex: 100, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '2rem' }}>
          <div style={{ position: 'absolute', inset: 0, background: 'rgba(0, 0, 0, 0.5)', backdropFilter: 'blur(4px)' }} onClick={closeModal} />
          
          <div className="animate-slideUp" style={{ position: 'relative', width: '100%', maxWidth: '1200px', maxHeight: '90vh', background: 'var(--bg-primary)', borderRadius: 'var(--radius-xl)', boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
            
            <div style={{ padding: '1.5rem 2rem', borderBottom: '1px solid var(--border-default)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: 'var(--bg-secondary)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                <div style={{ padding: '0.5rem', background: 'var(--primary-100)', color: 'var(--primary-700)', borderRadius: 'var(--radius-md)' }}>
                  <Briefcase size={20} />
                </div>
                <h2 style={{ fontSize: '1.5rem', fontWeight: 800, margin: 0, color: 'var(--text-primary)' }}>
                  {modalMode === 'edit' ? 'Edit Job Posting' : 'Create New Job Posting'}
                </h2>
                {modalMode === 'create' && savedDraftId ? (
                  <span className="badge badge-warning badge-dot" style={{ marginLeft: '0.25rem' }}>
                    Draft saved
                  </span>
                ) : null}
              </div>
              <button onClick={closeModal} className="btn btn-ghost" style={{ padding: '0.5rem', borderRadius: '50%' }}>
                <X size={24} className="text-secondary" />
              </button>
            </div>

            <div style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'row', flexWrap: 'wrap' }}>
              {/* Form Fields Section */}
              <div style={{ flex: '1 1 500px', padding: '2rem', borderRight: '1px solid var(--border-default)' }}>
                <div className="grid grid-2" style={{ gap: '1.5rem' }}>
                  
                  <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                    <EmployerCampusTargetPicker
                      campuses={approvedCampuses}
                      selection={selectedTenantIds}
                      onSelectionChange={setSelectedTenantIds}
                      label={(
                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.4rem', fontWeight: 700 }}>
                          <Building2 size={16} className="text-primary-600" aria-hidden />
                          Target campuses
                        </span>
                      )}
                      required
                      hint="Campuses will receive notifications when this job is published."
                      emptyMessage="No approved campuses yet. Request access from the campus directory first."
                    />
                  </div>

                  <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                    <label className="form-label font-bold">Job Title <span className="required">*</span></label>
                    <input className="form-input" placeholder="e.g. Software Development Engineer" value={form.title} onChange={(e) => setField('title', e.target.value)} style={{ fontSize: '1.1rem', padding: '0.75rem' }} />
                  </div>

                  <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                    <label className="form-label font-bold">Key skills</label>
                    <input className="form-input" placeholder="e.g. Java, AWS, stakeholder management, system design" value={form.keywords} onChange={(e) => setField('keywords', e.target.value)} />
                    <p className="text-xs text-tertiary" style={{ marginTop: '0.35rem' }}>Comma-separated skills (like Naukri / Monster key skills).</p>
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Employment type <span className="required">*</span></label>
                    <select className="form-select" value={form.type} onChange={(e) => setField('type', e.target.value)}>
                      {Object.entries(ALUMNI_EMPLOYMENT_TYPE_LABELS).map(([value, label]) => (
                        <option key={value} value={value}>{label}</option>
                      ))}
                    </select>
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Seniority band</label>
                    <select className="form-select" value={form.seniorityLevel} onChange={(e) => setField('seniorityLevel', e.target.value)}>
                      {ALUMNI_SENIORITY_LEVELS.map((o) => (
                        <option key={o.value} value={o.value}>{o.label}</option>
                      ))}
                    </select>
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Min experience (years)</label>
                    <ValidatedNumberInput
                      fieldId={FIELD_IDS.EMPLOYER_MIN_EXPERIENCE}
                      placeholder="2"
                      value={form.minExperience}
                      onChange={(v) => setField('minExperience', v)}
                      className="form-input"
                    />
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Max experience (years)</label>
                    <ValidatedNumberInput
                      fieldId={FIELD_IDS.EMPLOYER_MAX_EXPERIENCE}
                      context={{ minExperience: form.minExperience }}
                      placeholder="8"
                      value={form.maxExperience}
                      onChange={(v) => setField('maxExperience', v)}
                      className="form-input"
                    />
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Work mode</label>
                    <select className="form-select" value={form.workMode} onChange={(e) => setField('workMode', e.target.value)}>
                      {ALUMNI_WORK_MODES.map((o) => (
                        <option key={o.value} value={o.value}>{o.label}</option>
                      ))}
                    </select>
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Job location</label>
                    <input className="form-input" placeholder="e.g. Bengaluru, Chennai" value={form.location} onChange={(e) => setField('location', e.target.value)} />
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Industry / function</label>
                    <input className="form-input" placeholder="e.g. IT Services, Product Engineering" value={form.industry} onChange={(e) => setField('industry', e.target.value)} />
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Education</label>
                    <select className="form-select" value={form.educationLevel} onChange={(e) => setField('educationLevel', e.target.value)}>
                      {ALUMNI_EDUCATION_LEVELS.map((o) => (
                        <option key={o.value} value={o.value}>{o.label}</option>
                      ))}
                    </select>
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Notice period (days)</label>
                    <ValidatedNumberInput
                      fieldId={FIELD_IDS.EMPLOYER_NOTICE_PERIOD}
                      placeholder="30"
                      value={form.noticePeriodDays}
                      onChange={(v) => setField('noticePeriodDays', v)}
                      className="form-input"
                    />
                  </div>
                  
                  <div className="form-group">
                    <label className="form-label font-bold">Min salary (annual CTC)</label>
                    <CurrencyAmountInput
                      fieldId={FIELD_IDS.EMPLOYER_SALARY_MIN}
                      placeholder="800000"
                      value={form.salaryMin}
                      onChange={(v) => setField('salaryMin', v)}
                    />
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Max salary (annual CTC)</label>
                    <CurrencyAmountInput
                      fieldId={FIELD_IDS.EMPLOYER_SALARY_MAX}
                      context={{ salaryMin: form.salaryMin }}
                      placeholder="1500000"
                      value={form.salaryMax}
                      onChange={(v) => setField('salaryMax', v)}
                    />
                  </div>

                  <div className="form-group">
                    <label className="form-label font-bold">Openings</label>
                    <ValidatedNumberInput fieldId={FIELD_IDS.EMPLOYER_VACANCIES} placeholder="10" value={form.vacancies} onChange={(v) => setField('vacancies', v)} />
                  </div>
                </div>
              </div>

              {/* Preview & Editor Section */}
              <div style={{ flex: '1 1 500px', display: 'flex', flexDirection: 'column', background: 'var(--bg-secondary)' }}>
                <div style={{ padding: '1.5rem', borderBottom: '1px solid var(--border-default)', background: 'var(--bg-primary)' }}>
                  <h3 style={{ fontSize: '1.1rem', fontWeight: 700, display: 'flex', alignItems: 'center', gap: '0.5rem', margin: 0 }}>
                    <AlignLeft size={18} className="text-secondary" /> Job Description Preview
                  </h3>
                  <p className="text-xs text-secondary" style={{ margin: '0.25rem 0 0' }}>
                    Auto-generated from fields. Edit below to refine.
                  </p>
                </div>
                
                <div style={{ padding: '1.5rem', flex: 1, display: 'flex', flexDirection: 'column' }}>
                  <textarea
                    className="form-textarea"
                    style={{ flex: 1, minHeight: '400px', fontSize: '0.95rem', lineHeight: 1.6, padding: '1.25rem', fontFamily: 'var(--font-mono, monospace)', background: 'var(--bg-primary)' }}
                    placeholder="Description is generated from the fields…"
                    value={form.description}
                    onChange={(e) => setField('description', e.target.value)}
                  />
                </div>
              </div>
            </div>

            <div style={{ padding: '1.5rem 2rem', borderTop: '1px solid var(--border-default)', display: 'flex', justifyContent: 'flex-end', gap: '1rem', background: 'var(--bg-primary)' }}>
              <button className="btn btn-ghost" type="button" disabled={submitting} onClick={closeModal} style={{ fontWeight: 600 }}>
                Cancel
              </button>
              <button className="btn btn-secondary" type="button" disabled={submitting} onClick={() => submitJob(true)} style={{ fontWeight: 600 }}>
                Save as Draft
              </button>
              <button className="btn btn-primary" type="button" disabled={submitting} onClick={() => submitJob(false)} style={{ fontWeight: 600, display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                <CheckCircle2 size={16} />
                {modalMode === 'edit' && editingJob?.status === 'published'
                  ? 'Update Published Job'
                  : submitting
                    ? 'Publishing…'
                    : 'Publish Job'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useCallback, useMemo, useState } from 'react';
import useSWR from 'swr';
import Link from 'next/link';
import { FileEdit, Plus } from 'lucide-react';
import { useToast } from '@/components/ToastProvider';
import { DEFAULT_OFFER_TEMPLATE_BODY, OFFER_TEMPLATE_PLACEHOLDERS } from '@/lib/offerTemplateRender';
import { formatCurrency } from '@/lib/utils';
import ValidatedNumberInput from '@/components/form/ValidatedNumberInput';
import ValidatedDateInput from '@/components/form/ValidatedDateInput';
import { FIELD_IDS } from '@/lib/inputConstraints';
import EmployerListFormLayout from '@/components/employer/EmployerListFormLayout';
import OfferEventTypeTabs, { OFFER_EVENT_TABS } from '@/components/employer/OfferEventTypeTabs';
import { countOfferEventTypes, normalizeOfferEventType, templateMatchesEventTab } from '@/lib/offerEventType';
import { StandardTableIconAction } from '@/components/ui/StandardTableIconAction';

const fetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load templates');
  return json;
};

const emptyForm = {
  name: '',
  jobTitle: '',
  salary: '',
  location: '',
  joiningDate: '',
  responseDeadline: '',
  bodyTemplate: DEFAULT_OFFER_TEMPLATE_BODY,
  eventType: 'drive',
};

function eventTypeLabel(id) {
  return OFFER_EVENT_TABS.find((t) => t.id === id)?.label || id;
}

export default function EmployerOfferTemplatesPage() {
  const { addToast } = useToast();
  const { data, error, isLoading, mutate } = useSWR('/api/employer/offer-templates', fetcher);
  const templates = Array.isArray(data?.templates) ? data.templates : [];

  const [eventTab, setEventTab] = useState('drive');
  const [mode, setMode] = useState(null);
  const [editId, setEditId] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);

  const eventCounts = useMemo(
    () =>
      countOfferEventTypes(templates, (t) =>
        normalizeOfferEventType(t.eventType ?? t.event_type),
      ),
    [templates],
  );

  const tabTemplates = useMemo(
    () => templates.filter((t) => templateMatchesEventTab(t, eventTab)),
    [templates, eventTab],
  );

  const openCreate = () => {
    setEditId(null);
    setForm({ ...emptyForm, eventType: eventTab });
    setMode('form');
  };

  const openEdit = (t) => {
    setEditId(t.id);
    setForm({
      name: t.name || '',
      jobTitle: t.jobTitle || '',
      salary: t.salary != null ? String(t.salary) : '',
      location: t.location || '',
      joiningDate: t.joiningDate || '',
      responseDeadline: t.responseDeadline || '',
      bodyTemplate: t.bodyTemplate || DEFAULT_OFFER_TEMPLATE_BODY,
      eventType: normalizeOfferEventType(t.eventType ?? t.event_type),
    });
    setMode('form');
  };

  const saveTemplate = async () => {
    setSaving(true);
    try {
      const payload = {
        ...form,
        salary: Number(form.salary || 0),
      };
      const url = editId ? `/api/employer/offer-templates/${editId}` : '/api/employer/offer-templates';
      const res = await fetch(url, {
        method: editId ? 'PATCH' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Save failed');
      addToast(editId ? 'Template updated.' : 'Template created.', 'success');
      setMode(null);
      await mutate();
    } catch (e) {
      addToast(e.message || 'Save failed', 'error');
    } finally {
      setSaving(false);
    }
  };

  const deactivate = useCallback(
    async (id) => {
      if (!window.confirm('Remove this template? Existing offers keep their generated letters.')) return;
      try {
        const res = await fetch(`/api/employer/offer-templates/${id}`, { method: 'DELETE' });
        const json = await res.json();
        if (!res.ok) throw new Error(json?.error || 'Delete failed');
        addToast('Template removed.', 'success');
        await mutate();
      } catch (e) {
        addToast(e.message || 'Delete failed', 'error');
      }
    },
    [addToast, mutate],
  );

  if (mode === 'form') {
    return (
      <EmployerListFormLayout
        title={editId ? 'Edit offer template' : 'New offer template'}
        subtitle="CTC and dates are fixed for every student when you bulk-generate. Use placeholders in the letter body for student-specific text."
        onBack={() => setMode(null)}
        footer={
          <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end' }}>
            <button type="button" className="btn btn-secondary" onClick={() => setMode(null)} disabled={saving}>
              Cancel
            </button>
            <button type="button" className="btn btn-primary" onClick={saveTemplate} disabled={saving}>
              {saving ? 'Saving…' : 'Save template'}
            </button>
          </div>
        }
      >
        <div className="grid grid-2">
          <div className="form-group">
            <label className="form-label">Template name</label>
            <input className="form-input" value={form.name} onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))} placeholder="e.g. TechCorp SDE — Mar 2026" />
          </div>
          <div className="form-group">
            <label className="form-label">Event type</label>
            <select
              className="form-select"
              value={form.eventType}
              onChange={(e) => setForm((p) => ({ ...p, eventType: e.target.value }))}
            >
              {OFFER_EVENT_TABS.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.label}
                </option>
              ))}
            </select>
          </div>
          <div className="form-group">
            <label className="form-label">Role / job title</label>
            <input className="form-input" value={form.jobTitle} onChange={(e) => setForm((p) => ({ ...p, jobTitle: e.target.value }))} />
          </div>
          <div className="form-group">
            <label className="form-label">CTC (INR annual — fixed for all offers from this template)</label>
            <ValidatedNumberInput fieldId={FIELD_IDS.EMPLOYER_OFFER_SALARY} value={form.salary} onChange={(v) => setForm((p) => ({ ...p, salary: v }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Location</label>
            <input className="form-input" value={form.location} onChange={(e) => setForm((p) => ({ ...p, location: e.target.value }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Joining date</label>
            <ValidatedDateInput fieldId={FIELD_IDS.EMPLOYER_OFFER_JOINING} context={{ deadline: form.responseDeadline }} value={form.joiningDate} onChange={(v) => setForm((p) => ({ ...p, joiningDate: v }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Response deadline</label>
            <ValidatedDateInput fieldId={FIELD_IDS.EMPLOYER_OFFER_DEADLINE} value={form.responseDeadline} onChange={(v) => setForm((p) => ({ ...p, responseDeadline: v }))} />
          </div>
        </div>
        <div className="form-group">
          <label className="form-label">Letter body</label>
          <p className="text-xs text-secondary" style={{ margin: '0 0 0.5rem' }}>
            Placeholders:{' '}
            {OFFER_TEMPLATE_PLACEHOLDERS.map((p) => `{{${p.key}}}`).join(', ')}. CTC is <strong>not</strong> a placeholder — it
            comes from the CTC field above.
          </p>
          <textarea className="form-textarea" rows={12} value={form.bodyTemplate} onChange={(e) => setForm((p) => ({ ...p, bodyTemplate: e.target.value }))} />
        </div>
      </EmployerListFormLayout>
    );
  }

  return (
    <div className="animate-fadeIn">
      <div className="page-header">
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <FileEdit size={22} /> Offer templates
          </h1>
          <p className="text-secondary" style={{ margin: '0.25rem 0 0', lineHeight: 1.55 }}>
            Reusable letter layouts with fixed CTC. Use{' '}
            <Link href="/dashboard/employer/offers" className="link-inline" style={{ fontWeight: 600 }}>
              Offers → Generate from selections
            </Link>{' '}
            to create pending offers and email all new selections.
          </p>
        </div>
        <button type="button" className="btn btn-primary" onClick={openCreate}>
          <Plus size={16} aria-hidden /> New template
        </button>
      </div>

      <OfferEventTypeTabs activeTab={eventTab} onTabChange={setEventTab} counts={eventCounts} />

      {error ? <p style={{ color: 'var(--danger-600)' }}>{error.message}</p> : null}
      {isLoading ? <div className="skeleton skeleton-card" style={{ height: 200 }} /> : null}

      {!isLoading && tabTemplates.length === 0 ? (
        <div className="card" style={{ padding: '2rem', textAlign: 'center' }}>
          <p className="text-secondary">
            No {eventTypeLabel(eventTab).toLowerCase()} templates yet.
            {eventTab === 'drive'
              ? ' Create one before bulk-generating drive offers.'
              : eventTab === 'internship'
                ? ' Create one for internship selection offers (and PPO job offers after internship).'
                : ' Create one for alumni job offer letters.'}
          </p>
          <button type="button" className="btn btn-primary" style={{ marginTop: '1rem' }} onClick={openCreate}>
            Create {eventTypeLabel(eventTab).toLowerCase()} template
          </button>
        </div>
      ) : null}

      <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        {tabTemplates.map((t) => (
          <div key={t.id} className="card" style={{ padding: '1.25rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', gap: '1rem', flexWrap: 'wrap' }}>
              <div>
                <h3 style={{ margin: '0 0 0.25rem', fontSize: '1.05rem' }}>{t.name}</h3>
                <p className="text-sm text-secondary" style={{ margin: 0 }}>
                  {t.jobTitle} · CTC {formatCurrency(Number(t.salary) || 0)} · {t.location || 'Location TBD'}
                </p>
              </div>
              <div style={{ display: 'flex', gap: '0.35rem' }}>
                <StandardTableIconAction action="edit" onClick={() => openEdit(t)} />
                <StandardTableIconAction action="delete" variant="danger" onClick={() => deactivate(t.id)} />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import { useCallback, useState, useMemo } from 'react';
import useSWR from 'swr';
import { RotateCcw, CheckCircle, Clock, XCircle, Search, Mail, Send, FileText } from 'lucide-react';
import { formatDate, formatCurrency, formatStatus, getStatusColor } from '@/lib/utils';
import { StandardTableIconAction } from '@/components/ui/StandardTableIconAction';
import { ExportCsvSplitButton } from '@/components/export/ExportCsvSplitButton';
import { useToast } from '@/components/ToastProvider';
import ValidatedNumberInput from '@/components/form/ValidatedNumberInput';
import ValidatedDateInput from '@/components/form/ValidatedDateInput';
import { FIELD_IDS } from '@/lib/inputConstraints';
import { validateEmployerOfferPayload } from '@/lib/apiInputValidation';
import EmployerListFormLayout from '@/components/employer/EmployerListFormLayout';
import BulkOfferGeneratePanel from '@/components/employer/BulkOfferGeneratePanel';
import OfferEventTypeTabs from '@/components/employer/OfferEventTypeTabs';
import AppPageHeader from '@/components/layout/AppPageHeader';
import AppStatCard from '@/components/layout/AppStatCard';
import AppContentCard from '@/components/layout/AppContentCard';
import {
  classifyOfferEventType,
  countOfferEventTypes,
  templateMatchesEventTab,
} from '@/lib/offerEventType';

const emptyOfferForm = {
  studentId: '',
  driveId: '',
  jobTitle: '',
  salary: '',
  location: '',
  joiningDate: '',
  deadlineAt: '',
  offerLetterUrl: '',
};

const fetcher = async (url) => {
  const res = await fetch(url);
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || 'Failed to load offers');
  return data;
};

export default function EmployerOffersPage() {
  const { addToast } = useToast();
  const { data, error, isLoading, mutate } = useSWR('/api/employer/offers', fetcher);
  const { data: optionsData } = useSWR('/api/employer/offers/options', fetcher);
  const { data: templatesData } = useSWR('/api/employer/offer-templates', fetcher);
  const [showCreate, setShowCreate] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [sortOption, setSortOption] = useState('date_desc');
  const [eventTab, setEventTab] = useState('drive');
  const [editId, setEditId] = useState(null);
  const [viewRow, setViewRow] = useState(null);
  const [form, setForm] = useState(emptyOfferForm);
  const [editForm, setEditForm] = useState({
    driveId: '',
    jobTitle: '',
    salary: '',
    location: '',
    joiningDate: '',
    deadlineAt: '',
  });

  const offers = Array.isArray(data?.offers) ? data.offers : [];
  const students = Array.isArray(optionsData?.students) ? optionsData.students : [];
  const drives = Array.isArray(optionsData?.drives) ? optionsData.drives : [];
  const internships = Array.isArray(optionsData?.internships) ? optionsData.internships : [];
  const templates = Array.isArray(templatesData?.templates) ? templatesData.templates : [];

  const eventCounts = useMemo(
    () => countOfferEventTypes(offers, classifyOfferEventType),
    [offers],
  );

  const tabOffers = useMemo(
    () => offers.filter((o) => classifyOfferEventType(o) === eventTab),
    [offers, eventTab],
  );

  const driveTemplates = useMemo(
    () => templates.filter((t) => templateMatchesEventTab(t, 'drive')),
    [templates],
  );

  const internshipTemplates = useMemo(
    () => templates.filter((t) => templateMatchesEventTab(t, 'internship')),
    [templates],
  );

  const filteredOffers = useMemo(() => {
    const result = tabOffers.filter((o) => {
      if (statusFilter && o.status !== statusFilter) return false;
      if (search) {
        const q = search.toLowerCase();
        const blob = [o.student_name, o.college_name, o.job_title, o.location].filter(Boolean).join(' ').toLowerCase();
        if (!blob.includes(q)) return false;
      }
      return true;
    });

    return result.sort((a, b) => {
      if (sortOption === 'date_desc') return new Date(b.created_at || 0) - new Date(a.created_at || 0);
      if (sortOption === 'date_asc') return new Date(a.created_at || 0) - new Date(b.created_at || 0);
      if (sortOption === 'salary_desc') return (Number(b.salary) || 0) - (Number(a.salary) || 0);
      if (sortOption === 'name_asc') return (a.student_name || '').localeCompare(b.student_name || '');
      return 0;
    });
  }, [tabOffers, search, statusFilter, sortOption]);

  const submitCreateOffer = async () => {
    if (!form.studentId || !form.jobTitle.trim()) {
      addToast('Student and job title are required.', 'warning');
      return;
    }
    const offerErr = validateEmployerOfferPayload({
      salary: form.salary,
      deadline: form.deadlineAt,
      joiningDate: form.joiningDate,
    });
    if (offerErr) {
      addToast(offerErr, 'warning');
      return;
    }
    setSubmitting(true);
    try {
      const res = await fetch('/api/employer/offers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...form,
          salary: Number(form.salary || 0),
          deadlineAt: form.deadlineAt ? new Date(`${form.deadlineAt}T23:59:59`).toISOString() : null,
          offerLetterUrl: form.offerLetterUrl.trim() || null,
        }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Failed to create offer');
      setShowCreate(false);
      setForm(emptyOfferForm);
      await mutate();
      addToast('Offer created successfully.', 'success');
    } catch (e) {
      addToast(e.message || 'Failed to create offer', 'error');
    } finally {
      setSubmitting(false);
    }
  };

  const revokeOffer = async (id) => {
    try {
      const res = await fetch('/api/employer/offers', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, status: 'revoked' }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Failed to revoke offer');
      await mutate();
      addToast('Offer revoked.', 'success');
    } catch (e) {
      addToast(e.message || 'Failed to revoke offer', 'error');
    }
  };

  const reopenOffer = async (id) => {
    if (!confirm('Reopen this offer as pending? Clears acceptance / decline timestamps so the student can respond again.')) {
      return;
    }
    try {
      const res = await fetch('/api/employer/offers', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, status: 'pending' }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Failed to reopen offer');
      await mutate();
      addToast('Offer set back to pending.', 'success');
    } catch (e) {
      addToast(e.message || 'Failed to reopen offer', 'error');
    }
  };

  const openEdit = (offer) => {
    setEditId(offer.id);
    setShowCreate(false);
    setViewRow(null);
    setEditForm({
      driveId: offer.drive_id || '',
      jobTitle: offer.job_title || '',
      salary: offer.salary != null ? String(offer.salary) : '',
      location: offer.location || '',
      joiningDate: offer.joining_date ? String(offer.joining_date).slice(0, 10) : '',
      deadlineAt: offer.deadline_at ? String(offer.deadline_at).slice(0, 10) : '',
      offerLetterUrl: offer.offer_letter_url || '',
    });
  };

  const submitEditOffer = async () => {
    if (!editId) return;
    const offerErr = validateEmployerOfferPayload({
      salary: editForm.salary,
      deadline: editForm.deadlineAt,
      joiningDate: editForm.joiningDate,
    });
    if (offerErr) {
      addToast(offerErr, 'warning');
      return;
    }
    setSubmitting(true);
    try {
      const res = await fetch('/api/employer/offers', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: editId,
          driveId: editForm.driveId || null,
          jobTitle: editForm.jobTitle.trim(),
          salary: Number(editForm.salary || 0),
          location: editForm.location.trim() || null,
          joiningDate: editForm.joiningDate || null,
          deadlineAt: editForm.deadlineAt ? new Date(`${editForm.deadlineAt}T23:59:59`).toISOString() : null,
          offerLetterUrl: editForm.offerLetterUrl.trim() || null,
          syncReportedCompanyFromProfile: true,
        }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Failed to update offer');
      setEditId(null);
      await mutate();
      addToast('Offer updated.', 'success');
    } catch (e) {
      addToast(e.message || 'Failed to update offer', 'error');
    } finally {
      setSubmitting(false);
    }
  };

  const deleteOffer = async (id) => {
    if (!confirm('Delete this offer row permanently?')) return;
    try {
      const res = await fetch('/api/employer/offers', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Failed to delete offer');
      if (editId === id) setEditId(null);
      if (viewRow?.id === id) setViewRow(null);
      await mutate();
      addToast('Offer removed.', 'success');
    } catch (e) {
      addToast(e.message || 'Failed to delete offer', 'error');
    }
  };

  const resendOfferEmail = async (id) => {
    try {
      const res = await fetch(`/api/employer/offers/${id}/resend`, { method: 'POST' });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(json?.error || 'Failed to resend email');
      addToast(json.message || 'Offer email sent again.', 'success');
    } catch (e) {
      addToast(e.message || 'Failed to resend email', 'error');
    }
  };

  const getOffersCsv = useCallback((_scope) => {
    const list = _scope === 'current' ? filteredOffers : tabOffers;
    const headers = ['Student', 'College', 'Role', 'Salary_INR', 'Salary_display', 'Location', 'Deadline', 'Status', 'Created'];
    const rows = list.map((o) => [
      o.student_name || '—',
      o.college_name || '—',
      o.job_title || '—',
      String(Number(o.salary) || 0),
      formatCurrency(Number(o.salary) || 0),
      o.location || '—',
      o.deadline_at || '',
      o.status || '',
      o.created_at || '',
    ]);
    return { headers, rows };
  }, [tabOffers, filteredOffers]);

  if (isLoading) {
    return (
      <div className="app-page-shell">
        <div className="skeleton skeleton-card" style={{ height: 120 }} />
        <div className="app-stat-grid">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="skeleton skeleton-card" style={{ height: 104 }} />
          ))}
        </div>
        <div className="skeleton skeleton-card" style={{ height: 320 }} />
      </div>
    );
  }

  if (error) {
    return (
      <div className="app-page-shell">
        <AppContentCard title="Could not load offers">
          <p style={{ margin: 0, color: 'var(--danger-600)' }}>{error.message || 'Could not load offers.'}</p>
          <p className="text-sm text-secondary" style={{ margin: '0.5rem 0 0' }}>
            Confirm you are signed in as an employer, then reload or contact support if this continues.
          </p>
        </AppContentCard>
      </div>
    );
  }

  const acceptedCount = tabOffers.filter((offer) => offer.status === 'accepted').length;
  const pendingCount = tabOffers.filter((offer) => offer.status === 'pending').length;
  const declinedCount = tabOffers.filter((offer) => ['rejected', 'declined'].includes(offer.status)).length;

  const closeCreateForm = () => {
    setShowCreate(false);
    setForm(emptyOfferForm);
  };

  const closeEditForm = () => setEditId(null);

  if (showCreate) {
    return (
      <EmployerListFormLayout
        title="Create offer"
        subtitle="Creates a pending offer the student can accept or decline on My Offers."
        onBack={closeCreateForm}
        footer={
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem' }}>
            <button type="button" className="btn btn-secondary" disabled={submitting} onClick={closeCreateForm}>
              Cancel
            </button>
            <button type="button" className="btn btn-primary" onClick={submitCreateOffer} disabled={submitting}>
              {submitting ? 'Creating…' : 'Create Offer'}
            </button>
          </div>
        }
      >
        <div className="grid grid-2">
          <div className="form-group">
            <label className="form-label">Student</label>
            <select className="form-select" value={form.studentId} onChange={(e) => setForm((p) => ({ ...p, studentId: e.target.value }))}>
              <option value="">Select student</option>
              {students.map((s) => (
                <option key={s.id} value={s.id}>{s.name}{s.collegeName ? ` — ${s.collegeName}` : ''}</option>
              ))}
            </select>
          </div>
          <div className="form-group">
            <label className="form-label">Drive (optional)</label>
            <select className="form-select" value={form.driveId} onChange={(e) => setForm((p) => ({ ...p, driveId: e.target.value }))}>
              <option value="">Not linked</option>
              {drives.map((d) => (
                <option key={d.id} value={d.id}>{d.title} {d.drive_date ? `(${formatDate(d.drive_date)})` : ''}</option>
              ))}
            </select>
          </div>
          <div className="form-group">
            <label className="form-label">Job title</label>
            <input className="form-input" value={form.jobTitle} onChange={(e) => setForm((p) => ({ ...p, jobTitle: e.target.value }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Salary (INR annual)</label>
            <ValidatedNumberInput fieldId={FIELD_IDS.EMPLOYER_OFFER_SALARY} value={form.salary} onChange={(v) => setForm((p) => ({ ...p, salary: v }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Location</label>
            <input className="form-input" value={form.location} onChange={(e) => setForm((p) => ({ ...p, location: e.target.value }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Joining date</label>
            <ValidatedDateInput fieldId={FIELD_IDS.EMPLOYER_OFFER_JOINING} context={{ deadline: form.deadlineAt }} value={form.joiningDate} onChange={(v) => setForm((p) => ({ ...p, joiningDate: v }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Response deadline</label>
            <ValidatedDateInput fieldId={FIELD_IDS.EMPLOYER_OFFER_DEADLINE} value={form.deadlineAt} onChange={(v) => setForm((p) => ({ ...p, deadlineAt: v }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Offer letter URL (optional)</label>
            <input className="form-input" placeholder="https://..." value={form.offerLetterUrl} onChange={(e) => setForm((p) => ({ ...p, offerLetterUrl: e.target.value }))} />
          </div>
        </div>
      </EmployerListFormLayout>
    );
  }

  if (editId) {
    return (
      <EmployerListFormLayout
        title="Edit offer"
        subtitle="Updates terms for this row. Use Reopen to pending on the list to roll back status."
        onBack={closeEditForm}
        footer={
          <div style={{ display: 'flex', gap: '0.5rem' }}>
            <button type="button" className="btn btn-primary" onClick={submitEditOffer} disabled={submitting}>
              {submitting ? 'Saving…' : 'Save changes'}
            </button>
            <button type="button" className="btn btn-secondary" onClick={closeEditForm} disabled={submitting}>
              Cancel
            </button>
          </div>
        }
      >
        <div className="grid grid-2">
          <div className="form-group">
            <label className="form-label">Drive (optional)</label>
            <select className="form-select" value={editForm.driveId} onChange={(e) => setEditForm((p) => ({ ...p, driveId: e.target.value }))}>
              <option value="">Not linked</option>
              {drives.map((d) => (
                <option key={d.id} value={d.id}>{d.title} {d.drive_date ? `(${formatDate(d.drive_date)})` : ''}</option>
              ))}
            </select>
          </div>
          <div className="form-group">
            <label className="form-label">Job title</label>
            <input className="form-input" value={editForm.jobTitle} onChange={(e) => setEditForm((p) => ({ ...p, jobTitle: e.target.value }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Salary (INR annual)</label>
            <ValidatedNumberInput fieldId={FIELD_IDS.EMPLOYER_OFFER_SALARY} value={editForm.salary} onChange={(v) => setEditForm((p) => ({ ...p, salary: v }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Location</label>
            <input className="form-input" value={editForm.location} onChange={(e) => setEditForm((p) => ({ ...p, location: e.target.value }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Joining date</label>
            <ValidatedDateInput fieldId={FIELD_IDS.EMPLOYER_OFFER_JOINING} context={{ deadline: editForm.deadlineAt }} value={editForm.joiningDate} onChange={(v) => setEditForm((p) => ({ ...p, joiningDate: v }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Response deadline</label>
            <ValidatedDateInput fieldId={FIELD_IDS.EMPLOYER_OFFER_DEADLINE} value={editForm.deadlineAt} onChange={(v) => setEditForm((p) => ({ ...p, deadlineAt: v }))} />
          </div>
          <div className="form-group">
            <label className="form-label">Offer letter URL (optional)</label>
            <input className="form-input" placeholder="https://..." value={editForm.offerLetterUrl} onChange={(e) => setEditForm((p) => ({ ...p, offerLetterUrl: e.target.value }))} />
          </div>
        </div>
      </EmployerListFormLayout>
    );
  }

  const tabLabel =
    eventTab === 'internship' ? 'Internship' : eventTab === 'alumni_jobs' ? 'Alumni jobs' : 'Drive';

  return (
    <div className="app-page-shell animate-fadeIn">
      <AppPageHeader
        title="Offers"
        description="Issue formal offer letters after selection. Bulk-generate from drive or internship selections, or create a single offer for special cases."
        actions={
          <>
            <ExportCsvSplitButton
              filenameBase="placement_offers"
              currentCount={filteredOffers.length}
              fullCount={tabOffers.length}
              getRows={getOffersCsv}
            />
            <StandardTableIconAction
              action="add"
              variant="primary"
              onClick={() => {
                setShowCreate(true);
                setEditId(null);
              }}
            />
          </>
        }
      />

      <div className="app-stat-grid">
        <AppStatCard
          label={`${tabLabel} offers`}
          value={tabOffers.length}
          hint="In this tab"
          icon={Send}
          tone="indigo"
        />
        <AppStatCard label="Accepted" value={acceptedCount} icon={CheckCircle} tone="green" />
        <AppStatCard label="Pending response" value={pendingCount} icon={Clock} tone="amber" />
        <AppStatCard label="Declined / rejected" value={declinedCount} icon={XCircle} tone="rose" />
      </div>

      <OfferEventTypeTabs activeTab={eventTab} onTabChange={setEventTab} counts={eventCounts} />

      {eventTab === 'drive' ? (
        <BulkOfferGeneratePanel scope="drive" postings={drives} templates={driveTemplates} onGenerated={mutate} />
      ) : null}

      {eventTab === 'internship' ? (
        <>
          <BulkOfferGeneratePanel
            scope="internship"
            postings={internships}
            templates={internshipTemplates}
            onGenerated={mutate}
          />
          <AppContentCard
            title="PPO (full-time after internship)"
            description={
              <>
                Pre-Placement Offers are separate from internship selection offers. Confirm PPO on or after internship
                start, then generate from{' '}
                <a href="/dashboard/employer/internship-ppo" className="link-inline" style={{ fontWeight: 600 }}>
                  Internship PPO
                </a>
                .
              </>
            }
          />
        </>
      ) : null}

      {eventTab === 'alumni_jobs' ? (
        <AppContentCard
          title="Alumni job offers"
          description="One-off offers for alumni job selections — use Create offer without linking a placement drive."
        />
      ) : null}

      <details className="app-help-disclosure">
        <summary>How offers work on PlacementHub</summary>
        <div className="app-help-disclosure__body">
          <p>
            <strong>Bulk generate</strong> creates pending offers for selected students who do not have one yet. Students
            accept or decline on <strong>My Offers</strong>.
          </p>
          <p>
            <strong>Resend email</strong> if a student did not receive the letter. Each row is one student — five students
            with the same package means five rows.
          </p>
        </div>
      </details>

      <AppContentCard title="Offer register" description={`${tabLabel} offers issued to students.`} padding={false}>
        <div style={{ padding: '1.25rem 1.5rem 0' }}>
          <div className="app-table-toolbar">
            <div className="app-table-toolbar__search">
              <Search size={15} className="app-table-toolbar__search-icon" aria-hidden />
              <input
                className="form-input"
                placeholder="Search student, college, role..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
            <select className="form-select" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={{ maxWidth: 180 }}>
              <option value="">All statuses</option>
              <option value="pending">Pending</option>
              <option value="accepted">Accepted</option>
              <option value="declined">Declined</option>
              <option value="rejected">Rejected</option>
              <option value="revoked">Revoked</option>
              <option value="expired">Expired</option>
            </select>
            <select className="form-select" value={sortOption} onChange={(e) => setSortOption(e.target.value)} style={{ maxWidth: 180 }}>
              <option value="date_desc">Newest first</option>
              <option value="date_asc">Oldest first</option>
              <option value="salary_desc">Highest salary</option>
              <option value="name_asc">Name (A–Z)</option>
            </select>
            <span className="app-table-toolbar__meta">
              {filteredOffers.length} of {tabOffers.length} shown
            </span>
          </div>
        </div>

        <div style={{ padding: '0 1.5rem 1.5rem' }}>
          <div className="table-container">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Student</th>
                  <th>Role</th>
                  <th>Salary</th>
                  <th>Location</th>
                  <th>Deadline</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredOffers.length > 0 ? (
                  filteredOffers.map((offer) => (
                    <tr key={offer.id}>
                      <td>
                        <div className="app-table-primary">{offer.student_name || '—'}</div>
                        <div className="app-table-secondary">{offer.college_name || '—'}</div>
                      </td>
                      <td>{offer.job_title || '—'}</td>
                      <td className="font-bold">{formatCurrency(Number(offer.salary) || 0)}</td>
                      <td>{offer.location || '—'}</td>
                      <td className="text-sm">{offer.deadline_at ? formatDate(offer.deadline_at) : '—'}</td>
                      <td>
                        <span className={`badge badge-${getStatusColor(offer.status)} badge-dot`}>
                          {formatStatus(offer.status || 'unknown')}
                        </span>
                      </td>
                      <td>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.35rem', alignItems: 'center' }}>
                          <StandardTableIconAction
                            action="view"
                            showLabel={false}
                            onClick={() => {
                              setViewRow(offer);
                            }}
                          />
                          <StandardTableIconAction action="edit" showLabel={false} onClick={() => openEdit(offer)} />
                          {['accepted', 'rejected', 'revoked', 'expired'].includes(offer.status) && (
                            <button
                              type="button"
                              className="btn btn-secondary btn-icon btn-sm"
                              title="Restore pending offer"
                              aria-label="Restore pending offer"
                              onClick={() => reopenOffer(offer.id)}
                            >
                              <RotateCcw size={16} strokeWidth={2} aria-hidden />
                            </button>
                          )}
                          {offer.status === 'pending' && (
                            <>
                              <button
                                type="button"
                                className="btn btn-secondary btn-icon btn-sm"
                                title="Resend offer email"
                                aria-label="Resend offer email"
                                onClick={() => resendOfferEmail(offer.id)}
                              >
                                <Mail size={16} strokeWidth={2} aria-hidden />
                              </button>
                              <StandardTableIconAction
                                action="archive"
                                variant="danger"
                                showLabel={false}
                                onClick={() => revokeOffer(offer.id)}
                              />
                            </>
                          )}
                          <StandardTableIconAction
                            action="delete"
                            variant="danger"
                            showLabel={false}
                            onClick={() => deleteOffer(offer.id)}
                          />
                        </div>
                      </td>
                    </tr>
                  ))
                ) : null}
                {tabOffers.length === 0 && (
                  <tr>
                    <td colSpan="7" style={{ padding: '3rem 1rem' }}>
                      <div className="empty-state-container" style={{ textAlign: 'center', maxWidth: '420px', margin: '0 auto' }}>
                        <FileText size={32} strokeWidth={1.5} style={{ color: 'var(--text-tertiary)', marginBottom: '0.75rem' }} />
                        <h3 style={{ fontSize: '1.125rem', fontWeight: 600, color: 'var(--text-primary)', marginBottom: '0.5rem' }}>
                          No {eventTab === 'internship' ? 'internship' : eventTab === 'alumni_jobs' ? 'alumni job' : 'drive'} offers yet
                        </h3>
                        <p style={{ color: 'var(--text-secondary)', fontSize: '0.9375rem', marginBottom: 0, lineHeight: 1.5 }}>
                          {eventTab === 'drive'
                            ? 'Mark students selected on a drive, create a Drive template, then use Generate offers above — or Create offer for one student.'
                            : eventTab === 'internship'
                              ? 'Mark students selected on Applications → Internships, create an Internship template, then use Generate internship offers above. PPO is a separate step after the internship.'
                              : 'Use Create offer for alumni selections that are not tied to a campus placement drive.'}
                        </p>
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </AppContentCard>

      {viewRow ? (
        <AppContentCard
          title="Offer detail"
          actions={
            <button type="button" className="btn btn-secondary btn-sm" onClick={() => setViewRow(null)}>
              Close
            </button>
          }
        >
          <div className="text-sm" style={{ lineHeight: 1.7 }}>
            <div><strong>Student:</strong> {viewRow.student_name}</div>
            <div><strong>College:</strong> {viewRow.college_name || '—'}</div>
            <div><strong>Role:</strong> {viewRow.job_title || '—'}</div>
            <div><strong>Salary:</strong> {formatCurrency(Number(viewRow.salary) || 0)}</div>
            <div><strong>Location:</strong> {viewRow.location || '—'}</div>
            <div><strong>Joining:</strong> {viewRow.joining_date ? formatDate(viewRow.joining_date) : '—'}</div>
            <div><strong>Deadline:</strong> {viewRow.deadline_at ? formatDate(viewRow.deadline_at) : '—'}</div>
            <div><strong>Status:</strong> {formatStatus(viewRow.status)}</div>
            {viewRow.offer_letter_url ? (
              <div>
                <strong>Offer letter:</strong>{' '}
                <a href={viewRow.offer_letter_url} target="_blank" rel="noopener noreferrer" className="link-inline">
                  View document
                </a>
              </div>
            ) : null}
          </div>
        </AppContentCard>
      ) : null}
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import useSWR from 'swr';
import { ArrowLeft, Search, Building2, CheckCircle2, Clock, Info } from 'lucide-react';
import EntityLogo from '@/components/EntityLogo';
import { formatFilterBadgeLabelParen } from '@/lib/filterBadgeLabel';

const fetcher = async (url) => {
  const res = await fetch(url, { credentials: 'include', cache: 'no-store' });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || `Failed to load (${res.status})`);
  if (!data.colleges || !Array.isArray(data.colleges)) {
    throw new Error(data.error || 'Invalid response from server');
  }
  return data;
};

function normalizeApprovalStatus(raw) {
  if (raw == null || raw === '') return null;
  const s = String(raw).trim().toLowerCase();
  if (['approved', 'pending', 'rejected', 'blacklisted'].includes(s)) return s;
  return null;
}

function canRequestTieUp(status) {
  const s = normalizeApprovalStatus(status);
  return s === null || s === 'rejected' || s === 'blacklisted';
}

export default function CreateTieupPage() {
  const router = useRouter();
  const { data, error, isLoading } = useSWR('/api/employer/campuses', fetcher);

  const [selectedCollegeId, setSelectedCollegeId] = useState('');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('available');
  const [requesting, setRequesting] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3500);
  };

  const colleges = data?.colleges ?? [];
  const campusOptions = useMemo(
    () => [...colleges].sort((a, b) => (a.name || '').localeCompare(b.name || '')),
    [colleges],
  );
  const filteredOptions = useMemo(() => {
    const q = search.trim().toLowerCase();
    return campusOptions.filter((c) => {
      const status = normalizeApprovalStatus(c.approval_status);
      const matchesSearch = !q || (c.name || '').toLowerCase().includes(q) || (c.city || '').toLowerCase().includes(q);
      const matchesStatus =
        statusFilter === 'all' ||
        (statusFilter === 'available' && canRequestTieUp(c.approval_status)) ||
        (statusFilter === 'approved' && status === 'approved') ||
        (statusFilter === 'pending' && status === 'pending') ||
        (statusFilter === 'rejected' && (status === 'rejected' || status === 'blacklisted'));
      return matchesSearch && matchesStatus;
    });
  }, [campusOptions, search, statusFilter]);

  const selectedCollege = useMemo(
    () => (selectedCollegeId ? colleges.find((c) => c.id === selectedCollegeId) : null),
    [colleges, selectedCollegeId],
  );

  const approvedCount = colleges.filter(c => normalizeApprovalStatus(c.approval_status) === 'approved').length;
  const pendingCount = colleges.filter(c => normalizeApprovalStatus(c.approval_status) === 'pending').length;
  const availableCount = colleges.filter(c => canRequestTieUp(c.approval_status)).length;

  const handleRequestAccess = async () => {
    if (!selectedCollege) return;
    setRequesting(true);
    try {
      const res = await fetch('/api/employer/campuses', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ collegeId: selectedCollege.id }),
      });
      const json = await res.json();
      if (res.ok) {
        if (json.alreadyPending) {
          showToast(json.message || 'Already pending', 'error');
        } else {
          showToast(json.message || `Tie-up requested for ${selectedCollege.name}`);
          setTimeout(() => router.push('/dashboard/employer/select-campus'), 1500);
        }
      } else {
        showToast(json.error || 'Request failed', 'error');
      }
    } catch {
      showToast('Network error', 'error');
    } finally {
      setRequesting(false);
    }
  };

  return (
    <div className="animate-fadeIn" style={{ paddingBottom: '3rem' }}>
      {/* Toast */}
      {toast && (
        <div className="animate-slideUp" style={{
          position: 'fixed', bottom: '2rem', right: '2rem', zIndex: 9999,
          padding: '1rem 1.5rem', borderRadius: 'var(--radius-lg)', fontWeight: 600, fontSize: '0.95rem',
          background: toast.type === 'error' ? 'var(--danger-50)' : 'var(--success-50)',
          border: `1px solid ${toast.type === 'error' ? 'var(--danger-200)' : 'var(--success-200)'}`,
          color: toast.type === 'error' ? 'var(--danger-700)' : 'var(--success-700)',
          boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)',
          display: 'flex', alignItems: 'center', gap: '0.75rem'
        }}>
          {toast.type === 'error' ? '❌' : '✅'} {toast.msg}
        </div>
      )}

      {/* Navigation Breadcrumb */}
      <button
        onClick={() => router.push('/dashboard/employer/select-campus')}
        className="btn btn-ghost"
        style={{ marginBottom: '1.25rem', display: 'inline-flex', alignItems: 'center', gap: '0.5rem', paddingLeft: 0, color: 'var(--text-secondary)', fontSize: '0.9rem', fontWeight: 600 }}
      >
        <ArrowLeft size={16} /> Back to Directory
      </button>

      {/* High-Fidelity Glassmorphic Hero Banner */}
      <div 
        style={{
          position: 'relative',
          background: 'var(--banner-gradient)',
          borderRadius: 'var(--radius-xl)',
          padding: '2.5rem',
          color: 'white',
          overflow: 'hidden',
          marginBottom: '2.5rem',
          boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1)',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '1.5rem',
        }}
      >
        {/* Decorative Elements */}
        <div style={{ position: 'absolute', top: '-50px', right: '-50px', width: '250px', height: '250px', background: 'radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 60%)', borderRadius: '50%' }} />
        <div style={{ position: 'absolute', bottom: '-50px', left: '10%', width: '150px', height: '150px', background: 'radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 60%)', borderRadius: '50%' }} />

        <div style={{ position: 'relative', zIndex: 1, maxWidth: '600px' }}>
          <h1 style={{ color: '#ffffff', fontSize: '2.25rem', fontWeight: 800, margin: '0 0 0.5rem', letterSpacing: '-0.02em', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Building2 size={28} /> Create Tie-up Request
          </h1>
          <p style={{ fontSize: '1.05rem', color: 'rgba(255,255,255,0.85)', margin: 0, lineHeight: 1.5 }}>
            Choose a college and send a partnership request. The college admin will review your request.
          </p>
        </div>
      </div>

      {/* Stats Row */}
      {!isLoading && !error && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '1.5rem', marginBottom: '2.5rem' }}>
          <div className="card" style={{ padding: '1.5rem', display: 'flex', alignItems: 'center', gap: '1rem', border: '1px solid var(--success-200)', background: 'linear-gradient(135deg, white, var(--success-50))' }}>
            <div style={{ width: 48, height: 48, borderRadius: '12px', background: 'var(--success-100)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, color: 'var(--success-600)' }}>
              <CheckCircle2 size={24} strokeWidth={2.5} />
            </div>
            <div>
              <div style={{ fontSize: '1.75rem', fontWeight: 800, color: 'var(--success-800)', lineHeight: 1 }}>{approvedCount}</div>
              <div style={{ fontSize: '0.9rem', color: 'var(--success-700)', marginTop: '0.2rem', fontWeight: 600 }}>Approved Tie-ups</div>
            </div>
          </div>
          
          <div className="card" style={{ padding: '1.5rem', display: 'flex', alignItems: 'center', gap: '1rem', border: '1px solid var(--warning-200)', background: 'linear-gradient(135deg, white, var(--warning-50))' }}>
            <div style={{ width: 48, height: 48, borderRadius: '12px', background: 'var(--warning-100)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, color: 'var(--warning-600)' }}>
              <Clock size={24} strokeWidth={2.5} />
            </div>
            <div>
              <div style={{ fontSize: '1.75rem', fontWeight: 800, color: 'var(--warning-800)', lineHeight: 1 }}>{pendingCount}</div>
              <div style={{ fontSize: '0.9rem', color: 'var(--warning-700)', marginTop: '0.2rem', fontWeight: 600 }}>Pending Requests</div>
            </div>
          </div>

          <div className="card" style={{ padding: '1.5rem', display: 'flex', alignItems: 'center', gap: '1rem', border: '1px solid var(--primary-200)', background: 'linear-gradient(135deg, var(--bg-primary), var(--primary-50))' }}>
            <div style={{ width: 48, height: 48, borderRadius: '12px', background: 'var(--primary-100)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, color: 'var(--primary-600)' }}>
              <Building2 size={24} strokeWidth={2.5} />
            </div>
            <div>
              <div style={{ fontSize: '1.75rem', fontWeight: 800, color: 'var(--text-primary)', lineHeight: 1 }}>{availableCount}</div>
              <div style={{ fontSize: '0.9rem', color: 'var(--primary-700)', marginTop: '0.2rem', fontWeight: 600 }}>Available Colleges</div>
            </div>
          </div>
        </div>
      )}

      {/* Main Content: 2-column layout */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 340px', gap: '2rem', alignItems: 'start' }}>

        {/* Left: Form */}
        <div className="card" style={{ padding: '2rem', border: '1px solid var(--border-default)' }}>
          <h2 style={{ fontSize: '1.15rem', fontWeight: 800, margin: '0 0 0.5rem', color: 'var(--text-primary)' }}>
            Select a College
          </h2>
          <p style={{ fontSize: '0.95rem', color: 'var(--text-secondary)', margin: '0 0 2rem' }}>
            Filter colleges by status and search by name/city. Select an available college from the list to request access.
          </p>

          {isLoading && (
            <div>
              <div className="skeleton" style={{ height: 48, borderRadius: 'var(--radius-lg)', marginBottom: '1rem' }} />
              <div className="skeleton skeleton-card" style={{ height: 300 }} />
            </div>
          )}
          
          {error && (
            <div style={{ padding: '1.5rem', background: 'var(--danger-50)', border: '1px solid var(--danger-200)', borderRadius: 'var(--radius-md)', color: 'var(--danger-700)', fontSize: '0.95rem', fontWeight: 500 }}>
              {error.message || 'Failed to load colleges. Please refresh and try again.'}
            </div>
          )}

          {!isLoading && !error && (
            <>
              <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
                <div style={{ position: 'relative', flex: '1 1 300px' }}>
                  <Search size={18} color="var(--text-tertiary)" style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)' }} />
                  <input
                    type="text"
                    className="form-input"
                    placeholder="Search college name or city..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    style={{ paddingLeft: '2.75rem', paddingRight: '1rem', paddingTop: '0.65rem', paddingBottom: '0.65rem', fontSize: '0.95rem' }}
                  />
                </div>
                
                <select className="form-select" style={{ width: 'auto', padding: '0.65rem 2rem 0.65rem 1rem', fontSize: '0.95rem', fontWeight: 500 }} value={statusFilter} onChange={e => setStatusFilter(e.target.value)}>
                  <option value="available">{formatFilterBadgeLabelParen('Available', availableCount)}</option>
                  <option value="approved">{formatFilterBadgeLabelParen('Approved', approvedCount)}</option>
                  <option value="pending">{formatFilterBadgeLabelParen('Pending', pendingCount)}</option>
                  <option value="rejected">Rejected/Blacklisted</option>
                  <option value="all">All Colleges ({colleges.length})</option>
                </select>
              </div>

              <div className="table-container" style={{ marginBottom: '1.5rem', border: '1px solid var(--border-default)', borderRadius: 'var(--radius-md)' }}>
                <table className="data-table">
                  <thead>
                    <tr style={{ background: 'var(--bg-secondary)' }}>
                      <th style={{ width: 48, paddingLeft: '1.5rem', textAlign: 'center' }}>Select</th>
                      <th>College</th>
                      <th>Location</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredOptions.length === 0 ? (
                      <tr>
                        <td colSpan={4} style={{ textAlign: 'center', color: 'var(--text-tertiary)', padding: '3rem 1.5rem' }}>
                          <Building2 size={32} style={{ margin: '0 auto 0.75rem', opacity: 0.3 }} />
                          <div style={{ fontWeight: 600, fontSize: '1rem', color: 'var(--text-primary)' }}>No colleges match your filter</div>
                        </td>
                      </tr>
                    ) : (
                      filteredOptions.map((c) => {
                        const isSelected = selectedCollegeId === c.id;
                        const status = normalizeApprovalStatus(c.approval_status);
                        const selectable = canRequestTieUp(c.approval_status);
                        return (
                          <tr
                            key={c.id}
                            onClick={() => selectable && setSelectedCollegeId(c.id)}
                            style={{ 
                              opacity: selectable ? 1 : 0.65, 
                              cursor: selectable ? 'pointer' : 'not-allowed',
                              background: isSelected ? 'var(--primary-50)' : 'transparent',
                              transition: 'all 0.15s'
                            }}
                          >
                            <td style={{ paddingLeft: '1.5rem', textAlign: 'center' }}>
                              <input
                                type="radio"
                                checked={isSelected}
                                onChange={() => selectable && setSelectedCollegeId(c.id)}
                                disabled={!selectable}
                                aria-label={`Select ${c.name}`}
                                style={{ width: '1.25rem', height: '1.25rem', accentColor: 'var(--primary-600)', cursor: selectable ? 'pointer' : 'not-allowed' }}
                              />
                            </td>
                            <td>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                                <EntityLogo name={c.name} website={c.website} size="sm" shape="rounded" />
                                <div style={{ fontWeight: isSelected ? 700 : 600, color: isSelected ? 'var(--primary-900)' : 'var(--text-primary)' }}>{c.name}</div>
                              </div>
                            </td>
                            <td style={{ color: 'var(--text-secondary)' }}>{c.city || '—'}</td>
                            <td>
                              <span style={{
                                padding: '0.2rem 0.6rem', borderRadius: '999px', fontSize: '0.75rem', fontWeight: 600,
                                background: status === 'approved' ? 'var(--success-50)' : status === 'pending' ? 'var(--warning-50)' : status === 'blacklisted' ? 'var(--danger-50)' : 'var(--primary-50)',
                                color: status === 'approved' ? 'var(--success-700)' : status === 'pending' ? 'var(--warning-700)' : status === 'blacklisted' ? 'var(--danger-700)' : 'var(--primary-700)',
                              }}>
                                {status ? (status === 'blacklisted' ? 'Blacklisted' : status[0].toUpperCase() + status.slice(1)) : 'Available'}
                              </span>
                            </td>
                          </tr>
                        );
                      })
                    )}
                  </tbody>
                </table>
              </div>

              {selectedCollege && (
                <div className="animate-slideUp" style={{
                  marginTop: '1rem', padding: '1.25rem 1.5rem',
                  background: 'var(--primary-50)', border: '1px solid var(--primary-200)',
                  borderRadius: 'var(--radius-lg)', display: 'flex', alignItems: 'center', gap: '1rem',
                  boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.1)'
                }}>
                  <div style={{ padding: '0.75rem', background: 'var(--primary-100)', borderRadius: '12px', color: 'var(--primary-600)' }}>
                    <Building2 size={24} />
                  </div>
                  <div>
                    <div style={{ fontWeight: 800, fontSize: '1.1rem', color: 'var(--primary-900)', marginBottom: '0.2rem' }}>{selectedCollege.name}</div>
                    {selectedCollege.city && (
                      <div style={{ fontSize: '0.9rem', color: 'var(--primary-700)', fontWeight: 500 }}>{selectedCollege.city}</div>
                    )}
                  </div>
                </div>
              )}

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '1rem', marginTop: '2rem', paddingTop: '2rem', borderTop: '1px solid var(--border-default)' }}>
                <button
                  type="button"
                  className="btn btn-ghost"
                  onClick={() => router.push('/dashboard/employer/select-campus')}
                  style={{ fontWeight: 600, padding: '0.75rem 1.5rem' }}
                >
                  Cancel
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  disabled={!selectedCollege || !canRequestTieUp(selectedCollege.approval_status) || requesting}
                  onClick={handleRequestAccess}
                  style={{ minWidth: '200px', fontWeight: 600, padding: '0.75rem 1.5rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}
                >
                  {requesting ? 'Sending Request...' : <>Send Tie-up Request <ArrowLeft size={16} style={{ transform: 'rotate(180deg)' }} /></>}
                </button>
              </div>
            </>
          )}
        </div>

        {/* Right: Help Panel */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
          <div className="card" style={{ padding: '1.5rem', border: '1px solid var(--border-default)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', marginBottom: '1.25rem' }}>
              <div style={{ padding: '0.4rem', background: 'var(--primary-50)', color: 'var(--primary-600)', borderRadius: '8px' }}>
                <Info size={18} />
              </div>
              <h3 style={{ margin: 0, fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)' }}>How it works</h3>
            </div>
            
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {[
                { step: '1', text: 'Search and select an available college.' },
                { step: '2', text: 'Click "Send Tie-up Request".' },
                { step: '3', text: 'The college admin reviews your request.' },
                { step: '4', text: 'Once approved, you can schedule placement drives.' },
              ].map(item => (
                <div key={item.step} style={{ display: 'flex', alignItems: 'flex-start', gap: '0.75rem' }}>
                  <div style={{ width: 24, height: 24, borderRadius: '50%', background: 'var(--bg-secondary)', border: '1px solid var(--border-default)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-secondary)', flexShrink: 0 }}>
                    {item.step}
                  </div>
                  <div style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', lineHeight: 1.5, paddingTop: '0.1rem' }}>
                    {item.text}
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="card" style={{ padding: '1.5rem', background: 'linear-gradient(135deg, white, var(--warning-50))', border: '1px solid var(--warning-200)' }}>
            <h3 style={{ margin: '0 0 0.75rem', fontSize: '0.95rem', fontWeight: 800, color: 'var(--warning-900)' }}>
              ⚠️ Important Note
            </h3>
            <p style={{ margin: 0, fontSize: '0.9rem', color: 'var(--warning-800)', lineHeight: 1.5 }}>
              Colleges marked as <strong>Approved</strong> or <strong>Pending</strong> cannot be re-requested. Only colleges showing <strong>Available</strong> can receive a new tie-up request.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import useSWR from 'swr';
import { Building2, Settings2 } from 'lucide-react';
import { useToast } from '@/components/ToastProvider';
import EmployerCampusTargetPicker from '@/components/employer/EmployerCampusTargetPicker';
import { getConstraintAllowlist } from '@/lib/employerPostingCampusConstraints';

const fetcher = async (url) => {
  const res = await fetch(url, { credentials: 'include', cache: 'no-store' });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(json.error || 'Request failed');
  return json;
};

function buildSelectionFromAllowlist(allowlist, approvedCampuses) {
  const allowed = new Set((allowlist || []).map(String));
  const sel = {};
  for (const c of approvedCampuses) {
    sel[c.id] = allowed.has(String(c.id));
  }
  return sel;
}

export default function EmployerSettingsPage() {
  const { addToast } = useToast();
  const { data: campusData, isLoading: campusesLoading } = useSWR('/api/employer/campuses', fetcher, {
    revalidateOnFocus: true,
  });
  const {
    data: constraintsData,
    error: constraintsError,
    isLoading: constraintsLoading,
    mutate: mutateConstraints,
  } = useSWR('/api/employer/posting-campus-constraints', fetcher, { revalidateOnFocus: true });

  const approvedCampuses = useMemo(
    () =>
      (campusData?.colleges || []).filter(
        (c) => String(c.approval_status || '').toLowerCase() === 'approved',
      ),
    [campusData],
  );

  const categories = constraintsData?.categories || [];
  const savedConstraints = constraintsData?.constraints || {};

  const [draftRestricted, setDraftRestricted] = useState({});
  const [draftSelection, setDraftSelection] = useState({});
  const [savingCategory, setSavingCategory] = useState(null);

  useEffect(() => {
    if (!categories.length) return;
    const restricted = {};
    const selection = {};
    for (const cat of categories) {
      const allowlist = getConstraintAllowlist(savedConstraints, cat.id);
      restricted[cat.id] = Boolean(allowlist?.length);
      selection[cat.id] = buildSelectionFromAllowlist(allowlist, approvedCampuses);
    }
    setDraftRestricted(restricted);
    setDraftSelection(selection);
  }, [categories, savedConstraints, approvedCampuses]);

  const saveCategory = useCallback(
    async (categoryId) => {
      setSavingCategory(categoryId);
      try {
        const restricted = draftRestricted[categoryId] === true;
        const tenantIds = Object.entries(draftSelection[categoryId] || {})
          .filter(([, on]) => on)
          .map(([id]) => id);

        const res = await fetch('/api/employer/posting-campus-constraints', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({
            category: categoryId,
            restricted,
            tenantIds,
          }),
        });
        const json = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(json.error || 'Save failed');

        await mutateConstraints();
        addToast(
          restricted
            ? 'Campus limit saved for this posting type.'
            : 'All approved colleges are now eligible for this posting type.',
          'success',
        );
      } catch (e) {
        addToast(e.message || 'Could not save campus limits', 'error');
      } finally {
        setSavingCategory(null);
      }
    },
    [addToast, draftRestricted, draftSelection, mutateConstraints],
  );

  const loading = campusesLoading || constraintsLoading;

  return (
    <div className="animate-fadeIn">
      <div className="page-header">
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Settings2 size={22} strokeWidth={1.75} style={{ color: 'var(--primary-500)', flexShrink: 0 }} />
            Employer settings
          </h1>
          <p className="text-secondary" style={{ margin: 0 }}>
            Limit which approved colleges can receive each type of posting. When unrestricted, all approved tie-ups
            remain eligible.
          </p>
        </div>
      </div>

      {constraintsError ? (
        <div className="card" style={{ marginBottom: '1rem', borderColor: 'var(--danger-500)' }}>
          <p className="text-sm" style={{ margin: 0 }}>
            Could not load campus posting limits: {constraintsError.message}
          </p>
        </div>
      ) : null}

      {!loading && approvedCampuses.length === 0 ? (
        <div
          className="card"
          style={{ marginBottom: '1rem', background: 'var(--warning-50)', border: '1px solid var(--warning-200)' }}
        >
          <p className="text-sm" style={{ margin: 0 }}>
            <strong>No approved college partnerships yet.</strong> Request campus access first, then return here to
            narrow posting targets per category.
          </p>
        </div>
      ) : null}

      <div style={{ display: 'grid', gap: '1rem' }}>
        {loading ? (
          <div className="card">
            <p className="text-sm text-secondary" style={{ margin: 0 }}>
              Loading settings…
            </p>
          </div>
        ) : (
          categories.map((cat) => {
            const restricted = draftRestricted[cat.id] === true;
            const selection = draftSelection[cat.id] || {};
            return (
              <div key={cat.id} className="card">
                <div className="card-header" style={{ alignItems: 'flex-start', gap: '0.75rem' }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <h3 className="card-title" style={{ marginBottom: '0.35rem' }}>
                      {cat.label}
                    </h3>
                    <p className="text-sm text-secondary" style={{ margin: 0 }}>
                      {cat.description}
                    </p>
                  </div>
                  <span
                    className={`badge ${restricted ? 'badge-indigo' : 'badge-gray'}`}
                    style={{ flexShrink: 0 }}
                  >
                    {restricted ? 'Limited' : 'All approved'}
                  </span>
                </div>

                <label
                  className="text-sm"
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                    marginBottom: '0.75rem',
                    cursor: 'pointer',
                  }}
                >
                  <input
                    type="checkbox"
                    checked={restricted}
                    disabled={!approvedCampuses.length || savingCategory === cat.id}
                    onChange={(e) => {
                      const next = e.target.checked;
                      setDraftRestricted((p) => ({ ...p, [cat.id]: next }));
                      if (next && !Object.values(selection).some(Boolean)) {
                        setDraftSelection((p) => ({
                          ...p,
                          [cat.id]: buildSelectionFromAllowlist(
                            getConstraintAllowlist(savedConstraints, cat.id) ||
                              approvedCampuses.slice(0, 1).map((c) => c.id),
                            approvedCampuses,
                          ),
                        }));
                      }
                    }}
                  />
                  Limit to selected colleges only
                </label>

                {restricted ? (
                  <EmployerCampusTargetPicker
                    campuses={approvedCampuses}
                    selection={selection}
                    onSelectionChange={(next) =>
                      setDraftSelection((p) => ({
                        ...p,
                        [cat.id]: next,
                      }))
                    }
                    label={
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
                        <Building2 size={14} aria-hidden />
                        Eligible colleges
                      </span>
                    }
                    required
                    hint="Only these approved campuses will appear when publishing this posting type."
                    emptyMessage="No approved campuses available."
                  />
                ) : (
                  <p className="text-sm text-secondary" style={{ margin: '0 0 0.75rem' }}>
                    All {approvedCampuses.length} approved college
                    {approvedCampuses.length === 1 ? '' : 's'} can receive {cat.label.toLowerCase()}.
                  </p>
                )}

                <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '0.75rem' }}>
                  <button
                    type="button"
                    className="btn btn-primary btn-sm"
                    disabled={!approvedCampuses.length || savingCategory === cat.id}
                    onClick={() => void saveCategory(cat.id)}
                  >
                    {savingCategory === cat.id ? 'Saving…' : 'Save'}
                  </button>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

