'use client';
import { useSession } from 'next-auth/react';
import { useRouter, usePathname } from 'next/navigation';
import { useEffect, useMemo, useState } from 'react';
import useSWR, { mutate as swrMutate } from 'swr';
import Link from 'next/link';
import { signOut } from '@/lib/clientSignOut';
import ThemeToggleButton from '@/components/ThemeToggleButton';
import { getInitials, getRoleDisplayName } from '@/lib/utils';
import EntityLogo from '@/components/EntityLogo';
import SessionAdBanner from '@/components/SessionAdBanner';
import PageLoading from '@/components/PageLoading';
import {
  getDashboardMenu,
  ROLE_HOME_PATHS,
  getRoleProfilePath,
  getRoleProfileLabel,
  NAV_SECTION_STORAGE_KEY,
  findSectionIdByPath,
  isSidebarItemActive,
  isSidebarItemActiveInMenu,
  isRoleDashboardHome,
  getDashboardNavItemKey,
} from '@/config/dashboardMenu';
import NotificationDropdown from '@/components/NotificationDropdown';
import DevScreenTag from '@/components/DevScreenTag';
import ScreenSearchBar from '@/components/ScreenSearchBar';
import DocumentationHelpWidget from '@/components/DocumentationHelpWidget';
import { Menu, Mail, Home, PanelLeft, PanelLeftClose, LogOut, ChevronRight, ArrowLeft } from 'lucide-react';
import { getAcademicYearOptions, getCurrentAcademicYear } from '@/lib/academicYear';
import {
  ACTIVE_ACADEMIC_YEAR_KEY,
  writeActiveAcademicYearContext,
} from '@/lib/collegeAcademicYearContext';
import {
  readEmployerAcademicYearContext,
  writeEmployerAcademicYearContext,
} from '@/lib/employerAcademicYearContext';
import { resolveBrandLogoUrl } from '@/lib/resolveBrandLogoUrl';
import { DEFAULT_ENTITY_LOGO_URL } from '@/lib/clientAssetUrl';
import { isCollegeStaffRole } from '@/lib/collegeAccess';
import DashboardErrorBoundary from '@/components/DashboardErrorBoundary';

const settingsFetcher = async (url) => {
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json?.error || 'Failed to load settings');
  return json;
};

export default function DashboardLayout({ children }) {
  const { data: session, status, update: updateSession } = useSession();
  const router = useRouter();
  const pathname = usePathname();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  useEffect(() => {
    try {
      const collapsed =
        localStorage.getItem('placementhub_sidebar_collapsed') === '1' ||
        localStorage.getItem('placementhub_sidebar_hidden') === '1';
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSidebarCollapsed(collapsed);
    } catch {
      /* ignore */
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('placementhub_sidebar_collapsed', sidebarCollapsed ? '1' : '0');
    } catch {
      /* ignore */
    }
  }, [sidebarCollapsed]);
  const [employerCampusLabel, setEmployerCampusLabel] = useState(null);
  const [employerActiveCampus, setEmployerActiveCampus] = useState(null);
  const [employerAcademicYearOverride, setEmployerAcademicYearOverride] = useState(null);
  const [academicYearOverride, setAcademicYearOverride] = useState(null);
  const { data: collegeSettings, isLoading: collegeSettingsLoading } = useSWR(
    session?.user?.role === 'college_admin' ? '/api/college/settings' : null,
    settingsFetcher,
  );
  const { data: employerProfileData, isLoading: employerProfileLoading } = useSWR(
    session?.user?.role === 'employer' ? '/api/employer/profile' : null,
    settingsFetcher,
  );
  const { data: academicYearsBundle } = useSWR(
    isCollegeStaffRole(session?.user?.role) ? '/api/college/academic-years' : null,
    settingsFetcher,
  );
  const { data: employerAcademicYearsBundle } = useSWR(
    session?.user?.role === 'employer' && employerActiveCampus?.id
      ? `/api/employer/academic-years?campusId=${encodeURIComponent(employerActiveCampus.id)}`
      : null,
    settingsFetcher,
  );
  const fallbackAcademicYearOptions = getAcademicYearOptions(getCurrentAcademicYear(), 3);
  const academicYearOptions = useMemo(() => {
    if (!isCollegeStaffRole(session?.user?.role)) return fallbackAcademicYearOptions;
    const fromTenant = Array.isArray(academicYearsBundle?.years)
      ? academicYearsBundle.years.map((y) => y.label).filter(Boolean)
      : [];
    if (fromTenant.length) return fromTenant;
    const fromServer = Array.isArray(collegeSettings?.academicYearsWithData)
      ? collegeSettings.academicYearsWithData.filter((v) => typeof v === 'string' && v.trim())
      : [];
    return fromServer.length ? fromServer : fallbackAcademicYearOptions;
  }, [
    academicYearsBundle?.years,
    collegeSettings?.academicYearsWithData,
    fallbackAcademicYearOptions,
    session?.user?.role,
  ]);

  const systemDefaultAcademicYear = useMemo(() => {
    const fromTenantCalendar = academicYearsBundle?.current?.label?.trim();
    if (fromTenantCalendar) return fromTenantCalendar;
    return getCurrentAcademicYear();
  }, [academicYearsBundle?.current?.label]);

  const employerAcademicYearOptions = useMemo(() => {
    const fromTenant = Array.isArray(employerAcademicYearsBundle?.years)
      ? employerAcademicYearsBundle.years.map((y) => y.label).filter(Boolean)
      : [];
    return fromTenant.length ? fromTenant : fallbackAcademicYearOptions;
  }, [employerAcademicYearsBundle?.years, fallbackAcademicYearOptions]);

  const employerDefaultAcademicYear = useMemo(() => {
    const fromTenantCalendar = employerAcademicYearsBundle?.current?.label?.trim();
    if (fromTenantCalendar) return fromTenantCalendar;
    return getCurrentAcademicYear();
  }, [employerAcademicYearsBundle?.current?.label]);

  const employerAcademicYear = useMemo(() => {
    if (employerAcademicYearOverride != null && employerAcademicYearOverride !== '') {
      return employerAcademicYearOverride;
    }
    if (typeof window !== 'undefined' && employerActiveCampus?.id) {
      try {
        const stored = readEmployerAcademicYearContext(employerActiveCampus.id);
        if (stored?.label && employerAcademicYearOptions.includes(stored.label)) {
          return stored.label;
        }
      } catch {
        /* ignore */
      }
    }
    return employerDefaultAcademicYear;
  }, [
    employerAcademicYearOverride,
    employerActiveCampus?.id,
    employerAcademicYearOptions,
    employerDefaultAcademicYear,
  ]);

  useEffect(() => {
    if (session?.user?.role !== 'employer' || !employerActiveCampus?.id) return;
    const match = employerAcademicYearsBundle?.years?.find((y) => y.label === employerAcademicYear);
    writeEmployerAcademicYearContext(employerActiveCampus.id, {
      id: match?.id || null,
      label: employerAcademicYear,
    });
  }, [
    session?.user?.role,
    employerActiveCampus?.id,
    employerAcademicYear,
    employerAcademicYearsBundle?.years,
  ]);

  useEffect(() => {
    if (session?.user?.role !== 'employer' || !employerActiveCampus?.id) return;
    setEmployerAcademicYearOverride(null);
  }, [employerActiveCampus?.id, session?.user?.role]);

  const academicYear = useMemo(() => {
    if (academicYearOverride != null && academicYearOverride !== '') return academicYearOverride;
    if (typeof window !== 'undefined') {
      try {
        const saved = sessionStorage.getItem('activeAcademicYear')?.trim();
        if (saved && academicYearOptions.includes(saved)) return saved;
      } catch {
        /* ignore */
      }
    }
    return systemDefaultAcademicYear;
  }, [academicYearOverride, academicYearOptions, systemDefaultAcademicYear]);

  useEffect(() => {
    if (session?.user?.role !== 'college_admin' || !session?.user?.id) return;
    const storageKey = 'placementhub_college_admin_id';
    try {
      const prev = sessionStorage.getItem(storageKey);
      if (prev && prev !== session.user.id) {
        sessionStorage.removeItem(ACTIVE_ACADEMIC_YEAR_KEY);
        sessionStorage.removeItem('activeAcademicYear');
        setAcademicYearOverride(null);
      }
      sessionStorage.setItem(storageKey, session.user.id);
    } catch {
      /* ignore */
    }
  }, [session?.user?.id, session?.user?.role]);

  useEffect(() => {
    try {
      sessionStorage.setItem('activeAcademicYear', academicYear);
      const match = academicYearsBundle?.years?.find((y) => y.label === academicYear);
      writeActiveAcademicYearContext({
        id: match?.id || null,
        label: academicYear,
      });
    } catch {
      /* ignore */
    }
  }, [academicYear, academicYearsBundle?.years]);

  useEffect(() => {
    if (session?.user?.role !== 'employer') return;
    const readCampus = () => {
      try {
        const raw = sessionStorage.getItem('activeCampus');
        if (!raw) {
          setEmployerActiveCampus(null);
          setEmployerCampusLabel(null);
          return;
        }
        const parsed = JSON.parse(raw);
        if (parsed?.id) {
          setEmployerActiveCampus(parsed);
          setEmployerCampusLabel(parsed.name || null);
        } else {
          setEmployerActiveCampus(null);
          setEmployerCampusLabel(null);
        }
      } catch {
        setEmployerActiveCampus(null);
        setEmployerCampusLabel(null);
      }
    };
    readCampus();
    window.addEventListener('placementhub-active-campus', readCampus);
    return () => window.removeEventListener('placementhub-active-campus', readCampus);
  }, [session?.user?.role]);

  useEffect(() => {
    if (!session?.user?.role) return;
    const menu = getDashboardMenu(session.user.role, session.user);
    const id = findSectionIdByPath(menu, pathname);
    if (id) {
      try {
        sessionStorage.setItem(NAV_SECTION_STORAGE_KEY, id);
      } catch {
        /* ignore */
      }
    }
  }, [pathname, session]);

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.replace('/login');
    }
  }, [status, router]);

  const role = session?.user?.role;
  const brandProfileLoaded =
    role === 'employer'
      ? !employerProfileLoading
      : role === 'college_admin'
        ? !collegeSettingsLoading
        : true;
  const resolvedBrandLogoUrl = useMemo(
    () =>
      session?.user
        ? resolveBrandLogoUrl({
            role,
            employerProfile: employerProfileData?.profile,
            collegeSettings,
            sessionUser: session.user,
            profileLoaded: brandProfileLoaded,
          })
        : null,
    [session?.user, role, employerProfileData?.profile, collegeSettings, brandProfileLoaded],
  );

  useEffect(() => {
    if (!session?.user || !brandProfileLoaded || !resolvedBrandLogoUrl) return;
    if (role !== 'employer' && role !== 'college_admin') return;
    if (session.user.brandLogoUrl === resolvedBrandLogoUrl) return;
    updateSession({ brandLogoUrl: resolvedBrandLogoUrl });
  }, [session?.user, brandProfileLoaded, resolvedBrandLogoUrl, role, updateSession]);

  if (status === 'loading') {
    return <PageLoading message="Signing you in…" delayMs={0} />;
  }

  if (!session) return null;

  const menu = getDashboardMenu(role, session.user);
  const sectionId = findSectionIdByPath(menu, pathname);
  const activeSection = menu.sections.find((s) => s.id === sectionId) || menu.sections[0];
  const homePath = ROLE_HOME_PATHS[role] || ROLE_HOME_PATHS.student;
  const employerDisplayName =
    role === 'employer'
      ? (employerProfileData?.profile?.company_name && String(employerProfileData.profile.company_name).trim()) ||
        session.user.tenantName ||
        session.user.name
      : null;
  const isHub = isRoleDashboardHome(pathname, role);
  /** Super admin: show every workspace link in the sidebar (not only the current section). */
  const showFullSidebarNav = role === 'super_admin';

  const studentVerifyBanner =
    role === 'student' && session.user.studentPlacementVerified === false ? (
      <div
        className="card banner-verify-pending"
        style={{
          margin: isHub ? '1rem auto 0' : '0 0 1rem',
          maxWidth: isHub ? '56rem' : undefined,
          padding: '0.75rem 1rem',
          fontSize: '0.875rem',
        }}
      >
        Your college has not marked your profile as <strong>Verified</strong> yet. You can still apply and use the portal —
        this badge is informational for employers and does not block hiring. After you edit your profile or upload a CV,
        college or placement committee staff need to re-verify you from the <strong>Students</strong> screen.
      </div>
    ) : null;

  const committeeReadOnlyBanner =
    role === 'placement_committee' ? (
      <div
        className="card"
        style={{
          margin: isHub ? '1rem auto 0' : '0 0 1rem',
          maxWidth: isHub ? '56rem' : undefined,
          padding: '0.75rem 1rem',
          fontSize: '0.875rem',
          borderColor: 'var(--border-default)',
          background: 'var(--bg-secondary)',
        }}
      >
        <strong>Read-only placement committee view.</strong> You can browse students and applications for your college. Adding or editing records requires a college administrator.
      </div>
    ) : null;

  if (isHub) {
    return (
      <>
        {studentVerifyBanner}
        {committeeReadOnlyBanner}
        {children}
      </>
    );
  }

  const renderSidebarNavItem = (item, activeFn) => {
    const key = getDashboardNavItemKey(item);
    const icon = (
      <span className="sidebar-link-icon">
        <item.icon size={18} aria-hidden="true" />
      </span>
    );
    const label = <span className="sidebar-link-label">{item.label}</span>;

    if (item.disabled) {
      return (
        <span
          key={key}
          className="sidebar-link sidebar-link--disabled"
          title={item.label}
          aria-disabled="true"
        >
          {icon}
          {label}
        </span>
      );
    }

    const active = activeFn(item.href);
    return (
      <Link
        key={key}
        href={item.href}
        className={`sidebar-link ${active ? 'active' : ''}`}
        onClick={() => setMobileOpen(false)}
        aria-current={active ? 'page' : undefined}
        title={item.label}
      >
        {icon}
        {label}
      </Link>
    );
  };

  return (
    <div className={`dashboard-layout ${sidebarCollapsed ? 'sidebar-collapsed' : ''}`}>
      <aside
        className={`sidebar ${mobileOpen ? 'mobile-open' : ''} ${sidebarCollapsed ? 'collapsed' : ''}`}
        aria-expanded={!sidebarCollapsed}
      >
        <div className="sidebar-toolbar">
          <Link
            href={homePath}
            className="sidebar-logo"
            onClick={() => {
              try {
                window.dispatchEvent(new Event('placementhub-clear-search'));
              } catch {
                /* ignore */
              }
              setMobileOpen(false);
            }}
          >
            <div className="sidebar-logo-icon">P</div>
            <span className="sidebar-logo-label">PlacementHub</span>
          </Link>
          <button
            type="button"
            className="btn btn-ghost btn-icon sidebar-collapse-toggle"
            onClick={() => setSidebarCollapsed((v) => !v)}
            title={sidebarCollapsed ? 'Expand menu' : 'Collapse menu'}
            aria-label={sidebarCollapsed ? 'Expand menu' : 'Collapse menu'}
          >
            {sidebarCollapsed ? <PanelLeft size={18} aria-hidden="true" /> : <PanelLeftClose size={18} aria-hidden="true" />}
          </button>
        </div>

        <nav className="sidebar-nav">
          <Link
            href={homePath}
            className={`sidebar-link ${pathname === homePath ? 'active' : ''}`}
            onClick={() => setMobileOpen(false)}
            aria-current={pathname === homePath ? 'page' : undefined}
            title="Home"
          >
            <span className="sidebar-link-icon">
              <Home size={18} aria-hidden="true" />
            </span>
            <span className="sidebar-link-label">Home</span>
          </Link>
          {showFullSidebarNav ? (
            menu.sections.map((section) => (
              <div key={section.id}>
                <div className="sidebar-section-title">{section.title}</div>
                {section.items.map((item) =>
                  renderSidebarNavItem(item, (href) => isSidebarItemActiveInMenu(href, menu, pathname)),
                )}
              </div>
            ))
          ) : (
            <>
              <div className="sidebar-section-title">{activeSection.title}</div>
              {activeSection.items.map((item) =>
                renderSidebarNavItem(item, (href) => isSidebarItemActive(href, activeSection, pathname)),
              )}
            </>
          )}
        </nav>

        <div className="sidebar-footer">
          <Link
            href={getRoleProfilePath(role)}
            className="dashboard-identity-link"
            onClick={(e) => {
              setMobileOpen(false);
              const dest = getRoleProfilePath(role);
              if (!dest) {
                e.preventDefault();
                return;
              }
              // Use client navigation explicitly so the footer identity card always works
              e.preventDefault();
              if (pathname === dest) {
                router.refresh();
              } else {
                router.push(dest);
              }
            }}
            aria-label={`${getRoleProfileLabel(role)} — ${session.user.name}`}
            title={getRoleProfileLabel(role)}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '0.5rem' }}>
              {(role === 'employer' || role === 'college_admin') ? (
                <EntityLogo
                  name={
                    role === 'employer'
                      ? employerDisplayName || session.user.name
                      : (collegeSettings?.institution?.collegeName || session.user.tenantName || session.user.name)
                  }
                  logoUrl={resolvedBrandLogoUrl}
                  placeholderUrl={DEFAULT_ENTITY_LOGO_URL}
                  size="sm"
                  shape="rounded"
                />
              ) : (
                <div className="avatar avatar-md">
                  {getInitials(session.user.name)}
                </div>
              )}
              <div className="sidebar-footer-meta" style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: '0.875rem', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {session.user.name}
                </div>
                <div style={{ fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>
                  {getRoleDisplayName(role, { isAlumni: Boolean(session.user?.isAlumni) })}
                </div>
              </div>
              <ChevronRight
                size={16}
                aria-hidden="true"
                className="sidebar-footer-chevron"
                style={{ flexShrink: 0, color: 'var(--text-tertiary)' }}
              />
            </div>
          </Link>
        </div>
      </aside>

      <div className="main-content">
        <header className="topbar">
          <div className="topbar-left">
            <button
              type="button"
              className="btn btn-ghost btn-icon dashboard-mobile-menu-toggle"
              onClick={() => setMobileOpen(!mobileOpen)}
              aria-label="Toggle navigation menu"
            >
              <Menu size={18} aria-hidden="true" />
            </button>
            <Link
              href="/"
              className="btn btn-ghost btn-sm dashboard-mobile-landing-link"
              title="Back to landing page"
              aria-label="Back to landing page"
            >
              <ArrowLeft size={16} aria-hidden="true" />
              <span>Landing</span>
            </Link>

            <div
              style={{
                marginLeft: '0.5rem',
                display: 'flex',
                alignItems: 'center',
                gap: '1rem',
                flexWrap: 'wrap',
                minWidth: 0,
                flex: '1 1 auto',
              }}
            >
              <Link
                href={homePath}
                className="btn btn-ghost btn-sm"
                style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem', fontWeight: 700, flexShrink: 0 }}
                title="Full workspace menu"
              >
                <Home size={16} aria-hidden="true" /> Home
              </Link>
              <div className="topbar-divider-mobile-hide" style={{ width: '1px', height: '24px', background: 'var(--border)', flexShrink: 0 }} />
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', minWidth: 0, maxWidth: 'min(100%, 22rem)' }}>
                <EntityLogo
                  name={
                    role === 'super_admin'
                      ? 'PlacementHub'
                      : role === 'employer'
                        ? employerDisplayName || session.user.name
                        : (collegeSettings?.institution?.collegeName || '').trim() ||
                          session.user.tenantName ||
                          session.user.name
                  }
                  logoUrl={resolvedBrandLogoUrl}
                  placeholderUrl={
                    role === 'employer' || role === 'college_admin' ? DEFAULT_ENTITY_LOGO_URL : null
                  }
                  size="sm"
                  shape="rounded"
                />
                <div style={{ minWidth: 0 }}>
                  <h2 style={{ fontSize: '1rem', fontWeight: 700, margin: 0, lineHeight: 1.2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {role === 'super_admin'
                      ? 'PlacementHub SuperAdmin'
                      : role === 'employer'
                        ? employerDisplayName
                        : (collegeSettings?.institution?.collegeName || '').trim() ||
                          session.user.tenantName ||
                          session.user.name}
                  </h2>
                  <p style={{ margin: 0, fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>
                    {role === 'employer'
                      ? 'Corporate Partner'
                      : role === 'student'
                        ? session.user?.isAlumni
                          ? 'Alumni Portal'
                          : 'Student Portal'
                        : 'College Administration'}
                  </p>
                </div>
              </div>

              {role === 'employer' && (
                <>
                  <div className="topbar-divider-mobile-hide" style={{ width: '1px', height: '24px', background: 'var(--border)', margin: '0 0.5rem' }} />
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', minWidth: 0 }}>
                    <span style={{ fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-tertiary)', textTransform: 'uppercase', flexShrink: 0 }}>Campus:</span>
                    <Link
                      href="/dashboard/employer/select-campus"
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '0.4rem',
                        padding: '0.25rem 0.75rem',
                        borderRadius: '4px',
                        background: 'var(--bg-secondary)',
                        border: '1px solid var(--border)',
                        fontSize: '0.875rem',
                        color: 'var(--text-primary)',
                        textDecoration: 'none',
                        fontWeight: 600,
                        maxWidth: '14rem',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                      title="View campus partnerships (all approved campuses are in scope)"
                    >
                      All campuses
                      <span style={{ fontSize: '0.6rem', color: 'var(--text-tertiary)' }}>▼</span>
                    </Link>
                  </div>
                  <div className="topbar-divider-mobile-hide" style={{ width: '1px', height: '24px', background: 'var(--border)', margin: '0 0.5rem' }} />
                  <div className="topbar-academic-year-selector" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', minWidth: 0 }}>
                    <span style={{ fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-tertiary)', textTransform: 'uppercase', flexShrink: 0 }}>Academic Year:</span>
                    <select
                      className="form-input"
                      aria-label="Academic Year"
                      style={{ width: 'auto', padding: '0.25rem 0.5rem', fontSize: '0.875rem', maxWidth: '9rem', opacity: 0.65 }}
                      value={employerAcademicYear}
                      disabled
                      title="Not used for employer login — data includes all campuses and seasons"
                    >
                      {employerAcademicYearOptions.map((opt) => (
                        <option key={opt} value={opt}>{opt}</option>
                      ))}
                    </select>
                  </div>
                </>
              )}

              {(role === 'college_admin' || role === 'placement_committee') && (
                <>
                  <div className="topbar-divider-mobile-hide" style={{ width: '1px', height: '24px', background: 'var(--border)', margin: '0 0.5rem' }} />
                  <div className="topbar-academic-year-selector" style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <span style={{ fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-tertiary)', textTransform: 'uppercase' }}>Academic Year:</span>
                    <select
                      className="form-input"
                      aria-label="Academic Year"
                      style={{ width: 'auto', padding: '0.25rem 0.5rem', fontSize: '0.875rem', opacity: 0.65, cursor: 'not-allowed' }}
                      value={academicYear}
                      disabled
                      title="Academic year switching is not active yet — display only"
                    >
                      <option value={academicYear}>{academicYear}</option>
                    </select>
                  </div>
                </>
              )}


            </div>
          </div>

          <div className="topbar-right" style={{ flexShrink: 0, flexWrap: 'wrap', justifyContent: 'flex-end', alignItems: 'center', gap: '0.5rem' }}>
            <ScreenSearchBar />
            <DevScreenTag />
            {role === 'student' && (
              <Link
                href="/dashboard/student/reminders"
                className="btn btn-ghost btn-sm topbar-label-hide-mobile"
                style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem', fontWeight: 600 }}
                title="Reminders & email preview"
                aria-label="Email reminders"
              >
                <Mail size={16} aria-hidden="true" /> Email
              </Link>
            )}
            <ThemeToggleButton />

            <NotificationDropdown />

            <div className="dropdown" style={{ position: 'relative' }}>
              <button
                type="button"
                className="btn btn-ghost btn-sm topbar-label-hide-mobile"
                onClick={() => signOut({ callbackUrl: '/login?force=1' })}
                style={{ color: 'var(--text-secondary)', display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}
                title="Sign out"
                aria-label="Sign out"
              >
                <LogOut size={16} aria-hidden="true" />
                Sign Out
              </button>
            </div>
          </div>
        </header>

        <main id="main-content" className="page-content">
          {studentVerifyBanner}
          {committeeReadOnlyBanner}
          <DashboardErrorBoundary>{children}</DashboardErrorBoundary>
        </main>
        <SessionAdBanner />
        <DocumentationHelpWidget />
      </div>

      {mobileOpen && (
        <div
          style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', zIndex: 99 }}
          onClick={() => setMobileOpen(false)}
        />
      )}
    </div>
  );
}

'use client';

import { useCallback, useMemo, useState } from 'react';
import useSWR from 'swr';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMMON_SORT_OPTIONS } from '@/lib/tableQueryPresets';
import { useSession } from 'next-auth/react';
import { useToast } from '@/components/ToastProvider';
import { formatDate, formatStatus } from '@/lib/utils';
import PageLoading from '@/components/PageLoading';

const historyFetcher = async (url) => {
  const res = await fetch(url);
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || 'Failed to load');
  return data;
};

const registryFetcher = async (url) => {
  const res = await fetch(url);
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || 'Failed to load screens');
  return data;
};

export default function MyExportsPage() {
  const { data: session } = useSession();
  const { addToast } = useToast();
  const { data: hist, mutate, error, isLoading } = useSWR('/api/user/data-export', historyFetcher);
  const { data: reg } = useSWR('/api/screens/registry', registryFetcher);
  const [busy, setBusy] = useState(false);
  const [showAllScreens, setShowAllScreens] = useState(false);
  const [statusFilter, setStatusFilter] = useState('');
  const [sectionFilter, setSectionFilter] = useState('');

  const exports = hist?.exports || [];
  const screens = reg?.screens || [];
  const defaultExportExt = 'csv';
  const preFilteredExports = useMemo(() => {
    const q = sectionFilter.trim().toLowerCase();
    return exports.filter((row) => {
      if (statusFilter && String(row.status || '') !== statusFilter) return false;
      if (!q) return true;
      let s = row.section_summary;
      if (typeof s === 'string') {
        try {
          s = JSON.parse(s);
        } catch {
          return false;
        }
      }
      const text = Array.isArray(s) ? s.map((x) => x.key).filter(Boolean).join(', ').toLowerCase() : '';
      return text.includes(q);
    });
  }, [exports, statusFilter, sectionFilter]);
  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered: filteredExports,
    filteredCount,
    totalCount: exportsTableTotal,
    hasActiveFilters: exportsHasActiveFilters,
    clearFilters: clearExportsFilters,
  } = useDataTableQuery(preFilteredExports, {
    getSearchText: (row) => {
      let s = row.section_summary;
      if (typeof s === 'string') {
        try {
          s = JSON.parse(s);
        } catch {
          s = null;
        }
      }
      const sections = Array.isArray(s) ? s.map((x) => x.key).filter(Boolean).join(' ') : '';
      return [row.status, row.format, sections].filter(Boolean).join(' ');
    },
    sortOptions: COMMON_SORT_OPTIONS,
    defaultSort: 'date_desc',
  });

  const runExport = useCallback(async () => {
    setBusy(true);
    try {
      const res = await fetch('/api/user/data-export', { method: 'POST' });
      if (!res.ok) {
        const j = await res.json().catch(() => ({}));
        throw new Error(j.error || 'Export failed');
      }
      const cd = res.headers.get('Content-Disposition') || '';
      const m = cd.match(/filename="([^"]+)"/);
      const name = m?.[1] || `placementhub-export-${new Date().toISOString().slice(0, 10)}.${defaultExportExt}`;
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = name;
      a.style.display = 'none';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      addToast('Download started. A confirmation email was sent if SMTP is configured.', 'success');
      await mutate();
    } catch (e) {
      addToast(e.message || 'Export failed', 'error');
    } finally {
      setBusy(false);
    }
  }, [addToast, mutate, defaultExportExt]);

  return (
    <div className="animate-fadeIn">
      <div className="page-header">
        <div className="page-header-left">
          <h1>📦 My data export</h1>
          <p>
            Download a CSV snapshot of the data this platform associates with your login ({session?.user?.role?.replace(/_/g, ' ') || '…'}).
            Each request is recorded for audit. Use the <strong>Screens</strong> button in the top bar to jump to any page.
          </p>
        </div>
        <div className="page-header-actions">
          <button className="btn btn-primary" type="button" disabled={busy} onClick={runExport}>
            {busy ? 'Preparing…' : 'Download full export'}
          </button>
        </div>
      </div>

      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3 className="card-title">Export history</h3>
        <div style={{ display: 'flex', gap: '0.6rem', flexWrap: 'wrap', marginBottom: '0.75rem' }}>
          <select className="form-input" style={{ width: 180 }} value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option value="">All statuses</option>
            <option value="completed">Completed</option>
            <option value="pending">Pending</option>
            <option value="failed">Failed</option>
          </select>
          <input
            className="form-input"
            style={{ width: 240 }}
            placeholder="Filter by section..."
            value={sectionFilter}
            onChange={(e) => setSectionFilter(e.target.value)}
          />
        </div>
        {isLoading && <PageLoading message="Loading export history…" inline />}
        {error && <p className="text-sm" style={{ color: 'var(--danger-600)' }}>{error.message}</p>}
        {!isLoading && !error && exports.length === 0 && (
          <p className="text-sm text-secondary">No exports yet. Run a download to create the first entry.</p>
        )}
        {!isLoading && !error && exports.length > 0 && filteredExports.length === 0 && (
          <p className="text-sm text-secondary">No exports match your filters or search.</p>
        )}
        {exportsTableTotal > 0 && (
          <DataTableToolbar
            search={search}
            onSearchChange={setSearch}
            searchPlaceholder="Search status or sections…"
            sort={sort}
            onSortChange={setSort}
            sortOptions={COMMON_SORT_OPTIONS}
            filteredCount={filteredCount}
            totalCount={exportsTableTotal}
            hasActiveFilters={exportsHasActiveFilters}
            onClear={clearExportsFilters}
            style={{ marginBottom: '1rem' }}
          />
        )}
        {filteredExports.length > 0 && (
          <div className="table-container">
            <table className="data-table">
              <thead>
                <tr>
                  <th>When</th>
                  <th>Status</th>
                  <th>Format</th>
                  <th>Size</th>
                  <th>Sections</th>
                </tr>
              </thead>
              <tbody>
                {filteredExports.length === 0 && exportsTableTotal > 0 ? (
                  <tr>
                    <td colSpan={5} className="text-center text-secondary">No exports match your search.</td>
                  </tr>
                ) : null}
                {filteredExports.map((row) => (
                  <tr key={row.id}>
                    <td>{row.created_at ? formatDate(row.created_at) : '—'}</td>
                    <td>{formatStatus(row.status)}</td>
                    <td>{(row.format || 'csv').toUpperCase()}</td>
                    <td>{row.byte_size != null ? `${row.byte_size} B` : '—'}</td>
                    <td className="text-sm text-secondary">
                      {(() => {
                        let s = row.section_summary;
                        if (typeof s === 'string') {
                          try {
                            s = JSON.parse(s);
                          } catch {
                            return '—';
                          }
                        }
                        return Array.isArray(s) ? s.map((x) => x.key).filter(Boolean).join(', ') : '—';
                      })()}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div className="card">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '0.5rem' }}>
          <h3 className="card-title" style={{ margin: 0 }}>Screens available to you</h3>
          <button type="button" className="btn btn-secondary btn-sm" onClick={() => setShowAllScreens((v) => !v)}>
            {showAllScreens ? 'Hide list' : `Show all (${screens.length})`}
          </button>
        </div>
        <p className="text-sm text-secondary" style={{ marginTop: '0.5rem' }}>
          Same directory as the <strong>Screens</strong> search in the header. Optional smart matching may be unavailable on this deployment.
        </p>
        {showAllScreens && (
          <div className="table-container" style={{ marginTop: '0.75rem' }}>
            <table className="data-table">
              <thead>
                <tr>
                  <th>Label</th>
                  <th>Section</th>
                  <th>Screen tag</th>
                  <th>Path</th>
                </tr>
              </thead>
              <tbody>
                {screens.map((s) => (
                  <tr key={s.href}>
                    <td>
                      <a href={s.href}>{s.label}</a>
                    </td>
                    <td>{s.section}</td>
                    <td>
                      <code>{s.screenId}</code>
                    </td>
                    <td className="text-xs text-secondary">{s.href}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';
import { useEffect, useState } from 'react';
import useSWR, { mutate as swrMutate } from 'swr';
import { useRouter } from 'next/navigation';
import { useSession } from 'next-auth/react';
import { formatDate, formatStatus, getStatusColor } from '@/lib/utils';
import EntityLogo from '@/components/EntityLogo';
import CompanyNameLink from '@/components/CompanyNameLink';
import PageError from '@/components/PageError';
import PageLoading from '@/components/PageLoading';
import { useToast } from '@/components/ToastProvider';
import { ExportCsvSplitButton } from '@/components/export/ExportCsvSplitButton';
import StudentSelectionOfferPanel from '@/components/student/StudentSelectionOfferPanel';
import { ClipboardList, Mail, X } from 'lucide-react';
import { notFound } from 'next/navigation';
import { use, useMemo } from 'react';
import DataTableToolbar from '@/components/DataTableToolbar';
import { useDataTableQuery } from '@/hooks/useDataTableQuery';
import { COMPANY_SORT_OPTIONS, applicationSearchText } from '@/lib/tableQueryPresets';
import ConfirmDialog from '@/components/ConfirmDialog';
import {
  WITHDRAWAL_CONFIRM_BODY,
  WITHDRAWAL_CONFIRM_TITLE,
} from '@/lib/applicationWithdrawal';
import { ALUMNI_BROWSE_JOBS_PATH } from '@/lib/alumniRoutes';
import { isAlumniStudent } from '@/lib/studentAlumni';
import { useTableRowSelection, usePruneRowSelection } from '@/hooks/useTableRowSelection';
import TableBulkActionBar from '@/components/table/TableBulkActionBar';
import OpportunityEmailComposeModal from '@/components/student/OpportunityEmailComposeModal';
import { StandardTableIconAction } from '@/components/ui/StandardTableIconAction';
import { downloadStudentOpportunityCsv } from '@/lib/studentOpportunityCsvExport';
import {
  applicationStatusCounts,
  filterApplicationsByStatusTab,
  normalizeAppStatus,
  studentApplicationStageLabel,
} from '@/lib/studentApplicationListTabs';
import { formatFilterBadgeLabelParen } from '@/lib/filterBadgeLabel';

const fetcher = async (url) => {
  const res = await fetch(url);
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.error || 'Failed to load applications');
  }
  return res.json();
};

function roundLabel(item) {
  return studentApplicationStageLabel(item);
}

/** Map application row to opportunity shape for email / CSV actions. */
function appToOpportunityRow(app) {
  return {
    id: app.jobId,
    title: app.role || app.title,
    companyName: app.company || app.companyName,
    website: app.website || null,
    hasApplied: true,
    applicationStatus: app.status,
  };
}

const VALID_TYPES = ['jobs', 'internships', 'projects', 'mentorship', 'hackathons', 'drives'];

const TYPE_META = {
  drives: {
    title: 'Drive',
    browseHref: '/dashboard/student/drives',
    browseText: 'Browse Drives',
    emptyMessage:
      "You haven't applied to any placement drives yet. Start exploring active drives and apply to kickstart your career!",
  },
  jobs: {
    title: 'Alumni Job',
    browseHref: ALUMNI_BROWSE_JOBS_PATH,
    browseText: 'Browse Alumni Jobs',
    emptyMessage: "You haven't applied to any alumni jobs yet. Browse published alumni jobs for your campus network and apply.",
  },
  internships: {
    title: 'Internship',
    browseHref: '/dashboard/student/internships',
    browseText: 'Browse Internships',
    emptyMessage: "You haven't applied to any internships yet. Start exploring available internships and apply!",
  },
  projects: {
    title: 'Project',
    browseHref: '/dashboard/student/projects',
    browseText: 'Browse Projects',
    emptyMessage: "You haven't applied to any short projects yet. Browse projects for your campus and apply.",
  },
  hackathons: {
    title: 'Hackathon',
    browseHref: '/dashboard/student/hackathons',
    browseText: 'Browse Hackathons',
    emptyMessage: "You haven't applied to any hackathons yet. Browse hackathons for your campus and apply.",
  },
  mentorship: {
    title: 'Mentorship',
    browseHref: '/dashboard/student/internships',
    browseText: 'Browse Programs',
    emptyMessage: "You haven't applied to any mentorship programs yet.",
  },
};

export default function StudentApplicationsPage({ params }) {
  const unwrappedParams = use(params);
  const type = unwrappedParams.type;

  if (!VALID_TYPES.includes(type)) {
    notFound();
  }

  const { addToast } = useToast();
  const router = useRouter();
  const { data: session, status } = useSession();
  const isAlumni = isAlumniStudent(session?.user);
  const [statusTab, setStatusTab] = useState('');
  const [withdrawingId, setWithdrawingId] = useState(null);
  const [withdrawConfirmId, setWithdrawConfirmId] = useState(null);
  const [selectedApp, setSelectedApp] = useState(null);
  const [emailComposeRows, setEmailComposeRows] = useState(null);
  const isJobApplications = type === 'jobs';

  useEffect(() => {
    if (status === 'loading' || !isJobApplications) return;
    if (!isAlumni) {
      router.replace('/dashboard/student/applications/drives');
    }
  }, [isAlumni, isJobApplications, router, status]);

  const apiEndpoint = type === 'drives' ? '/api/student/applications' : '/api/student/program-applications';
  const blockJobFetch = isJobApplications && !isAlumni;
  const { data, error, isLoading, mutate } = useSWR(blockJobFetch ? null : apiEndpoint, fetcher);
  const {
    data: offers,
    mutate: mutateOffers,
  } = useSWR('/api/student/offers', async (url) => {
    const res = await fetch(url);
    const json = await res.json();
    if (!res.ok) throw new Error(json?.error || 'Failed to load offers');
    return json;
  });
  const allApplications = (data?.items || []).map(item => ({
    ...item,
    company: item.company || item.companyName,
    role: item.role || item.title,
    driveDate: item.driveDate || null,
  }));

  const appTypeOf = (app) => {
    if (type === 'drives' && app.drive_id) return 'drive';

    const kind = String(app?.jobType || '').toLowerCase();
    if (kind === 'internship') return 'internship';
    if (kind === 'short_project') return 'project';
    if (kind === 'mentorship') return 'mentorship';
    if (kind === 'hackathon') return 'hackathon';
    if (kind === 'guest_faculty') return 'guest';
    return 'job';
  };

  const typeMatcher = {
    jobs: 'job',
    internships: 'internship',
    projects: 'project',
    mentorship: 'mentorship',
    hackathons: 'hackathon',
    drives: 'drive'
  }[type];

  const typeApplications = useMemo(() => {
    return allApplications.filter(a => appTypeOf(a) === typeMatcher);
  }, [allApplications, typeMatcher]);

  const tabFiltered = useMemo(
    () => filterApplicationsByStatusTab(typeApplications, statusTab),
    [typeApplications, statusTab],
  );

  const {
    search,
    setSearch,
    sort,
    setSort,
    filtered: displayApplications,
    filteredCount,
    totalCount: tabTotalCount,
    hasActiveFilters,
    clearFilters,
  } = useDataTableQuery(tabFiltered, {
    getSearchText: applicationSearchText,
    sortOptions: COMPANY_SORT_OPTIONS,
    defaultSort: 'company_asc',
  });

  const statusCounts = useMemo(
    () => applicationStatusCounts(typeApplications),
    [typeApplications],
  );

  const selection = useTableRowSelection({ getRowId: (app) => String(app.id) });
  usePruneRowSelection(selection, isJobApplications ? displayApplications : []);

  const userEmail = String(session?.user?.email || session?.user?.communicationEmail || '').trim();

  const emailJobs = (apps) => {
    const rows = (apps || [])
      .map(appToOpportunityRow)
      .filter((row) => row.id);
    if (!rows.length) {
      addToast('Select at least one job application to email.', 'warning');
      return;
    }
    setEmailComposeRows(rows);
  };

  const emailFilteredJobs = () => emailJobs(displayApplications);
  const emailAllJobs = () => emailJobs(typeApplications);
  const emailSelectedJobs = () => emailJobs(selection.selectedRows(displayApplications));

  const downloadJobApplication = (app) => {
    const row = appToOpportunityRow(app);
    if (!row.id) {
      addToast('Job details are unavailable for this application.', 'warning');
      return;
    }
    downloadStudentOpportunityCsv(row, { kind: 'job' });
  };

  const pageAllSelected = selection.allSelected(displayApplications);
  const pageSomeSelected = selection.someSelected(displayApplications);

  const requestWithdraw = (applicationId) => {
    setWithdrawConfirmId(applicationId);
  };

  const handleWithdraw = async (applicationId) => {
    setWithdrawingId(applicationId);
    try {
      const cancelEndpoint = type === 'drives' ? '/api/student/applications/cancel' : '/api/student/program-applications/cancel';
      const res = await fetch(cancelEndpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ application_id: applicationId }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error || 'Failed to withdraw application');
      addToast(
        'Application withdrawn permanently. You cannot apply again, and the employer will no longer see you as an applicant.',
        'success',
      );
      setSelectedApp(null);
      await mutate();
      if (type === 'drives') {
        await swrMutate('/api/student/drives');
      }
    } catch (e) {
      addToast(e.message || 'Failed to withdraw application', 'error');
    } finally {
      setWithdrawingId(null);
      setWithdrawConfirmId(null);
    }
  };

  const buildCsvRows = (scope) => {
    const dataset = scope === 'full' ? typeApplications : displayApplications;
    const headers = ['Company', 'Role', 'Status', 'Current Stage', 'Applied Date'];
    if (type === 'jobs') headers.push('Drive Date');
    const rows = dataset.map((app) => {
      const row = [
        app.company,
        app.role,
        app.status,
        roundLabel(app),
        formatDate(app.appliedAt),
      ];
      if (type === 'jobs') row.push(formatDate(app.driveDate));
      return row;
    });
    return { headers, rows };
  };

  if (error) return <PageError error={error} />;

  if (isJobApplications && (status === 'loading' || !isAlumni)) {
    return <PageLoading message="Loading…" />;
  }

  const meta = TYPE_META[type] || TYPE_META.drives;
  const pageTitle = meta.title;
  const browseHref = meta.browseHref;
  const browseText = meta.browseText;
  const emptyMessage = meta.emptyMessage;

  return (
    <div className="animate-fadeIn">
      <div className="page-header">
        <div className="page-header-left">
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <ClipboardList size={28} /> My {type === 'hackathons' ? 'Hackathons' : `${pageTitle} Applications`}
          </h1>
          <p>Track the status of your {type === 'hackathons' ? 'hackathon' : type} applications</p>
        </div>
        <div className="page-header-actions" style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem', alignItems: 'center' }}>
          <a href={browseHref} className="btn btn-secondary">
            {browseText}
          </a>
          {isJobApplications && tabTotalCount > 0 ? (
            <>
              <button
                type="button"
                className="btn btn-secondary btn-sm"
                onClick={emailFilteredJobs}
                title="Compose email for jobs in the current view"
                style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}
              >
                <Mail size={15} aria-hidden />
                Email view ({displayApplications.length})
              </button>
              {displayApplications.length !== typeApplications.length ? (
                <button
                  type="button"
                  className="btn btn-ghost btn-sm"
                  onClick={emailAllJobs}
                  title="Compose email for all your job applications"
                  style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}
                >
                  <Mail size={15} aria-hidden />
                  Email all ({typeApplications.length})
                </button>
              ) : null}
            </>
          ) : null}
          <ExportCsvSplitButton
            filenameBase={`${type}_applications`}
            currentCount={displayApplications.length}
            fullCount={typeApplications.length}
            getRows={buildCsvRows}
          />
        </div>
      </div>

      {/* Status Tabs */}
      <div className="tabs">
        {[
          { key: '', label: 'All', count: statusCounts.all },
          { key: 'applied', label: 'Applied', count: statusCounts.applied },
          { key: 'shortlisted', label: 'Shortlisted', count: statusCounts.shortlisted },
          { key: 'selected', label: 'Selected', count: statusCounts.selected },
          { key: 'rejected', label: 'Rejected', count: statusCounts.rejected },
          { key: 'withdrawn', label: 'Withdrawn', count: statusCounts.withdrawn },
        ].map(({ key, label, count }) => (
          <button
            key={key || 'all'}
            className={`tab ${statusTab === key ? 'active' : ''}`}
            onClick={() => setStatusTab(key)}
          >
            {formatFilterBadgeLabelParen(label, count)}
          </button>
        ))}
      </div>

      {/* Tabular Applications */}
      <div style={{ marginTop: '1.5rem' }}>
        {isLoading && <PageLoading message="Loading applications…" inline />}

        {!isLoading && tabTotalCount > 0 && (
          <DataTableToolbar
            search={search}
            onSearchChange={setSearch}
            searchPlaceholder="Search company, role, or status…"
            sort={sort}
            onSortChange={setSort}
            sortOptions={COMPANY_SORT_OPTIONS}
            filteredCount={filteredCount}
            totalCount={tabTotalCount}
            hasActiveFilters={hasActiveFilters}
            onClear={clearFilters}
          />
        )}

        {isJobApplications && !isLoading && tabTotalCount > 0 ? (
          <TableBulkActionBar
            count={selection.count}
            onEmail={emailSelectedJobs}
            onClear={selection.clear}
            emailLabel="Email selected jobs"
          />
        ) : null}

        {!isLoading && tabTotalCount > 0 && (
          <div className="card card-table-shell">
            <div className="table-container">
            <table className={`data-table data-table-mobile-cards${isJobApplications ? ' student-opportunities-table' : ''}`}>
              <thead>
                <tr>
                  {isJobApplications ? (
                    <th className="student-opportunities-col-select" style={{ paddingLeft: '0.75rem' }}>
                      <input
                        type="checkbox"
                        aria-label="Select all job applications on this page"
                        checked={pageAllSelected}
                        ref={(el) => {
                          if (el) el.indeterminate = pageSomeSelected;
                        }}
                        onChange={() => selection.toggleAll(displayApplications)}
                      />
                    </th>
                  ) : null}
                  <th style={{ paddingLeft: isJobApplications ? '0.5rem' : '1rem' }}>Company</th>
                  <th>Role</th>
                  <th>Status</th>
                  <th>Stage</th>
                  <th>Applied On</th>
                  {type === 'jobs' && <th>Drive Date</th>}
                  <th
                    className={isJobApplications ? 'student-opportunities-col-actions' : undefined}
                    style={{ textAlign: isJobApplications ? 'right' : 'center', paddingRight: isJobApplications ? '1rem' : undefined }}
                  >
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody>
                {displayApplications.length === 0 ? (
                  <tr>
                    <td colSpan={isJobApplications ? 8 : type === 'jobs' ? 7 : 6} className="text-center text-secondary">
                      No applications match your search.
                    </td>
                  </tr>
                ) : null}
                {displayApplications.map(app => (
                  <tr
                    key={app.id}
                    className={isJobApplications && selection.isSelected(app) ? 'is-row-selected' : undefined}
                  >
                    {isJobApplications ? (
                      <td className="student-opportunities-col-select" data-label="" style={{ paddingLeft: '0.75rem' }}>
                        <input
                          type="checkbox"
                          aria-label={`Select ${app.role || 'job application'} at ${app.company || 'company'}`}
                          checked={selection.isSelected(app)}
                          onChange={() => selection.toggle(app)}
                        />
                      </td>
                    ) : null}
                    <td data-label="Company" style={{ paddingLeft: isJobApplications ? '0.5rem' : '1rem' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        <EntityLogo name={app.company} size="sm" shape="rounded" />
                        <CompanyNameLink name={app.company} website={app.website} className="font-semibold" />
                      </div>
                    </td>
                    <td className="text-sm" data-label="Role">{app.role}</td>
                    <td data-label="Status">
                      <span className={`badge badge-${getStatusColor(app.status)} badge-dot`}>{formatStatus(app.status)}</span>
                    </td>
                    <td className="text-sm" data-label="Stage">{roundLabel(app)}</td>
                    <td className="text-sm" data-label="Applied">{formatDate(app.appliedAt)}</td>
                    {type === 'jobs' && <td className="text-sm" data-label="Drive date">{formatDate(app.driveDate)}</td>}
                    <td
                      className={isJobApplications ? 'student-opportunities-col-actions' : undefined}
                      data-label="Actions"
                      style={{ textAlign: isJobApplications ? 'right' : 'center', paddingRight: isJobApplications ? '1rem' : undefined }}
                    >
                      {isJobApplications ? (
                        <div
                          className="table-actions"
                          style={{
                            display: 'inline-flex',
                            gap: '0.35rem',
                            alignItems: 'center',
                            justifyContent: 'flex-end',
                            flexWrap: 'nowrap',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          <StandardTableIconAction
                            action="view"
                            showLabel={false}
                            onClick={() => setSelectedApp(app)}
                            tooltip="View application details"
                          />
                          <StandardTableIconAction
                            action="email"
                            showLabel={false}
                            onClick={() => emailJobs([app])}
                            tooltip="Email this job"
                            disabled={!app.jobId}
                          />
                          <StandardTableIconAction
                            action="download"
                            showLabel={false}
                            onClick={() => downloadJobApplication(app)}
                            tooltip="Download job details as CSV"
                            disabled={!app.jobId}
                          />
                          {normalizeAppStatus(app.status) === 'applied' ? (
                            <button
                              type="button"
                              className="btn btn-danger btn-sm btn-icon"
                              disabled={withdrawingId === app.id}
                              onClick={() => requestWithdraw(app.id)}
                              title="Withdraw application"
                              aria-label="Withdraw application"
                            >
                              <X size={14} aria-hidden />
                            </button>
                          ) : null}
                        </div>
                      ) : (
                        <div
                          className="table-actions"
                          style={{
                            display: 'inline-flex',
                            gap: '0.35rem',
                            alignItems: 'center',
                            justifyContent: 'flex-end',
                            flexWrap: 'nowrap',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          <StandardTableIconAction
                            action="view"
                            showLabel={false}
                            onClick={() => setSelectedApp(app)}
                            tooltip="View application details"
                          />
                          {normalizeAppStatus(app.status) === 'applied' ? (
                            <StandardTableIconAction
                              action="withdraw"
                              variant="danger"
                              loading={withdrawingId === app.id}
                              disabled={withdrawingId === app.id}
                              onClick={() => requestWithdraw(app.id)}
                            />
                          ) : null}
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            </div>
          </div>
        )}

        {!isLoading && tabTotalCount === 0 && (
          <div className="empty-state-container" style={{ textAlign: 'center', padding: '3rem 1rem', background: 'var(--bg-surface)', border: '1px solid var(--border-color)', borderRadius: 'var(--radius-xl)' }}>
            <div style={{ background: 'var(--primary-50)', width: '64px', height: '64px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem' }}>
              <span style={{ fontSize: '1.75rem' }}>📝</span>
            </div>
            <h3 style={{ fontSize: '1.25rem', fontWeight: '600', color: 'var(--text-primary)', marginBottom: '0.5rem' }}>
              {statusTab === '' ? `No ${type} applications yet` : `No ${statusTab} applications`}
            </h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '0.95rem', marginBottom: '1.5rem', lineHeight: '1.5', maxWidth: '400px', margin: '0 auto 1.5rem' }}>
              {statusTab === '' 
                ? emptyMessage 
                : `You don't have any applications in the '${statusTab}' stage at the moment.`}
            </p>
            {statusTab === '' && (
              <div style={{ display: 'flex', justifyContent: 'center' }}>
                <a href={browseHref} className="btn btn-primary">
                  {browseText}
                </a>
              </div>
            )}
            {statusTab !== '' && (
              <div style={{ display: 'flex', justifyContent: 'center' }}>
                  <button
                    className="btn btn-secondary"
                    onClick={() => setStatusTab('')}
                  >
                    View All
                  </button>
              </div>
            )}
          </div>
        )}
      </div>

      {/* ── Detail drawer ── */}
      {selectedApp && (
        <div
          style={{
            position: 'fixed', inset: 0, zIndex: 1000,
            background: 'rgba(0,0,0,0.45)', backdropFilter: 'blur(4px)',
            display: 'flex', justifyContent: 'flex-end',
          }}
          onClick={() => setSelectedApp(null)}
        >
          <div
            className="animate-fadeIn app-detail-drawer"
            style={{
              width: '480px', maxWidth: '95vw', height: '100vh',
              background: 'var(--bg-surface)', boxShadow: 'var(--shadow-xl)',
              overflow: 'auto', padding: '2rem',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '1.5rem' }}>
              <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center' }}>
                <EntityLogo name={selectedApp.company} size="lg" shape="rounded" />
                <div>
                  <h2 style={{ fontSize: '1.25rem', fontWeight: 700, margin: 0 }}>
                    <CompanyNameLink name={selectedApp.company} website={selectedApp.website} />
                  </h2>
                  <p className="text-sm text-secondary" style={{ margin: '0.125rem 0 0 0' }}>{selectedApp.role}</p>
                </div>
              </div>
              <button className="btn btn-secondary btn-sm" onClick={() => setSelectedApp(null)} title="Close">
                <X size={16} />
              </button>
            </div>

            {/* Status */}
            <div style={{ marginBottom: '1.25rem' }}>
              <span className={`badge badge-${getStatusColor(selectedApp.status)} badge-dot`} style={{ fontSize: '0.85rem', padding: '0.375rem 0.75rem' }}>
                {formatStatus(selectedApp.status)}
              </span>
              {normalizeAppStatus(selectedApp.status) === 'selected' && (
                <span className="badge badge-blue" style={{ padding: '0.375rem 1rem', marginLeft: '0.5rem' }}>
                  Selection complete
                </span>
              )}
            </div>

            {normalizeAppStatus(selectedApp.status) === 'selected' && (
              <StudentSelectionOfferPanel
                application={selectedApp}
                offers={offers}
                type={type}
                onOfferUpdated={async () => {
                  await mutateOffers();
                  await mutate();
                }}
              />
            )}

            {/* Details grid */}
            <div
              className="form-grid-2"
              style={{
                display: 'grid', gridTemplateColumns: '1fr 1fr',
                gap: '1rem', padding: '1.25rem',
                background: 'var(--bg-tertiary)', borderRadius: 'var(--radius-lg)',
                marginBottom: '1.5rem',
              }}
            >
              <div>
                <div className="text-xs text-tertiary" style={{ textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.25rem' }}>Current Stage</div>
                <div className="text-sm font-semibold">{roundLabel(selectedApp)}</div>
              </div>
              <div>
                <div className="text-xs text-tertiary" style={{ textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.25rem' }}>Applied On</div>
                <div className="text-sm font-semibold">{formatDate(selectedApp.appliedAt)}</div>
              </div>
              {type === 'jobs' && selectedApp.driveDate && (
                <div>
                  <div className="text-xs text-tertiary" style={{ textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.25rem' }}>Drive Date</div>
                  <div className="text-sm font-semibold">{formatDate(selectedApp.driveDate)}</div>
                </div>
              )}
              {selectedApp.notes && (
                <div style={{ gridColumn: '1 / -1' }}>
                  <div className="text-xs text-tertiary" style={{ textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.25rem' }}>Notes</div>
                  <div className="text-sm">{selectedApp.notes}</div>
                </div>
              )}
            </div>

            {/* Withdraw */}
            {normalizeAppStatus(selectedApp.status) === 'applied' && (
              <button
                className="btn btn-danger"
                style={{ width: '100%' }}
                disabled={withdrawingId === selectedApp.id}
                onClick={() => requestWithdraw(selectedApp.id)}
              >
                {withdrawingId === selectedApp.id ? 'Withdrawing...' : 'Withdraw Application'}
              </button>
            )}
          </div>
        </div>
      )}

      <ConfirmDialog
        open={Boolean(withdrawConfirmId)}
        title={WITHDRAWAL_CONFIRM_TITLE}
        message={WITHDRAWAL_CONFIRM_BODY}
        confirmLabel="Yes, withdraw permanently"
        cancelLabel="Keep my application"
        confirmTone="danger"
        loading={Boolean(withdrawingId)}
        onCancel={() => {
          if (!withdrawingId) setWithdrawConfirmId(null);
        }}
        onConfirm={() => {
          if (withdrawConfirmId) void handleWithdraw(withdrawConfirmId);
        }}
      />

      {emailComposeRows ? (
        <OpportunityEmailComposeModal
          rows={emailComposeRows}
          kind="job"
          defaultTo={userEmail}
          onClose={() => setEmailComposeRows(null)}
        />
      ) : null}
    </div>
  );
}

