              </div>
            ))}
          </div>
        </div>
        )}

        {activeTab === 'activities' && (
        <div className="card" style={{ gridColumn: '1 / -1' }}>
          <div className="card-header">
            <h3 className="card-title">🏅 Activities</h3>
