'use client';

import { useMemo, useState, useEffect, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';

const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const MAX_VISIBLE_EVENTS = 2;

function pad2(n) {
  return String(n).padStart(2, '0');
}

function getWeekStart(date) {
  const d = new Date(date);
  const day = d.getDay();
  const diff = d.getDate() - day;
  return new Date(d.setDate(diff));
}

/** Shared event colors — uses tokens defined in globals.css */
export function getCalendarEventColor(type) {
  const t = String(type || '').toLowerCase();
  if (t === 'completed' || t === 'holiday') {
    return { bg: 'var(--success-100)', text: 'var(--success-700)', border: 'var(--success-500)' };
  }
  if (t === 'approved' || t === 'placement_drive' || t === 'drive' || t === 'on_campus' || t === 'booking') {
    return { bg: 'var(--primary-100)', text: 'var(--primary-700)', border: 'var(--primary-300)' };
  }
  if (t === 'interview' || t === 'virtual' || t === 'workshop') {
    return { bg: 'var(--info-100)', text: 'var(--info-600)', border: 'var(--info-500)' };
  }
  if (t === 'exam') {
    return { bg: 'var(--danger-100)', text: 'var(--danger-600)', border: 'var(--danger-500)' };
  }
  if (t === 'imported') {
    return { bg: 'var(--warning-100)', text: 'var(--warning-700)', border: 'var(--warning-500)' };
  }
  if (t === 'off_campus') {
    return { bg: 'var(--warning-100)', text: 'var(--warning-600)', border: 'var(--warning-500)' };
  }
  return { bg: 'var(--gray-100)', text: 'var(--gray-700)', border: 'var(--gray-300)' };
}

function eventTooltipLines(ev) {
  return [
    ev.time ? `Time: ${ev.time}` : null,
    ev.title,
    ev.college ? `Campus: ${ev.college}` : null,
    ev.meta || null,
  ].filter(Boolean);
}

function dayEventsTooltipLines(events, dayLabel) {
  if (!events?.length) return [];
  const lines = [dayLabel];
  events.forEach((ev, idx) => {
    if (idx > 0) lines.push('—');
    lines.push(...eventTooltipLines(ev));
  });
  return lines;
}

function monthPillLabel(ev) {
  const parts = [];
  if (ev.time) parts.push(ev.time);
  if (ev.title) parts.push(ev.title);
  return parts.join(' ') || 'Event';
}

export function CalendarHoverTooltip({ lines, children, wrapperClassName = 'campus-cal-month__pill-wrap' }) {
  const [open, setOpen] = useState(false);
  const [pos, setPos] = useState({ top: 0, left: 0 });
  const anchorRef = useRef(null);

  const show = useCallback(() => {
    const el = anchorRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    setPos({
      top: Math.max(8, rect.top - 8),
      left: Math.min(rect.left, window.innerWidth - 200),
    });
    setOpen(true);
  }, []);

  const hide = useCallback(() => setOpen(false), []);

  if (!lines?.length) return children;

  return (
    <>
      <div
        ref={anchorRef}
        className={wrapperClassName}
        onMouseEnter={show}
        onMouseLeave={hide}
        onFocus={show}
        onBlur={hide}
      >
        {children}
      </div>
      {open && typeof document !== 'undefined'
        ? createPortal(
            <div
              role="tooltip"
              className="campus-cal-tooltip"
              style={{
                top: pos.top,
                left: pos.left,
                transform: 'translateY(-100%)',
              }}
            >
              {lines.map((line, i) => (
                <div
                  key={i}
                  style={{
                    fontWeight: i === 1 ? 600 : 400,
                    color: i === 0 ? 'var(--text-secondary)' : 'inherit',
                    marginTop: i > 0 ? '0.2rem' : 0,
                    wordBreak: 'break-word',
                  }}
                >
                  {line}
                </div>
              ))}
            </div>,
            document.body,
          )
        : null}
    </>
  );
}

function MonthEventPill({ ev }) {
  const colors = getCalendarEventColor(ev.type);

  return (
    <CalendarHoverTooltip lines={eventTooltipLines(ev)}>
      <div
        className="campus-cal-month__pill"
        style={{
          background: colors.bg,
          color: colors.text,
          border: `1px solid ${colors.border}`,
        }}
        title=""
      >
        {monthPillLabel(ev)}
      </div>
    </CalendarHoverTooltip>
  );
}

/**
 * Shared month / week / year calendar grid.
 * @param {{ id: string|number, date: string, title: string, time?: string, meta?: string, type?: string, college?: string }} items
 */
export function CampusCalendarGrid({
  items,
  initialYear,
  initialMonth,
  viewMode = 'month',
  onCursorChange,
  onChangeView,
  onDaySelect,
  showToolbar = true,
}) {
  const now = new Date();
  const [cursor, setCursor] = useState(() => ({
    y: initialYear ?? now.getFullYear(),
    m: initialMonth ?? now.getMonth(),
    d: now.getDate(),
  }));

  useEffect(() => {
    if (initialYear !== undefined && initialMonth !== undefined) {
      setCursor((c) => ({ ...c, y: initialYear, m: initialMonth }));
    }
  }, [initialYear, initialMonth]);

  const updateCursor = (ny, nm, nd = 1) => {
    setCursor({ y: ny, m: nm, d: nd });
    if (onCursorChange) onCursorChange(ny, nm);
  };

  const byDay = useMemo(() => {
    const map = new Map();
    for (const it of items) {
      const k = (it.date || '').slice(0, 10);
      if (!k || k.length < 10) continue;
      if (!map.has(k)) map.set(k, []);
      map.get(k).push(it);
    }
    return map;
  }, [items]);

  const { y, m, d } = cursor;

  const prev = () => {
    if (viewMode === 'year') {
      updateCursor(y - 1, m, d);
    } else if (viewMode === 'week') {
      const current = new Date(y, m, d);
      current.setDate(current.getDate() - 7);
      updateCursor(current.getFullYear(), current.getMonth(), current.getDate());
    } else {
      let nm = m - 1;
      let ny = y;
      if (nm < 0) {
        nm = 11;
        ny -= 1;
      }
      updateCursor(ny, nm, d);
    }
  };

  const next = () => {
    if (viewMode === 'year') {
      updateCursor(y + 1, m, d);
    } else if (viewMode === 'week') {
      const current = new Date(y, m, d);
      current.setDate(current.getDate() + 7);
      updateCursor(current.getFullYear(), current.getMonth(), current.getDate());
    } else {
      let nm = m + 1;
      let ny = y;
      if (nm > 11) {
        nm = 0;
        ny += 1;
      }
      updateCursor(ny, nm, d);
    }
  };

  const today = new Date();
  const isToday = (dy, dm, dd) => today.getFullYear() === dy && today.getMonth() === dm && today.getDate() === dd;

  const renderMonthView = () => {
    const first = new Date(y, m, 1);
    const startPad = first.getDay();
    const daysInMonth = new Date(y, m + 1, 0).getDate();

    const cells = [];
    for (let i = 0; i < startPad; i += 1) {
      cells.push({ type: 'pad', key: `pad-${i}` });
    }
    for (let dNum = 1; dNum <= daysInMonth; dNum += 1) {
      cells.push({ type: 'day', d: dNum, key: `day-${dNum}` });
    }

    return (
      <div style={{ background: 'var(--bg-primary)', overflow: 'hidden' }}>
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, minmax(0, 1fr))',
            borderBottom: '1px solid var(--border-default)',
            background: 'var(--bg-secondary)',
          }}
        >
          {weekdays.map((w) => (
            <div
              key={w}
              style={{
                padding: '0.75rem',
                textAlign: 'center',
                fontSize: '0.85rem',
                fontWeight: 600,
                color: 'var(--text-secondary)',
                textTransform: 'uppercase',
                letterSpacing: '0.05em',
              }}
            >
              {w}
            </div>
          ))}
        </div>
        <div className="campus-cal-month">
          {cells.map((cell) =>
            cell.type === 'pad' ? (
              <div key={cell.key} className="campus-cal-month__pad" aria-hidden="true" />
            ) : (
              (() => {
                const dayKey = `${y}-${pad2(m + 1)}-${pad2(cell.d)}`;
                const dayEvents = byDay.get(dayKey) || [];
                const visible = dayEvents.slice(0, MAX_VISIBLE_EVENTS);
                const hiddenCount = Math.max(0, dayEvents.length - MAX_VISIBLE_EVENTS);
                const moreLines = dayEvents.slice(MAX_VISIBLE_EVENTS).flatMap((ev, idx) => {
                  const block = eventTooltipLines(ev);
                  return idx === 0 ? block : ['—', ...block];
                });
                const todayCell = isToday(y, m, cell.d);

                return (
                  <div
                    key={cell.key}
                    className={`campus-cal-month__cell${todayCell ? ' campus-cal-month__cell--today' : ''}`}
                    onClick={() => {
                      updateCursor(y, m, cell.d);
                      if (onDaySelect) {
                        onDaySelect(y, m, cell.d);
                      } else if (onChangeView) {
                        onChangeView('week');
                      }
                    }}
                    onMouseOver={(e) => {
                      if (!todayCell) e.currentTarget.style.background = 'var(--bg-secondary)';
                    }}
                    onMouseOut={(e) => {
                      if (!todayCell) e.currentTarget.style.background = 'var(--bg-primary)';
                    }}
                  >
                    <div
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        width: '26px',
                        height: '26px',
                        borderRadius: '50%',
                        fontSize: '0.8rem',
                        fontWeight: todayCell ? 700 : 500,
                        color: todayCell ? 'white' : 'var(--text-primary)',
                        background: todayCell ? 'var(--primary-600)' : 'transparent',
                        marginBottom: '0.25rem',
                        flexShrink: 0,
                      }}
                    >
                      {cell.d}
                    </div>
                    <div className="campus-cal-month__events">
                      {visible.map((ev) => (
                        <MonthEventPill key={ev.id} ev={ev} />
                      ))}
                      {hiddenCount > 0 ? (
                        <CalendarHoverTooltip
                          lines={[`${hiddenCount} more event${hiddenCount === 1 ? '' : 's'}`, ...moreLines]}
                        >
                          <div
                            style={{
                              fontSize: '0.68rem',
                              color: 'var(--text-secondary)',
                              paddingLeft: '0.15rem',
                              fontWeight: 600,
                              whiteSpace: 'nowrap',
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              cursor: 'default',
                            }}
                          >
                            +{hiddenCount} more
                          </div>
                        </CalendarHoverTooltip>
                      ) : null}
                    </div>
                  </div>
                );
              })()
            ),
          )}
        </div>
      </div>
    );
  };

  const renderWeekView = () => {
    const startOfWeek = getWeekStart(new Date(y, m, d));
    const cells = [];
    for (let i = 0; i < 7; i++) {
      const current = new Date(startOfWeek);
      current.setDate(startOfWeek.getDate() + i);
      cells.push(current);
    }

    return (
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(7, minmax(0, 1fr))',
          gap: '1px',
          background: 'var(--border-default)',
          minHeight: '500px',
          overflow: 'hidden',
        }}
      >
        {cells.map((date, idx) => {
          const cy = date.getFullYear();
          const cm = date.getMonth();
          const cd = date.getDate();
          const isCurrToday = isToday(cy, cm, cd);
          return (
            <div
              key={idx}
              style={{
                background: isCurrToday ? 'var(--primary-50)' : 'var(--bg-primary)',
                padding: '0.75rem',
                minWidth: 0,
                overflow: 'hidden',
              }}
            >
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  marginBottom: '1rem',
                  paddingBottom: '0.75rem',
                  borderBottom: isCurrToday ? '2px solid var(--primary-500)' : '1px solid var(--border-default)',
                }}
              >
                <span
                  style={{
                    fontSize: '0.75rem',
                    textTransform: 'uppercase',
                    color: isCurrToday ? 'var(--primary-600)' : 'var(--text-secondary)',
                    fontWeight: 600,
                    letterSpacing: '0.05em',
                  }}
                >
                  {weekdays[date.getDay()]}
                </span>
                <span
                  style={{
                    fontSize: '1.5rem',
                    fontWeight: isCurrToday ? 700 : 500,
                    color: isCurrToday ? 'var(--primary-700)' : 'var(--text-primary)',
                  }}
                >
                  {cd}
                </span>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', minWidth: 0 }}>
                {(byDay.get(`${cy}-${pad2(cm + 1)}-${pad2(cd)}`) || []).map((ev) => {
                  const colors = getCalendarEventColor(ev.type);
                  return (
                    <CalendarHoverTooltip key={ev.id} lines={eventTooltipLines(ev)}>
                      <div
                        style={{
                          padding: '0.5rem',
                          borderRadius: 'var(--radius-md)',
                          background: colors.bg,
                          borderLeft: `3px solid ${colors.border}`,
                          color: colors.text,
                          cursor: 'default',
                          minWidth: 0,
                          overflow: 'hidden',
                        }}
                      >
                        <div style={{ fontWeight: 600, fontSize: '0.75rem', opacity: 0.8, marginBottom: '2px' }}>
                          {ev.time || 'All day'}
                        </div>
                        <div
                          style={{
                            fontSize: '0.85rem',
                            fontWeight: 600,
                            lineHeight: 1.2,
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {ev.title}
                        </div>
                      </div>
                    </CalendarHoverTooltip>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderYearView = () => {
    return (
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '1.5rem', padding: '1.5rem', background: 'var(--bg-inset)' }}>
        {months.map((monthName, idx) => {
          const first = new Date(y, idx, 1);
          const startPad = first.getDay();
          const daysInMonth = new Date(y, idx + 1, 0).getDate();

          let eventCount = 0;
          for (let dNum = 1; dNum <= daysInMonth; dNum++) {
            if (byDay.has(`${y}-${pad2(idx + 1)}-${pad2(dNum)}`)) {
              eventCount += byDay.get(`${y}-${pad2(idx + 1)}-${pad2(dNum)}`).length;
            }
          }

          return (
            <div
              key={monthName}
              className="card animate-fadeIn"
              style={{ cursor: 'pointer', padding: '1.25rem', transition: 'all 0.2s', border: '1px solid transparent' }}
              onClick={() => {
                updateCursor(y, idx, 1);
                if (onChangeView) onChangeView('month');
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-2px)';
                e.currentTarget.style.boxShadow = '0 10px 15px -3px rgba(0,0,0,0.1)';
                e.currentTarget.style.borderColor = 'var(--primary-200)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'none';
                e.currentTarget.style.boxShadow = 'var(--shadow-sm)';
                e.currentTarget.style.borderColor = 'transparent';
              }}
            >
              <h4 style={{ margin: '0 0 1.25rem 0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '1.1rem', fontWeight: 700 }}>
                {monthName}
                {eventCount > 0 && (
                  <span className="badge badge-blue" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem', borderRadius: '12px' }}>
                    {eventCount} events
                  </span>
                )}
              </h4>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '4px', textAlign: 'center', fontSize: '0.75rem', color: 'var(--text-secondary)' }}>
                {weekdays.map((w) => (
                  <div key={w} style={{ fontWeight: 600, marginBottom: '0.5rem' }}>
                    {w.charAt(0)}
                  </div>
                ))}
                {Array.from({ length: startPad }).map((_, i) => (
                  <div key={`pad-${i}`} />
                ))}
                {Array.from({ length: daysInMonth }).map((_, i) => {
                  const dNum = i + 1;
                  const dayKey = `${y}-${pad2(idx + 1)}-${pad2(dNum)}`;
                  const dayEvents = byDay.get(dayKey) || [];
                  const hasEvents = dayEvents.length > 0;
                  const isCurrToday = isToday(y, idx, dNum);
                  const dayLabel = `${monthName} ${dNum}, ${y}`;

                  const dayCell = (
                    <div
                      style={{
                        padding: '6px 0',
                        borderRadius: '4px',
                        background: isCurrToday ? 'var(--primary-600)' : hasEvents ? 'var(--primary-100)' : 'transparent',
                        color: isCurrToday ? 'white' : hasEvents ? 'var(--primary-700)' : 'inherit',
                        fontWeight: hasEvents || isCurrToday ? 700 : 500,
                        position: 'relative',
                      }}
                    >
                      {dNum}
                      {hasEvents && !isCurrToday ? (
                        <div
                          style={{
                            position: 'absolute',
                            bottom: '2px',
                            left: '50%',
                            transform: 'translateX(-50%)',
                            width: '3px',
                            height: '3px',
                            borderRadius: '50%',
                            background: 'var(--primary-600)',
                          }}
                        />
                      ) : null}
                    </div>
                  );

                  if (!hasEvents) {
                    return <div key={dNum}>{dayCell}</div>;
                  }

                  return (
                    <CalendarHoverTooltip
                      key={dNum}
                      lines={dayEventsTooltipLines(dayEvents, dayLabel)}
                      wrapperClassName="campus-cal-year__day"
                    >
                      {dayCell}
                    </CalendarHoverTooltip>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  let label = '';
  if (viewMode === 'year') {
    label = `${y}`;
  } else if (viewMode === 'week') {
    const startOfWeek = getWeekStart(new Date(y, m, d));
    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(endOfWeek.getDate() + 6);
    label = `${startOfWeek.toLocaleString('default', { month: 'short', day: 'numeric' })} - ${endOfWeek.toLocaleString('default', { month: 'short', day: 'numeric', year: 'numeric' })}`;
  } else {
    label = `${months[m]} ${y}`;
  }

  return (
    <div style={{ background: 'var(--bg-primary)', overflow: 'hidden' }}>
      {showToolbar ? (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '1rem 1.5rem', borderBottom: '1px solid var(--border-default)' }}>
          <h3 style={{ margin: 0, fontSize: '1.25rem', fontWeight: 700, color: 'var(--text-primary)' }}>{label}</h3>
          <div style={{ display: 'flex', gap: '0.5rem' }}>
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              onClick={prev}
              aria-label="Previous"
              style={{ padding: '0.4rem 0.8rem', borderRadius: 'var(--radius-md)' }}
            >
              ← Prev
            </button>
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              onClick={() => updateCursor(today.getFullYear(), today.getMonth(), today.getDate())}
              style={{ padding: '0.4rem 1rem', borderRadius: 'var(--radius-md)' }}
            >
              Today
            </button>
            <button
              type="button"
              className="btn btn-secondary btn-sm"
              onClick={next}
              aria-label="Next"
              style={{ padding: '0.4rem 0.8rem', borderRadius: 'var(--radius-md)' }}
            >
              Next →
            </button>
          </div>
        </div>
      ) : null}

      {viewMode === 'month' && renderMonthView()}
      {viewMode === 'week' && renderWeekView()}
      {viewMode === 'year' && renderYearView()}
    </div>
  );
}

'use client';

import { useState, useRef, useEffect, useMemo } from 'react';
import useSWR from 'swr';
import { Plus, Loader2, Save, Upload } from 'lucide-react';
import TagPicker from '@/components/TagPicker';
import { resolveStudentRollNumber } from '@/lib/validators';
import {
  ADD_STUDENT_DEPARTMENTS,
  GENDERS,
  CATEGORIES,
  DISABILITY_OPTIONS,
  PLACEMENT_STATUSES,
  INTERNSHIP_STATUSES,
  SEMESTER_OPTIONS,
  initialCollegeStudentForm,
  validateCollegeStudentForm,
} from '@/lib/collegeStudentAdminFields';
import AcademicProgramPicker from '@/components/college/AcademicProgramPicker';
import AdmissionBatchYearPicker from '@/components/college/AdmissionBatchYearPicker';
import { mapProgramToStudentFields } from '@/lib/academicTaxonomy/mapProgram';
import { getMaxAdmissionBatchYear } from '@/lib/admissionBatchYear';
import ValidatedNumberInput from '@/components/form/ValidatedNumberInput';
import ValidatedDateInput from '@/components/form/ValidatedDateInput';
import CurrencyAmountInput from '@/components/form/CurrencyAmountInput';
import { FIELD_IDS } from '@/lib/inputConstraints';
import StudentListAvatar from '@/components/student/StudentListAvatar';
import { uploadCollegeStudentAvatarViaServer } from '@/lib/clientCollegeStudentAvatarUpload';
import { studentAvatarAcceptAttr } from '@/lib/studentAvatarUpload';
import { errorMessageFromApiBody } from '@/lib/errorReference';

export { ADD_STUDENT_DEPARTMENTS };

const settingsFetcher = (url) => fetch(url).then((r) => r.json());

function SectionLegend({ children }) {
  return (
    <legend
      style={{
        fontWeight: 700,
        fontSize: '0.75rem',
        color: 'var(--text-tertiary)',
        textTransform: 'uppercase',
        letterSpacing: '0.06em',
        marginBottom: '0.875rem',
      }}
    >
      {children}
    </legend>
  );
}

function Field({ label, error, hint, children, fullWidth = false }) {
  return (
    <div className="form-group" style={fullWidth ? { gridColumn: '1 / -1' } : undefined}>
      <label className="form-label">{label}</label>
      {children}
      {error ? <p className="form-error">{error}</p> : null}
      {hint && !error ? (
        <p className="form-hint" style={{ margin: '0.35rem 0 0', fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>
          {hint}
        </p>
      ) : null}
    </div>
  );
}

/**
 * Shared add/edit student form (aligned with CSV import + full profile fields).
 */
export default function AddStudentForm({
  active,
  onSuccess,
  onCancel,
  bodyPadding = '1.5rem',
  editStudentId = null,
  initialValues = null,
}) {
  const isEdit = Boolean(editStudentId);
  const [form, setForm] = useState(initialCollegeStudentForm);
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);
  const [serverError, setServerError] = useState('');
  const [pendingAvatarFile, setPendingAvatarFile] = useState(null);
  const [pendingAvatarPreview, setPendingAvatarPreview] = useState('');
  const [avatarUploading, setAvatarUploading] = useState(false);
  const nameRef = useRef(null);
  const { data: collegeSettings } = useSWR(active ? '/api/college/settings' : null, settingsFetcher);
  const { data: taxonomySettings } = useSWR(
    active && !isEdit ? '/api/college/settings/academic-taxonomy' : null,
    settingsFetcher,
  );
  const collegeShortCode = collegeSettings?.institution?.shortCode?.trim() || '';

  const rollPreview = useMemo(() => {
    if (!form.roll_number.trim()) return '';
    const r = resolveStudentRollNumber(form.roll_number, collegeShortCode);
    return r.systemId || '';
  }, [form.roll_number, collegeShortCode]);

  useEffect(() => {
    if (!active) return;
    setErrors({});
    setServerError('');
    setPendingAvatarFile(null);
    setPendingAvatarPreview((prev) => {
      if (prev) URL.revokeObjectURL(prev);
      return '';
    });
    if (isEdit && initialValues) {
      setForm({ ...initialCollegeStudentForm(), ...initialValues });
    } else {
      setForm(initialCollegeStudentForm());
      setTimeout(() => nameRef.current?.focus(), 100);
    }
  }, [active, isEdit, initialValues]);

  useEffect(() => {
    return () => {
      if (pendingAvatarPreview) URL.revokeObjectURL(pendingAvatarPreview);
    };
  }, [pendingAvatarPreview]);

  const displayPhoto = pendingAvatarPreview || form.photo_url || '';

  const handlePhotoSelected = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;

    setErrors((err) => ({ ...err, photo_url: '' }));
    setServerError('');

    if (isEdit && editStudentId) {
      setAvatarUploading(true);
      try {
        const result = await uploadCollegeStudentAvatarViaServer(editStudentId, file);
        if (!result.ok) {
          setErrors((err) => ({ ...err, photo_url: result.error || 'Upload failed' }));
          return;
        }
        setForm((f) => ({ ...f, photo_url: result.avatar_url || '' }));
        setPendingAvatarFile(null);
        setPendingAvatarPreview((prev) => {
          if (prev) URL.revokeObjectURL(prev);
          return '';
        });
      } finally {
        setAvatarUploading(false);
      }
      return;
    }

    // Add flow: upload after the student record is created.
    setPendingAvatarFile(file);
    setPendingAvatarPreview((prev) => {
      if (prev) URL.revokeObjectURL(prev);
      return URL.createObjectURL(file);
    });
  };

  const clearPendingPhoto = () => {
    setPendingAvatarFile(null);
    setPendingAvatarPreview((prev) => {
      if (prev) URL.revokeObjectURL(prev);
      return '';
    });
    if (!isEdit) {
      setForm((f) => ({ ...f, photo_url: '' }));
    }
  };

  useEffect(() => {
    if (!active || isEdit || !taxonomySettings?.settings?.defaultProgramCode) return;
    const code = taxonomySettings.settings.defaultProgramCode;
    const program = taxonomySettings.academicPrograms?.find((p) => p.code === code);
    const mapped = mapProgramToStudentFields(program);
    setForm((f) => {
      if (f.academic_program_code) return f;
      if (!mapped) return { ...f, academic_program_code: code };
      return { ...f, ...mapped };
    });
  }, [active, isEdit, taxonomySettings]);

  const set = (field, val) => {
    setForm((f) => ({ ...f, [field]: val }));
    if (errors[field]) setErrors((e) => ({ ...e, [field]: '' }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const { errors: nextErrors, valid } = validateCollegeStudentForm(form, { isEdit, collegeShortCode });
    if (!valid) {
      setErrors(nextErrors);
      return;
    }
    setSubmitting(true);
    setServerError('');

    try {
      const res = await fetch(
        isEdit ? `/api/college/students/${editStudentId}` : '/api/college/students',
        {
          method: isEdit ? 'PATCH' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(form),
        },
      );
      const json = await res.json();
      if (!res.ok) {
        setServerError(
          errorMessageFromApiBody(json, isEdit ? 'Failed to update student.' : 'Failed to add student.'),
        );
        return;
      }

      if (!isEdit && pendingAvatarFile && json.studentId) {
        setAvatarUploading(true);
        const uploaded = await uploadCollegeStudentAvatarViaServer(json.studentId, pendingAvatarFile);
        setAvatarUploading(false);
        if (!uploaded.ok) {
          onSuccess({
            ...json,
            message: `${json.message || 'Student added.'} Photo upload failed: ${uploaded.error}`,
            photoUploadError: uploaded.error,
          });
          return;
        }
      }

      onSuccess(json);
    } catch {
      setServerError(errorMessageFromApiBody(null, 'Network error. Please try again.'));
    } finally {
      setAvatarUploading(false);
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
      <div style={{ flex: 1, overflowY: 'auto', padding: bodyPadding }}>
        {serverError ? (
          <div
            style={{
              background: '#fef2f2',
              border: '1px solid #fecaca',
              borderRadius: '8px',
              padding: '0.875rem 1rem',
              marginBottom: '1.25rem',
              color: '#dc2626',
              fontSize: '0.875rem',
              fontWeight: 500,
            }}
          >
            {serverError}
          </div>
        ) : null}

        <fieldset style={{ border: 'none', padding: 0, margin: '0 0 1.5rem' }}>
          <SectionLegend>Identity {isEdit ? '(locked)' : '(primary)'}</SectionLegend>
          {isEdit ? (
            <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', margin: '0 0 0.875rem' }}>
              Name, roll number, and login email cannot be changed after creation.
            </p>
          ) : null}
          <div className="add-student-grid">
            <Field label="Full Name *" error={errors.name} fullWidth>
              <input
                ref={nameRef}
                className={`form-input${errors.name ? ' input-error' : ''}`}
                value={form.name}
                onChange={(e) => set('name', e.target.value)}
                disabled={isEdit}
                readOnly={isEdit}
                autoComplete="name"
              />
            </Field>
            <Field
              label="Roll No / System ID *"
              error={errors.roll_number}
              hint={
                !isEdit && rollPreview
                  ? `System ID: ${rollPreview}`
                  : !isEdit && collegeShortCode
                    ? `Stored as ${collegeShortCode}-<roll> when needed`
                    : undefined
              }
            >
              <input
                className={`form-input${errors.roll_number ? ' input-error' : ''}`}
                value={form.roll_number}
                onChange={(e) => set('roll_number', e.target.value)}
                disabled={isEdit}
                readOnly={isEdit}
              />
            </Field>
            <Field label="Login Email *" error={errors.email}>
              <input
                className={`form-input${errors.email ? ' input-error' : ''}`}
                type="email"
                value={form.email}
                onChange={(e) => set('email', e.target.value)}
                disabled={isEdit}
                readOnly={isEdit}
              />
            </Field>
            <Field label="Communication Email" error={errors.communication_email}>
              <input
                className={`form-input${errors.communication_email ? ' input-error' : ''}`}
                type="email"
                value={form.communication_email}
                onChange={(e) => set('communication_email', e.target.value)}
                placeholder="Defaults to login email if blank"
              />
            </Field>
            <Field label="Phone" error={errors.phone}>
              <input
                className={`form-input${errors.phone ? ' input-error' : ''}`}
                value={form.phone}
                onChange={(e) => set('phone', e.target.value)}
                placeholder="+91 9876543210"
              />
            </Field>
            <Field label="Enrollment No.">
              <input
                className="form-input"
                value={form.enrollment_number}
                onChange={(e) => set('enrollment_number', e.target.value)}
              />
            </Field>
            <Field
              label="Profile photo"
              error={errors.photo_url}
              hint="Upload a JPEG, PNG, WebP, or GIF (max 2MB). Files are stored in Amazon S3 — URL pasting is not supported."
              fullWidth
            >
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '1rem',
                  flexWrap: 'wrap',
                  padding: '0.75rem 1rem',
                  border: '1px solid var(--border-default)',
                  borderRadius: '10px',
                  background: 'var(--bg-secondary)',
                }}
              >
                {pendingAvatarPreview ? (
                  <img
                    src={pendingAvatarPreview}
                    alt=""
                    width={56}
                    height={56}
                    style={{
                      width: 56,
                      height: 56,
                      borderRadius: '50%',
                      objectFit: 'cover',
                      border: '1px solid var(--border-default)',
                      flexShrink: 0,
                    }}
                  />
                ) : (
                  <StudentListAvatar photo={displayPhoto} name={form.name || 'Student'} size={56} />
                )}
                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.45rem', minWidth: 0 }}>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                    <label
                      className="btn btn-secondary btn-sm"
                      style={{
                        cursor: avatarUploading || submitting ? 'wait' : 'pointer',
                        opacity: avatarUploading || submitting ? 0.75 : 1,
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '0.35rem',
                        margin: 0,
                      }}
                    >
                      {avatarUploading ? <Loader2 size={14} className="animate-spin" aria-hidden /> : <Upload size={14} aria-hidden />}
                      {avatarUploading ? 'Uploading…' : displayPhoto || pendingAvatarFile ? 'Change photo' : 'Upload photo'}
                      <input
                        type="file"
                        accept={studentAvatarAcceptAttr()}
                        hidden
                        disabled={avatarUploading || submitting}
                        onChange={handlePhotoSelected}
                      />
                    </label>
                    {!isEdit && pendingAvatarFile ? (
                      <button type="button" className="btn btn-ghost btn-sm" onClick={clearPendingPhoto} disabled={avatarUploading || submitting}>
                        Remove
                      </button>
                    ) : null}
                  </div>
                  <p style={{ margin: 0, fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>
                    {isEdit
                      ? form.photo_url
                        ? 'Photo uploaded to S3 and linked to this student.'
                        : 'No photo yet — upload one for this student (stored in S3).'
                      : pendingAvatarFile
                        ? `${pendingAvatarFile.name} will upload to S3 when you save.`
                        : 'Optional — can also be uploaded later from the student profile (S3).'}
                  </p>
                </div>
              </div>
            </Field>
          </div>
        </fieldset>

        <fieldset style={{ border: 'none', padding: 0, margin: '0 0 1.5rem' }}>
          <SectionLegend>Academic context</SectionLegend>
          <div className="add-student-grid">
            <AcademicProgramPicker
              value={form.academic_program_code}
              error={errors.academic_program_code || errors.department}
              onChange={(code, mapped) => {
                if (!mapped) {
                  set('academic_program_code', '');
                  set('eligibility_group_code', '');
                  set('eligibility_group_name', '');
                  set('academic_program_display', '');
                  return;
                }
                setForm((f) => ({
                  ...f,
                  academic_program_code: mapped.academic_program_code,
                  degree_pursued: mapped.degree_pursued,
                  department: mapped.department,
                  branch: mapped.branch,
                  eligibility_group_code: mapped.eligibility_group_code,
                  eligibility_group_name: mapped.eligibility_group_name,
                  academic_program_display: mapped.academic_program_display,
                }));
                setErrors((e) => ({
                  ...e,
                  academic_program_code: '',
                  department: '',
                }));
              }}
            />
            <Field label="Batch *" error={errors.batch} fullWidth>
              <AdmissionBatchYearPicker
                value={form.batch}
                onChange={(year) => {
                  set('batch', year);
                  set('batch_year', year);
                }}
                error={errors.batch}
              />
              <p className="form-hint" style={{ margin: '0.35rem 0 0', fontSize: '0.75rem', color: 'var(--text-tertiary)' }}>
                Intake year (YYYY). Latest batch today: {getMaxAdmissionBatchYear()}. A new year is added each May when admissions open.
              </p>
            </Field>
            <Field label="Current academic year">
              <input
                className="form-input"
                value={form.academic_year}
                onChange={(e) => set('academic_year', e.target.value)}
                placeholder="e.g. 2025-26"
              />
            </Field>
            <Field label="Semester" error={errors.semester}>
              <select
                className={`form-select${errors.semester ? ' input-error' : ''}`}
                value={form.semester}
                onChange={(e) => set('semester', e.target.value)}
              >
                <option value="">Select…</option>
                {SEMESTER_OPTIONS.map((s) => (
                  <option key={s} value={s}>{s}</option>
                ))}
              </select>
            </Field>
            <Field label="Department" error={errors.department}>
              <input
                className={`form-input${errors.department ? ' input-error' : ''}`}
                value={form.department}
                readOnly={Boolean(form.academic_program_code)}
                onChange={(e) => set('department', e.target.value)}
                placeholder={form.academic_program_code ? 'Filled from academic program' : 'Select program above or enter manually'}
              />
            </Field>
            <Field label="Specialization / Branch">
              <input
                className="form-input"
                maxLength={100}
                value={form.branch}
                readOnly={Boolean(form.academic_program_code)}
                onChange={(e) => set('branch', e.target.value)}
              />
            </Field>
            <Field label="Degree Pursued">
              <input
                className="form-input"
                value={form.degree_pursued}
                readOnly={Boolean(form.academic_program_code)}
                onChange={(e) => set('degree_pursued', e.target.value)}
                placeholder="e.g. B.Tech"
              />
            </Field>
            <Field label="CGPA" error={errors.cgpa}>
              <ValidatedNumberInput
                fieldId={FIELD_IDS.STUDENT_CGPA}
                className={`form-input${errors.cgpa ? ' input-error' : ''}`}
                step="0.01"
                value={form.cgpa}
                onChange={(v) => set('cgpa', v)}
              />
            </Field>
            <Field label="Class X %" error={errors.tenth_percentage}>
              <ValidatedNumberInput
                fieldId={FIELD_IDS.STUDENT_PERCENT}
                context={{ label: 'Class X %' }}
                className={`form-input${errors.tenth_percentage ? ' input-error' : ''}`}
                step="0.01"
                value={form.tenth_percentage}
                onChange={(v) => set('tenth_percentage', v)}
              />
            </Field>
            <Field label="Class XII %" error={errors.twelfth_percentage}>
              <ValidatedNumberInput
                fieldId={FIELD_IDS.STUDENT_PERCENT}
                context={{ label: 'Class XII %' }}
                className={`form-input${errors.twelfth_percentage ? ' input-error' : ''}`}
                step="0.01"
                value={form.twelfth_percentage}
                onChange={(v) => set('twelfth_percentage', v)}
              />
            </Field>
            <Field label="Diploma %" error={errors.diploma_percentage}>
              <ValidatedNumberInput
                fieldId={FIELD_IDS.STUDENT_PERCENT}
                context={{ label: 'Diploma %' }}
                className={`form-input${errors.diploma_percentage ? ' input-error' : ''}`}
                step="0.01"
                value={form.diploma_percentage}
                onChange={(v) => set('diploma_percentage', v)}
              />
            </Field>
            <Field label="Active Backlogs" error={errors.backlogs_active}>
              <ValidatedNumberInput
                fieldId={FIELD_IDS.STUDENT_BACKLOGS_ACTIVE}
                className={`form-input${errors.backlogs_active ? ' input-error' : ''}`}
                value={form.backlogs_active}
                context={{ backlogsTotal: form.backlogs_history }}
                onChange={(v) => set('backlogs_active', v)}
              />
            </Field>
            <Field label="Total Backlogs (history)" error={errors.backlogs_history}>
              <ValidatedNumberInput
                fieldId={FIELD_IDS.STUDENT_BACKLOGS_TOTAL}
                className={`form-input${errors.backlogs_history ? ' input-error' : ''}`}
                value={form.backlogs_history}
                context={{ backlogsActive: form.backlogs_active }}
                onChange={(v) => set('backlogs_history', v)}
              />
            </Field>
          </div>
        </fieldset>

        <fieldset style={{ border: 'none', padding: 0, margin: '0 0 1.5rem' }}>
          <SectionLegend>Programme timeline</SectionLegend>
          <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', margin: '0 0 0.875rem' }}>
            Optional calendar years for eligibility. Admission year is usually the start year of the joining batch.
          </p>
          <div className="add-student-grid">
            <Field label="Admission year" error={errors.batch_year} hint="Calendar year (often batch start year)">
              <input
                className={`form-input${errors.batch_year ? ' input-error' : ''}`}
                inputMode="numeric"
                value={form.batch_year}
                onChange={(e) => set('batch_year', e.target.value)}
                placeholder="e.g. 2022"
              />
            </Field>
            <Field label="Graduation year" error={errors.graduation_year} hint="Expected pass-out year">
              <input
                className={`form-input${errors.graduation_year ? ' input-error' : ''}`}
                inputMode="numeric"
                value={form.graduation_year}
                onChange={(e) => set('graduation_year', e.target.value)}
                placeholder="e.g. 2026"
              />
            </Field>
          </div>
        </fieldset>

        <fieldset style={{ border: 'none', padding: 0, margin: '0 0 1.5rem' }}>
          <SectionLegend>Demographics</SectionLegend>
          <div className="add-student-grid">
            <Field label="Gender">
              <select className="form-select" value={form.gender} onChange={(e) => set('gender', e.target.value)}>
                <option value="">Select…</option>
                {GENDERS.map((g) => (
                  <option key={g} value={g}>{g}</option>
                ))}
              </select>
            </Field>
            <Field label="Diversity Category">
